window.TOPICS=[{"t":"개인적 종교","sum":"개인적 종교는 전통이나 교회 권위에 기대는 ‘마음의 종교’와 달리, 각 사람이 자기 혼 안에서 하나님을 스스로 발견하고 체험하는 ‘영의 종교’이다. 그것은 남에게 받거나 빌리거나 배워서 얻을 수 없고, 최상 가치에 대한 충성과 함께 자라난다. 예수는 권위의 종교를 넘어 이 살아 있는 개인 체험의 종교를 선포했으며, 그 열매는 사랑과 봉사로 드러난다.","sections":[{"h":"마음의 종교와 영의 종교","items":[{"x":"종교에는 두려움의 원시 종교, 전통 권위에 근거한 문명의 종교, 인간 체험에서 입증되는 계시의 종교가 있다.","r":["155:5.3","155:5.4","155:5.5"]},{"q":"예수는 마음의 종교와 영의 종교의 큰 차이는 전자가 교회 권위에 의해 지탱되는 반면, 후자는 전적으로 인간 체험에 기초한다는 점을 명확히 했다.","r":"155:5.6"},{"x":"권위의 종교는 두렵고 불안한 혼에게 쉬운 피난처가 되지만, 수동적이고 지적인 동의만을 요구한다.","r":["155:5.9"]},{"q":"영의 종교는 노력, 투쟁, 갈등, 신앙, 결단, 사랑, 충성, 진보를 의미한다.","r":"155:5.11"},{"x":"마음의 종교는 사람을 과거에 묶어 두지만, 영의 종교는 점진적 계시로 더 높은 성취를 향해 늘 손짓한다.","r":["155:6.4"]}]},{"h":"스스로 하나님을 발견하는 체험","items":[{"x":"인간 혼이 이룰 수 있는 가장 위대한 발견은 자기 안에서 스스로 하나님을 발견하고 그것을 개인적 체험으로 사는 것이다.","r":["155:6.3"]},{"x":"과거의 하나님을 아는 지도자들을 존경하는 것은 좋지만, 그 때문에 스스로 하나님을 아는 체험을 희생해서는 안 된다.","r":["155:6.7"]},{"x":"하나님의 말씀을 옛 기록에서만 찾지 말고, 영으로 거듭난 이는 어디서 오든 하나님의 말씀을 분별한다.","r":["155:6.12"]},{"x":"혼 속에서 하나님을 발견하기 시작하면 곧 다른 이들의 혼과 모든 창조계 속에서도 그분을 발견하게 된다.","r":["155:6.13"]},{"x":"사도들의 종교는 두려움을 피하는 신학적 피난처가 아니라, 하나님이 그들을 발견하고 높였음을 증언하는 실제 체험이어야 한다.","r":["155:6.18"]}]},{"h":"남에게 받을 수 없는 종교","items":[{"q":"종교는 증여되거나, 받거나, 빌려주거나, 배우거나, 잃어버릴 수 없다.","r":"100:1.7"},{"x":"모든 아이에게 자기 종교 체험을 스스로 키울 기회를 주어야 하며, 완성된 어른의 체험을 강요해서는 안 된다.","r":["100:1.3"]},{"x":"아이들은 함께 지내는 어른들의 충성심에 의해서만 영원한 인상을 받는다.","r":["100:1.4"]},{"q":"올챙이가 개구리가 되는 가장 빠른 방법은 매 순간을 충성스럽게 올챙이로 사는 것이다.","r":"100:1.4"},{"x":"어떤 이들은 너무 바빠서 성장하지 못하며, 성장의 주된 장애물은 편견과 무지이다.","r":["100:1.2"]}]},{"h":"개인적 종교의 성장","items":[{"x":"영적 발달은 참된 영적 세력과 살아 있는 연결을 유지하고, 받은 것을 동료에게 나누는 열매를 맺는 데 달려 있다.","r":["100:2.1"]},{"x":"영성은 하나님께 가까운 정도이자 동료에게 유익한 정도의 척도이며, 사랑에서 이기적 요소를 덜어 내는 만큼 자란다.","r":["100:2.4"]},{"x":"신성한 가치에 대한 민감함, 성찰적 명상, 예배하는 자세의 문제 해결 같은 습관이 종교적 성장을 돕는다.","r":["100:1.8"]},{"x":"역경과 미움의 홍수가 덮쳐도 하나님을 아는 이에게는 결코 공격받지 않는 영의 성채가 있다.","r":["100:2.7"]},{"q":"영성은 하나님께 가까이 있는 정도이자 동료 존재들에게 유익한 정도의 척도이다.","r":"100:2.4"}]},{"h":"개인적 종교의 사회적 열매","items":[{"x":"권위의 종교는 사람들을 분열시키지만, 영의 종교는 신념의 다양성을 허용하면서 체험과 운명의 일치로 사람들을 묶는다.","r":["155:6.9"]},{"x":"인류의 통일과 형제단은 오직 개인적 영적 체험의 종교를 통해서만 이룰 수 있다.","r":["155:6.8"]},{"x":"하나님을 안다는 증거는 일상에서 맺는 영의 열매와, 생존의 모험에 모든 것을 건 삶의 계획이다.","r":["155:6.14","155:6.15","155:6.16"]},{"x":"왕국의 종교는 개인적이지만 그 열매는 가족적이고 사회적이며, 아무도 자기 안에만 담아 둘 수 없다.","r":["170:3.9","170:3.10"]},{"x":"아버지는 신앙의 미미한 불꽃에도 응답하시지만, 부름받은 이는 몸과 마음과 영 전체로 믿어야 한다.","r":["155:6.17"]},{"q":"권위의 종교는 사람들을 분열시키고 양심에 따라 서로 맞서게 할 뿐이다.","r":"155:6.9"}]}],"see":["종교 체험","제도 종교","신앙","하나님 나라","생각 조절자","성장"],"n":55,"en":"Personal Religion"},{"t":"결혼과 가정","sum":"결혼은 양성이라는 생물학적 사실에 대한 인간 사회의 제도적 응답이며, 가정은 그 오랜 진화적 투쟁이 맺은 최고의 열매이다. 유란시아서는 결혼이 신성한 성례가 아니라 본질적으로 인간적인 제도라고 말하면서도, 짝을 이루는 결혼과 좋은 가정이 문명의 안정과 도덕성의 뿌리이며 하나님의 아버지됨과 사람의 형제됨을 처음 배우는 자리라고 가르친다.","sections":[{"h":"결혼의 기원과 사회적 의미","items":[{"x":"결혼은 짝짓기 본능 자체가 아니라, 그 본능을 다스리기 위해 사회가 발전시킨 제도적 반응이다.","r":["82:1.1","82:3.1"]},{"q":"결혼은 인류에게 가정을 선사했으며, 가정은 길고 힘겨운 진화적 투쟁 전체의 최고 영광이다.","r":"82:0.1"},{"x":"결혼에는 도덕률과 법이 규제하는 바깥 영역과, 남녀 사이의 사적이고 개인적인 영역이 언제나 함께 있다.","r":["82:3.2"]},{"x":"결혼은 늘 재산·종교와 얽혀 있었으니, 재산은 결혼을 안정시키고 종교는 결혼을 도덕화했다.","r":["82:4.1"]},{"x":"물질적 필요가 결혼을 낳고, 성적 욕구가 꾸미고, 종교가 승인했으며, 나중에 사랑이 결혼을 정당화하게 되었다.","r":["84:0.1"]},{"x":"강한 성적 충동을 사회 규제에 지성적으로 맞추는 일은 문명의 실제성을 가늠하는 최상의 시험이며, 자기 통제가 늘 요구된다.","r":["82:1.10"]}]},{"h":"일부일처제와 짝을 이루는 결혼","items":[{"x":"일부일처제는 진화하는 인간에게 본래 자연스럽지는 않지만 문화적으로 큰 가치를 지니며, 자녀에게는 확실히 최선이다.","r":["83:6.1","83:6.2"]},{"q":"일부일처제는 항상 그래왔고, 지금도 그러하며, 영원히 인간 성(性) 진화의 이상적인 목표일 것이다.","r":"83:6.6"},{"x":"짝 결혼의 이상은 자기 부정을 요구하므로, 당사자에게 굳건한 자제력이 없을 때 흔히 실패한다.","r":["83:6.6"]},{"x":"일부일처제는 섬세한 감정과 도덕적 성품의 정련, 영적 성장을 북돋우며, 부모의 행복과 자녀의 안녕에 가장 좋다.","r":["83:6.7","83:6.8"]},{"x":"배우자를 얻지 못한 이들의 처지를 사회는 외면하지 말고, 그들을 늘 친절하고 배려 깊게 대해야 한다.","r":["83:6.4","83:6.5"]}]},{"h":"성례가 아닌 인간의 제도","items":[{"q":"가정으로 완성되는 결혼은 실로 인간의 가장 고귀한 제도이지만, 본질적으로 인간적인 것이다.","r":"83:8.1"},{"x":"남편과 아내의 결합을 조절자와 사람의 관계나 신성한 결합에 견주는 것은 큰 혼란을 낳은 불행한 비유이다.","r":["83:8.2","83:8.3"]},{"x":"결혼이 해소될 수 있다는 사실 자체가 하나님이 그 결합을 맺어 주는 당사자가 아님을 보여 준다.","r":["83:8.4"]},{"x":"그래도 높은 구체에는 결혼의 이상이 있어, 물질 아들과 딸이 그 정점을 구현한다. 이상적인 필사자 결혼은 인간적으로 신성하다.","r":["83:8.5"]},{"x":"젊은이의 결혼 이상은 꺾지 말되, 가정생활의 현실을 미리 배워 어느 정도의 환멸로 균형을 잡아야 한다.","r":["83:8.6","83:8.7"]}]},{"h":"가정, 문명의 으뜸 주체","items":[{"x":"종교·사회·교육 제도도 필요하지만, 아이는 삶의 필수 요소 대부분을 가정과 이웃에서 배우므로 가정이 으뜸가는 문명화 주체이다.","r":["82:0.2","82:0.3"]},{"q":"결혼은 모든 인간 제도의 어머니이니, 그것이 직접적으로 가정 설립과 가정 유지로 이어지며, 이는 사회의 구조적 기반이기 때문이다.","r":"84:6.8"},{"q":"가정이 좋으면 사회도 좋다.","r":"84:7.1"},{"x":"남녀는 서로를 완전히 이해할 수 없지만 효과적으로 서로를 보완하며, 그 차이는 모론시아와 영의 생애에서도 이어진다.","r":["84:6.3","84:6.6","84:6.7"]},{"x":"결혼은 이제 아내를 재산으로 보던 단계를 벗어나, 인격을 존중하는 새로운 시대로 넘어가고 있다.","r":["84:7.3","84:5.10"]}]},{"h":"부모와 자녀, 가정의 영적 의미","items":[{"x":"아이를 낳는 것은 부모의 권리가 아니라 인간 실존의 최고 책임이며, 문명은 부모에게 의무를, 아이에게 권리를 둔다.","r":["84:7.25","84:7.26"]},{"x":"가정은 형제애에 필요한 인내·이타심·관용·오래 참음을 부모와 자녀가 함께 배우는 형제단의 근본 단위이다.","r":["84:7.28"]},{"x":"안드족처럼 가족 일을 형제처럼 자유롭게 의논하는 가족 회의의 관행으로 돌아가면 사회가 크게 나아질 것이다.","r":["84:7.29"]},{"q":"가정생활은 참된 도덕성의 시조이며, 의무에 대한 충성심 의식의 조상이다.","r":"84:7.30"},{"x":"예수는 왕국의 복음이 가족 관계의 말로, 곧 하나님의 아버지됨과 사람의 형제됨으로 이해될 때 더 잘 받아들여질 것이라 했다.","r":["142:7.4"]},{"x":"예수는 참된 가족이 존재, 안전과 즐거움, 교육, 징계, 동반자 관계, 사랑과 자비, 미래 대비라는 일곱 가지 사실 위에 선다고 가르쳤다.","r":["142:7.5","142:7.11"]},{"x":"요셉이 죽은 뒤 젊은 예수는 가족을 부양하는 일을 첫 의무로 삼고 동생들에게 아버지 역할을 했다.","r":["126:3.2","126:3.5"]}]},{"h":"가정을 위협하는 것","items":[{"x":"가정생활에 대한 가장 큰 위협은 자기 만족을 좇는 현대의 쾌락 광기이다.","r":["84:8.1"]},{"q":"혼의 갈망은 육체적 쾌락으로는 채워질 수 없으며, 가정과 자녀에 대한 사랑은 지혜롭지 못한 쾌락 추구로 증대되지 않는다.","r":"84:8.4"},{"x":"건전한 놀이와 오락은 가치가 있지만, 쾌락이 결혼과 가정의 붕괴를 부른다면 그것은 자멸적이다.","r":["84:8.5","84:8.6"]},{"x":"부모의 책임을 국가나 교회로 넘기려는 시도는 문명의 안녕과 진보에 자살 행위가 될 것이다.","r":["84:7.27"]}]}],"see":["문명","도덕성","사람의 형제됨","사랑","물질 아들과 딸","정부와 사회"],"n":81,"en":"Marriage and Family"},{"t":"계시","sum":"계시는 진화 종교가 우회하며 찾던 진리를 실제 영적 세계가 직접 제시하는 것으로, 진화 종교를 분류하고 고양한다. 진리는 조절자를 통해 올 때는 자체 계시이고, 천상 존재들을 통해 올 때는 시대적 계시이다. 유란시아에는 시대적 계시가 다섯 번 있었으며, 계시는 그 시대의 사상과 너무 멀어지지 않도록 진화와 접촉을 유지하고, 과학과 종교와 철학을 하나의 진리로 조율한다.","sections":[{"h":"진화 종교와 계시 종교","items":[{"q":"계시는 진화적이지만 언제나 진보적이다.","r":"92:4.1"},{"q":"진화 종교는 진리를 찾기 위한 인류의 우회적 탐색을 묘사하지만, 계시된 종교는 그 진리 자체이다.","r":"92:4.3"},{"x":"계시된 종교는 최종 가치의 신에 대한 믿음과 죽음 뒤 인격 생존에 대한 개념을 늘 특징으로 한다.","r":["92:4.2"]},{"x":"계시는 진화 종교를 고양하기 위해, 그 시대의 사상에서 너무 멀리 벗어나지 않는 가르침을 제시해야 한다.","r":["92:4.1"]},{"x":"진화 종교의 도덕은 두려움으로 몰아가지만, 계시 종교는 하나님처럼 되려는 갈망으로 사랑의 하나님을 찾게 한다.","r":["5:4.1"]}]},{"h":"다섯 번의 시대적 계시","items":[{"x":"시대적 의미를 지닌 계시는 다섯 번뿐이었으니, 첫째는 칼리가스티아 참모진 100인의 달라마시아 가르침이다.","r":["92:4.4","92:4.5"]},{"x":"둘째는 아담과 이브의 에덴 가르침이며, 동산의 붕괴로 중단되었으나 셋족 사제들이 일부를 이어 갔다.","r":["92:4.6"]},{"x":"셋째는 살렘의 멜기세덱이 신뢰와 신앙을 가르친 계시이다.","r":["92:4.7"]},{"x":"넷째는 하나님을 우주 아버지로 드러내고 사랑과 봉사를 가르친 나사렛 예수이다.","r":["92:4.8"]},{"x":"다섯째는 많은 존재가 함께 제시한 유란시아 문서들이다.","r":["92:4.9"]},{"q":"그러나 우주 아버지에 이르기 전까지 어떤 계시도 완전할 수 없다.","r":"92:4.9"}]},{"h":"진리는 언제나 계시이다","items":[{"q":"진리는 언제나 계시이다. 내주하는 조절자의 작업의 결과로 나타날 때는 자체 계시이며, 다른 어떤 천상의 기관, 집단 또는 인격체의 기능에 의해 제시될 때는 시대적 계시이다.","r":"101:4.3"},{"q":"지식의 추구는 과학을 이루고, 지혜의 탐구는 철학이며, 하나님에 대한 사랑은 종교이고, 진리에 대한 갈망은 계시이다.","r":"102:3.12"},{"x":"과학의 제1원인이 자비로 충만한 아버지라는 사실은 계시를 통해서만 알 수 있다.","r":["4:4.7","101:2.3"]},{"x":"계시는 과학과 종교를 창시하지 않으며, 그 기능은 둘을 실체의 진리와 조율하는 것이다.","r":["103:7.8"]},{"x":"계시는 오직 인간의 체험으로만 검증되며, 과학과 종교와 철학의 접근이 조화를 이룸을 확증한다.","r":["101:2.8"]}]},{"h":"계시의 방법과 한계","items":[{"x":"계시자들은 현존하는 가장 높은 인간 개념을 우선하고, 적절한 표현이 없을 때에만 순수한 계시에 의존한다.","r":["0:12.11"]},{"x":"이 문서들은 하나님을 아는 필사자들에게서 모은 천 개가 넘는 인간 개념을 기초로 삼았다.","r":["0:12.12"]},{"x":"계시의 법칙은 아직 얻지 않았거나 시기상조인 지식을 주는 것을 금하므로, 계시에 담긴 우주론은 곧 낡게 된다.","r":["101:4.1","101:4.2"]},{"x":"계시는 영적 현상이지만 우주론에 관한 진술은 영감받은 것이 아니며, 오류를 줄이고 잃어버린 지식을 되살리는 데 가치가 있다.","r":["101:4.5","101:4.6","101:4.8"]},{"x":"반란으로 인한 고립 때문에 진리의 계시가 일시적인 우주론과 섞였으나, 그 때문에 영원한 진리를 가볍게 여겨서는 안 된다.","r":["102:1.3"]}]},{"h":"계시가 하는 일","items":[{"x":"계시는 모론시아 관점의 부재를 보완해, 물질과 영의 관계를 이해하는 통일 기법을 제공한다.","r":["101:2.2"]},{"q":"진정한 계시는 결코 과학을 부자연스럽게 만들지 않고, 종교를 비합리적으로 만들지 않으며, 철학을 비논리적으로 만들지 않는다.","r":"101:2.2"},{"x":"계시는 진화하는 철학의 연약함을 보완하며, 형이상학이 하지 못한 일을 완성한다.","r":["103:8.6","101:2.7"]},{"x":"계시는 사람을 해방하여 영원한 모험으로 이끌고, 인격의 생존에 대한 확신을 준다.","r":["102:3.6","102:3.9"]},{"x":"계시는 사람을 영화롭게 하며 그가 하나님과 동역할 수 있는 능력을 드러낸다.","r":["102:3.7"]}]}],"see":["진리","과학과 종교","철학","마키벤타 멜기세덱","아담과 이브","예수의 증여"],"n":75,"en":"Revelation"},{"t":"과학과 종교","sum":"과학은 이성으로 사실과 에너지-물질의 세계를 탐구하고, 종교는 신앙으로 가치와 영적 실체를 체험한다. 둘은 서로 다른 가정에서 출발하는 독립된 영역이며, 철학이 그 사이를 조율하려 하고 계시는 과학의 제1원인과 종교의 구원의 하나님이 같은 분임을 확언한다. 과학은 미신을 걷어 내 종교를 정화하고, 종교는 과학 시대의 문명이 함께 살아갈 형제 됨의 충동을 준다.","sections":[{"h":"서로 다른 두 영역","items":[{"q":"과학은 사실을 다루고, 종교는 오직 가치에 관여한다.","r":"101:5.2"},{"q":"이성은 과학의 방법이고, 신앙은 종교의 방법이며, 논리는 철학의 시도된 기법이다.","r":"101:2.2"},{"x":"과학은 물질·운동·생명의 실체를, 종교는 마음·영·최상 존재를 증명 없이 가정하고 출발한다.","r":["103:7.11","103:7.10"]},{"q":"과학의 확실성은 전적으로 지성에서 비롯되지만, 종교의 확신은 인격 전체의 기초에서 우러나온다.","r":"102:1.4"},{"x":"과학에서는 관념이 표현보다 앞서지만, 종교에서는 실현의 체험이 관념의 표현보다 앞선다.","r":["102:3.13"]}]},{"h":"하나님을 보는 서로 다른 눈","items":[{"x":"하나님은 과학에는 원인이요, 철학에는 관념이며, 종교에는 인격이자 사랑의 하늘 아버지이시다.","r":["1:6.2","4:4.7"]},{"x":"하나님의 존재는 과학적 실험이나 순수 논리로는 결코 입증될 수 없고, 오직 인간 체험 안에서 실현된다.","r":["1:2.7","101:10.6"]},{"x":"이성은 자연을 연구해 제1원인에 이를 수 있지만, 그것을 구원의 하나님으로 바꾸는 데는 신앙이 필요하다.","r":["101:2.3"]},{"x":"계시는 과학의 제1원인과 종교의 구원의 하나님이 동일한 신임을 확언한다.","r":["101:2.7"]},{"x":"과학에서 하나님은 가능성이고, 철학에서는 개연성이며, 종교에서는 확실성이다.","r":["102:6.8"]}]},{"h":"서로를 돕는 관계","items":[{"q":"과학은 오류 제거로 철학을 안정시키고, 미신 파기로 종교를 정화한다.","r":"81:6.10"},{"x":"진화 종교는 계시의 검열과 참된 과학의 용광로 속에서 끊임없이 정제되어야 한다.","r":["92:3.10","99:3.7"]},{"x":"과학은 물리 환경을 다스리게 하고, 종교는 과학 시대의 복잡한 문명에서 함께 살게 하는 형제 됨의 충동을 준다.","r":["103:7.9"]},{"x":"과학과 종교 모두 더 면밀하고 두려움 없는 자기비판이 필요하며, 두 영역의 교사들은 흔히 지나치게 교의적이다.","r":["103:7.7"]},{"x":"과학의 발견과 종교의 통찰을 조화시키려면 진리가 어디로 이끌든 따르려는 진실한 열망이 있어야 한다.","r":["103:7.5"]}]},{"h":"조율하는 철학과 계시","items":[{"x":"과학은 물질 세계를 발견하고 종교는 그것을 평가하며, 철학은 두 관점을 조율해 의미를 해석하려 한다.","r":["103:7.15"]},{"x":"과학과 종교의 조화가 어려운 것은 모론시아라는 중간 영역을 모르기 때문이며, 모론시아 관점은 그 차이를 없앤다.","r":["103:6.7"]},{"x":"형이상학은 모론시아 모타의 부재를 메우려는 진지하지만 실패한 인간의 시도이다.","r":["103:6.7"]},{"x":"계시는 과학이나 종교를 창시하지 않으며, 그 기능은 둘을 실체의 진리와 조율하는 것이다.","r":["103:7.8"]},{"x":"참된 계시는 과학을 부자연스럽게, 종교를 비합리적으로, 철학을 비논리적으로 만들지 않는다.","r":["101:2.2","102:3.15"]}]},{"h":"물질주의 시대를 넘어","items":[{"x":"계시서의 물리 과학 진술은 곧 수정이 필요할 것이며, 그 우주론은 영감받은 것이 아니다.","r":["101:4.2"]},{"q":"너희가 과학을 더 많이 알수록 확신할 수 있는 것은 더 줄어들고, 너희가 종교를 더 많이 가질수록 더욱 확신하게 된다.","r":"102:1.3"},{"x":"과학자들은 뜻하지 않게 인류를 물질주의적 공황에 몰아넣었지만, 예수의 종교는 결코 파산하지 않았다.","r":["195:6.1"]},{"x":"과학이 무너뜨린 것은 잘못된 해석에서 나온 유치한 환상뿐이며, 참된 종교는 손대지 않은 채 남아 있다.","r":["195:6.4"]},{"q":"사실은 결코 진정한 영적 신앙과 충돌하지 않지만, 이론은 그럴 수 있다.","r":"195:7.1"}]}],"see":["철학","계시","진리","신앙","종교 체험","모론시아"],"n":73,"en":"Science and Religion"},{"t":"궁극 하나님","sum":"궁극 하나님은 최상 존재에 이어 창발하는 둘째 체험적 신으로, 주(主) 우주의 시간과 공간을 초월한 아절대 수준에서 기능하는 초월적 권능-인격이다. 그는 최상 창조자들과 최상 존재와 주 우주 건축자들로 이루어질 궁극 삼위일체의 통일에서 창발하며, 그의 완전한 출현은 주 우주 창조의 완성을 뜻한다. 대우주가 빛과 생명 속에 정착한 뒤 최종자들과 완성된 시민들이 나아갈 다음 탐구의 대상이다.","sections":[{"h":"아절대 수준의 신","items":[{"q":"궁극 하나님—초(超)시간과 초월된 공간의, 창발하는 하나님이다.","r":"0:2.17"},{"x":"아절대 실체는 창조되지 않고 창발하며 시작도 끝도 없이 시간과 공간을 초월하는 사물과 존재들이고, 이들과 관련된 신의 기능이 궁극위성이다.","r":["0:1.12"]},{"q":"최상위가 유한 존재들에 의해 이해될 수 있는 삼위일체 통합이라면, 궁극자는 아절대 존재들에 의해 이해될 수 있는 파라다이스 삼위일체 통합이다.","r":"0:9.2"},{"x":"신의 일곱 본성 가운데 최상위는 진화적-체험적 자아이고, 궁극위는 초월적-체험적 자아이다.","r":["118:0.5","118:0.7"]},{"x":"궁극 하나님은 시간과 공간을 초월하고 절대자들과 기능적으로 연합할 능력이 있지만, 그럼에도 아절대이다.","r":["106:4.4"]}]},{"h":"최상위와 궁극위","items":[{"q":"칠중 하나님이 최상위의 진화적 성취에 필수적이듯, 최상위도 궁극위의 최종적 출현에 필수적이다.","r":"118:0.9"},{"x":"최상위와 궁극위는 운명의 성취에서 서로 보완하며, 주 우주의 모든 창조적 성장의 시작과 완성을 잇는 체험적 다리를 이룬다.","r":["118:0.9"]},{"x":"궁극위와 최상위는 비교할 수 있지만 같지 않으며, 궁극위가 최상위를 단순히 확대한 것도 아니다.","r":["106:8.15"]},{"x":"최상 존재가 대우주의 잠재성에서 진화하듯, 궁극 하나님은 주 우주의 시간과 공간을 초월한 영역에 있는 신성 잠재력에서 창발한다.","r":["0:9.1"]},{"x":"최상 하나님이 시간과 공간의 우주를 직접 다스리게 되면, 그 행정은 궁극위의 상위통제 아래 기능하고 궁극 하나님은 초월적 전능자로 나타나기 시작할 것이다.","r":["118:2.4"]}]},{"h":"궁극 삼위일체","items":[{"x":"궁극 삼위일체는 최상 창조자들, 최상 하나님, 주 우주 건축자들로 이루어지는 신 연합이며 지금 진화하는 중이다.","r":["0:12.6","106:8.10"]},{"q":"궁극 하나님은 결국 그리고 필연적으로 거의 한계가 없는 주(主) 우주의 확장하는 무대에서 이 체험적 궁극 삼위일체의 통일이 가져오는 신 결과로서 권능화하고 인격화할 것이다.","r":"0:12.6"},{"x":"현 우주 시대가 끝나 전능 최상위가 출현하면, 첫째 체험적 삼위일체가 온전히 기능하여 주 창조의 진화를 더 깊이 통합할 것이다.","r":["106:3.2"]},{"x":"이 삼위일체에는 주 창조자 아들들이 들어 있어, 실제 창조체의 체험이 그 연합 안에 포함된다.","r":["106:3.3"]},{"q":"궁극위의 완성된 창발은 주(主) 창조의 완성을 의미하며, 동시에 이 초월적 신의 완전한 출현을 함축한다.","r":"106:4.2"},{"x":"주 우주의 통일은 궁극자의 창발 행위이며, 파라다이스 삼위일체의 아절대 상위통제의 어떤 국면을 반영한다고 여겨진다.","r":["10:8.2"]}]},{"h":"지금 드러나는 궁극위","items":[{"x":"최상위가 하보나에 영적·인격적으로 현존하듯, 궁극위도 그곳에 아절대적·초인격적 의미로 존재한다.","r":["106:4.3"]},{"x":"궁극위의 제한 대리 통치자들이 이미 존재한다고 알려졌으나, 그들의 현재 위치와 역할은 계시되지 않았다.","r":["106:4.3","117:7.4"]},{"x":"궁극 하나님은 빛과 생명으로 정착된 지역 우주의 후기 단계에서 자신의 초월적 상위통제를 미리 드러낸다.","r":["56:7.5"]},{"x":"빛과 생명의 일곱째 단계에 이른 필사자들은 최상 하나님을 알아 가면서 궁극 하나님의 두루 미치는 사역을 어렴풋이 분별한다.","r":["56:10.1"]},{"x":"분화되지 않은 잠재성을 규정된 우주 계획으로 바꾸는 ‘우주 용량의 창발’은 궁극위성과 초월 매개체들의 활동이다.","r":["118:4.6"]}]},{"h":"최종자의 다음 목표","items":[{"x":"상승자는 하보나에서 최상 하나님을 발견하고, 최종자가 된 뒤에는 그를 궁극위로 알고자 시도하게 된다.","r":["118:2.2"]},{"x":"최상 존재의 진리·아름다움·선하심이 끝까지 스며들면, 진보하는 창조체에게 그 개념 수준을 넘어선 궁극 신성의 아절대 특질들이 열린다.","r":["115:3.19"]},{"x":"궁극 하나님은 칠중 하나님의 사역으로 아절대 수준에 이른 모든 창조체에게 궁극적 봉사의 운명을 제공하도록 마련되어 있다.","r":["0:9.1"]},{"q":"확실히, 틀림없이, 그리고 가차 없이 출현하는 신인 궁극 하나님의 수수께끼는 정착된 우주들의 이 완전해진 시민들에게 새로운 도전을 던질 것이며, 이는 한때 그들의 진화적 조상들에게 최상 하나님 탐구가 던졌던 도전과 동일하다.","r":"117:7.17"},{"x":"궁극위를 성취한 최종자에게 남는 길은 절대자 탐구이며, 그들은 그 끝에서도 같은 파라다이스 아버지를 만나게 됨을 안다.","r":["118:2.2"]},{"x":"최상·궁극 하나님은 과거로는 영원하지 않고 미래로만 영원한 신들로, 인격의 시작은 있지만 끝은 없다.","r":["0:9.5"]}]}],"see":["최상 존재","파라다이스 삼위일체","세 절대자","최종자 군단","대우주와 주(主)우주","빛과 생명"],"n":9,"en":"God the Ultimate"},{"t":"기도","sum":"기도는 영을 향한 혼의 태도를 인격적이고 자발적으로 표현하는 것이며, 하나님과 아들됨의 교제를 나누는 혼의 숨결이다. 원시 시대의 물질적 간청에서 시작된 기도는 점차 윤리적이고 영적인 교통으로 진화했다. 기도는 하나님을 바꾸지 않지만 기도하는 사람을 바꾸며, 사물이 아니라 가치를, 만족이 아니라 성장을 구할 때 가장 참되다. 예수는 기도로 아버지의 뜻에 헌신한 삶을 살았다.","sections":[{"h":"기도란 무엇인가","items":[{"q":"기도는 전적으로 영을 향한 혼의 태도를 인격적이고 자발적으로 표현하는 것이다.","r":"144:2.2"},{"x":"기도는 아들됨의 교제이자 친교의 표현이며, 이상적인 기도는 지성적 예배로 이끄는 영적 교통이다.","r":["144:2.2"]},{"x":"기도는 혼의 숨결로서 아버지의 뜻을 깨닫기 위해 끊임없이 애쓰도록 이끈다.","r":["144:2.3"]},{"x":"기도는 인간의 의지를 신성한 의지로 바꾸는 과정이며, 지금 있는 것을 마땅히 되어야 할 것으로 바꾸는 신성한 계획의 일부이다.","r":["144:4.9"]},{"x":"참된 기도는 창조체의 영적 본성이 어디에나 계신 창조주의 영과 나누는 진실하고 신뢰에 찬 소통이다.","r":["91:8.4"]},{"q":"기도는 혼의 숨결이며, 아버지의 뜻을 깨닫기 위해 지속적으로 노력하도록 너희를 이끌어야 한다.","r":"144:2.3"}]},{"h":"기도의 진화","items":[{"x":"원시인은 음식이나 비 같은 물질적 축복을 위해 기도했는데, 이는 기도의 왜곡이었지만 사회적·윤리적 노력을 자극하기도 했다.","r":["91:1.3"]},{"x":"기도는 가장 원시적인 마음에서만 독백이며, 곧 대화가 되고 집단 예배로 넓어진다.","r":["91:1.4"]},{"x":"마법은 신을 조건에 맞추려는 시도였고, 기도는 인격을 신의 뜻에 맞추려는 노력이다.","r":["91:8.2"]},{"x":"희생 제물의 관념은 의지 대신 물질을 바치게 하여 참된 기도의 효능을 떨어뜨린다.","r":["91:2.4"]}]},{"h":"참된 기도의 원칙","items":[{"x":"이기적이고 물질적인 기도는 이타적 사랑에 기초한 윤리적 종교와 함께할 수 없다.","r":["91:4.1"]},{"q":"기도는 행동의 대체물이 될 만큼 타락해서는 결코 안 된다.","r":"91:4.2"},{"x":"하나님께 문제를 대신 해결해 달라고 할 만큼 게으르지 말고, 문제에 맞서는 동안 지혜와 힘을 구하라.","r":["91:6.5"]},{"q":"사물이 아니라 가치를 위해, 만족이 아니라 성장을 위해 기도하라.","r":"91:8.13"},{"x":"하나님은 말이 아니라 혼의 태도에 응답하시며, 진리와 아름다움과 선에 대한 더 깊은 계시로 기도에 답하신다.","r":["91:8.11","91:8.12"]},{"x":"효과적인 기도에는 실체에 용감히 맞섬, 성실한 노력, 신성한 뜻의 선택과 실천, 그리고 살아 있는 신앙이 필요하다.","r":["91:9.2","91:9.5","91:9.8"]}]},{"h":"기도가 바꾸는 것","items":[{"x":"기도가 하나님을 바꾸지는 않지만 신앙으로 기도하는 사람 안에는 크고 지속적인 변화가 일어난다.","r":["91:4.5"]},{"q":"기도는 인간을 향한 신성한 태도를 바꾸지 않지만, 기도는 변하지 않는 아버지에 대한 인간의 태도를 변화시킨다.","r":"146:2.8"},{"x":"날개를 펴야 상승 기류를 타듯, 기도는 우주의 영적 기류를 타고 사람을 높이 들어 올린다.","r":["91:8.9"]},{"x":"친구를 비판하는 습관을 고치는 가장 빠른 길은 그를 위해 날마다 기도하는 것이다.","r":["91:5.3"]},{"x":"신앙으로 진실하게 드리는 기도는 어리석은 청원일지라도 혼의 영적 수용 능력을 넓히는 데 결코 실패하지 않는다.","r":["144:4.2"]},{"q":"기억하라, 기도가 하나님을 바꾸지 않더라도 신앙과 확신에 찬 기대 속에서 기도하는 사람 안에는 자주 크고 지속적인 변화가 일어난다.","r":"91:4.5"}]},{"h":"예수가 가르친 기도","items":[{"x":"아버지의 뜻을 행하는 데 온전히 헌신할 때 기도는 그 뜻과 일치하므로 모든 청원에 응답이 있다.","r":["146:2.7"]},{"x":"예수는 자신을 위한 기도보다 형제들의 영적 진보를 위해 더 많이 기도하고, 원수와 박해자를 위해 특히 기도하라고 했다.","r":["146:2.10","146:2.11"]},{"x":"괴로울 때만이 아니라 혼이 평안할 때에도 아들로서 아버지와 말할 줄 알아야 한다.","r":["146:2.12"]},{"x":"예수는 기도한 뒤 잠시 침묵 속에 기다려 내주하는 영이 혼에게 말할 기회를 주라고 가르쳤다.","r":["146:2.17"]},{"x":"예수는 보통 단수가 아닌 복수로 기도했고, 지상 생애의 큰 위기 때에만 자신을 위해 기도했다.","r":["144:4.6"]},{"x":"예수에게 기도는 종교적 의무가 아니라 영적 태도의 진실한 표현이자 하나님과의 끊임없는 교통이었다.","r":["196:0.10"]}]}],"see":["예배","하나님의 뜻","신앙","하나님의 아들됨","종교 체험","개인적 종교"],"n":52,"en":"Prayer"},{"t":"기쁨과 행복","sum":"참된 행복은 부나 환경보다 내적 삶에서 나오며, 이기적 욕망과 내주하는 영의 이타적 충동이 하나의 의지 안에서 화해될 때 이루어진다. 최고의 행복은 영적 진보와 떼려야 뗄 수 없고, 기쁨은 홀로가 아니라 사랑과 봉사를 나눌 때 체험된다. 예수는 슬픔의 사람이 아니라 기쁨의 사람이었으며, 그의 평화는 하나님의 뜻을 행하는 사람의 기쁨이자 만족이다.","sections":[{"h":"행복은 어디서 오는가","items":[{"q":"행복과 기쁨은 내적 삶에서 기원한다. 너희는 진정한 기쁨을 홀로 체험할 수 없다. 고립된 삶은 행복에 치명적이다.","r":"111:4.7"},{"x":"행복은 타고난 충동을 더 나은 방법으로 채우는 기법의 총합이며, 환경에 크게 의존하지 않는다.","r":["140:4.10"]},{"x":"사람의 행복은 자아의 욕망과 더 높은 자아인 신성한 영의 이타적 충동이 하나의 의지로 조율될 때 이루어진다.","r":["103:5.5"]},{"x":"건강과 정신적 효율과 행복은 몸과 마음과 영이 하나로 통일되는 데서 비롯된다.","r":["100:4.3"]},{"q":"노력이 언제나 기쁨을 낳지는 않으나, 지성적인 노력 없이는 행복도 없다.","r":"48:7.10"}]},{"h":"영적 성장과 지속되는 기쁨","items":[{"x":"최고의 행복은 영적 진보와 불가분하며, 영적 성장은 지속적인 기쁨과 이해를 초월하는 평화를 낳는다.","r":["100:4.3"]},{"x":"조절자는 이기적 동기의 가치도 존중하지만, 행복과 하늘 왕국의 기쁨으로 이끄는 이타적 충동에 무게를 싣는다.","r":["103:2.7"]},{"x":"영으로 태어난 사람은 자기 부정의 속박에서 벗어나 기쁨이 넘치는 영의 왕국으로 옮겨진다.","r":["143:2.8"]},{"q":"과학은 지식을 낳고, 종교는 행복을 낳으며, 철학은 통일성을 낳는다.","r":"101:2.8"},{"x":"자유 의지 실존에는 모든 외부 영향과 상관없이 본래 기쁨이 있으며, 실존의 기쁨 천사들이 그것을 입증하려 애쓴다.","r":["28:5.16"]}]},{"h":"예수가 가르친 행복","items":[{"x":"산상의 지복 설교는 행복이라는 음조로 시작되었으며, 그 신앙과 사랑은 성품을 강하게 하고 행복을 창조한다.","r":["140:5.6"]},{"x":"아이의 행복은 즉각적 쾌락이지만, 어른은 더 큰 행복을 위해 자기 부정의 씨앗을 뿌린다.","r":["140:5.7"]},{"x":"겸손히 하나님을 찾는 이들은 먼 미래의 보상을 기다리지 않고 지금 마음속에서 왕국의 행복을 체험한다.","r":["140:5.7"]},{"x":"어떤 이들이 더 행복한 까닭을 묻자, 예수는 많은 것이 내주하는 아버지의 영의 인도를 받으려는 의지에 달렸다고 답했다.","r":["149:5.1","149:5.2"]},{"x":"많은 슬픔은 좌절된 야망과 상처 입은 자존심에서 오므로, 최선을 다한 뒤에는 처지를 받아들이고 창의력을 발휘해야 한다.","r":["149:5.3"]},{"q":"“그러므로 거짓된 평화와 일시적인 기쁨을 찾지 말고, 오히려 신앙의 확신과 신성한 아들됨의 보증을 구하라.","r":"149:5.4"}]},{"h":"사랑과 봉사의 기쁨","items":[{"x":"새 계명은 짐이 아니라 동료에게 애정을 나누는 새로운 기쁨을 주려는 것이었다.","r":["180:1.2"]},{"q":"만일 너희가 주님의 기쁨을 나누고자 한다면, 너희는 그의 사랑을 나누어야 한다.","r":"180:1.5"},{"x":"예수는 두려움에 짓눌린 젊은이에게 사랑의 활동이 주는 기쁨으로 이끄는 봉사의 오솔길과 행복의 큰길을 보여 주었다.","r":["130:6.2"]},{"x":"온전한 애정으로 하는 사랑의 봉사는 희생이 아니라 최상의 기쁨이 된다.","r":["180:1.6"]},{"x":"오순절 뒤 신자들은 기쁨과 한마음으로 함께 빵을 떼며, 형제단의 교제가 주는 영적 기쁨을 누렸다.","r":["194:4.3","190:5.4"]}]},{"h":"기쁨의 사람 예수","items":[{"q":"갈릴리의 이 사람은 슬픔의 사람이 아니라 기쁨의 사람이었다.","r":"100:7.13"},{"x":"예수의 평화는 스토아적 체념이나 막연한 낙관이 아니라, 하나님의 뜻을 행하는 법을 완전히 배운 사람의 기쁨이자 만족이다.","r":["181:1.7","181:1.8"]},{"x":"예수의 종교는 이 삶에서 달아나지 않고, 영적 존재 상태의 기쁨과 평화로 지금의 삶을 고귀하게 한다.","r":["194:3.3"]},{"x":"모론시아 생애는 일과 놀이가 거의 반반이며, 염려하던 많은 일이 하찮았음을 깨닫는 데서 오는 유머를 누린다.","r":["48:4.1","48:4.6"]},{"x":"예수는 이 세상을 눈물의 골짜기가 아니라 영원한 영이 태어나는, 혼이 형성되는 골짜기로 보았다.","r":["149:5.5"]}]}],"see":["두려움과 걱정","봉사","사랑","성장","하나님 나라","개인적 종교"],"n":70,"en":"Joy and Happiness"},{"t":"기적","sum":"예수는 광야에서 기적과 이적으로 사람들의 관심과 지지를 얻지 않기로 결정했고, 그 결정을 끝까지 지켰다. 그러나 무한한 창조자 특권을 지닌 이가 신성한 자비와 인간적 공감을 품고 땅에 있었기에, 치유와 같은 비범한 일들이 그의 뜻과 무관하게 따라 일어나기도 했다. 유란시아서는 기적처럼 보인 많은 일이 실은 자연스러운 사건이었음을 밝히고, 참된 기적도 자연 법칙을 깨뜨린 것이 아니라 시간 요소가 제거된 것이었다고 설명한다.","sections":[{"h":"기적을 쓰지 않겠다는 결정","items":[{"x":"광야의 40일 동안 예수는 표적을 바라는 유대인의 갈망을 채우려고 우주 권능을 쓰지 않기로 결심했다.","r":["136:8.1"]},{"q":"그는 기적을 베풀어 군중을 끌어모으는 존재가 되기를 단호히 거부했다.","r":"136:8.2"},{"x":"놀라운 이적은 물질적 사고를 자극해 겉으로만 충성하게 할 뿐, 하나님을 계시하지도 사람을 구원하지도 못한다.","r":["136:8.2"]},{"q":"예수는 인류의 마음속에 하늘 왕국을 세우기 위해 자연스럽고 평범하며 어렵고 인내가 필요한 길을 선택했다.","r":"136:8.6"},{"x":"바리새인들이 증거를 요구할 때도, 갈보리에서 십자가에서 내려오라는 조롱을 받을 때도 그는 이 결정을 어기지 않았다.","r":["136:7.4"]}]},{"h":"가나의 포도주","items":[{"x":"가나의 결혼 잔치에서 다른 이들은 기적을 기대했지만, 가장 놀란 사람은 그것을 하지 않기로 결심했던 예수 자신이었다.","r":["137:4.12"]},{"q":"그러나 이것은 기적이 아니었다. 어떤 자연 법칙도 변경되거나 폐기되거나, 심지어 초월되지도 않았다.","r":"137:4.13"},{"x":"창조자의 대리자들은 보통의 자연 과정대로 포도주를 만들되, 다만 시간에 구애받지 않았을 뿐이다.","r":["137:4.13"]},{"x":"이 일이 아버지의 뜻에 어긋났다면 일어나지 않았을 것이니, 예수는 이미 모든 일을 아버지 뜻에 맡겨 두었기 때문이다.","r":["137:4.14"]}]},{"h":"기적이 아니었던 일들","items":[{"x":"많은 물고기를 잡은 일은 기적이 아니라, 물고기 습성을 잘 아는 노련한 어부 예수가 고기 떼 있는 곳을 일러 준 것이었다.","r":["145:1.3"]},{"x":"베드로 장모의 열병이 나은 것도 기적이 아니었지만, 기적을 좇는 세대는 이런 우연을 모두 기적으로 삼았다.","r":["145:2.16","145:2.17"]},{"x":"예수는 평범한 물리적 사건에 영적 원인을 갖다 붙이지 말고, 모든 현상의 참된 원인을 찾으라고 사도들을 격려했다.","r":["164:3.6"]},{"x":"랍비들은 날 때부터의 눈멂을 죄의 결과로 보았지만, 예수는 이러한 미신적 설명을 받아들이지 않았다.","r":["164:3.2","164:3.3"]}]},{"h":"해 질 녘의 치유와 참된 기적들","items":[{"x":"가버나움에서 예수가 아버지의 뜻에 어긋나지 않는다면 자녀들이 온전하기를 바란다고 말하자, 순식간에 683명이 치유되었다.","r":["145:3.9","145:3.10"]},{"x":"이 치유에 가장 놀란 이는 예수 자신이었으니, 그는 창조자 특권의 시간 요소를 제한할 수 없다는 경고를 잠시 잊었다.","r":["145:3.11"]},{"q":"예수의 지상 사명을 때때로 따랐던 치유 기적들은 왕국 선포 계획의 일부가 아니었다.","r":"145:3.15"},{"x":"나병 환자를 깨끗하게 한 일은 예수가 의도적으로 행한 첫 이른바 기적이었다.","r":["146:4.5"]},{"q":"그리고 이것이 예수가 의식적인 사전 계획의 결과로 행한 처음이자 유일한 자연 기적이었다.","r":"152:2.10"},{"x":"나사로를 살릴 때 예수가 아버지께 감사드리자, 천상 무리가 움직여 지상 시간으로 열두 초 만에 그가 살아났다.","r":["168:2.2","168:2.3"]}]},{"h":"기적이 남긴 것","items":[{"x":"기적으로 배를 채운 오천 명 가운데 끝까지 예수를 따른 이는 약 오백 명뿐이었다.","r":["152:5.2"]},{"x":"예수는 이적을 구하는 이들의 호기심을 채우려고 아버지를 드러내는 사명에서 등을 돌리지 않겠다고 했다.","r":["145:5.6"]},{"x":"치유의 명성은 편견을 일으키는 소문과 원치 않는 명성을 불러와 예수에게 많은 어려움을 주었다.","r":["145:3.12","145:3.15"]},{"x":"나사로의 부활은 신자들의 신앙을 굳혔지만, 종교 지도자들은 오히려 예수를 없애려는 결정을 서둘렀다.","r":["168:3.1","168:3.4"]}]},{"h":"가장 큰 기적","items":[{"x":"지역 우주 시민에게 기적은 거의 없으며, 그 가운데 가장 흥미로운 것은 파라다이스 아들의 육신화 증여이다.","r":["120:4.5"]},{"q":"나사렛 예수는 기적적인 개인이었다.","r":"120:4.5"},{"x":"이 모든 비범한 체험 속에서도 아버지는 정상적이고 자연스러우며 믿을 만한 방식으로 자신을 나타내기를 택하셨다.","r":["120:4.6"]}]}],"see":["예수의 증여","예수의 성품","신앙","자비","예수의 가르침","생각 조절자"],"n":88,"en":"Miracles"},{"t":"대우주와 주(主)우주","sum":"주(主) 우주는 파라다이스를 중심으로 하보나, 일곱 초우주, 그리고 네 외부 공간 수준까지 여섯 개의 동심 타원 공간 수준으로 이루어진 전체 창조계이다. 그 가운데 지금 조직되고 거주되는 부분, 곧 하보나와 일곱 초우주를 대우주라 한다. 외부 공간에서는 지금도 거대한 미래 창조가 형성되고 있으며, 완성된 대우주의 상승자들은 장차 그곳에서 봉사할 것으로 보인다.","sections":[{"h":"대우주와 주 우주의 구분","items":[{"x":"중앙의 신성한 우주와 그 둘레의 일곱 초우주를 합쳐 대우주라 부르며, 이것이 현재 조직되고 거주되는 창조계이다.","r":["0:0.6"]},{"x":"주 우주는 대우주에 더하여, 아직 사람이 살지 않고 체계를 갖추어 가는 외부 공간의 우주들까지 포함한다.","r":["0:0.6"]},{"x":"유란시아는 네바돈 지역 우주에, 네바돈은 일곱째 초우주 오르본톤에 속하며, 일곱 초우주는 중앙 우주 하보나 주위를 돈다.","r":["0:0.5","12:1.12"]},{"x":"대우주는 약 칠조 개의 거주 행성에 이르는 진화적 잠재력을 지니고 있으나, 그 들쭉날쭉한 가장자리는 아직 미완성이다.","r":["12:1.13"]},{"q":"창조된 존재들에게 주(主) 우주는 거의 무한하게 보일 수 있으나, 그것은 완성과는 거리가 멀다.","r":"12:0.3"}]},{"h":"여섯 공간 수준","items":[{"x":"주 우주는 무한 평면도 끝없는 원도 아니며, 분명한 차원과 한계를 지닌 하나의 조율된 공간 단위로 기능한다.","r":["12:1.1"]},{"x":"파라다이스에서 바깥으로 하보나, 일곱 초우주, 그리고 네 개의 외부 공간 수준이 동심 타원으로 놓여 있다.","r":["12:1.3","12:1.9"]},{"q":"영원한 섬을 둘러싸는 영원한 우주인 파라다이스-하보나 체계는 주(主) 우주의 완전하고 영원한 핵을 구성한다.","r":"12:1.11"},{"x":"공간 수준들 사이에는 비교적 고요한 지대가 있고, 연속된 수준들은 번갈아 반대 방향으로 돌아 중력 긴장을 고르게 한다.","r":["11:7.7","12:4.15"]},{"q":"중앙 우주는 영원의 창조이며, 일곱 초우주는 시간의 창조이다.","r":"12:1.16"},{"x":"네 외부 공간 수준은 창조의 궁극위성을 창발-진화시키도록 운명 지어져 있다.","r":["12:1.16"]}]},{"h":"외부 공간의 미래 창조","items":[{"x":"대우주 주변부 너머 약 오십만 광년에서 시작해 이천오백만 광년 넘게 뻗은 거대한 에너지 활동 지대가 첫째 외부 공간 수준이다.","r":["12:1.14"]},{"x":"일곱 초우주 바깥 공간은 대체로 무제한 절대자의 영역으로 여겨지며, 그곳의 에너지는 파라다이스 힘 조직자들이 변형한다.","r":["12:2.1","12:2.4"]},{"x":"외부 공간의 에너지와 물질은 이미 일곱 초우주 전체 질량의 여러 배에 이르지만, 그곳에는 알려진 물질 존재나 천사가 살지 않는다.","r":["12:2.4","12:2.5"]},{"x":"파라다이스 절대 중력의 약 95퍼센트는 현재 조직된 우주들의 경계 너머에 있는 물질 체계를 붙드는 데 쓰이고 있다.","r":["12:3.8"]},{"x":"영 인력은 거의 전부가 대우주에서 기능하므로 외부 우주들은 아직 비영적인 것으로 보이며, 마음 인력은 약 15퍼센트가 대우주 밖에서 작용한다.","r":["12:3.9","12:3.10"]},{"q":"미래의 더 큰 창조가 형성 과정에 있다.","r":"12:2.5"}]},{"h":"팽창하는 공간과 시간","items":[{"x":"충만한 모든 공간의 물리적 창조계는 이십억 년 주기의 공간 호흡에 따라 지금 바깥으로 균일하게 팽창하고 있다.","r":["12:4.12"]},{"x":"먼 우주들의 겉보기 후퇴 속도는 실제가 아니며, 관측 각도와 시공간 왜곡 같은 여러 오류 요인에서 비롯된다.","r":["12:4.14"]},{"x":"공간은 파라다이스에서 비롯되지만 무한하지 않으며, 시간과 공간은 오직 일곱 초우주의 시공간 창조계 안에서만 분리될 수 없다.","r":["12:5.2","12:5.3"]},{"q":"주(主) 우주 전체에서 하보나의 바로 그 중심, 중력의 중심인 영원한 파라다이스 섬을 제외하고는 절대적으로 아무것도 정지해 있지 않다.","r":"12:4.1"}]},{"h":"전체를 돌보는 손길","items":[{"x":"주 우주 전체의 필요는 잠재성에서는 절대자들에게, 방향에서는 궁극자에게, 진화적 조율에서는 최상자에게, 초기 행정에서는 주 우주 건축자들에게 의존한다.","r":["12:6.8","12:6.12"]},{"x":"아절대 건축자들이 계획을 세우고, 최상 창조자들이 그것을 존재하게 하며, 최상 존재가 그 충만함을 완성한다.","r":["106:3.1"]},{"x":"자비는 개인을 향한 하나님의 태도이고 공정성은 전체를 향한 태도이며, 하나님의 뜻은 결국 우주들의 우주 전체를 다스린다.","r":["12:7.1"]},{"x":"시간과 공간은 유한 창조체가 무한자와 함께 코스모스에 존재할 수 있게 해 주는 우주 기제이다.","r":["118:9.1"]},{"x":"외부 공간의 새로운 창조는 모여들고 있는 최종자 군단의 미래 활동 무대가 될 것이라고 믿어진다.","r":["12:2.6"]},{"x":"미래 시대에 일곱 초우주는 외부 공간 출신 존재들을 위한 중급 학교가 되고, 하보나는 최종 학교가 될 것으로 보인다.","r":["14:6.41"]},{"q":"주(主) 우주는 여전히 젊어 보일 것이며, 실로 끝없는 영원의 한계 없는 가능성 앞에서는 항상 젊을 것이다.","r":"106:7.8"}]}],"see":["하보나","일곱 초우주","파라다이스","궁극 하나님","최종자 군단","시간과 공간"],"n":13,"en":"Grand and Master Universe"},{"t":"도덕성","sum":"도덕성은 옳고 그름을 분별하고 수단뿐 아니라 목적의 가치까지 판단하는 인간 인격 고유의 능력으로, 사람을 동물과 구별 짓는다. 그것은 자의식의 이성에서 진화했으며, 법이나 힘이 아니라 인격적 선택과 감화로 자란다. 도덕은 종교의 전제 조건이지만 종교 체험의 전부는 아니며, 최상의 도덕적 선택은 하나님의 뜻을 행하기로 하는 것이다.","sections":[{"h":"인격에 깃든 도덕적 본성","items":[{"q":"지성만으로는 도덕적 본성을 설명할 수 없다. 도덕성, 즉 미덕은 인간 인격에 토착이다.","r":"16:7.1"},{"x":"사람은 탐사나 실험에 앞서 도덕적 통찰을 행사할 수 있으며, 오직 인격만이 행하기 전에 자기가 무엇을 하는지 안다.","r":["16:7.2","16:7.3"]},{"x":"지성은 수단을 고를 뿐이지만, 도덕적 존재는 목적 자체의 가치를 분별한다.","r":["16:7.4"]},{"x":"자기 분투의 목적을 분별하지 못하는 사람은 동물 수준에서 사는 것이며, 인격의 이점을 쓰지 못한 것이다.","r":["16:7.5"]},{"x":"아이의 첫 도덕적 선택은 일곱째 보조 마음 영에서 나타나며, 그것이 기록된 뒤에야 조절자가 배정된다.","r":["108:2.1"]}]},{"h":"미덕과 도덕적 선택","items":[{"q":"미덕은 의로움, 곧 코스모스와의 일치이다. 미덕들의 이름을 대는 것이 그것들을 정의하는 것이 아니요, 그것들을 사는 것이 그것들을 아는 것이다.","r":"16:7.6"},{"x":"선악의 선택은 도덕적 예리함뿐 아니라 무지와 미성숙, 망상의 영향을 받으므로, 비례 감각과 측정의 기술이 필요하다.","r":["16:7.7","16:7.8"]},{"x":"도덕적 행위란 더 높은 목적을 고르고 그 목적에 맞는 도덕적 수단을 고르는, 가장 높은 지성의 수행이다.","r":["16:7.10"]},{"q":"가장 높은 도덕적 선택은 가능한 가장 높은 가치의 선택이며, 어느 구체에서든, 모든 구체에서 언제나 이것은 하나님의 뜻을 행하기로 선택하는 것이다.","r":"39:4.14"}]},{"h":"도덕성의 진화","items":[{"x":"도덕성은 자의식의 이성에서 생겨났으며, 동물을 넘어서지만 전적으로 진화의 산물이다.","r":["5:5.1"]},{"x":"귀신을 달래려던 길고 낭비적인 투쟁을 거치며 사람은 상대적인 옳고 그름을 자각했고, 이로써 윤리가 태어났다.","r":["86:6.7","68:4.3"]},{"x":"초기의 의무감은 감정적 두려움에서 나왔지만, 이타적 봉사의 충동은 내주하는 신성한 영에게서 온다.","r":["103:5.1"]},{"q":"양심은 인간의 혼에게 말하는 신성한 음성이 아니다.","r":"92:2.6"},{"x":"정적인 윤리와 전통적 도덕은 동물 수준을 조금 넘을 뿐이며, 윤리는 역동적이고 진보할 때 참으로 인간다워진다.","r":["12:5.10"]}]},{"h":"도덕과 종교","items":[{"q":"도덕적 행위는 언제나 진화된 종교의 선행 조건이며 계시 종교에서조차 그 일부이지만, 결코 종교 체험의 전부는 아니다.","r":"5:5.4"},{"x":"진화 종교의 도덕은 두려움으로 사람을 밀어붙이지만, 계시 종교는 하나님처럼 되려는 사랑의 갈망으로 이끈다.","r":["5:4.1"]},{"x":"종교가 진화하면 윤리는 도덕의 철학이 되고, 도덕은 최상의 영적 이상에 따라 자아를 훈육하는 일이 된다.","r":["92:7.5"]},{"x":"진리와 아름다움을 떼어 놓은 채 고립된 도덕만 강조하는 종교는 현대인의 충성을 얻지 못한다.","r":["2:7.9"]},{"x":"예수는 윤리를 종교 자리에 두지 않고, 종교를 원인으로, 윤리를 결과로 가르쳤다.","r":["170:3.8"]}]},{"h":"도덕이 자라고 퍼지는 길","items":[{"q":"도덕성은 결코 법이나 힘으로 증진될 수 없다.","r":"16:7.9"},{"x":"도덕은 인격의 자유 의지에 달린 일이어서, 도덕적으로 향기로운 사람과의 접촉이라는 전염으로 퍼져야 한다.","r":["16:7.9"]},{"x":"예수는 황금률을 육체·감정·마음·형제 사랑·도덕·영의 수준으로 해석해, 가장 높게는 하나님처럼 사람을 대하라고 가르쳤다.","r":["147:4.3","147:4.8","147:4.9"]},{"x":"원시인의 이웃은 가까운 사람뿐이었지만, 예수는 이웃을 온 인류와 원수에게까지 넓혔고 사람의 마음은 그것이 옳다고 안다.","r":["103:5.2"]},{"x":"철학과 형제애의 시대에 사람들은 참으로 도덕적 존재가 되어 황금률에 따라 사는 법을 배운다.","r":["50:5.8"]}]}],"see":["선함","자유 의지","하나님의 뜻","종교 체험","지혜","죄"],"n":65,"en":"Morality"},{"t":"두려움과 걱정","sum":"두려움은 원시인을 사회로 묶고 종교의 첫 토양을 마련한 강력한 감정이었지만, 이성에 근거하지 않은 두려움과 걱정은 오늘날 혼의 진보를 가로막는 독이 된다. 계시 종교와 생각 조절자는 하나님에 대한 두려움을 사랑과 신뢰로 바꾸려 하며, 예수는 앞을 내다보는 신중함은 허락하되 걱정과 불안은 버리고 아버지를 신뢰하라고 가르쳤다. 그의 평화는 마음이 근심하지도 두려워하지도 않게 하는 평화이다.","sections":[{"h":"진화 속의 두려움","items":[{"x":"초기 인간은 불운에 대한 끊임없는 두려움 속에 살았으며, 그 두려움은 마비시키는 힘을 지녔다.","r":["86:1.3","86:1.4"]},{"x":"굶주림과 사랑이 사람을 모았다면, 허영심과 귀신에 대한 두려움이 원시 사회를 묶어 두었다.","r":["68:3.4","68:3.1"]},{"x":"생명의 신성함이 아니라 죽음의 충격이 불러일으킨 두려움이 원시 종교를 길러 냈다.","r":["86:3.1","87:1.1"]},{"x":"원시 종교의 거짓 두려움은 마음의 토양을 준비했고, 조절자들은 그 뒤로 두려움을 하나님에 대한 사랑으로 바꾸어 왔다.","r":["86:7.6"]},{"x":"진화 종교는 두려움으로 사람을 몰아가지만, 계시 종교는 하나님처럼 되려는 갈망으로 사랑의 하나님을 찾게 한다.","r":["5:4.1","101:0.1"]}]},{"h":"혼을 해치는 독","items":[{"q":"이성에 근거하지 않은 두려움은 진화하는 필사자 혼에게 가해지는 으뜸가는 지적 사기이다.","r":"48:7.4"},{"x":"두려움·분노·시기·의심 같은 마음의 독소는 육체의 독처럼 혼의 영적 진보를 크게 방해한다.","r":["110:1.5"]},{"x":"천사들이 사람에게서 가장 이해하기 어려워하는 감정은 신앙조차 공황에 빠뜨리는 동물적 공포의 유산이다.","r":["113:2.5"]},{"q":"“두려움은 사람을 얽매는 으뜸가는 것이고, 자만은 그의 큰 약점이다.","r":"142:0.2"},{"q":"“증오는 두려움의 그림자이며, 복수는 겁쟁이의 가면이다.”","r":"145:3.4"},{"q":"낙담, 걱정, 게으름은 도덕적 미성숙의 분명한 증거이다.","r":"160:1.6"}]},{"h":"예수가 가르친 걱정 없는 삶","items":[{"x":"예수는 앞날을 신중하게 내다보는 것은 금하지 않았으나, 걱정과 불안은 반대했다.","r":["140:8.3"]},{"x":"염려한다고 키 한 뼘이나 생명 하루를 더할 수 없으니, 까마귀도 먹이시는 아버지를 신뢰하라고 했다.","r":["165:5.2"]},{"x":"필요를 두고 지나치게 염려하지 말고, 기도와 감사로 그것을 아버지 앞에 펼쳐 놓으라고 권했다.","r":["146:2.16"]},{"x":"많은 일로 마음이 어지러운 마르다에게, 삶의 작은 일들은 왕국의 더 큰 일 앞에서 물러나야 한다고 일렀다.","r":["162:8.3"]},{"x":"사람들은 실제로는 안전에서 멀지 않은데도, 길 잃은 아이처럼 두려움에 울며 많은 시간을 보낸다.","r":["132:6.1"]},{"x":"산에서 쉬고 돌아온 사도들은 많은 급박한 문제가 과장된 두려움과 불안의 산물임을 깨달았다.","r":["143:3.6"]}]},{"h":"두려움을 이기는 길","items":[{"x":"예수는 두려움에 짓눌린 젊은이에게, 마음을 두려움의 노예가 아니라 문제를 푸는 용감한 동맹으로 삼으라고 했다.","r":["130:6.3"]},{"x":"내주하는 영을 두려움의 족쇄에서 풀어 주면, 하나님의 자녀라는 의식이 사람에 대한 두려움을 이기게 한다.","r":["130:6.3","130:6.4"]},{"q":"생각 조절자들은 너희의 두려움의 감정을 사랑과 신뢰의 확신으로 바꾸고 싶어 하지만, 그들은 기계적으로나 임의로 그렇게 할 수 없다.","r":"108:5.8"},{"x":"우주에서 홀로라는 두려움에서 오는 불안은 아버지에 대한 신앙의 사색과 예배의 휴식으로 풀어야 한다.","r":["143:7.3"]},{"x":"행복하고 효과적인 사람은 잘못에 대한 두려움이 아니라 옳은 일을 행하는 사랑에서 동기를 얻는다.","r":["140:4.6","140:5.6"]},{"x":"단순한 믿음은 의심과 두려움을 이기지 못할 수 있지만, 살아 있는 신앙은 언제나 의심을 극복한다.","r":["102:6.7"]}]},{"h":"두려움 없는 평화","items":[{"x":"예수는 두려움을 몰랐으며, 두려움 없이 삶의 현실에 직면하면서도 언제나 밝고 기뻤다.","r":["100:7.4","100:7.12"]},{"x":"예수의 평화는 소극적인 고요가 아니라 시련과 박해 속에서 마음이 근심하지도 두려워하지도 않게 하는 평화이다.","r":["140:5.18"]},{"q":"너희 심정이 근심하지 말고 두려워하지도 말라. 내가 세상을 이겼으니, 내 안에서 너희 모두가 신앙으로 승리할 것이다.","r":"181:1.5"},{"x":"모론시아 세계에서 상승자들은 불평 없이 도전을 받아들이고 두려움 없이 어려움과 불확실성에 맞서는 법을 배운다.","r":["48:6.35"]},{"x":"교사들은 모든 두려움을 내쫓는 하나님의 사랑을 선포하라는 권고를 받는다.","r":["48:6.8"]}]}],"see":["신앙","기쁨과 행복","역경과 시련","생각 조절자","사랑","제도 종교"],"n":69,"en":"Fear and Worry"},{"t":"루시퍼 반란","sum":"루시퍼 반란은 약 이십만 년 전 사타니아 체계의 주권자 루시퍼가 첫째 부관 사탄과 함께 일으킨 반역으로, 아버지의 실체와 미가엘의 주권, 상승 계획을 부정하는 ‘자유 선언’에서 시작되었다. 서른일곱 행성의 영주들이 가담했고 유란시아도 그중 하나였다. 반란은 자기 관조와 교만에서 나왔으며, 우주 통치자들은 모든 존재가 충분히 선택하도록 오래 기다렸고, 미가엘의 증여는 반란을 사실상 끝냈다.","sections":[{"h":"루시퍼와 반란의 기원","items":[{"x":"루시퍼는 상승 존재가 아니라 지역 우주에서 창조된 빛나는 아들이었으며, 607개 거주 세계를 둔 사타니아를 다스렸다.","r":["53:1.1","53:1.2"]},{"q":"자기 관조는 천상 세계 고귀한 인격들에게조차 가장 파멸적인 것이다.","r":"53:1.3"},{"x":"사타니아에는 반란을 부추긴 특별한 조건이 없었으며, 반역의 생각은 루시퍼 자신의 마음에서 비롯되었다.","r":["53:2.2","53:2.3"]},{"x":"자기기만에 이른 교만 속에서 그는 어느 순간 불성실해졌고, 악은 고의적인 죄로 변했다.","r":["53:2.5"]},{"x":"루시퍼는 유란시아에서 자기 대의를 첫째 부관 사탄에게 맡겼으며, 칼리가스티아가 이곳에서 그 편에 섰다.","r":["53:1.4","53:7.2"]}]},{"h":"루시퍼 자유 선언","items":[{"x":"루시퍼는 우주 아버지가 실재하지 않으며, 아들들이 통치를 유지하려고 만든 신화라고 주장했다.","r":["53:3.2"]},{"x":"그는 지역 체계의 자치를 요구하며 미가엘의 주권과 옛적부터 늘 계신 이들의 간섭을 폭정이라 공격했다.","r":["53:3.3","53:3.4"]},{"x":"그는 상승 필사자를 오래 훈련시키는 계획이 시간과 에너지의 낭비라고 비난했다.","r":["53:3.6"]},{"q":"자기 주장은 루시퍼 반란의 전투 구호였다.","r":"53:4.2"},{"x":"루시퍼는 정의의 자비로운 지연을 아들들의 정부가 무능하다는 증거로 내세웠다.","r":["53:4.5"]}]},{"h":"하늘의 전쟁과 그 손실","items":[{"x":"미가엘은 아직 증여를 마치지 않아 불간섭을 택했고, 가브리엘이 충성스러운 무리를 이끌었다.","r":["53:5.1","53:5.4"]},{"x":"하늘의 전쟁은 물리적 충돌이 아니었지만 영원한 생명을 걸었기에 훨씬 더 치명적이었다.","r":["53:5.6","53:5.7"]},{"x":"서른일곱 행성 영주가 반역에 가담했으며, 파놉티아에서만 백성이 영주를 따르지 않고 미가엘 편에 섰다.","r":["53:7.1"]},{"x":"천사 계층의 손실이 가장 컸으나, 파라다이스 기원의 존재와 삼위일체화된 아들들은 아무도 이탈하지 않았다.","r":["53:7.5","53:7.6","53:7.8"]},{"q":"예루셈에 거주하는 사타니아 상승 시민 가운데 단 한 명도 루시퍼 반란에 가담하지 않았다는 것이 상승 계획의 지혜의 영광으로 기록되어 있다.","r":"53:7.10"}]},{"h":"참된 자유와 거짓 자유","items":[{"x":"루시퍼 반란이 남긴 가장 큰 혼란은 참된 자유와 거짓 자유를 구별하지 못하는 데서 생겼다.","r":["54:1.1"]},{"q":"참된 자유는 자기 통제의 열매이며, 거짓 자유는 자기 주장의 전제이다.","r":"54:1.6"},{"x":"자유는 정의와 공정, 관용과 도덕적 의무, 영적 가치에서 떨어져 나가면 자멸적인 것이 된다.","r":["54:1.3","54:1.4"]},{"x":"루시퍼의 어리석음은 체험적 우주에서 시간을 단락시키려 한 데 있었다.","r":["54:2.3"]}]},{"h":"지연의 지혜와 반란의 종식","items":[{"q":"최상 정의는 아버지의 사랑에 지배되므로, 정의는 자비가 구원할 수 있는 어떤 것도 결코 파괴하지 않는다.","r":"54:5.3"},{"x":"자의적으로 진압했다면 적어도 세 배 많은 존재가 미혹되었을 것이라는 조언이 있었다.","r":["54:5.12"]},{"x":"미가엘은 반역자들에게 회개하면 용서와 봉사의 복귀를 제안했으나, 지도자 가운데 아무도 받아들이지 않았다.","r":["53:9.1"]},{"x":"미가엘의 증여는 사타니아 전역에서 반란을 끝냈고, 그 뒤 루시퍼는 옛적부터 늘 계신 이들에게 구금되었다.","r":["53:8.3","53:9.2"]},{"q":"신앙은 죄와 불법에 대한 효과적인 갑옷이다.","r":"53:8.8"},{"x":"멜기세덱들은 사타니아 반란에서 생긴 선이 모든 악을 합친 것보다 천 배 이상 많다고 가르친다.","r":["54:6.6"]}]}],"see":["칼리가스티아","자유 의지","죄","악","창조자 아들 미가엘","별자리와 지역 체계"],"n":76,"en":"Lucifer Rebellion"},{"t":"마음","sum":"마음은 셋째 근원이며 중심, 곧 무한 영에게서 비롯되어 일곱 주(主) 영과 지역 우주 어머니 영을 거쳐 창조체에게 증여되는 지성의 선물이다. 마음은 에너지와 영 사이에서 의미를 다루며, 물질을 다스리면서도 영의 인도에 반응한다. 사람에게 마음은 스스로 결정을 내리고 하나님을 택하거나 버리는 무대이므로, 그 마음을 어떻게 쓰느냐가 영원한 생존을 가른다.","sections":[{"h":"마음의 근원: 셋째 근원이며 중심","items":[{"x":"창조체 마음의 기원은 오직 셋째 근원이며 중심에 있으며, 그가 바로 마음의 증여자이다.","r":["9:5.2"]},{"x":"공동 행위자는 모든 마음에 인력을 행사하며, 참된 지적 가치와 신성한 생각은 모두 절대 마음 회로로 이끌린다.","r":["9:6.1","9:6.2"]},{"x":"사람의 마음은 무한 영의 창조적 딸이 지역 우주에 증여한 우주 마음의 개별화된 회로이자 비인격적 일부이다.","r":["9:5.4"]},{"q":"공동 창조자는 마음의 근원이지만, 마음은 곧 공동 창조자가 아니다.","r":"9:5.5"},{"x":"마음은 파라다이스에서 절대적, 하보나에서 아절대, 오르본톤에서 유한하지만, 모든 수준이 공동 행위자의 마음-인력에 덮여 있다.","r":["42:10.7"]}]},{"h":"마음의 여러 수준과 우주 마음","items":[{"x":"전(前)보조 영 마음은 체험하지 못하는 기계적 마음으로, 주(主) 물리적 통제자들이 사역한다.","r":["42:10.3"]},{"x":"보조 영 마음은 어머니 영이 일곱 보조 마음-영으로 사역하는 가르칠 수 있는 수준이며, 여기서 마음은 비로소 체험한다.","r":["42:10.4"]},{"x":"모론시아 마음은 상승 생애에 있는 인격들의 확장되는 의식으로, 570 수준의 모론시아 생명에 맞추어 차등적으로 기능한다.","r":["42:10.5"]},{"x":"일곱 주(主) 영은 우주 마음의 칠중 근원으로, 각자 한 초우주에 마음을 분배하며 네바돈은 그 오르본톤형 변형으로 채워져 있다.","r":["9:4.3","16:6.1"]},{"x":"우주 마음은 인과(과학), 의무(도덕), 예배(종교)라는 세 실체 수준에 틀림없이 반응하며, 이것이 반성적 사고의 바탕이 된다.","r":["16:6.6","16:6.7","16:6.8"]},{"x":"에너지는 사물이고 마음은 의미이며 영은 가치이니, 마음은 시공간에서 에너지와 영 사이에 관계를 세운다.","r":["9:4.5"]}]},{"h":"물질과 영 사이에서 일하는 마음","items":[{"q":"마음은 영의 가치들을 지성의 의미들로 변환시키며, 의지는 마음의 의미들을 물질적 및 영적 영역에서 열매 맺게 하는 권능을 지닌다.","r":"9:4.6"},{"q":"영은 건축가이고 마음은 건설자이며 몸은 물질적 건물이다.","r":"42:12.12"},{"x":"마음은 언제나 창조적이어서, 우주 마음과 보조 마음-영의 연락이 진화하는 인간에게 알맞은 몸을 빚어낸다.","r":["42:12.9","42:12.11"]},{"x":"우주는 마음이 계획하고 만들고 관리하지만, 낮은 마음은 우주 기제 속에 숨은 창조적 영-마음을 분별하지 못한다.","r":["42:11.2","42:11.8"]},{"q":"마음은 보편적으로 물질을 지배하며, 마음 또한 영의 궁극적 상위통제에 반응한다.","r":"42:12.15"}]},{"h":"인간의 마음: 동물적 뿌리와 도덕적 통찰","items":[{"x":"인간 지성은 동물 종족의 물질적 기원에 뿌리를 두므로, 마음의 모든 현상을 신성하다고 여겨서는 안 된다.","r":["9:5.5"]},{"q":"마음은 참으로 신성한 기원을 지니고 있으며, 실제로 신성한 운명을 향해 나아가지만, 너희의 필사 마음은 아직 신성한 존엄에 이르지 못했다.","r":"9:5.6"},{"x":"사람은 불성실과 불의, 동물적 공포와 쓸데없는 근심으로 마음을 더럽히므로, 미성숙한 지성 앞에서는 겸손해야 한다.","r":["9:5.7"]},{"x":"인격만이 행하기 전에 무엇을 하는지 알며, 사람은 실험에 앞서 과학적·도덕적·영적 통찰을 행사할 수 있다.","r":["16:7.2","16:7.3"]},{"x":"이 타고난 우주적 통찰을 날카롭게 하는 것이 교육이요, 고귀하게 하는 것이 종교이며, 통일하는 것이 인격의 목적이다.","r":["16:6.11"]}]},{"h":"선택의 무대인 마음","items":[{"q":"물질 마음은 인간 인격이 살고 자의식을 지니며, 결정을 내리고 하나님을 택하거나 버리며, 스스로를 영원하게 만들거나 파멸시키는 무대이다.","r":"111:1.3"},{"x":"마음은 물질 일생 동안 빌려준 일시적 지적 체계이며, 그것을 쓰는 방식에 따라 영원한 실존의 잠재성을 받아들이거나 물리친다.","r":["111:1.5"]},{"x":"마음이 무엇을 이해하느냐보다 무엇을 이해하기 원하느냐, 무엇과 같아지려 하느냐가 생존과 영의 동일화를 이룬다.","r":["111:1.5"]},{"x":"마음은 의지에 따라 파괴의 불협화음을 낼 수도, 하나님과 동일화되는 절묘한 선율을 낼 수도 있는 우주적 악기이다.","r":["111:1.6"]},{"q":"마음은 너희의 배요, 조절자는 항해사, 인간의 의지는 선장이다.","r":"111:1.9"},{"x":"인격적 마음이라도 영과 동일화되지 않으면 생존 특성이 없으며, 예배하고 생존을 갈망할 능력이 없을 때 그것은 불멸이 아니다.","r":["36:5.17"]}]}],"see":["우주 마음","보조 마음 영","무한 영","인격","자유 의지","혼"],"n":37,"en":"Mind"},{"t":"마키벤타 멜기세덱","sum":"마키벤타 멜기세덱은 아담의 실패 뒤 한 분 하나님에 대한 진리가 꺼져 가던 때, 예수 탄생 1,973년 전 팔레스타인 살렘에 비상 아들로 육신화한 멜기세덱이다. 그는 구십사 년 동안 엘 엘리온, 곧 지고자를 믿는 신앙만으로 하나님의 은총을 받는다는 언약을 가르쳤고, 아브라함을 통해 그 진리를 이어 가게 했다. 그는 미가엘의 증여를 위한 길을 닦았으며, 지금은 유란시아의 대리 통치 행성 영주로 불린다.","sections":[{"h":"비상 아들의 육신화","items":[{"x":"아담의 사명이 실패한 뒤 수천 년 동안 계시된 진리는 꺼질 위기에 처했고, 기원전 3000년경 하나님 개념은 매우 흐려졌다.","r":["93:1.1"]},{"x":"열두 행성 접수자 가운데 마키벤타가 자원해, 네바돈 역사에서 여섯 번뿐이었던 비상 아들의 육신화를 이루었다.","r":["93:1.3"]},{"q":"마키벤타가 유란시아의 인류에게 증여된 것은 예수의 탄생 1,973년 전이었다.","r":"93:2.1"},{"x":"그는 목자 암돈의 장막에 나타나 처음으로 물질 음식을 먹었고, 그날 밤 하나님 실재의 진리를 계시하기 시작했다.","r":["93:2.1","93:2.2","93:2.3"]},{"x":"그는 생각 조절자를 받았으나 결혼하지 않았고 자손을 남길 수 없었으며, 100인 참모진과 같은 유형의 몸을 지녔다.","r":["93:2.6","93:2.7"]}]},{"h":"살렘의 가르침","items":[{"x":"그는 셋족 사제들의 교육 체제를 본떠 살렘에 학교를 세웠고, ‘엘 엘리온의 사제’, ‘살렘의 현자’로 알려졌다.","r":["93:2.4","93:3.1"]},{"q":"나는 엘 엘리온, 지고자 하나님, 만물의 유일한 우주 아버지요 창조주를 믿는다.","r":"93:4.2"},{"x":"살렘의 신조는 지고자를 믿고, 제물이 아닌 신앙에 은총을 베푸신다는 언약을 받아들이며, 일곱 계명을 지키는 것이었다.","r":["93:4.3","93:4.4","93:4.5"]},{"q":"신앙이 영원한 구원의 유일한 조건임을 의심하지 말라.","r":"93:4.8"},{"x":"그는 살렘에서 희생을 허용하지 않고, 피의 제사 대신 떡과 포도주의 성례를 제시했다.","r":["93:4.14"]},{"x":"세 동심원 휘장은 낙원 삼위일체를 상징했으나, 대부분은 사람·천사·하나님의 세 왕국으로 이해했다.","r":["93:3.3"]}]},{"h":"아브라함과의 언약","items":[{"x":"멜기세덱 접수자들은 아브라함의 조상들을 오래 관찰했고, 테라의 가족은 그 기대를 충족시켰다.","r":["93:5.3","93:5.4"]},{"x":"왕이 되려는 야망을 품었던 아브라함은 멜기세덱의 만류 속에서도 싯딤 전투에서 이긴 뒤 십일조를 바쳤다.","r":["93:5.9","93:5.13"]},{"q":"이 언약에서 하나님은 모든 일을 행하기로 약속하고, 사람은 오직 하나님의 약속을 믿고 그의 지시를 따르기로 동의한다.","r":"93:6.4"},{"x":"멜기세덱은 구원이 신앙으로 얻어진다는 소식을 다시 전했지만, 셈족 부족들은 피의 희생 제도로 되돌아갔다.","r":["93:6.4"]},{"x":"아브라함이 개인적 야망을 공개적으로 포기한 뒤 언약은 완성되었고, 살렘 형제단에는 십만 명이 넘는 이들이 올랐다.","r":["93:6.7","93:6.8"]}]},{"h":"사명의 목적과 퍼짐","items":[{"q":"그는 두 가지 과업을 이루기 위해 왔다. 지상에서 한 분 하나님의 진리를 살아 있게 하는 것과, 그 우주 아버지의 파라다이스 아들이 훗날 필사자로 증여될 길을 예비하는 것이었다.","r":"93:4.15"},{"x":"그는 또 다른 하나님의 아들이 여인에게서 태어나 올 것이라고 가르쳤다.","r":["93:3.7"]},{"x":"살렘 선교사들은 이집트, 메소포타미아, 소아시아를 넘어 유럽과 영국 제도에까지 나아갔다.","r":["93:7.1","93:7.2"]},{"x":"미가엘은 지상에 나타나 멜기세덱이 파라다이스 아버지에 관해 가르친 모든 것을 확증했다.","r":["93:3.8"]},{"x":"멜기세덱의 가르침을 잃어버렸기에, 미가엘이 육신으로 왔을 때 그를 알아본 이가 거의 없었다.","r":["93:9.10"]}]},{"h":"떠남과 그 뒤의 행보","items":[{"x":"사람들이 그를 반신으로 여기며 미신적으로 경외하기 시작하자, 그는 소돔과 고모라의 파괴 직후 갑자기 떠났다.","r":["93:8.1"]},{"x":"그의 사라짐은 아브라함에게 평생 극복하지 못한 슬픔을 남겼다.","r":["93:9.1","93:9.2"]},{"x":"구약에서 아브라함과 하나님의 대화로 묘사된 내용은 실제로 아브라함과 멜기세덱의 회의였다.","r":["93:9.7"]},{"x":"그는 열아홉 세기 동안 선지자들과 협력해 살렘의 진리를 보존했고, 지금은 유란시아의 대리 통치 행성 영주로 불린다.","r":["93:10.4","93:10.7"]},{"q":"이것은 마키벤타 멜기세덱의 이야기로서, 그는 유란시아의 역사와 관련을 맺은 모든 인물 가운데 가장 독특한 하나이며,","r":"93:10.11"}]}],"see":["멜기세덱","계시","신앙","유란시아","예수의 증여","아담과 이브"],"n":79,"en":"Machiventa Melchizedek"},{"t":"맨션 세계","sum":"맨션 세계는 지역 체계 수도 예루셈을 둘러싼 일곱 전환 세계로, 예수가 말한 ‘아버지의 집에 있는 많은 맨션’에 해당한다. 죽음 뒤 생존한 필사자는 첫째 맨션 세계의 부활 전당에서 깨어나, 지상에서 못다 이룬 결핍을 보충하고 일곱 세계를 차례로 거치며 점점 덜 필사적이고 더 모론시아적인 존재가 된다. 이곳은 물질 생애와 영 생애를 잇는 첫 상승 학교이다.","sections":[{"h":"일곱 맨션 세계란","items":[{"x":"예수가 말한 ‘많은 맨션’은 예루셈을 둘러싼 첫째 전환 세계의 일곱 위성을 특히 가리킨다.","r":["47:0.1"]},{"x":"맨션 세계들은 모론시아 감독자와 멜기세덱들이 책임지며, 각 세계에 총독 대행과 여러 봉사 집단의 본부가 있다.","r":["47:0.4"]},{"x":"체계가 빛과 생명에 정착하면 맨션 세계들은 차례로 훈련소 구실을 그치고 최종자들이 넘겨받는다.","r":["47:0.3"]},{"x":"일곱 세계는 사실상 탈필사화 구체여서, 첫째 세계에서는 대체로 인간이지만 졸업할 무렵에는 모론시아인에 가까워진다.","r":["47:9.5"]}]},{"h":"첫째 맨션 세계의 깨어남","items":[{"x":"첫째 맨션 세계 한가운데에는 인격 조립의 사원인 부활 전당이 있어, 수호 세라핌과 조절자와 천사장들이 함께 일한다.","r":["47:3.2"]},{"x":"세라핌이 맡은 모론시아 혼과 조절자가 지닌 영-마음이 다시 결합하여 잠자는 생존자가 부활한다.","r":["47:3.3"]},{"q":"너희는 여기 아래에서 그만둔 바로 그 자리에서 저기서 시작한다.","r":"47:3.7"},{"x":"부활한 이는 열흘간의 자유를 얻어 새 거처를 살피고 먼저 온 사랑하는 이들을 찾아볼 수 있다.","r":["47:3.6"]},{"x":"모론시아 동반자들이 상승자들의 다정한 벗이자 안내자로 배정된다.","r":["47:3.11","47:3.12"]},{"q":"부활한 필사 생존자들은 맨션 세계에서 죽음이 덮쳤을 때 멈춘 바로 그 자리에서 삶을 이어 간다.","r":"47:3.1"}]},{"h":"결핍을 보충하는 교정의 세계","items":[{"x":"첫째 맨션 세계의 체험은 거의 모두 육신 생애에서 생긴 성품의 결함과 체험의 결핍을 바로잡는 데 집중된다.","r":["47:3.8"]},{"x":"어떤 상승자도 자녀를 기르는 체험을 피할 수 없으며, 아버지도 어머니만큼 이 체험을 거쳐야 한다.","r":["47:1.6"]},{"q":"아이들은 어머니만큼 아버지를 필요로 하며, 아버지 또한 어머니만큼 이 부모 체험을 필요로 한다.","r":"47:1.6"},{"x":"둘째 맨션 세계는 지성적 갈등을 없애고 온갖 정신적 부조화를 치유하는 데 힘쓴다.","r":["47:4.8"]},{"x":"처음 두 세계가 결핍을 보충하는 소극적 훈련이라면, 셋째 세계부터 참으로 진보적인 모론시아 문화가 시작된다.","r":["47:5.3"]}]},{"h":"세계에서 세계로","items":[{"x":"세계를 옮길 때마다 수면에 들었다가 새 모론시아 몸으로 깨어나지만, 이때는 조절자가 떠나지 않는다.","r":["47:4.4"]},{"x":"생존 가치가 있는 기억은 조절자가 대응물을 만들어 두어 상승 생애 내내 간직된다.","r":["47:4.5"]},{"x":"모론시아 몸으로도 먹고 마시고 쉬지만, 그 음식은 남는 찌꺼기 없이 완전히 활용된다.","r":["47:4.6"]},{"x":"넷째 세계에서는 이기적 정복이 아니라 상호 감상과 이타적 봉사에 바탕한 참된 사회 생활을 처음 배운다.","r":["47:6.3"]},{"q":"우주 의식의 참된 탄생이 다섯째 맨션 세계에서 일어난다.","r":"47:7.5"},{"x":"다섯째나 여섯째 세계에서 조절자와의 융합이 실제로 이루어지는 경우가 많고, “이는 내가 기뻐하는 사랑하는 아들이다”라는 선언이 따른다.","r":["47:8.3","47:8.4"]},{"q":"새로 발달되고 알맞게 조정된 모론시아 몸은 한 맨션 세계에서 다른 맨션 세계로 나아갈 때마다 얻게 된다.","r":"47:4.4"}]},{"h":"예루셈 시민으로","items":[{"x":"일곱째 맨션 세계에서는 불행한 유전과 건전하지 못한 환경의 잔재가 깨끗이 씻겨 출신 세계의 차이가 사라진다.","r":["47:9.1"]},{"x":"일곱째 세계에서 아버지의 세계를 방문하여 보이지 않는 아버지에 대한 더 영적인 예배를 시작한다.","r":["47:9.2"]},{"x":"졸업생들은 집단으로 유리 바다에서 배웅을 받으며 예루셈 시민으로 환영받는다.","r":["47:9.4","47:10.1"]},{"x":"맨션 세계 전체를 거치는 이는 조정 수면과 부활의 깨어남을 일곱 번 체험하며, 그 뒤로는 의식이 끊기지 않는다.","r":["47:10.5"]},{"q":"필사자의 죽음은 육신의 물질적 생명에서 벗어나는 기법이다.","r":"47:10.7"}]}],"see":["모론시아","죽음","생존","필사자의 상승 여정","조절자 융합","별자리와 지역 체계"],"n":44,"en":"Mansion Worlds"},{"t":"멜기세덱","sum":"멜기세덱 아들들은 창조자 아들과 어머니 영, 그리고 아버지 멜기세덱이 함께 낳은 지역 우주의 맏아들 계층이다. 높은 신성과 가장 낮은 창조체 생명의 중간에 서 있어서 육신화하지 않고도 진화 종족을 섬길 수 있으며, 우주의 교사이자 자치의 본보기, 어떤 위기에도 먼저 달려가는 비상 아들로 일한다. 상승 필사자들은 맨션 세계에서 샐빙턴의 멜기세덱 대학에 이르기까지 줄곧 이들의 가르침을 받는다.","sections":[{"h":"지역 우주의 맏아들","items":[{"x":"창조자 아들과 창조 영의 새로운 창조적 연합에서 아버지 멜기세덱이 먼저 나왔고, 그가 두 창조자와 협력해 이 계층 전체를 존재하게 했다.","r":["35:1.1","20:1.10"]},{"x":"네바돈의 멜기세덱들은 표준 시간 천 년 안에 모두 창조되었으며, 수가 늘지 않는 계층으로 그 수는 천만을 넘는다.","r":["35:1.3","35:2.9"]},{"q":"이 아들들은 천성적으로 위대한 인격 하강의 중간점에 있으며,","r":"35:2.1"},{"x":"그래서 이들은 높은 신성한 실존과 물질적 생명 사이의 자연스러운 매개자가 되고, 모든 지성적 생명체에게 친구이자 교사, 조언자가 된다.","r":["35:2.1"]},{"x":"아버지 멜기세덱은 가브리엘의 첫째 집행 동료로서 비상 위원회들을 주재하며, 가브리엘이 없을 때 네바돈의 최고 집행자로 기능한다.","r":["35:1.2"]}]},{"h":"자치와 신뢰의 계층","items":[{"x":"멜기세덱들은 스스로 행정 우두머리를 선출하는 자율 계층으로, 지역 우주 존재들이 자기 결정을 시도한 첫 사례이다.","r":["35:1.3","35:2.2"]},{"q":"오르본톤 초우주 전체를 통틀어 이 멜기세덱 아들들은 신뢰를 배신한 적이 단 한 번도 없었다.","r":"35:2.2"},{"x":"이들은 스스로 우주를 순찰하며 정규 기관과 별도로 창조자 아들에게 보고하고, 세계들을 순회하는 자문 재심 법정으로도 기능한다.","r":["35:2.3","35:2.4"]},{"q":"멜기세덱은 지혜가 거의 완벽하지만, 판단에 있어서는 무오하지는 않다.","r":"35:2.8"},{"x":"루시퍼 반란 때 멜기세덱들은 모두 미가엘에게 충성했으며, 파놉티아에서는 이들의 지도로 주민 전체가 미가엘 편에 섰다.","r":["53:7.4","53:7.1"]}]},{"h":"우주의 교사","items":[{"x":"샐빙턴 회로의 인도 세계인 멜기세덱 구체와 그 부속 세계들은 멜기세덱 대학이라 불리며, 모든 상승 필사자가 이곳의 훈련을 거친다.","r":["35:3.1"]},{"q":"한 상승자에게 이 세계는 아마도 온 네바돈에서 가장 흥미로운 장소일 것이다.","r":"35:3.11"},{"x":"상승 필사자들의 진보적인 모론시아 생애 교육은 삼위일체 교사 아들들과 연계하여 멜기세덱의 총괄 감독 아래 이루어진다.","r":["35:4.1"]},{"x":"멜기세덱들은 맨션 세계의 큰 교사 군단을 이끌며, 육신의 생애에서 이루지 못한 혼의 성취를 그곳에서 계속하도록 돕는다.","r":["45:7.1"]},{"x":"예루셈에서는 서른 개가 넘는 교육 센터를 운영하며, 대의 정부를 맡을 상승 필사자들을 행정 학교에서 길러 낸다.","r":["45:7.3","45:7.4"]},{"q":"대의 정부는 완전하지 않은 존재들 사이에서 자치의 신성한 이상이다.","r":"45:7.3"}]},{"h":"비상 아들","items":[{"q":"언제 어디서든 특별한 도움이 필요한 곳에는 반드시 하나 이상의 멜기세덱 아들이 있을 것이다.","r":"35:4.2"},{"x":"이들은 어떤 비상사태에서든 가장 먼저 행동하며, 탈선한 행성의 임시 관리인이나 직무를 저버린 행성 정부의 수탁자가 되기도 한다.","r":["35:4.4"]},{"x":"네바돈에서 멜기세덱이 필사 육체의 모습으로 진화 세계를 섬긴 일이 일곱 번 있었으며, 아브라함 시대 살렘의 멜기세덱도 그중 하나이다.","r":["35:4.4","35:4.5"]},{"x":"아보날 아들이 증여에 나설 때는 열두 멜기세덱이 후원자로 동행하고, 치안 임무에서도 아보날을 돕는다.","r":["35:2.6"]},{"x":"멜기세덱들은 생명 운반자들과 협력해 새 세계의 생명 계획을 검토하고, 멜기세덱 우두머리가 종종 창조자 아들을 대표한다.","r":["36:2.12"]}]},{"h":"유란시아와 멜기세덱","items":[{"x":"행성 영주의 반역 이후 유란시아는 오랫동안 열두 멜기세덱으로 이루어진 행성 수탁자 평의회가 관리했다.","r":["67:6.5","67:6.6"]},{"x":"멜기세덱 수탁자들은 아담 부부에게 반역 영주의 위험을 경고했고, 아담이 온 지 약 칠 년 뒤에 세계 행정을 그에게 넘겼다.","r":["51:3.4","74:5.1"]},{"x":"미가엘의 첫째 증여에서 그는 낯선 멜기세덱 아들로 나타나 이 계층의 비상 봉사에 함께했다.","r":["119:1.3","119:1.6"]},{"q":"보편적 동의로 그는 멜기세덱들의 우두머리가 되었으니,","r":"119:1.5"},{"x":"멜기세덱들은 앞으로도 기원 우주에 남아 지역 우주 통치와 행정에서 점점 더 중요한 역할을 맡을 운명이라고 믿어진다.","r":["55:10.11"]}]}],"see":["마키벤타 멜기세덱","창조자 아들 미가엘","지역 우주 어머니 영","아보날 아들","맨션 세계","지역 우주 네바돈"],"n":24,"en":"Melchizedeks"},{"t":"모론시아","sum":"모론시아는 물질적인 것과 영적인 것 사이에 놓인 광대한 중간 수준이다. 하나님은 동물 기원의 필사자를 한 걸음에 완전한 영으로 바꾸지 않으시므로, 생존한 인간은 지역 우주의 여러 모론시아 세계를 거치며 수백 번의 점진적 변형을 통해 영의 문턱에 이른다. 모론시아 생명은 지상에서 혼이 잉태될 때 이미 시작되며, 그 철학적 통찰을 ‘모타’라 부른다.","sections":[{"h":"물질과 영 사이의 수준","items":[{"q":"모론시아의 날실은 영적이고, 그 씨실은 물리적이다.","r":"0:5.12"},{"x":"모론시아는 인격적이거나 비인격적일 수 있고, 생명이 있거나 없는 에너지일 수도 있는 넓은 실체 수준이다.","r":["0:5.12"]},{"x":"모론시아 세계들은 백 가지 물리적 원소에 더해 모론시아 물질이라는 백 가지 에너지 조직을 갖춘 건축 구체이다.","r":["48:1.3"]},{"x":"바울이 말한 ‘더 좋고 영속하는 실체’처럼 모론시아 물질은 실재하며 문자 그대로이다.","r":["48:1.7"]},{"x":"모론시아 마음은 물질적 마음과 영적 마음이 협력하는 이중 마음으로, 하나의 의지가 이를 다스린다.","r":["110:2.6"]}]},{"h":"왜 모론시아 단계가 필요한가","items":[{"x":"신들은 동물 기원의 창조체를 신비로운 마법으로 단번에 완전한 영으로 바꾸지 않는다.","r":["48:0.1"]},{"x":"죽음이라는 한 걸음이 필사적 마음을 즉시 완전한 영으로 바꾼다는 믿음은 무지한 미신이다.","r":["48:0.2"]},{"x":"필사 상태와 영 지위 사이에는 언제나 모론시아 전환이 끼어 있으며, 그 목적은 모든 지역 창조계에서 비슷하다.","r":["48:0.3"]},{"x":"모론시아 생애는 진화적 물질 실존과 더 높은 영 달성 사이의 전환 생명이다.","r":["47:10.7"]},{"q":"그러한 믿음은 무지한 미신이며 듣기 좋은 우화에 지나지 않는다.","r":"48:0.2"}]},{"h":"모론시아 몸과 점진적 변형","items":[{"x":"모론시아 동력 감독자들은 네바돈의 모론시아 생애 동안 570개의 모론시아 몸을 잇달아 제공한다.","r":["48:1.5"]},{"x":"필사 시절에는 영이 거의 별개의 것처럼 내주하지만, 모론시아 생명에서는 영이 인격의 실제적인 일부가 된다.","r":["48:1.6"]},{"x":"이른 모론시아 생명은 물질 세계와 비슷하지만, 별자리와 샐빙턴으로 갈수록 더 영적인 수준이 된다.","r":["48:1.4"]},{"x":"부활하신 예수가 지녔던 몸도 모론시아 몸으로, 피가 돌지 않고 물질 음식을 먹지 않지만 실재한다.","r":["190:0.3"]}]},{"h":"모론시아 생명을 돕는 이들","items":[{"x":"모론시아 동반자는 지역 우주 어머니 영의 자손으로, 상승자의 다정한 벗이자 안내자이며 통역자이다.","r":["48:3.1","48:3.5","48:3.12"]},{"x":"맨션 세계 교사들은 세라핌에게서 남겨진 체루빔과 사노빔으로, 생각·감정·행함의 학교를 이끈다.","r":["48:5.1","48:5.6"]},{"q":"파라다이스에 이르는 왕도도, 지름길도, 쉬운 길도 없다.","r":"48:5.7"},{"x":"모론시아 생애는 미루는 버릇, 불성실, 문제 회피 같은 동물적 잔재를 영원히 뿌리 뽑으려 한다.","r":["48:5.8"]},{"x":"전환 세라핌은 진로 선택을 돕되 해가 되지 않는 한 상승자의 자유 의지 선택을 존중한다.","r":["48:6.5","48:6.6"]},{"q":"어떠한 선한 행위도 결코 온전히 사라지지 않는다.","r":"48:6.7"}]},{"h":"모타와 모론시아 진보자","items":[{"x":"모타는 철학보다 우월한 통찰로서, 두 눈이 한 눈에 대해 그렇듯 의미와 가치에 입체적 깊이를 준다.","r":["48:6.28"]},{"x":"첫째 맨션 세계에서는 모타 개념과 그에 상응하는 인간 철학의 진술을 나란히 놓고 가르친다.","r":["48:7.1"]},{"q":"진화하는 혼은 무엇을 행하느냐가 아니라 무엇을 행하려고 애쓰느냐로 신성해진다.","r":"48:7.24"},{"x":"모론시아 생명은 지상에서 조절자가 내주하여 혼이 잉태되는 순간 실제로 시작된다.","r":["48:6.2"]},{"x":"맨션 세계를 졸업한 뒤 영 지위를 얻기까지 상승자는 모론시아 진보자라 불린다.","r":["48:8.1"]},{"x":"이 긴 훈련의 목적은 단지 영원한 안락이 아니라 미래 시대의 초월적 봉사를 준비하는 데 있다.","r":["48:8.3"]},{"q":"모타는 우월한 철학 이상이다.","r":"48:6.28"}]}],"see":["맨션 세계","혼","필사자의 상승 여정","죽음","예수의 부활","철학"],"n":45,"en":"Morontia"},{"t":"무한 영","sum":"무한 영은 아버지와 아들이 하나의 연합된 행동을 품은 순간 존재하게 된 신의 셋째 개인, 곧 공동 행위자이자 공동 창조자이다. 그는 아버지-아들 동반자 관계의 집행자로서 마음의 근원이며 에너지의 조종자이고, 아버지의 사랑과 아들의 자비를 모든 창조체에게 베푸는 어디에나 계신 영이다. 그의 수많은 영 자녀들은 필사자가 파라다이스로 오르는 살아 있는 사다리가 된다.","sections":[{"h":"행동의 하나님","items":[{"x":"아버지와 아들이 하나의 무한한 행동, 곧 절대적 생각-계획의 실행을 함께 품은 바로 그 순간 무한 영이 완전한 모습으로 존재하게 된다.","r":["8:0.3"]},{"x":"이런 기원 순서는 인간의 이해를 돕기 위한 설명일 뿐이며, 세 분은 모두 시작도 끝도 없이 영원부터 존재한다.","r":["8:0.4"]},{"x":"무한 영은 아버지께 영원한 충성을 맹세하고 아들께 영원한 의존을 인정했으며, 이로써 파라다이스 삼위일체가 존재하게 되었다.","r":["8:1.2","8:1.3"]},{"x":"무한 영은 중앙 우주 하보나의 탄생과 함께 영원하게 되었고, 이 공동 창조 행위를 통해 영원한 공동 창조자가 되었다.","r":["8:1.7"]},{"q":"무한 영은 그가 영원하므로 중앙 우주도 영원하다고 증언한다.","r":"8:1.9"}]},{"h":"본질과 위치","items":[{"x":"그는 우주 영, 공동 창조자, 무한 마음, 영들의 영, 공동 행위자 등 많은 이름으로 불리며, 유란시아에서는 때로 우주 마음과 혼동된다.","r":["8:2.2"]},{"x":"무한 영은 아버지의 완전함과 의로움과 사랑을 공유하되 영원 아들의 자비 쪽으로 기울어, 파라다이스 신들의 자비 사역자가 된다.","r":["8:2.6"]},{"x":"셋째 근원이 인격화된 뒤 아버지는 몸소 우주 창조에 참여하지 않으시고, 가능한 모든 것을 아들에게, 아들은 다시 공동 창조자에게 맡기신다.","r":["8:3.2"]},{"q":"영원 아들은 우주 아버지께 나아가는 유일한 길이며, 무한 영은 영원 아들에게 도달하는 유일한 수단이다.","r":"8:3.7"},{"x":"만물의 중심에서 상승하는 순례자가 맨 처음 도달하는 파라다이스 신이 바로 무한 영이다.","r":["8:3.8"]}]},{"h":"사역하는 영","items":[{"q":"하나님은 사랑이시고, 아들은 자비이시며, 영은 사역이시다.","r":"8:4.2"},{"x":"지역 우주에서는 창조적 딸인 어머니 영을 통해 창조자 아들과 함께 물질 창조체들의 영적 상승을 육성한다.","r":["8:4.4"]},{"x":"영은 육신을 입고 내려오지는 않지만 일련의 신성 약화를 기쁘게 겪어, 마침내 천사로 우리 곁에 서서 땅의 길을 인도한다.","r":["8:4.5"]},{"x":"우리 우주는 정의의 모루와 고난의 망치 사이에서 빚어지지만, 그 망치를 드는 이들은 무한 영의 자녀인 자비의 존재들이다.","r":["9:1.8"]},{"x":"무한 영의 영 인격들은 필사 인간이 혼돈에서 영광으로 오르는 살아 있는 사다리를 이룬다.","r":["9:8.25"]}]},{"h":"어디에나 계신 하나님의 영","items":[{"x":"무한 영의 가장 뛰어난 속성은 전재이며, 그는 아버지의 전지를 공유하지만 오직 마음의 영역에서만 전능하다.","r":["8:5.1","9:1.5"]},{"x":"성령은 무한 영의 창조적 딸이 각 지역 우주에 펼치는 고유한 영적 회로이며, 무한 영 자신은 어디에나 계신다.","r":["8:5.3"]},{"q":"많은 영적 영향들이 존재하지만, 그들은 모두 하나와 같다.","r":"8:5.4"},{"x":"조절자, 영원 아들의 영, 무한 영의 현존은 기원이 달라도 사람의 마음과 혼 안에서 완전히 협력하여 하나의 영처럼 일한다.","r":["8:5.4","9:2.5"]}]},{"h":"에너지 조종자와 절대 마음","items":[{"x":"공동 창조자는 에너지 자체가 아니라 에너지의 조종자이며, 아버지나 아들에게서는 관찰되지 않는 반중력의 권능을 지닌다.","r":["9:3.2","9:3.5"]},{"q":"파라다이스는 무한의 원형이다. 행동의 하나님은 그 원형의 활성자이다.","r":"9:3.8"},{"x":"창조체 마음의 기원은 오직 셋째 근원에 있으며, 아버지의 단편조차 무한 영이 마음의 길을 마련하기 전에는 사람 안에 내주할 수 없다.","r":["9:5.2"]},{"x":"마음의 근원이 신성하다고 해서 모든 마음 현상이 신성한 것은 아니다. 인간의 지성은 동물적 기원에 뿌리를 두고 있다.","r":["9:5.5"]},{"x":"아버지가 모든 인격을, 아들이 모든 영을 끌어당기듯, 공동 행위자는 마음-인력 회로로 모든 마음을 끌어당긴다.","r":["9:6.2"]}]},{"h":"참된 인격","items":[{"x":"무한 영은 우주 현존이요 권능이요 보편적 마음이며 그 이상이지만, 동시에 참되고 신성한 인격이다.","r":["8:6.1"]},{"x":"무한 영은 마음뿐 아니라 의지도 지니며, 그의 사랑과 슬픔은 실재하고, 그는 한 개인으로서 우주에 반응한다.","r":["8:6.3","8:6.4"]},{"q":"그러므로 “하나님의 영을 슬프게 하지 말라.”","r":"8:6.4"},{"x":"무한 영 안에는 아버지와 아들이 언제나 무제한적인 완전함 속에서 상호적으로 현존하신다.","r":["8:6.7"]}]}],"see":["우주 아버지","영원 아들","지역 우주 어머니 영","우주 마음","일곱 주(主) 영","성령"],"n":5,"en":"Infinite Spirit"},{"t":"문명","sum":"문명은 인간이 동물에 가까운 상태에서 출발해 길고 고된 투쟁 끝에 얻어 낸 인종적 습득물이다. 유전으로 저절로 전해지지 않으므로 세대마다 가정과 교육을 통해 새로 물려주어야 한다. 유란시아서는 문명을 떠받치는 물질적·지적·사회적 요인을 하나하나 짚으면서도, 문화를 참으로 끌어올리는 힘은 영적 이상주의라고 말한다.","sections":[{"h":"문명은 습득된 유산","items":[{"q":"문명은 인종적 습득물이다. 그것은 생물학적으로 내재된 것이 아니다.","r":"68:0.2"},{"x":"과학적·철학적·종교적 성취는 유전되지 않으므로, 사회적 유산을 지혜롭게 보존하고 세대마다 새로 교육해야만 지켜진다.","r":["68:0.2"]},{"x":"생물학적 진화와 문화 문명은 반드시 함께 가지 않지만, 문화는 충분한 인종적 진보라는 배경 없이는 번성할 수 없다.","r":["81:5.1"]},{"x":"칼리가스티아와 아담의 사명이 실패했어도 진화는 인종들을 계속 앞으로 이끌었으니, 진화는 늦출 수는 있어도 멈출 수는 없다.","r":["81:0.1"]},{"x":"‘자연으로 돌아가자’는 구호는 존재한 적 없는 황금 시대를 믿는 무지의 망상이다.","r":["68:1.7"]}]},{"h":"사회는 어떻게 생겨났는가","items":[{"x":"원시인은 본래 형제애가 넘치지 않았고, 쓰라린 체험을 통해 뭉쳐야 산다는 것을 배워 마지못해 협동하게 되었다.","r":["68:1.1","68:1.4"]},{"x":"문명은 폭력적 죽음에 대비한 인간의 보험이 되었고, 사람은 사회의 규범에 복종하는 것으로 그 보험료를 낸다.","r":["68:1.2","81:5.4"]},{"x":"굶주림·성애·허영심·귀신에 대한 두려움이 사람들을 모으고 묶어 사회를 이루게 했다.","r":["68:2.4","68:2.6"]},{"q":"문명에서 오래 지속되는 가치를 지닌 거의 모든 것은 가정에 뿌리를 두고 있다.","r":"68:2.8"},{"x":"달라마시아의 100인은 원시 인종을 한꺼번에 바꾸려 하지 않고, 부족의 뛰어난 이들을 길러 사회적 고양의 사절로 돌려보냈다.","r":["66:6.3","66:6.4"]},{"x":"물질 아들과 딸의 주된 목적은 진화하는 인간을 사냥과 목축 단계에서 농경 단계로 옮겨 가게 하는 것이다.","r":["52:3.3"]}]},{"h":"문명을 떠받치는 요인들","items":[{"x":"자연 환경, 자본재, 과학 지식, 인적 자원, 언어, 기계, 전문가의 조율 같은 요인들이 오늘의 문명을 떠받친다.","r":["81:6.2","81:6.3","81:6.29"]},{"q":"문화는 빈곤 속에서는 자라지 않는다. 문명 진보에는 여가가 필수다.","r":"81:6.6"},{"x":"과학은 오류를 걸러 철학을 안정시키고 미신을 깨뜨려 종교를 정화한다.","r":["81:6.10"]},{"x":"공용어는 평화를 촉진하고 문화를 보장하며, 언어·무역·예술·과학·종교의 국제 교류는 장려되어야 한다.","r":["81:6.18","81:6.19"]},{"x":"지혜로 인도되는 과학은 인류를 해방할 수 있지만, 기계화의 전환기 문제를 조정할 지혜가 없는 나라에는 재앙이 된다.","r":["81:6.22"]}]},{"h":"이상, 교육, 지도력","items":[{"x":"문화의 횃불을 다음 세대에 전하는 기본 제도는 가정이며, 놀이와 사회생활, 그리고 학교가 그 뒤를 잇는다.","r":["81:6.23","81:6.24"]},{"q":"한 세대의 이상은 곧바로 다음 세대의 운명 경로를 판다.","r":"81:6.26"},{"x":"지성은 문명의 장치를 통제하고 지혜는 그것을 인도하지만, 문화를 한 단계씩 끌어올리는 에너지는 영적 이상주의이다.","r":["81:6.27"]},{"q":"처음엔 생존을 위한 싸움이었고, 지금은 생활 수준을 위한 싸움이다. 다음은 사고의 질을 위한 싸움이 될 것이니,","r":"81:6.28"},{"x":"높은 문명은 물질적 부, 지적 탁월성, 도덕적 가치, 사회적 영민함, 우주적 통찰이 지혜롭게 맞물릴 때 태어난다.","r":["81:6.38"]},{"x":"문명은 유능하고 지혜로운 지도력이 사라질 때 비로소 위태로워지며, 그런 지도력은 인구의 1퍼센트를 넘은 적이 없다.","r":["81:6.37","81:6.42"]}]},{"h":"문명의 의무와 위험","items":[{"x":"문화 사회는 무료 회원권의 클럽이 아니라, 후손을 위해 더 나은 세상을 만드는 노동자들의 조합이다.","r":["81:5.3"]},{"x":"모든 권리는 사회적 의무와 이어지며, 집단적 규제를 받아들이는 자유가 사회 진화의 정당한 목표이다.","r":["81:5.6","81:5.7"]},{"q":"자기 유지는 사회를 낳고, 과도한 자기만족은 문명을 파괴한다.","r":"68:2.2"},{"x":"사회는 신성한 제도가 아니라 진화의 현상이므로 두려움 없이 실험하되, 큰 변혁은 갑작스럽게 시도해서는 안 된다.","r":["81:6.39","81:6.40"]},{"x":"현대 문명은 지적·과학적으로 성장했지만 윤리 의식과 영적 발달, 가정의 수호에서는 정체되어 있다.","r":["81:6.25"]}]},{"h":"문명과 종교","items":[{"x":"종교는 세속 제도와 얽힘이 적을수록 가장 높은 사회적 봉사를 하며, 새 질서를 만들거나 옛 질서를 지키는 일에 직접 끼어들지 말아야 한다.","r":["99:0.1","99:0.2"]},{"x":"문명이 발전할수록 물질 문제를 푸는 노력 속에서도 먼저 하늘의 실체를 찾는 태도가 더욱 필요해진다.","r":["195:5.1"]},{"x":"현대 문화는 예수의 삶에 대한 새로운 계시로 영적으로 세례를 받아야 한다.","r":["195:10.1"]}]}],"see":["정부와 사회","결혼과 가정","인종","진화","과학과 종교","아담과 이브"],"n":82,"en":"Civilization"},{"t":"물질 아들과 딸","sum":"물질 아들과 딸은 창조자 아들이 지역 체계마다 지어 내는 성을 지닌 아들 계층으로, 진화 세계에 아담과 이브로 파견되어 인종을 생물학적으로 높이는 일을 맡는다. 그들은 물질적이어서 필사자에게 보이며, 보이지 않는 행성 영주와 인간을 잇는 마지막 연결 고리가 된다. 유란시아의 아담과 이브는 사명에서 불이행했지만, 그들의 기여는 인류를 크게 향상시켰다.","sections":[{"h":"기원과 본성","items":[{"x":"물질 아들과 딸은 창조자 아들의 자손이며, 우주 어머니 영은 이들의 생산에 참여하지 않는다.","r":["51:1.1"]},{"x":"창조자 아들은 체계마다 그 체계의 생명 원형에 맞춘 본래의 한 쌍만을 만들고, 나머지는 그 후손이다.","r":["51:1.2"]},{"x":"키가 여덟에서 열 피트에 이르고 보라색 광채를 띠며, 아담과 이브는 동등하면서 서로 보완하여 대개 쌍으로 일한다.","r":["51:1.3"]},{"x":"물질 음식과 우주 에너지를 함께 취하는 이중 체질이어서, 반역하면 생명 근원과의 연결이 끊겨 결국 물질적 죽음을 맞는다.","r":["51:1.4"]},{"q":"이 물질 아들들은 위로는 신성과 완전으로부터 아래로는 인간성과 물질적 실존에 이르는 인격 사슬의 마지막 물리적 고리이다.","r":"45:5.3"}]},{"h":"체계 수도 예루셈에서의 삶","items":[{"x":"물질 아들딸의 각 가족은 예루셈의 천 개 중심지로 된 아담들의 영역에서 살며, 자연적 생식으로 수가 늘어난다.","r":["45:5.2","45:5.4"]},{"x":"예루셈의 아담인들은 선거와 대의 정부로 자치를 실험하며, 수도 구체의 일상 사무 대부분을 처리한다.","r":["45:5.5","45:5.6"]},{"x":"멜기세덱들은 체계 본부마다 교사진을 두어 젊은 물질 아들딸의 교육과 영적 훈련을 맡는다.","r":["45:5.7"]},{"x":"체계 수도에 사는 동안 물질 아들은 생각 조절자가 없지만, 봉사를 통해 조절자 내주와 상승 생애를 위한 역량을 얻는다.","r":["51:1.6"]}]},{"h":"행성 아담의 사명","items":[{"x":"진화 세계가 물리적 진화의 정점에 이르면 자원한 한 쌍이 뽑혀, 비물질화된 뒤 세라핌에게 실려 그 세계로 간다.","r":["51:2.1","51:2.2"]},{"x":"도착하면 생명 운반자들의 지시로 재물질화되며, 이 과정 내내 세라핌 수면의 무의식이 이어진다.","r":["51:2.4"]},{"q":"그러한 들여온 한 쌍의 주요 임무는 시간의 자녀들을 번식시키고 고양시키는 것이다.","r":"51:3.3"},{"x":"아담과 이브는 진화 인종과 직접 짝을 맺지 않고, 그 자녀들이 동산에 인도된 우수한 남녀와 자발적으로 결합한다.","r":["51:5.3"]},{"x":"보라색 인종의 혈통이 더해지면 십만 년 동안 이전 백만 년보다 더 큰 진보가 이루어진다.","r":["51:5.6"]},{"x":"동산 학교는 실용 예술과 경제, 시민 정부를 가르치며 행성 영주의 학교와 함께 문명의 속도를 정한다.","r":["51:6.2","51:6.4"]}]},{"h":"하나님과 사람을 잇는 고리","items":[{"x":"다른 행성 아들들과 달리 물질 아들은 필사자에게 보이고 이해되며, 실제로 그들과 어울릴 수 있다.","r":["51:1.7"]},{"q":"이 불멸의 물질 아들과 딸들 안에서 우리는 영원한 창조자와 시간의 가장 낮은 유한 인격들 사이 거의 무한한 간극을 연결하며 하나님과 인간을 잇는 마지막이자 필수불가결한 연결 고리를 발견한다.","r":"51:6.5"},{"x":"그들은 보이지 않는 행성 영주와 그 참모를 볼 수 있어, 그를 필사자들에게 설명해 줄 수 있다.","r":["51:6.5"]},{"x":"필사자들은 상승 길에서 일곱 아버지를 알아보게 되는데, 그 둘째가 영역의 아버지인 행성 아담이다.","r":["51:6.6","51:6.8"]}]},{"h":"유란시아의 아담과 이브","items":[{"x":"유란시아에 온 아담과 이브는 예루셈 상급 군단의 14,311번 쌍으로, 생명 형태 변형을 다루는 연구소의 책임자였다.","r":["74:1.1","74:1.2"]},{"x":"칼리가스티아의 교묘한 반대 공작에 넘어가 계약을 어겼지만, 루시퍼 반란에 가담하지는 않았다.","r":["51:3.4"]},{"q":"“인간의 타락”은 없었다.","r":"75:8.2"},{"x":"신성한 계획은 실패했어도 아담의 증여는 유란시아 민족들을 이전보다 생물학적으로 크게 향상시켰다.","r":["75:8.1","75:8.3"]},{"x":"아담과 이브는 특별 부활로 맨션 세계에서 다시 깨어나 상승 시민으로 예루셈에 돌아갔다.","r":["76:6.2","76:6.3"]},{"q":"문명을 만드는 것은 사람들이며, 문명이 사람을 만드는 것은 아니다.","r":"76:6.4"}]},{"h":"상승하는 물질 아들","items":[{"q":"행성 아담들, 곧 진화 세계들의 물질 아들과 딸들은 하강하는 아들이며, 자신들의 기원 구체인 지역 체계 수도로부터 거주 세계로 내려온다.","r":"40:2.1"},{"x":"사명에 성공한 아담과 이브는 세계가 빛과 생명에 정착하면 행정에서 물러나 완전해진 물질 아들로 등록할 수 있다.","r":["40:2.2"]},{"x":"행성 배정이 오래 늦어지는 물질 아들도 시민권 지위에서 풀려나 상승 순례자와 함께 파라다이스로 나아갈 수 있다.","r":["31:5.1"]},{"x":"최종자 중대에 든 물질 아들은 드물지만 늘 지도자로 뽑히며, 에덴 쌍은 한 인격처럼 함께 일하기도 한다.","r":["31:5.3"]}]}],"see":["아담과 이브","인종","최종자 군단","생명 운반자","중도자","빛과 생명"],"n":31,"en":"Material Sons and Daughters"},{"t":"별자리와 지역 체계","sum":"지역 우주는 백 개의 별자리로, 별자리는 다시 백 개의 지역 체계로 나뉜다. 별자리는 보론다덱 아들인 지고자들이 다스리는 입법 단위로서 에덴시아 같은 본부에서 상승 필사자들을 사회화하고, 지역 체계는 라노난덱 아들인 체계 주권자가 다스리는 집행 단위로서 예루셈과 맨션 세계에서 갓 생존한 필사자들을 맞이한다. 유란시아는 놀라시아덱 별자리의 사타니아 체계에 속하며, 루시퍼 반란 이후 특별한 보살핌을 받고 있다.","sections":[{"h":"지역 우주의 구분","items":[{"x":"유란시아는 네바돈의 백 개 별자리 가운데 하나인 놀라시아덱에서, 사타니아 체계에 속한 606번째 거주 세계이다.","r":["43:0.1"]},{"x":"한 체계는 거주 가능한 약 천 개의 세계로, 한 별자리는 백 개의 체계로 이루어진다.","r":["15:2.3","15:2.4"]},{"x":"별자리는 입법 단위로, 지역 체계는 집행 단위로 기능하며, 샐빙턴 정부는 최상의 사법·조율 권위이다.","r":["43:2.2"]},{"x":"별자리 통치자들은 지역 체계를 샐빙턴의 우주 행정과 잇고, 반영력을 통해 유버사의 옛적부터 늘 계신 이들과도 연결한다.","r":["43:0.1"]}]},{"h":"별자리 정부와 지고자들","items":[{"x":"별자리는 보론다덱 계층의 세 지고자가 다스리며, 그 가운데 주재자를 별자리 아버지라 부른다.","r":["43:3.2"]},{"q":"네바돈에서 보론다덱 아들들의 이반은 한 번도 일어난 적이 없다.","r":"43:3.1"},{"x":"별자리 입법부는 상승자 하원, 세라핌 등으로 이루어진 중간 의원, 신성한 아들들의 귀족원이라는 세 집단으로 이루어진다.","r":["43:2.5","43:2.6","43:2.7"]},{"x":"지고자들은 개인보다 민족과 종족의 안녕에 관심을 두며, 개인의 가슴속보다 사람들의 왕국에서 다스린다.","r":["43:3.5","43:9.4"]},{"x":"반역으로 고립된 세계에는 보론다덱 관찰자가 주둔하는데, 실제로 ‘사람들의 왕국을 다스리는’ 이가 바로 그이다.","r":["43:5.17"]},{"x":"에덴시아의 충심으로 늘 계신 이는 삼위일체의 대표로서 별자리 아버지들 곁에 서 있지만, 요청받지 않으면 결코 조언하지 않는다.","r":["43:4.2"]}]},{"h":"에덴시아: 하나님의 동산","items":[{"x":"별자리 본부 에덴시아는 유란시아보다 약 백 배 크며, 일흔 개의 주요 구체와 칠백 개의 위성이 그 둘레를 돈다.","r":["43:0.2"]},{"x":"별자리 수도는 살아 있는 장식이 넘쳐 ‘하나님의 동산’이라 불리며, 에덴시아 면적의 절반이 지고자들의 동산이다.","r":["43:6.1","43:6.2"]},{"q":"온 에덴시아에는 어떤 살아 있는 존재를 두렵게 할 것이 아무것도 없다.","r":"43:6.5"},{"x":"상승 필사자는 일흔 세계를 거치며 유니비타티아와 함께 살고, 집단 윤리와 모론시아 인격의 참된 사회화를 배운다.","r":["43:8.3","43:8.4"]},{"q":"지성적으로, 사회적으로, 영적으로 두 도덕적 창조체는 동반 기법으로 우주 성취의 인격적 잠재력을 단지 두 배로 늘리는 것이 아니라, 달성과 성취의 가능성을 거의 네 배로 늘린다.","r":"43:8.11"},{"x":"별자리 체류는 동물 같은 존재에서 상승 영으로 가는 길의 중간 지점으로, 모론시아 생애에서 가장 균일하고 안정된 시기이다.","r":["43:9.2","43:9.3"]}]},{"h":"지역 체계와 예루셈","items":[{"x":"지역 체계의 최고 집행자는 1차 라노난덱 아들인 체계 주권자이며, 사타니아의 현 주권자는 루시퍼의 후계자 라나포지이다.","r":["45:2.1","45:3.2"]},{"x":"네바돈 역사에서 체계 주권자의 불충은 세 번 있었고, 사타니아의 루시퍼 반란이 마지막이자 가장 광범위한 것이었다.","r":["45:2.1"]},{"x":"예루셈은 일곱 전환 문화 세계와 그 위성들에 둘러싸여 있으며, 일곱 맨션 세계는 첫째 전환 세계의 위성이다.","r":["45:0.1","45:0.2"]},{"q":"체계 수도들은 우주적 실존의 세 국면, 곧 물질적·모론시아적·영적 국면을 거의 완전하게 모두 보여 주는 유일한 세계라는 점에서 독특하다.","r":"46:4.8"},{"x":"예루셈에는 밤낮과 계절이 따로 없고, 빛은 한 곳이 아니라 하늘 전체에서 고르게 걸러져 나온다.","r":["46:1.4","46:1.5"]},{"q":"대의 정부는 완전하지 않은 존재들 사이에서 자치의 신성한 이상이다.","r":"45:7.3"}]},{"h":"체계 수도에서의 상승 훈련","items":[{"x":"맨션 세계는 육신의 생애에서 조절자와 융합하지 못한 필사자들이 중단된 영적 성취를 이어 갈 기회를 얻는 곳이다.","r":["45:7.1"]},{"x":"물질 아들딸은 예루셈의 영구 시민으로서 상승 필사자들의 직접적인 후원자요 스승이 된다.","r":["45:5.5","45:6.2"]},{"x":"부모 체험이 없는 상승자는 예루셈의 물질 아들 가정이나 수습 보육원에서 그 필수 체험을 보완해야 한다.","r":["45:6.4","45:6.6"]},{"x":"예루셈 선거에서 한 표의 가치는 모론시아 지혜의 정도에 따라 달라지며, 모타 인격을 성취해야 별자리로 떠날 수 있다.","r":["45:7.6","45:7.8"]},{"x":"최종자 세계에서 열리는 집회는 맨션 세계 체류자들에게 그들도 그 긴 여정을 마칠 수 있다는 확신을 준다.","r":["45:1.2"]}]},{"h":"반란 이후의 특별한 보살핌","items":[{"x":"루시퍼 반란 이후 에덴시아의 지고자들은 반역 세계들에 대한 행성 권한의 일부를 장악하여 지금도 행사하고 있다.","r":["43:3.7"]},{"x":"루시퍼와 그를 따른 인격들의 대다수는 예루셈 아버지 세계 둘레의 감옥 세계에 갇혀 온 네바돈에 엄숙한 경고가 되고 있다.","r":["45:1.11"]},{"x":"그리스도 미가엘의 승리 이후 사탄은 에덴시아 대회에서 체계 주권자들에게 만장일치로 거절되었다.","r":["43:4.9"]},{"q":"악을 받아들일 열린 문이 없을 때, 죄를 받아들일 기회도 없다.","r":"43:4.9"},{"x":"예루셈의 스물네 조언자는 유란시아 출신 인물들로, 사타니아 점호와 고립 세계들의 상승 계획에서 미가엘을 대표한다.","r":["45:4.1","45:4.2"]}]}],"see":["지역 우주 네바돈","맨션 세계","루시퍼 반란","필사자의 상승 여정","물질 아들과 딸","멜기세덱"],"n":16,"en":"Constellations and Local Systems"},{"t":"보조 마음 영","sum":"일곱 보조 마음-영은 지역 우주 어머니 영이 창조한 마음 사역의 회로로, 직관·이해·용기·지식·상담·예배·지혜라는 이름을 지닌다. 독립된 인격이라기보다 회로에 가까우며, 체험으로 배울 수 있는 동물과 인간의 마음에 작용해 진화가 우연이 아니라 목적 있게 나아가도록 조건 짓는다. 예배와 지혜의 보조 영이 작동하기 시작하면 마음은 영적 사역의 문턱을 넘어 성령의 회로와 생각 조절자를 맞을 준비를 갖춘다.","sections":[{"h":"어머니 영의 마음 회로","items":[{"x":"일곱 보조 마음-영은 지역 우주의 신성한 사역자가 창조했으며, 성품은 비슷하나 권능은 다양하고 어머니와 별개의 인격으로 보기 어렵다.","r":["34:4.10"]},{"x":"네바돈의 세 영 회로 가운데 셋째가 일곱 보조 마음-영의 지성-사역 회로이다.","r":["34:4.4"]},{"q":"일곱 보조 마음-영들은 항상 생명 운반자들과 함께 새로운 행성으로 가지만, 그들은 실체로 간주되어서는 안 되며, 회로들에 더 가깝다.","r":"36:5.4"},{"x":"그들은 사실상 신성한 사역자의 한 의식 수준이며, 언제나 창조 어머니의 활동과 현존에 종속된다.","r":["36:5.4"]},{"x":"보조 영들은 체험을 통해 기능이 자라지만 결코 인격적 존재가 되지는 않는다.","r":["36:5.13"]},{"x":"이 사역은 지역 우주 본부에서 나오지만, 낮은 수준의 마음 기능에 대한 실제 지휘는 체계 수도에서 이루어진다.","r":["65:7.1"]},{"x":"진화 초기의 필사자 인종은 어머니 영의 일곱 보조 마음-영과 점차 접촉해 가며 지성의 등급을 올라간다.","r":["194:2.12","194:2.18"]}]},{"h":"일곱 보조 영의 이름과 기능","items":[{"x":"직관의 영은 빠른 지각과 반사 본능, 방향 감각을 주며, 기계적 마음 수준과 넓게 접촉하는 유일한 보조자이다.","r":["36:5.6","34:4.12"]},{"x":"이해의 영은 관념들을 자발적으로 연합하고 조율하는 선물로, 빠른 추론과 즉각적 결정으로 나타난다.","r":["36:5.7"]},{"q":"용기의 영—신실함의 부여물—으로서, 인격적 존재들 안에서는 성품 획득의 기초이자 도덕적 기력과 영적 용기의 지성적 뿌리.","r":"36:5.8"},{"x":"지식의 영은 모험과 발견을 낳는 호기심의 어머니요, 상담의 영은 동료와 조화를 이루게 하는 사회적 협력의 충동이다.","r":["36:5.9","36:5.10"]},{"q":"예배는 영적 상승 후보 자격의 휘장이다.","r":"36:5.11"},{"q":"이것은 보조자들 중 가장 높으며, 다른 모든 보조자들의 작업을 조율하고 명료하게 표현하는 영이다.","r":"36:5.12"},{"x":"지식이 새로운 의미 수준으로 높여져 지혜 보조 영의 현존으로 활성화될 때 그것이 지혜이다.","r":["180:5.3"]}]},{"h":"진화를 이끄는 사역","items":[{"x":"보조 마음-영들의 현존이 유기적 진화를 조건 짓기 때문에, 진화는 우연이 아니라 목적을 지닌다.","r":["36:5.1"]},{"x":"보조 영들은 순전히 기계적인 반응과는 접촉하지 않으며, 체험으로 배울 가능성이 생기는 순간 사역을 시작한다.","r":["65:7.5","65:7.6"]},{"x":"이들은 물리적 진화에는 관여하지 않지만 그 과정과 완벽히 맞물려, 사람은 마음 현상에서 자연의 작용만을 본다.","r":["65:7.2"]},{"x":"유란시아의 독특한 생명 원형 때문에 하위 보조 영들은 네바돈의 거의 어느 곳보다 큰 접촉의 어려움을 겪었다.","r":["65:7.3","65:7.4"]},{"x":"동물 단계에서 처음 다섯 보조 영이 기능한 것이 인간 지성에 필수적이므로, 동물은 인간의 지성 진화에도 없어서는 안 된다.","r":["36:5.13"]},{"x":"생명 운반자 본부의 중앙 주둔지는 처음 다섯 보조 영의 기능을 재지만, 예배와 지혜의 양적 활동은 샐빙턴의 어머니 영 현존에 등록된다.","r":["36:5.3"]},{"x":"어머니 영의 일은 주로 약속의 영들인 일곱 보조자를 통해 이루어지며, 인류를 언제나 더 높은 사상과 이상으로 이끈다.","r":["34:5.2"]}]},{"h":"영적 사역의 문턱","items":[{"q":"보조 영들은 여섯째 단계인 예배의 영에 이를 때까지, 체험하는 마음의 진화에서만 배타적으로 작용한다.","r":"65:7.7"},{"x":"마음이 예배와 지혜의 보조자를 받아들일 능력을 갖추면, 필사자는 처음으로 마음과 결합된 영의 사역을 체험한다.","r":["34:5.3"]},{"x":"신성을 인식하고 예배하기 이전의 창조체 마음은 보조 영들의 독점 영역이며, 영적 반응이 나타나면 곧 초(超)마음이 된다.","r":["36:5.15"]},{"x":"보조 영들은 성령의 고도로 영적인 기능과 직접 관련되지는 않지만, 진화인 안에서 그 영의 출현에 앞서 길을 준비한다.","r":["36:5.16"]},{"q":"인간의 마음이 조절자를 받아들일 자격을 갖추려면 모든 일곱 보조 영의 동격 기능이 필요하다.","r":"108:2.2"},{"x":"인간의 모든 진정한 종교적 반응은 예배 보조 영이 후원하고 지혜 보조 영이 검열한다.","r":["103:0.1"]}]}],"see":["지역 우주 어머니 영","마음","성령","생명 운반자","진화","생각 조절자"],"n":38,"en":"Adjutant Mind-Spirits"},{"t":"봉사","sum":"봉사는 신성이 인격 차원에서 드러나는 한 방식이며, 아들은 인류를 섬기고 무한 영과 그 자녀들은 사역하려는 충동을 본성으로 지닌다. 사람에게 봉사는 참된 종교가 맺는 사회적 열매로서, 하나님을 사랑하는 내적 체험이 동료를 향한 사랑의 섬김으로 흘러나오는 것이다. 예수는 발을 씻기며 섬기는 자가 큰 자임을 보였고, 상승의 길은 끝없는 우주 봉사로 이어진다.","sections":[{"h":"신성한 봉사의 근원","items":[{"x":"창조체는 신성을 인격 차원에서 사랑과 자비와 봉사로 이해할 수 있다.","r":["0:1.17"]},{"q":"아버지 하나님은 인류를 사랑하시며, 아들 하나님은 인류에게 봉사하시고,","r":"3:6.8"},{"x":"마음에 대한 사역은 무한 영의 본질이며, 그 모든 영 자손은 봉사하려는 신성한 충동을 함께 지닌다.","r":["8:4.1","8:4.2"]},{"x":"무한 영의 가족은 하나님의 사랑과 아들의 자비를 사역하는 봉사에 영원히 헌신하며, 필사자가 오르는 살아 있는 사다리가 된다.","r":["9:8.25"]},{"x":"하강하는 아들들이 보여 주는 자비와 봉사의 속성은 영원 아들에게서 비롯된다.","r":["7:6.2"]}]},{"h":"참된 종교의 열매","items":[{"q":"종교는 고요하고 안락한 마음의 평화를 얻기 위한 기법이 아니라, 혼을 조직하여 활동적인 봉사를 수행하게 하는 내적 충동이다.","r":"100:3.1"},{"x":"하나님을 발견한 사람은 자랑하려는 것이 아니라 넘치는 선함 때문에 덜 깨우친 동료들을 찾아 섬기게 된다.","r":["102:3.4"]},{"q":"종교의 지적 특징은 확실성이다. 철학적 특성은 일관성이다. 사회적 열매는 사랑과 봉사이다.","r":"102:7.5"},{"x":"예수는 종교를 원인으로, 윤리와 봉사를 그 결과로 가르쳤으며, 내적 종교는 실천적 사회 봉사로 드러난다.","r":["170:3.8","170:3.9"]},{"x":"종교가 개인 체험으로 바뀌어도 이타적인 사회봉사의 동기를 잃지 않는 한 위험하지 않다.","r":["99:4.7"]},{"x":"조절자와의 접촉은 명상으로도 촉진되지만, 동료에게 사랑으로 봉사할 때 더 자주 이루어진다.","r":["91:7.1"]}]},{"h":"예수가 보여 준 봉사의 길","items":[{"x":"마지막 만찬에서 예수는 자리다툼을 하던 사도들 앞에 종처럼 무릎 꿇고 열두 사람의 발을, 유다의 발까지 씻겼다.","r":["179:3.1","179:3.7"]},{"q":"너희 중 누구든지 위대해지려면, 어린 자처럼 되어야 하고, 누구든지 으뜸이 되려면, 섬기는 자처럼 되어야 한다.","r":"179:3.9"},{"x":"영적 왕국에서 위대함의 비밀은 물질 세계의 권력 방법과 다르다는 것이 발 씻김의 교훈이었다.","r":["179:3.8"]},{"q":"내 왕국은 사랑에 기초를 두고, 자비로 선포되며, 이타적인 봉사로 세워진다.","r":"155:1.2"},{"x":"예수는 희생이 아니라 충성을 요구했다. 친구가 친구를 위해 하는 봉사는 희생이라 불릴 수 없다.","r":["180:1.6"]},{"x":"목마른 혼에게 건넨 찬물 한 잔 같은 작은 사랑의 봉사도 아버지의 사자들이 언제나 기록한다.","r":["159:2.1"]}]},{"h":"사회와 문명 속의 봉사","items":[{"q":"경제학에서, 이윤 동기와 봉사 동기의 관계는, 종교에서 두려움과 사랑의 관계와 같다.","r":"71:6.2"},{"x":"이윤 동기는 갑자기 없앨 것이 아니라, 점차 이기적이지 않은 동기로 바뀌어 가야 한다.","r":["71:6.2"]},{"x":"부모의 본능 말고는 이타심이 저절로 생기지 않으므로, 이타적 사회 질서에는 이성과 도덕과 종교의 충동이 필요하다.","r":["16:9.7"]},{"x":"참된 부모는 자녀가 자라며 알아보고 감사하게 될 지속적인 봉사-사역에 참여한다.","r":["84:7.26"]},{"x":"신자의 사회적 봉사와 지적 교통은 소중하지만, 내적 변형의 부산물일 뿐 복음 선포를 대신할 수 없다.","r":["178:1.11"]}]},{"h":"영원으로 이어지는 봉사","items":[{"x":"넷째 맨션 세계에서 상승자들은 이기적 정복이 아니라 상호 봉사의 사랑에 기초한 사회 질서를 처음 체험한다.","r":["47:6.3"]},{"x":"아버지와 아들들이 베푼 것을 우리는 동료와 최상 존재에게 되돌려 베푼다. 사랑과 기쁨과 봉사의 체험은 상호적이다.","r":["56:8.3"]},{"x":"필사 최종자 군단에 들어가는 것은 파라다이스 삼위일체를 향한 영원한 봉사의 시작이다.","r":["27:7.8","27:7.10"]},{"x":"현 우주 시대에 최종자들은 시간의 우주들로 돌아와 여러 초우주에서 차례로 봉사한다.","r":["31:0.10"]}]}],"see":["사랑","사람의 형제됨","종교 체험","최종자 군단","예수의 가르침","무한 영"],"n":63,"en":"Service"},{"t":"비유","sum":"비유는 예수가 갈릴리 바닷가에서 무리에게 처음 쓰기 시작한 이후 공적 가르침의 거의 유일한 방법이 된 이야기 교수법이다. 그는 비유를 숨은 뜻을 하나하나 맞추는 우화로 풀지 말고, 하나의 중심 진리를 드러내는 실화로 받아들이라고 가르쳤다. 비유는 서로 다른 수준의 마음에 동시에 호소하고, 편견과 논쟁을 피하면서 새 진리를 심으며, 각 사람이 자기 혼 안에서 그 뜻을 찾게 한다.","sections":[{"h":"비유 가르침의 시작","items":[{"x":"예수는 바닷가 배 위에서 천 명 가까운 무리에게 씨 뿌리는 자의 비유를 들려주며 처음으로 이 방법을 썼다.","r":["151:1.1","151:1.2"]},{"x":"왕국에 들어가기를 참되게 원하는 이는 비유의 뜻을 깨닫고, 함정을 노리는 자는 보고도 깨닫지 못하게 하려는 뜻이 있었다.","r":["151:1.4"]},{"x":"그때부터 예수는 대중을 거의 비유로만 가르쳤고, 저녁에는 사도들에게 그 뜻을 더 자세히 설명했다.","r":["151:4.7"]},{"x":"자연에 호소하는 비유는 그의 일이 마귀의 힘으로 이루어진다는 비난에 대한 최선의 반박이었고, 적에게 트집 잡을 빌미도 덜 주었다.","r":["151:3.14"]}]},{"h":"우화가 아닌 비유","items":[{"x":"베드로와 나다니엘은 씨 뿌리는 자의 비유를 세부마다 숨은 뜻이 있는 우화로 풀다가 의견이 갈렸다.","r":["151:2.1","151:2.4"]},{"x":"도마는 예화에는 실화를 쓰고, 하나의 중심 진리를 드러내는 이야기를 골라야 한다는 주님의 가르침을 일깨웠다.","r":["151:2.5"]},{"q":"잘했다, 도마야. 너는 비유의 진정한 의미를 파악했다.","r":"151:2.7"},{"x":"사적인 상상의 비약은 유익할 수 있으나, 그것을 공적 가르침으로 내세우는 것은 실수라고 예수는 말했다.","r":["151:2.7"]},{"x":"예수는 우화나 알레고리를 피하고 비유, 특히 자연에서 가져온 비유를 자유롭게 쓰라고 권했다.","r":["151:3.3"]}]},{"h":"비유의 가치","items":[{"q":"비유는 아주 다른 수준의 마음과 영에 동시에 호소할 수 있는 방법을 제공한다.","r":"151:3.6"},{"q":"비유는 알려진 것에서 출발하여 미지의 것을 깨닫게 한다.","r":"151:3.7"},{"x":"비유는 편견을 비켜 가며 반감을 최소로 일으키면서 새 진리를 마음에 심는다.","r":["151:3.8"]},{"x":"비유는 전통과 권위와의 정면 충돌을 피하게 하고, 익숙한 장면을 다시 볼 때 가르침을 떠올리게 한다.","r":["151:3.10","151:3.11"]},{"x":"같은 이야기를 들어도 각 사람은 자기의 지적·영적 수준에 따라 비유를 해석할 수 있다.","r":["151:3.1"]}]},{"h":"자라는 씨앗의 비유들","items":[{"x":"씨 뿌리는 자의 비유는 그때까지의 사역을 돌아보고, 후대 사자들이 겪을 다양한 성공을 미리 보여 주는 것이었다.","r":["151:3.13"]},{"x":"감정이나 지성에만 호소하는 것은 열매가 없고, 사람 안에 사는 영에게 호소해야 성품이 참으로 변한다.","r":["152:6.3"]},{"x":"씨가 저절로 자라 이삭을 맺는 비유는 왕국의 성장이 사람의 이해를 넘어 조용히 일어남을 보여 준다.","r":["151:3.15"]},{"x":"겨자씨와 누룩의 비유는 작게 시작한 왕국이 크게 자라고 온 반죽을 부풀리듯 퍼져 나감을 말한다.","r":["151:4.2","151:4.3"]}]},{"h":"아버지의 사랑을 그린 비유","items":[{"q":"그러나 나는 너희가 하나님을 찾고 있는 동안 하나님도 너희를 찾고 계신다는 것을 보여주기 위해 왔다.","r":"169:1.2"},{"q":"너희가 회개하기도 전에 아버지가 너희를 받아들이시며,","r":"169:1.3"},{"x":"탕자의 아버지는 멀리서 돌아오는 아들을 보고 달려가 맞았고, 아들의 고백이 끝나기도 전에 잔치를 명했다.","r":["169:1.9","169:1.10"]},{"x":"잃은 양·잃은 동전·잃은 아들의 세 이야기는 각각 길 잃은 자를 찾는 아버지, 철저한 탐색, 완전한 회복을 보여 준다.","r":["169:1.15"]},{"x":"탕자의 비유와 선한 사마리아인 이야기는 아버지의 사랑과 사람의 이웃다움을 가르치는 예수가 가장 좋아한 방법이었다.","r":["169:1.16"]}]},{"h":"이웃, 겸손, 신실함","items":[{"x":"‘누가 내 이웃이냐’는 함정 질문에 예수는 선한 사마리아인 이야기로 답하여 율법사 스스로 답하게 했다.","r":["164:1.2","164:1.3","164:1.4"]},{"x":"바리새인과 세리의 비유는 구원이 행위로 살 수 없고 신앙을 가진 모든 이에게 거저 주어지는 선물임을 가르친다.","r":["167:5.1"]},{"x":"달란트와 파운드의 비유는 능력이 기회의 척도이며, 같은 신실함에는 같은 보상이 따른다는 것을 보여 준다.","r":["171:8.10","171:8.13"]},{"q":"모든 사람은 각자 자신과 자신의 혼 안에서 그 의미를 찾아야 한다.","r":"167:2.4"}]}],"see":["예수의 가르침","하나님 나라","사랑","용서","자비","열두 사도"],"n":87,"en":"Parables"},{"t":"빛과 생명","sum":"빛과 생명은 시간과 공간 세계가 도달하는 진화의 최종 성취로, 행성이 신성한 아들들의 연속된 사역을 거쳐 마침내 정착하는 시대이다. 이 시대에 행성은 하나의 언어와 종교와 철학 아래 번영하고, 전쟁과 가난은 사라지며, 많은 필사자가 죽음을 거치지 않고 조절자와 융합하여 모론시아 생애로 옮겨 간다. 그 정착은 행성에서 시작해 체계, 별자리, 지역 우주, 초우주로 일곱 단계에 걸쳐 넓어진다.","sections":[{"h":"진화 세계의 최종 목표","items":[{"q":"빛과 생명의 시대는 시간과 공간 세계의 최종적인 진화적 성취이다.","r":"55:0.1"},{"x":"거주 세계는 행성 영주, 아담, 치안 아들, 증여 아들의 시대를 거쳐 삼위일체 교사 아들들의 사역으로 이 시대를 준비한다.","r":["55:0.1","52:7.2"]},{"x":"이 시대는 교사 아들들이 최종 임무를 마칠 때 시작되어 그 세계에서 끝없이 계속된다.","r":["55:0.2","55:0.3"]},{"x":"빛과 생명은 행성·체계·별자리·지역 우주·소구역·대구역·초우주의 일곱 단계로 펼쳐진다.","r":["55:0.4","55:0.11"]}]},{"h":"모론시아 사원과 새 통치","items":[{"x":"행성 수도에 모론시아 사원이 나타나는 것은 그 세계가 빛과 생명에 들어섰다는 증명서이다.","r":["55:1.1"]},{"x":"사원 중심에는 증여 아들의 성소가, 양쪽에는 행성 주권자와 최종자 우두머리의 자리가 있다.","r":["55:1.2"]},{"x":"사원이 ‘하늘에서 내려온다’고 하지만, 실제로는 체계 수도에서 설계된 것을 모론시아 동력 감독자들이 현지에서 짓는다.","r":["55:1.3"]},{"x":"이 시대에 행성 영주는 행성 주권자로 높여지고, 파라다이스에 이른 최종자들이 돌아와 행성 일에 참여한다.","r":["55:7.1","55:4.1"]},{"x":"보이는 실제 통치자는 물질 아들과 딸이며, 이 배치가 우주 곳곳에서 왕과 왕비라는 관념에 명성을 주었다.","r":["55:7.2"]}]},{"h":"죽음 없는 이행","items":[{"q":"자연적·물리적 죽음은 필사자의 불가피한 숙명이 아니다.","r":"55:2.1"},{"x":"빛과 생명의 마지막 시대에 사는 시민 대다수는 죽지 않고 육신에서 곧바로 모론시아 실존으로 옮겨 간다.","r":["55:2.1","55:2.2"]},{"x":"융합이 임박하면 후보자는 의무에서 물러나 가족과 친구들이 모인 모론시아 사원에서 ‘생명 섬광’으로 이행한다.","r":["55:2.3","55:2.4"]},{"x":"이런 세계에서 넘어온 이들은 유란시아처럼 무질서한 세계 출신보다 훨씬 앞서 상승을 이어 갈 준비가 되어 있다.","r":["55:2.10"]}]},{"h":"정착된 세계의 삶","items":[{"x":"세계는 하나의 언어와 하나의 종교, 정상적인 경우 하나의 인종을 이루지만, 여전히 병원과 사고와 노쇠가 있어 완벽하지는 않다.","r":["55:3.1"]},{"x":"한 첫째 단계 세계는 수입의 십분의 일을 거두어 진리·아름다움·선함과 재난 대비에 나누어 썼다.","r":["55:3.2","55:3.6"]},{"x":"대부분의 공직과 교육과 사법은 남녀가 함께 맡았고, 최고의 영예는 ‘최상 봉사’ 훈장이었다.","r":["55:3.8","55:3.9"]},{"q":"전쟁은 역사의 한 장이 되었고, 더 이상 군대나 경찰력이 없다.","r":"55:5.4"},{"x":"자기 통제가 법을 대신하여 정부는 점차 줄어들며, 정부의 범위는 시민의 도덕성과 영성에 반비례한다.","r":["55:5.4"]},{"x":"가난과 사회적 불평등은 거의 사라지고, 경제생활은 윤리적이 된다.","r":["55:5.2","55:5.3"]}]},{"h":"그래도 여전히 필사자","items":[{"q":"이 위대한 진화는 하늘이 아니라, 파라다이스 상승 과정에서 맞이할 신성한 세계들의 숭고한 예표이다.","r":"55:6.2"},{"x":"사회는 더 평화로워지고, 사람들은 독립성과 가족 사랑을 잃지 않으면서도 더 이타적이고 형제다워진다.","r":["55:6.1"]},{"x":"그런 세계에도 진리와 오류, 선과 악 사이의 선택을 자극하는 잠재적 악이 여전히 풍부하다.","r":["55:3.10"]},{"x":"조절자와의 교통은 시대마다 깊어지고, 성령과 천사들의 사역도 더욱 효과적이 된다.","r":["55:6.4"]},{"q":"창조체의 영원한 진보라는 미래가 없다 해도, 그토록 완전하게 정착된 세계의 필사 인종이 이룩한 탁월한 진화적 성취만으로도 시간과 공간 세계들에서 인간 창조를 충분히 정당화할 것이다.","r":"55:6.9"}]},{"h":"유란시아와 빛과 생명","items":[{"x":"유란시아의 가장 큰 장애는 질병, 퇴행, 전쟁, 다색 인종, 다언어의 문제이다.","r":["55:3.21"]},{"q":"어떠한 진화 세계도 하나의 언어, 하나의 종교, 하나의 철학을 달성하기 전에는 빛 속에서의 정착의 첫째 단계를 넘어 발전하기를 기대할 수 없다.","r":"55:3.22"},{"x":"유란시아가 그 시대에 이르면 마키벤타 멜기세덱이 행성 주권자의 자리를 차지할 것이다.","r":["55:7.3"]},{"x":"고립된 세계에서도 개인의 성취는 막히지 않으니, 나사렛 예수는 유란시아에서 빛과 생명의 지위를 인격적으로 이루었다.","r":["55:11.7"]}]}],"see":["유란시아","조절자 융합","최종자 군단","물질 아들과 딸","진화","최상 존재"],"n":93,"en":"Light and Life"},{"t":"사람의 형제됨","sum":"사람의 형제됨은 모든 인격이 같은 하늘 아버지의 자녀라는 사실에서 나오는 보편적 관계이다. 하나님이 각 개인을 사랑하시고 그 사랑이 모두에게 미치기에, 사람들은 서로 형제로 묶인다. 예수는 하나님의 아버지됨과 사람의 형제단을 복음의 중심으로 가르쳤고, 그 실현은 법이나 힘이 아니라 상호 이해와 사랑, 그리고 인류의 영적 변혁에 달려 있다.","sections":[{"h":"아버지됨에서 나오는 형제됨","items":[{"x":"하나님은 각 사람을 개별 자녀로 사랑하시지만, 그 사랑이 모두에게 미치기에 보편적 형제 됨이 생겨난다.","r":["12:7.8","12:7.10"]},{"x":"형제 됨은 부분이 아니라 전체의 관계여서, 각 사람의 선은 모두를 돕고 각 사람의 악은 모두의 고난을 더한다.","r":["12:7.11"]},{"q":"사람의 형제단은 궁극적으로 하나님의 부성을 인정하는 데에 근거한다.","r":"52:6.7"},{"x":"우리가 하나님의 아들이라는 믿음이 유효해질 때, 이타적 확신인 형제단의 느낌도 실재가 된다.","r":["103:5.9"]}]},{"h":"예수가 가르친 형제단","items":[{"x":"예수는 혈연의 가족을 넘어서는 새롭고 더 큰 형제단, 곧 하나님의 아들들의 형제단을 가르쳤다.","r":["140:8.14"]},{"x":"예수는 하늘 가족의 두 법칙으로 아버지를 사랑하는 것과 형제를 자신처럼 사랑하는 것을 들고, 형제 사랑은 이타적 봉사로 나타난다고 했다.","r":["142:7.4"]},{"q":"곧 내가 너희를 사랑한 것처럼 너희가 서로 사랑하라.","r":"180:1.1"},{"x":"예수는 왕국을 가리키는 말로 하나님의 가족, 신자들의 교제, 사람의 형제단 같은 표현도 썼다.","r":["170:2.24"]},{"x":"예수가 창시한 종교는 하나님의 뜻을 행하고 인간 형제단을 섬기는 개인적 체험으로 이루어진다.","r":["196:2.6"]}]},{"h":"영적 형제단과 사회적 형제단","items":[{"q":"하늘 왕국은 사회적이거나 경제적 질서가 아니다. 그것은 하나님을 아는 개인들로 이루어진 오로지 영적인 형제단이다.","r":"99:3.2"},{"x":"하늘 왕국은 영으로 태어난 아들들의 영적 형제단이므로 물리적 힘이 아니라 영의 권능으로만 선포된다.","r":["178:1.2"]},{"x":"예수는 영적 형제단에 이르는 길을 곧바로 보여 주었지만, 사회적 형제단은 개인과 행성의 여러 변화에 달려 있다.","r":["52:6.2"]},{"x":"모든 종교가 교회적 권위와 영적 주권 주장을 버리지 않는 한 종교적 형제단은 이루어질 수 없다.","r":["134:4.4"]},{"q":"종교적 계시는 유란시아에서 형제단 실현에 필수적이다.","r":"52:6.2"}]},{"h":"형제됨을 이루는 길","items":[{"x":"여행과 교역과 교류를 통한 사회적 접촉, 서로의 사상을 익히는 지적 교류가 형제단을 앞당긴다.","r":["52:6.3","52:6.4"]},{"x":"무지는 의심을 낳고, 의심은 공감과 사랑과 함께할 수 없다.","r":["52:6.4"]},{"x":"윤리적 각성과 정치적 지혜, 무엇보다 영적 통찰이 형제단 실현에 필요하다.","r":["52:6.5","52:6.6","52:6.7"]},{"x":"형제단을 가장 빨리 이루는 길은 위로부터의 영적 압력으로 서로 이해하고 사랑하는 혼의 역량을 키우는 것이다.","r":["52:6.7"]},{"x":"유란시아처럼 고립된 세계에서는 종교적 계시가 형제단 실현에 꼭 필요하다.","r":["52:6.2"]},{"q":"무지는 의심을 낳고, 의심은 공감과 사랑이라는 본질적 태도와 양립할 수 없다.","r":"52:6.4"}]},{"h":"사랑의 전염과 미래 문명","items":[{"x":"의지력만으로는 동료를 사랑할 수 없으며, 사랑은 이웃의 동기와 정서를 깊이 이해할 때 태어난다.","r":["100:4.6"]},{"q":"오늘 모든 사람을 사랑하는 것보다, 오늘 하루 한 사람을 더 사랑하는 법을 배우는 것이 더 중요하다.","r":"100:4.6"},{"x":"모든 사람이 사랑의 중심이 되면 그 사랑이 문명 전체를 감싸 사람의 형제단이 실현될 것이다.","r":["100:4.6"]},{"x":"더 나은 문명의 비밀은 사랑과 상호 신뢰의 선의에 관한 예수의 형제단 가르침에 있다.","r":["194:3.12"]},{"x":"문명의 진보는 사람의 형제단이라는 사회적 성취와 하나님 의식이라는 인격적 지위로 이어진다.","r":["71:4.15"]},{"x":"현대 그리스도교의 희망은 하나님의 아버지됨과 사람의 형제단이라는 살아 있는 복음을 새롭게 배우는 데 있다.","r":["195:10.21"]}]}],"see":["하나님의 아들됨","우주 아버지","하나님 나라","사랑","봉사","문명"],"n":48,"en":"Brotherhood of Man"},{"t":"사랑","sum":"“하나님은 사랑이시다.” 유란시아서에서 사랑은 하나님이 창조체와 인격적으로 관계 맺는 모든 일의 지배적 특성이며, 진리와 아름다움과 선을 모두 포괄한다. 아버지의 사랑은 각 사람을 대체할 수 없는 자녀로 개별화하고, 조절자를 통해 사람 안에 내주한다. 사랑은 다른 이에게 선을 행하려는 소망이며, 붙잡아 둘 수 없고 동료에게 베풀 때에만 실재가 된다. 예수는 “내가 너희를 사랑한 것처럼” 서로 사랑하라는 새 계명을 주었다.","sections":[{"h":"하나님은 사랑이시다","items":[{"x":"하나님이 사랑이시므로 우주의 일들에 대한 그분의 유일한 인격적 태도는 언제나 신성한 애정의 반응이다.","r":["2:5.1"]},{"x":"하나님의 사랑은 희생이나 중재로 유도된 것이 아니며, 아버지께서 친히 우리를 사랑하신다.","r":["2:5.2"]},{"q":"하나님은 사랑이시다. 그러나 사랑이 하나님은 아니다.","r":"2:5.10"},{"x":"하나님의 사랑은 지혜와 통일되어 작용하는, 멀리 내다보는 부모의 애정이며 때로는 우리 유익을 위한 징계도 포함한다.","r":["2:5.3","2:5.10"]},{"x":"사랑은 하나님이 창조체들과 인격적으로 관계 맺는 모든 일에서 지배적인 특성이다.","r":["2:5.12"]}]},{"h":"아버지 사랑의 현시","items":[{"x":"아버지의 사랑은 각 인격을 영원히 대체할 수 없는 고유한 자녀로 개별화한다.","r":["12:7.9"]},{"x":"필사자를 향한 신성한 사랑의 가장 큰 현시는 조절자의 증여이고, 가장 큰 계시는 미가엘의 증여 생애이다.","r":["2:5.10"]},{"x":"조절자가 개인에게 바치는 사랑과 헌신은 모든 창조계에서 가장 참으로 신성한 애정이다.","r":["110:0.2"]},{"x":"하나님은 사랑이시고 아들은 자비이시니, 자비는 행동으로 나타난 적용된 사랑이다.","r":["6:3.5"]},{"x":"우리가 하나님을 사랑하는 것은 그분이 참으로 우리를 사랑하심을 분별하기 때문이며, 사랑하는 체험은 사랑받는 체험에 대한 반응이다.","r":["2:5.8"]},{"q":"아버지의 사랑은 지금도, 그리고 영원의 시대들의 끝없는 순환을 통하여 우리를 따라온다.","r":"2:5.9"}]},{"h":"사랑이란 무엇인가","items":[{"q":"사랑은 다른 이에게 선을 행하려는 소망이다.","r":"56:10.21"},{"x":"참된 의미에서 사랑은 인간적이든 신성하든 전체 인격들 사이의 상호 존중을 뜻한다.","r":["112:2.7"]},{"q":"그것은 창조되거나, 제조되거나, 살 수 있는 것이 아니다. 그것은 자라나야 한다.","r":"100:3.7"},{"x":"사랑은 이웃의 동기와 정서를 깊이 이해할 때에만 태어나며, 의지의 힘만으로는 동료를 사랑할 수 없다.","r":["100:4.6"]},{"x":"사랑은 진리의 영의 인도에 따라 사랑받는 이의 최고선에 대한 개념을 끊임없이 새로 적응해 나가야 한다.","r":["180:5.10"]}]},{"h":"흐르는 사랑의 회로","items":[{"x":"모든 참된 사랑은 하나님에게서 나오며, 사람은 그 사랑을 이웃에게 베풂으로써 신성한 애정을 받는다.","r":["117:6.10"]},{"q":"인간은 아버지의 사랑을 가져와서 자신의 가슴속에 가두어 둘 수 없다.","r":"117:6.10"},{"x":"사랑의 회로는 아버지에게서 나와 아들들을 통해 형제들에게 전해지고 최상위에 이른다.","r":["117:6.10"]},{"x":"사랑은 종교적 성장의 토양이며, 사랑은 종교의 본질이자 고등 문명의 원천이다.","r":["100:0.2","102:6.3"]}]},{"h":"예수가 계시한 사랑","items":[{"x":"예수는 사랑의 하나님을 계시했으며, 그 사랑은 진리와 아름다움과 선을 모두 포괄한다.","r":["5:4.6"]},{"q":"사랑은 모든 영적 실체 중에서 가장 위대하다.","r":"143:1.4"},{"x":"예수는 이웃을 자신처럼 사랑하라는 계명을 넘어 “내가 너희를 사랑한 것처럼 서로 사랑하라”는 새 계명을 주었다.","r":["180:1.1"]},{"x":"새 계명은 새로운 짐이 아니라 동료에게 애정을 나누는 새로운 기쁨을 주며, 친구를 위해 목숨을 버리는 것이 가장 큰 사랑이다.","r":["180:1.2","180:1.3"]},{"x":"주님의 사랑을 나누는 것은 그의 봉사를 나누는 것이며, 그 사랑은 새 세상을 만들지 않지만 옛 세상을 새롭게 한다.","r":["180:1.5"]},{"x":"빛과 생명의 세계에 사는 진보된 필사자들은 사랑이 우주에서 가장 위대함을 배웠고 하나님이 사랑임을 안다.","r":["56:10.20"]}]}],"see":["우주 아버지","자비","봉사","사람의 형제됨","선함","생각 조절자"],"n":60,"en":"Love"},{"t":"삼위일체 교사 아들","sum":"삼위일체 교사 아들(데이날)은 파라다이스 삼위일체에서 직접 나온 아들들로, 창조자 아들·치안 아들과 함께 파라다이스 아들의 셋째 계층을 이룬다. 그들은 다스리거나 심판하지 않고, 필사자와 영 존재 모두의 도덕적 깨달음과 영적 각성에 헌신하는 우주의 교육자들이다. 진화 세계에서는 영적 시대를 열어 행성을 빛과 생명의 시대로 이끄는 마지막 신성한 사역을 맡는다.","sections":[{"h":"삼위일체에서 나온 아들","items":[{"x":"파라다이스 삼위일체가 존재하게 한 아들들로, 하보나에서는 데이날, 오르본톤에서는 삼위일체 교사 아들, 샐빙턴에서는 파라다이스 영적 아들로 불린다.","r":["20:7.1"]},{"q":"이 존재들은 너희에게 계시된 하나님의 아들들 중에서 파라다이스 삼위일체에 기원을 두는 유일한 집단이다.","r":"19:1.3"},{"x":"기원은 삼위일체이지만 기능은 신성한 아들됨의 봉사여서, 삼위일체 기원 인격과 이중 기원 인격 사이를 잇는 연락 존재로 이중 자격을 지닌다.","r":["19:1.1"]},{"x":"수가 정해진 삼위일체의 고정 아들들과 달리 교사 아들은 계속 늘어나며, 보고된 수는 이백십억이 조금 넘고 그 밖에 큰 예비 인원이 파라다이스에 있다.","r":["19:1.2","20:7.2"]},{"x":"세 신의 연합된 본성을 공유하되, 하보나에서는 아버지를, 초우주에서는 영원 아들을, 지역 창조계에서는 무한 영을 더 드러내는 것처럼 보인다.","r":["20:7.4"]},{"q":"모든 우주에서 그들은 봉사의 화신이며 지혜의 분별이다.","r":"20:7.4"}]},{"h":"다스리지 않고 가르치는 아들","items":[{"x":"그들은 창조자도 회수자도 재판관도 통치자도 아니어서, 지역 우주나 초우주 정부의 유기적 부분이 아니다.","r":["20:7.3"]},{"q":"그들은 모든 영역의 영적 각성과 도덕적 지도에 헌신하는 보편적인 교육자들이다.","r":"20:7.3"},{"x":"중앙 우주의 예비 훈련 없이 곧바로 초우주 본부로 파견되며, 자기 영적 인력이 없어 창조자 아들과 치안 아들의 영적 영향력을 활용한다.","r":["20:7.5"]},{"x":"지역 체계에서 사역을 시작해 별자리를 거쳐 지역 창조계의 가장 높은 일로 나아가며, 필사자뿐 아니라 세라핌 등 지역 우주 원주민의 교육에도 똑같이 관심을 둔다.","r":["20:8.1","20:8.2"]},{"x":"우주 봉사의 하위 단계 자격 시험과 검사를 주관하는 교수진으로, 행성 과정부터 샐빙턴의 높은 지혜 대학까지 훈련 과정을 이끈다.","r":["20:8.3"]},{"x":"네바돈의 교육 체계는 교사 아들과 멜기세덱 교사 군단이 공동으로 관리하며, 우주 전체가 하나의 거대한 학교로 묘사된다.","r":["37:6.1","37:6.2"]},{"x":"창조체 삼위일체화 아들들을 견습생으로 입양해 훈련시키고, 삼위일체의 포용을 받도록 지명할 수 있다.","r":["22:8.3","22:8.4"]}]},{"h":"행성에 영적 시대를 연다","items":[{"x":"섭리 시대를 끝내거나 죽은 자를 심판하는 일과는 관계가 없고, 진화 행성에 영적 실체의 시대가 동트게 하는 일에 전적으로 관심을 둔다.","r":["20:9.2"]},{"q":"그들은 물질적 지식과 일시적 지혜의 영적 대응물을 실제가 되게 한다.","r":"20:9.2"},{"x":"한 행성의 교사 아들은 일흔 1차 아들, 열두 2차 아들, 최상 계층 셋의 도움을 받으며, 행성 시간으로 천 년 이상 머문다.","r":["52:7.2","20:9.3"]},{"q":"이 임무는 인간 거주 세계에서 사역해 온 모든 신성한 인격들의 선행 노력에 대한 삼위일체의 기여이다.","r":"52:7.2"},{"x":"필사자에게 보이도록 물질화하지 않으므로, 찬란한 저녁별들이 보이지 않는 교사 아들 군단과 필사자 사이의 연락책이 된다.","r":["20:9.3","37:2.9"]},{"x":"이 시대에는 많은 필사자가 살아서 변환되고, 조절자 융합이 늘면서 자연사가 점점 드물어진다.","r":["52:7.4"]}]},{"h":"유란시아와 빛과 생명의 미래","items":[{"x":"유란시아는 영적 시대를 겪어 본 적이 없어 이 아들들에게 익숙하지 않지만, 교사 아들들은 지금도 장래 체류를 계획하려고 이 세계를 방문한다.","r":["20:9.1"]},{"x":"그들은 이 세계의 거주자들이 동물성의 사슬과 물질주의의 족쇄에서 비교적 벗어난 뒤에 나타날 것이다.","r":["20:9.1"]},{"x":"예수가 약속한 재림이 치안 아들이나 교사 아들의 출현보다 먼저일지 나중일지는 아무도 알지 못한다.","r":["52:7.1"]},{"x":"반복되는 임무 가운데 하나가 끝날 때 행성 영주는 행성 주권자로 승격되고, 체계 주권자가 빛과 생명의 시대가 열렸음을 선포한다.","r":["52:7.10"]},{"q":"조만간 하나님의 은혜와 천사들의 사역이 삼위일체 교사 아들들 강림의 날을 열 것이며,","r":"52:7.14"},{"x":"진화 필사자의 생애와 오래 함께한 교사 아들들이 초우주가 빛과 생명에 정착할 때 최종자 군단과 영원히 연합하리라고 유버사에서는 믿는다.","r":["20:9.5"]}]},{"h":"세 파라다이스 아들의 협력","items":[{"x":"창조자 아들은 아버지의 성품을, 아보날은 영원 아들의 긍휼을, 데이날은 무한 영의 교사 인격을 드러내며, 함께 최상 하나님의 주권을 실현한다.","r":["20:10.4"]},{"q":"삼위일체 교사 아들들 안에서 세 파라다이스 신들의 사랑, 자비, 사역이 최고의 시공 가치 수준에서 조율되어, 살아 있는 진리, 신성한 선함, 참된 영적 아름다움으로 우주에 제시된다.","r":"20:10.3"},{"x":"교사 아들들은 삼위일체 기원의 최상 조율 인격들이다. 광대한 우주에는 협소한 관점과 분절된 실체 개념에 빠질 위험이 늘 크다.","r":["19:1.4"]},{"q":"그들은 모든 영 인격의 고귀한 스승이며, 심지어 하나님의 아들들 자신의 노련하고 진실한 스승이기도 하다.","r":"20:8.4"}]}],"see":["파라다이스 삼위일체","아보날 아들","창조자 아들 미가엘","빛과 생명","멜기세덱","최종자 군단"],"n":26,"en":"Trinity Teacher Sons"},{"t":"생각 조절자","sum":"생각 조절자는 우주 아버지에게서 직접 나와 사람의 마음속에 내주하는 하나님의 단편이다. 창조된 존재가 아니라 신성 그 자체이며, 사람이 아버지의 뜻을 행하도록 안에서 이끌고, 진화하는 혼과 하나 되어 영원한 생애로 함께 나아가려 한다. 유란시아서가 전하는 개인 종교의 중심에는 이 내주하는 아버지의 영이 있다.","sections":[{"h":"아버지에게서 온 신성한 단편","items":[{"x":"아버지는 파라다이스에 계시면서도 신비의 관찰자로서 사람의 마음속에 실제로 현존하신다.","r":["107:0.1"]},{"q":"그들은 창조된 존재가 아니며, 무한한 하나님의 단편화된 실체들로서 하나님의 실제적 현존을 구성한다.","r":"107:1.2"},{"x":"조절자는 범위는 한정되어 있지만 본질에서는 절대적이어서 ‘아버지의 제한된 절대 단편’이라 불린다.","r":["107:4.2"]},{"x":"조절자는 인격은 아니지만 우주에서 가장 순수한 계층의 참된 실체, 곧 신성한 현존이다.","r":["107:7.1"]},{"q":"어떤 조절자도 파라다이스 아버지께 불충한 적이 없다.","r":"107:4.3"}]},{"h":"언제, 어떻게 오는가","items":[{"x":"조절자는 아이가 첫 도덕적 선택을 내린 뒤에 배정되며, 유란시아에서는 평균 여섯째 생일 직전에 도착한다.","r":["108:2.1"]},{"x":"일곱 보조 마음 영의 준비와 성령의 회로 연결이 먼저 있어야 조절자가 마음에 들어올 수 있다.","r":["108:2.2"]},{"x":"완전한 조절자가 동물 기원의 필사자 안에 자원하여 머무는 것은 신성한 낮아짐의 경이로움이다.","r":["108:6.1"]},{"q":"조절자는 하나님으로부터 나와 인간을 찾아 육신 안에 있는 그 시절에도 그를 아들로 삼기 위해 온 존재이다.","r":"107:0.3"}]},{"h":"조절자가 하는 일","items":[{"x":"조절자의 근본 임무는 필사 창조체에게 우주 아버지를 대표하고, 바로 그 아버지가 되어 주는 것이다.","r":["108:0.1"]},{"x":"조절자는 이상적 삶의 계획을 가지고 오지만, 사람은 그 계획을 받아들이거나 거부할 자유를 가진다.","r":["110:2.1"]},{"x":"영적 지성체들의 권고를 받아 물질적 마음에 옮겨 전하는, 쉽지 않은 통역자의 일을 맡는다.","r":["108:5.1"]},{"q":"오직 가끔 너희는 신성한 목소리의 메아리, 희미하고 먼 메아리를 포착할 뿐이다.","r":"110:3.1"},{"x":"조절자는 마음 능력이 완전히 파괴되지 않는 한 모든 재난과 질병 속에서도 사람과 함께 있다.","r":["110:1.5"]}]},{"h":"조절자와 협동하는 삶","items":[{"q":"인간 존재의 위대한 목표는 내주하는 조절자의 신성에 조율되는 것이며,","r":"110:3.4"},{"x":"두려움·분노·시기·의심 같은 마음의 독소는 육체의 독소처럼 조절자의 일을 크게 지연시킨다.","r":["110:1.5"]},{"x":"혼란이나 낙담, 무지만으로는 생존이 막히지 않는다. 생존을 막는 것은 조절자의 인도에 대한 의식적 저항뿐이다.","r":["110:3.5"]},{"x":"구름이 몰려올 때 신앙은 조절자의 현존을 사실로 받아들이고 그 너머의 빛을 바라보아야 한다.","r":["108:6.8"]}]},{"h":"융합과 영원한 운명","items":[{"x":"조절자는 인간 혼 안에 육신화된 아버지 사랑이며, 시간 안에서 미리 맛보는 최종자 인격의 본질이다.","r":["107:0.2"]},{"x":"일곱 정신 원을 정복하는 것은 융합 자체가 아니라 융합에 이르는 준비 단계이다.","r":["110:6.1"]},{"q":"융합은 여전히 더 위대하고 더 숭고한 영적 성취, 즉 생각 조절자 안에 내주하는 하나님의 뜻과 필사 의지의 최종적이고 완전한 조율에 달려 있다.","r":"110:7.1"},{"x":"조절자와 완성된 창조체의 영원한 결합은 다른 어떤 우주 기법으로도 만들 수 없는 독특한 존재를 탄생시킨다.","r":["108:0.1"]}]}],"see":["조절자 융합","혼","인격","보조 마음 영","하나님의 뜻","생존"],"n":33,"en":"Thought Adjuster"},{"t":"생명 운반자","sum":"생명 운반자는 창조자 아들, 우주 어머니 영, 그리고 옛적부터 늘 계신 이 가운데 한 분이 함께 창조한 지역 우주의 아들로, 창조체 생명을 설계하여 행성에 심고 그 진화를 보살핀다. 생명의 불꽃은 그들을 통해 주어지지만 그 본질은 우주 어머니 영에게서 오며, 의지를 가진 존재가 나타나면 그들의 조작은 끝난다. 유란시아는 생명 변형 세계로서, 그 생명은 이 행성 위에서 새로 조성되었다.","sections":[{"h":"기원과 조직","items":[{"x":"생명 운반자는 창조자 아들, 우주 어머니 영, 그리고 지명된 옛적부터 늘 계신 이 한 분의 자손으로, 초우주 통치자가 창조에 참여하는 지역 우주 유일의 지성적 생명 집단이다.","r":["36:1.1"]},{"q":"그들은 창조체 생명을 설계하고 행성 구체들로 운반하는 책임을 위임받는다.","r":"36:0.1"},{"x":"지역 우주의 아들과 영은 멜기세덱 등 세 계층의 아들을 창조한 뒤, 칠중 하나님의 다음 수준과 협력하여 생명 운반자를 생산한다.","r":["35:0.7"]},{"x":"네바돈에는 일억 명이 창조되었으며, 가브리엘·아버지 멜기세덱·첫째로 태어난 생명 운반자 남비아로 된 생명 결정 삼인조의 지휘를 받는다.","r":["36:1.2"]},{"x":"선임 생명 운반자, 보조자, 관리인의 세 부문으로 나뉘며, 행성에 파견되는 군단은 보통 선임 백, 보조자 백, 관리인 천으로 이루어진다.","r":["36:1.3","36:3.2"]},{"x":"그들은 전기화학의 물리적 단계, 준(準)모론시아의 중간 단계, 반(半)영적 단계의 세 수준에서 기능할 수 있다.","r":["65:1.2","65:1.3","65:1.5"]}]},{"h":"생명을 설계하고 심다","items":[{"q":"생명은 우주에서 저절로 나타나지 않는다. 생명 운반자가 불모의 행성에서 그것을 시작해야 한다.","r":"36:3.1"},{"x":"샐빙턴 회로의 일곱 생명 운반자 세계에서 생명 계획, 보존, 진화, 마음과 연합된 생명 등을 연구하며, 원래의 생명 설계는 창조자 아들이 제공한다.","r":["36:2.1","36:2.12"]},{"q":"생명의 불꽃, 곧 생명의 신비는 생명 운반자들을 통해 증여되지, 그들에 의해 증여되는 것이 아니다.","r":"36:3.4"},{"x":"원형질을 공식화하는 것은 그들이지만, 몸을 살리고 마음을 예고하는 에너지 불꽃은 우주 어머니 영에게서 나온다.","r":["36:3.4"]},{"x":"생명을 줄 때 그들은 자기의 인격적 본성을 전혀 전달하지 않고, 살아 있는 촉매 현존으로서 물질의 필수적 회전을 시작할 뿐이다.","r":["36:3.5"]},{"q":"하나님의 아들들은 생명의 형태를 구성할 수 있지만, 실제로 생명의 불꽃을 기여하는 것은 하나님의 영이다.","r":"36:6.4"}]},{"h":"진화를 보살피는 일과 그 한계","items":[{"x":"새 세계에 생명을 확립하는 데 행성 시간으로 약 오십만 년이 주어지며, 그 기간이 끝나면 새로운 것을 더할 수 없다.","r":["36:3.6"]},{"x":"도덕적 존재가 나타나기까지 환경을 조작해 진화를 유리하게 이끌 수 있지만, 진화 과정에 기계적·자의적으로 간섭하는 것은 허락되지 않는다.","r":["36:3.7","65:3.2"]},{"q":"이 때문에 유란시아에서든 다른 어느 곳에서든, 진화는 언제나 목적을 지니며 결코 우연적으로 일어나지 않는다.","r":"65:0.7"},{"x":"의지를 가진 존재가 나타나면 그들의 일은 끝나며, 행성을 떠나거나 진화에 더는 영향을 주지 않겠다는 포기 서약을 해야 한다.","r":["36:3.8","65:1.8"]},{"x":"유란시아에는 지금도 선임 생명 운반자 둘과 관리인 열둘이 포기 서약을 하고 조언자로 남아 있다.","r":["36:3.9"]},{"x":"행성의 물리적 발달보다 생명이 빨리 전개되게 할 수 없으므로, 생명 운반자들은 지질학적 진화를 기다려야 한다.","r":["58:1.2","65:8.2"]}]},{"h":"유란시아의 생명 실험","items":[{"x":"유란시아는 십진 행성, 곧 생명 변형 세계로서 생명 운반자들이 표준 생명 설계를 수정하고 개선하려 시도한 곳이다.","r":["58:0.1","65:4.1"]},{"q":"유란시아의 생명은 독특하며 이 행성 고유의 것이다.","r":"58:4.1"},{"x":"유란시아 원형질은 소금 용액에서만 기능하도록 계획되었기에, 바닷물이 충분히 짜질 때까지 이식을 기다렸다.","r":["58:1.3"]},{"x":"5억5천만 년 전 생명 운반자 군단이 돌아와, 갈라지는 대륙 사이 중앙 바다의 보호된 열대 만에 세 차례 해양 생명을 심었다.","r":["58:4.2","58:4.4"]},{"x":"상처 치유의 화학 공식은 오십만 회 넘는 실험 끝에 선택된 것으로, 인간 생명이 지능적으로 계획되었음을 보여 준다.","r":["65:4.3","65:4.4"]},{"x":"유란시아는 유색 인종 이전의 인종에서 인간 유형의 의지가 나타난 사타니아의 유일한 행성이다.","r":["65:4.11"]}]},{"h":"생명과 마음과 영","items":[{"x":"일곱 보조 마음-영은 늘 생명 운반자와 함께 새 행성으로 가며, 그 중앙 배치 거점이 생명 운반자 본부 세계에 있다.","r":["36:5.4","36:2.10"]},{"q":"생명은 오직 생명에서만 비롯된다.","r":"36:6.2"},{"x":"그들이 샐빙턴 세계에서 조직하는 실험적 생명 형태는 언제나 번식 능력이 없다.","r":["36:6.3"]},{"x":"생명이 아버지를 통해 아들을 거쳐 영에 의해 흐른다는 것은 알지만, 생명 활성화 불꽃의 본질과 근원은 그들도 온전히 이해하지 못한다.","r":["36:6.7"]},{"x":"우주가 빛과 생명에 정착할 때 그들은 완전히 영적인 넷째 존재 단계에 이르기를 기대한다.","r":["65:1.9"]}]}],"see":["진화","지역 우주 어머니 영","보조 마음 영","유란시아","멜기세덱","창조자 아들 미가엘"],"n":30,"en":"Life Carriers"},{"t":"생존","sum":"생존은 필사 인격이 육신의 죽음을 넘어 모론시아 세계에서 다시 깨어나 영원한 상승을 이어 가는 것이다. 유란시아서는 생존이 하나님이 주시는 선물이지만 사람이 스스로 원하고 선택해야 하는 선물이라고 말한다. 살아남는 것은 조절자와 함께 지은 혼이며, 그 열쇠는 지식이나 교리가 아니라 하나님을 찾고 그분처럼 되려는 진실한 결심과 살아 있는 신앙이다.","sections":[{"h":"생존은 선택된 선물","items":[{"q":"생존은 시간의 창조체들이 원해야만 하는 신들의 선물이다.","r":"110:2.2"},{"x":"인간 정체성은 인격이 지속적인 우주 현상이 되기를 선택하는 한에서만 실제적이며, 그 길은 자유 의지로 추구해야 한다.","r":["112:5.3"]},{"x":"인격은 신의 운명에 이르도록 되어 있지만, 사람은 그 성취의 자리에 자신이 있을지 없을지를 스스로 선택해야 한다.","r":["112:5.2"]},{"x":"생존을 거부하는 능력은 루시퍼 반란 때 생긴 것이 아니라 필사자가 늘 지녀 온 선택의 부여물이다.","r":["54:6.9"]},{"q":"에너지 체계는 계속되어야 하며 선택의 여지가 없지만, 인간은 자신의 운명을 결정하는 데 전적으로 관여한다.","r":"112:5.3"}]},{"h":"무엇이 살아남는가","items":[{"x":"물질적 몸과 마음이 죽은 뒤에도 살아남는 실체는 혼, 곧 인간과 조절자가 함께 낳은 모론시아 자아이다.","r":["112:5.12"]},{"x":"죽음 뒤 조절자는 생애의 기억 기록을 지니고 디비닝턴으로 가고, 혼은 운명의 수호자가 보관한다.","r":["112:3.5"]},{"x":"생존할 자아는 정체성의 자리를 물질적 몸에서 불멸하는 모론시아 혼으로 옮김으로써만 진화한다.","r":["112:2.20"]},{"x":"영적 의미가 없는 기억은 뇌와 함께 사라지지만, 인격과 인격 사이의 관계에 대한 기억은 우주적 가치를 지니고 남는다.","r":["112:5.22"]},{"x":"사람은 내주하는 신성의 불꽃과 정체성이 하나 됨으로써 필사 죽음을 넘어 생존한다.","r":["132:3.6"]}]},{"h":"생존의 조건","items":[{"q":"생존의 비밀은 하나님과 같이 되고자 하는 최상의 인간적 욕망과, 그 압도하는 욕망의 최종 성취에 필수적인 모든 것을 행하고 그것이 되려는 그에 결부된 기꺼이 하려는 마음속에 싸여 있다.","r":"110:3.2"},{"x":"생존의 성패는 믿음의 이론보다 결정과 결심, 굳건한 신앙에 달려 있다.","r":["110:3.2"]},{"q":"오직 조절자의 인도에 대한 의식적인 저항만이 진화하는 불멸의 혼의 생존을 막을 수 있다.","r":"110:3.5"},{"x":"무지나 혼란, 두려운 의심만으로는 하나님을 아는 혼의 생존이 막히지 않는다.","r":["110:3.5"]},{"x":"하나님의 뜻을 행하는 것은 생존과 생존 속의 완전에 이르는 비밀이다.","r":["111:5.2"]}]},{"h":"신앙과 생존의 확신","items":[{"x":"종교 체험은 마침내 하나님에 대한 확실한 의식과, 신앙을 가진 인격이 생존하리라는 의심 없는 확신으로 이어진다.","r":["101:1.6"]},{"x":"예수는 신앙으로 한 번 하나님의 아들로 자신을 세웠다면 생존의 확실성에 대해 더 걱정할 것이 없다고 가르쳤다.","r":["176:3.3"]},{"x":"부활하신 예수는 생존이 먼저 진리와 하나님을 찾는 영에서 태어나는 데 달려 있다고 말했다.","r":["193:2.2"]},{"q":"최상 가치의 생존을 믿는 신앙이 종교의 핵심이며,","r":"111:3.5"},{"x":"신앙으로 활성화된 혼은 하나님을 찾는 과업을 지니고 있기에 멈출 수 없고, 목표에 이르면 결코 끝나지 않는다.","r":["132:3.7"]}]},{"h":"자비로운 판결과 다양한 생존 계층","items":[{"x":"모든 의지 창조체는 의심할 여지 없는 최종 선택을 할 수 있는 한 번의 진정한 기회를 반드시 체험하게 된다.","r":["112:5.9"]},{"x":"자기 잘못 없이 지상에서 원들을 통달하지 못한 이에게도 생존의 뜻이 있다면 보호 관찰 연장이 주어진다.","r":["112:5.6"]},{"x":"판결이 애매할 때 우주 정부는 언제나 그 개인에게 유리한 쪽으로 결정한다.","r":["112:5.7"]},{"x":"생존자는 섭리 시대 집단 소집, 개별 상승, 수습 의존 등 여러 계층으로 나뉘어 맨션 세계에 이른다.","r":["49:6.4","49:6.8","49:6.11"]},{"x":"셋째 원 이상에 이르러 개인 수호자를 받은 이들은 죽음 후 셋째 날 맨션 세계에서 재인격화될 수 있다.","r":["49:6.9","112:4.12"]},{"q":"우리는 어느 진화 세계의 고투하는 한 필사자에게서 상승 생애를 추구하는 영원한 기쁨을 박탈할 위험을 무릅쓰느니 차라리 체계 반란의 위험을 감수하겠다.","r":"112:5.8"}]}],"see":["죽음","혼","생각 조절자","맨션 세계","자유 의지","신앙"],"n":42,"en":"Survival"},{"t":"선함","sum":"선함은 진리·아름다움과 함께 신성을 이해하는 세 길 가운데 하나이지만, 오직 인격과의 관계 속에서만 이해된다. 하나님의 본원적 완전함은 그 본성에 내재한 선하심의 완전함에 있으며, 그 선하심은 개인적 종교 체험에서만 온전히 드러난다. 사람에게 선은 언제나 상대적이고 자라나는 것이어서, 파라다이스에 이르기까지 소유라기보다 추구이다. 하나님의 선하심은 사람을 회개로 이끈다.","sections":[{"h":"하나님의 선하심","items":[{"q":"하나님의 본원적 완전함은 가정된 의로움에 있는 것이 아니라, 그분의 신성한 본성에 내재한 선하심의 완전함에 있다.","r":"2:2.5"},{"q":"하나님의 선하심은 신성한 자유 의지성의 바탕에 놓여 있으니, 이는 사랑하고, 자비를 보이며, 인내를 나타내고, 용서를 베푸는 보편적 성향이다.","r":"2:6.9"},{"x":"하나님은 지극히 위대하시고 선하시며, 위대함과 선함은 하나님 안에서 분리될 수 없이 하나이다.","r":["28:6.21"]},{"x":"아버지의 무한한 선하심은 유한한 마음이 이해할 수 없어, 상대적 불완전함과의 대조 속에서만 식별된다.","r":["4:3.6"]},{"x":"최상 하나님은 진리·아름다움·선함이니, 이 개념들은 관념적 체험의 유한한 최대치이다.","r":["117:1.7"]}]},{"h":"인격과 종교에서의 선함","items":[{"x":"진리와 아름다움의 개념은 인격 없이도 품을 수 있지만, 신성한 선함은 오직 인격과의 관계 속에서만 이해된다.","r":["1:7.3"]},{"x":"하나님의 선하심은 개인적 종교 체험의 영적 세계에서만 발견되며, 종교는 본질적으로 그 선하심에 대한 신앙-신뢰이다.","r":["2:6.1"]},{"q":"인간은 위대한 하나님을 두려워할 수는 있으나, 오직 선한 하나님만을 신뢰하고 사랑한다.","r":"2:6.1"},{"x":"선은 신성한 완전성의 여러 수준에 대한 상대적 가치를 마음으로 인지하는 것이며, 선과 악을 분별하는 도덕적 마음을 전제한다.","r":["56:10.12"]},{"x":"선은 윤리와 도덕과 종교, 곧 체험적 완전성을 향한 갈망을 포괄한다.","r":["56:10.10"]}]},{"h":"선은 상대적이고 자라난다","items":[{"x":"선과 악은 관찰 가능한 우주에 대한 인간 이해의 상대적 수준을 나타내는 말이다.","r":["132:2.2"]},{"x":"사회 관례나 종교 전통을 선의 기준으로 삼지 말고, 내주하는 영이 세운 영적 기준으로 선을 선택해야 한다.","r":["132:2.2"]},{"x":"체험이 선이 되는 것은 아름다움의 감상을 깊게 하고 도덕적 의지를 강화하며 동료를 사랑하고 섬기는 능력을 넓힐 때이다.","r":["132:2.5"]},{"q":"네가 파라다이스 수준에 도달할 때까지, 선은 언제나 소유라기보다는 추구이며, 성취의 체험이라기보다는 목표일 것이다.","r":"132:2.8"},{"x":"우주의 척도를 오를수록 선은 늘고 악은 줄어들며, 파라다이스에서 선은 더 이상 대조적이지 않고 완전해진다.","r":["132:2.6","132:2.9"]},{"q":"선은 살아 있고, 상대적이며, 언제나 진보하고, 언제나 인격적 체험이며, 영원히 진리와 아름다움의 분별과 연관된다.","r":"132:2.7"}]},{"h":"선과 악의 가능성","items":[{"x":"악의 가능성은 도덕적 선택에 필수적이지만, 실제 악이 반드시 존재해야 하는 것은 아니다.","r":["132:2.10"]},{"x":"세상에 선과 악이 있다는 사실은 그 사이에서 선택하는 도덕적 의지를 지닌 인격이 실재한다는 증거이다.","r":["132:2.8"]},{"x":"영적 진화는 선을 점점 더 자발적으로 선택하는 체험이며, 그에 따라 악의 가능성은 줄어든다.","r":["132:3.8"]},{"x":"어떠한 선한 행위도 결코 온전히 사라지지 않으며, 그 동기의 신성함에 비례하여 영원히 효력을 지닌다.","r":["48:6.7"]}]},{"h":"선함이 사람을 이끄는 길","items":[{"q":"하나님의 선함은 회개로 이끌고, 하나님의 자비로운 혜택은 봉사로 이끌며, 하나님의 자비는 구원으로 이끌고, 하나님의 사랑은 지성적이고 자유로운 예배로 이끈다.","r":"149:6.4"},{"x":"선함은 은혜가 없으면 존경은 받아도 애정을 밀어내며, 은혜로울 때만 보편적으로 매력적이다.","r":["171:7.2"]},{"x":"행동의 의로움은 동기로 판단되어야 하므로, 가장 높은 선은 무의식적인 것이다.","r":["170:3.9"]},{"x":"진리를 배제하고 아름다움을 소홀히 한 채 선하심만 지나치게 강조한 고립된 도덕성은 많은 현대인의 마음을 붙잡지 못한다.","r":["2:7.9"]},{"x":"모든 참된 선하심은 개인 도덕이든 사회적 공정이든 신성한 사역이든 똑같이 참되고 아름답다.","r":["2:7.11"]}]}],"see":["진리","아름다움","악","도덕성","사랑","우주 아버지"],"n":59,"en":"Goodness"},{"t":"성령","sum":"성령은 지역 우주 어머니 영, 곧 신성한 사역자가 자기 우주에 펼치는 영 회로이자 그녀의 인격적 영향이다. 파라다이스 무한 영의 창조적 딸에게서 나오므로 그 지역 우주에 고유하며, 샐빙턴에 있는 그녀의 인격적 현존에 매여 있다. 예배와 지혜의 보조 영이 작동하는 마음은 곧 이 회로에 연결되는데, 이것이 인간이 받는 최초의 초(超)마음 부여물로서 조절자를 맞이할 바탕이 된다.","sections":[{"h":"어머니 영의 영 회로","items":[{"q":"성령은 파라다이스 무한 영의 창조적 딸의 영적 회로이다.","r":"8:5.3"},{"x":"성령은 각 지역 우주에 고유한 회로로 그 창조계의 영적 영역에 국한되지만, 무한 영은 어디에나 계신다.","r":["8:5.3"]},{"x":"거룩한 기록에서 ‘하나님의 영’이라는 말은 파라다이스의 무한 영과 지역 우주 창조 영을 번갈아 가리키는 듯하다.","r":["8:5.3"]},{"x":"네바돈의 세 영 회로 가운데 둘째가 신성한 사역자의 영 회로, 곧 성령이다.","r":["34:4.3","15:9.13"]},{"x":"성령은 무한 영과 우주 어머니 영의 영으로서 흔히 ‘우주 영의 영’으로 여겨지며, 삼중 영 은사 가운데 ‘영의 영’이다.","r":["194:2.17","194:2.11"]},{"x":"필사자도 무한 영의 현존을 알 수 있으니, 지역 우주가 증여한 성령으로 일하는 그 은혜를 실제로 체험하기 때문이다.","r":["9:2.5"]}]},{"h":"샐빙턴에 매인 현존","items":[{"q":"신성한 사역자의 성령은 만일 그녀의 인격적 현존이 샐빙턴에서 제거된다면 기능하지 않게 될 것이다.","r":"34:4.7"},{"x":"어머니 영은 우주 본부 세계를 결코 떠나지 않으며, 자신의 성령뿐 아니라 진리의 영의 우주 초점으로도 활동한다.","r":["34:4.7"]},{"x":"성령과 진리의 영은 지역 우주 본부에서 나와, 보조 마음-영들의 사역과 함께 물질적 마음의 낮은 수준에 이른다.","r":["56:3.3"]},{"x":"성령은 “모든 것을 살피므로” 샐빙턴의 어머니 영은 필사자를 온전히 안다.","r":["28:5.22"]}]},{"h":"최초의 초(超)마음 부여물","items":[{"q":"인간의 첫 초(超)마음 부여물은 우주 창조 영의 성령 안에서 인격이 회로화되는 것이다.","r":"103:0.1"},{"x":"이 영향은 신성한 아들의 증여나 조절자의 보편적 증여보다 훨씬 앞서 작용하며, 인간의 윤리·종교·영성의 시야를 넓힌다.","r":["103:0.1"]},{"q":"성령—최초의 초(超)마음 부여로서, 모든 참된 인간 인격에게 반드시 나타난다.","r":"92:0.4"},{"x":"예배와 지혜를 바라는 마음에 대한 이 사역은 인간 생존을 개념으로도, 실제 체험으로도 깨닫게 하는 능력을 낳는다.","r":["92:0.4"]},{"x":"예배와 지혜의 보조자가 기능하는 마음은 즉시 신성한 사역자의 영적 회로에 포함된다.","r":["34:5.3","36:5.15"]},{"x":"성령의 사역을 받은 마음은 조절자를 선택할 능력을 지니며, 조절자는 보조 영의 준비와 성령 회로 연결 뒤에야 들어온다.","r":["34:5.4","108:2.2","110:6.13"]}]},{"h":"내면의 사역과 영의 열매","items":[{"x":"영적 이성, 곧 혼의 지성은 창조 영이 사람에게 주는 선물인 성령의 부여물이다.","r":["101:3.2"]},{"x":"성령은 일부는 인간의 태도와 무관하게, 일부는 의지의 협력에 따라 일하며, 인도를 온전히 따르는 이의 내면을 성화한다.","r":["34:5.5"]},{"q":"이론적 진리의 씨앗은 죽었고, 가장 높은 도덕 개념도 효과가 없다. 신성한 영이 진리의 형태에 숨을 불어넣고 의로움의 공식들을 살리기 전까지는 말이다.","r":"34:6.6"},{"q":"영은 결코 강요하지 않고, 오직 인도할 뿐이다.","r":"34:6.11"},{"x":"영의 인도를 받는 삶에는 사랑·기쁨·평화 같은 영의 열매가 드러나며, 하나님의 왕국은 성령 안에서의 의로움과 평화와 기쁨이다.","r":["34:6.13","137:8.9"]},{"x":"빛과 생명에 정착된 세계에서는 시대가 흐를수록 성령과 천사들의 사역이 더욱 효과적이 된다.","r":["55:6.4"]}]},{"h":"다른 영 사역과의 하나됨","items":[{"x":"사람은 창조자 아들이나 어머니 영의 분리된 일부를 소유하지 않으며, 이 사역들은 조절자처럼 마음속에 내주하지 않는다.","r":["34:5.6"]},{"x":"필사자 안에 성령과 진리의 영, 조절자가 함께 있는 것은 영적 부여의 대칭이며, 하나님의 아들됨을 깨달을 자격을 준다.","r":["34:5.7"]},{"q":"기원이 복수일지라도 모든 영적 영향은 기능에 있어 하나이다.","r":"34:6.2"},{"x":"조절자, 진리의 영, 성령이라는 세 초필사 부여물은 최상위의 사역으로서 인간 체험 속에 하나로 통합된다.","r":["101:2.12","113:4.6"]},{"x":"상승자는 성령 같은 영 회로를 이용할 뿐 소유하지 않으며, 이 회로들은 인격 안에서 출현하는 가치를 최상위에게 전한다.","r":["117:5.8"]}]}],"see":["지역 우주 어머니 영","무한 영","보조 마음 영","진리의 영","생각 조절자","하나님 나라"],"n":40,"en":"Holy Spirit"},{"t":"성장","sum":"성장은 실제적인 것과 잠재적인 것이 결합하여 가치가 체험으로 실현되는 과정이며, 완전한 하보나와 달리 진화하는 대우주와 최상 존재를 특징짓는 표지이다. 사람의 영적 성장은 필요의 각성에서 의미의 분별과 가치의 발견으로 나아가며, 언제나 무의식적으로 이루어진다. 사람은 성장을 만들어 낼 수 없지만, 최상 가치에 대한 헌신과 살아 있는 신앙으로 그 조건을 마련할 수 있다.","sections":[{"h":"성장의 본질","items":[{"q":"실제적인 것과 잠재적인 것이 결합될 때 성장이 이루어지며, 이것이 곧 가치의 체험적 실현이다.","r":"100:3.6"},{"x":"성장은 단순한 진보가 아니다. 진보는 의미가 있지만, 성장이 없으면 상대적으로 가치가 없다.","r":["100:3.6"]},{"x":"가치는 결코 고정되어 있지 않으며, 의미가 넓어지고 가치가 높아지지 않는 변화는 잠재적 악이다.","r":["100:3.5"]},{"x":"인간 삶의 최상 가치는 가치의 성장과 의미의 진보, 그리고 그 둘의 우주적 관련을 깨닫는 데 있다.","r":["100:3.6"]},{"x":"부분의 성장은 전체의 성숙과 같지 않으며, 정신 원을 통과하려면 인격 전체가 조화롭게 자라야 한다.","r":["110:6.3"]}]},{"h":"성장하는 우주와 최상 존재","items":[{"q":"성장은 체험적 신의 표식이다. 하보나는 성장하지 않았다.","r":"116:0.3"},{"x":"체험적 성장은 창조체와 창조주의 동반 관계, 곧 하나님과 사람의 연합을 뜻한다.","r":["116:0.3"]},{"x":"최상 존재는 먼저 삼위일체에서 비롯된 영 인격이고, 둘째로 진화적 성장의 신이다.","r":["115:4.2"]},{"x":"전체의 성장은 부분들의 성장을 모두 합한 것이며, 그 완성은 전능 최상위의 행위이다.","r":["116:6.6"]},{"x":"창조적 성장은 끝이 없으나, 그 사이사이 만족스러운 목표 성취의 순간들이 새 모험의 전주곡이 된다.","r":["118:0.10"]}]},{"h":"영적 성장의 단계와 표지","items":[{"q":"영적 성장은 먼저 필요에 대한 각성으로 시작되고, 다음은 의미의 분별, 그리고 가치의 발견으로 이어진다.","r":"100:2.2"},{"x":"참된 영적 발달은 사랑으로 동기 부여되고 이타적 사역으로 활성화되며 온전한 예배로 다스려지는 삶에서 드러난다.","r":["100:2.2"]},{"x":"영적 발달은 참된 영적 세력과의 살아 있는 연결을 유지하고, 받은 것을 동료와 나누며 열매를 맺는 데 달려 있다.","r":["100:2.1"]},{"x":"영적 성장은 다른 종교인들과의 친밀한 교제로 서로 자극받으며, 사랑은 그 성장의 토양이다.","r":["100:0.2"]},{"x":"충성스러운 사람은 성장하는 사람이며, 아이들은 함께 지내는 어른들의 충성심에서 지속적인 인상을 받는다.","r":["100:1.4"]}]},{"h":"성장을 돕는 조건","items":[{"q":"인간은 성장을 일으킬 수는 없지만, 그에 유리한 조건을 만들 수 있다.","r":"100:3.7"},{"x":"성장은 육체적이든 지적이든 영적이든 언제나 무의식적이며, 사랑처럼 자라나야 하는 것이다.","r":["100:3.7","100:1.9"]},{"x":"신성한 가치에 대한 민감함, 성찰적 명상, 예배하는 자세의 문제 해결, 이기심 회피 같은 습관이 성장을 돕는다.","r":["100:1.8"]},{"x":"성장을 향한 타고난 추진력은 최상 가치에 전심으로 헌신하는 태도로 가장 확실하게 길러진다.","r":["100:1.6"]},{"q":"영적 성장은 외부 압박이 최소한일 때 가장 크게 일어난다.","r":"103:5.11"}]},{"h":"성장을 가로막는 것과 예수의 가르침","items":[{"q":"어떤 사람들은 너무 바빠서 성장하지 못하고, 그로 인해 영적 고착 상태의 심각한 위험에 처해 있다.","r":"100:1.2"},{"x":"예수는 성품을 쌓으라고 가르치지 않고 성품의 성장을 가르쳤으며, 하늘 왕국을 겨자씨에 비유했다.","r":["140:8.27","151:4.2"]},{"x":"혼은 살아 있는 성장체이며, 마음과 도덕은 그 더 높은 표현이 솟아날 토양이라고 예수는 목수의 비유로 가르쳤다.","r":["156:5.2"]},{"x":"참된 신자는 어제보다 오늘, 작년보다 올해 선함을 드러내는 데 더 능숙해지는지 스스로 물어야 한다.","r":["156:5.15"]},{"x":"모론시아 생애는 미루는 버릇과 회피 같은 동물적 잔재를 영원히 뿌리 뽑아 성장을 이어 가게 한다.","r":["48:5.8"]}]}],"see":["체험","최상 존재","혼","완전을 향한 여정","역경과 시련","개인적 종교"],"n":72,"en":"Growth"},{"t":"세 절대자","sum":"세 절대자는 잠재성의 절대자들, 곧 신 절대자·무제한 절대자·우주 절대자이다. 신 절대자는 모든 신 잠재력의 총체이고, 무제한 절대자는 신화되지 않은 실체와 모든 비인격적 잠재의 최종성이며, 우주 절대자는 이 둘을 통일하고 조율한다. 이들은 아버지의 자유 의지에 따른 실체 분화와 함께 영원히 존재하며, 유한한 우주와 인격이 무한과 함께 존재할 수 있게 하는 우주적 바탕이다.","sections":[{"h":"실체의 분화와 세 절대자","items":[{"x":"전체 무한 실체는 일곱 동격 절대자로 존재하며, 그 가운데 셋이 신 절대자·우주 절대자·무제한 절대자이다.","r":["0:3.1","104:3.5"]},{"x":"아버지가 자유 의지로 실체를 신화된 것과 신화되지 않은 것으로 나누었을 때 생긴 근원적 긴장을 우주 절대자가 해소한다.","r":["0:3.21","0:4.5"]},{"x":"하보나가 창조될 때 아버지는 그 현존을 무한 잠재력에서 분리했고, 이 잠재력은 무제한 절대자 안에 감추어진 채 신 절대자에 둘러싸여 있다.","r":["0:11.1"]},{"q":"궁극적인 분석과 최종적인 이해에 따르면 이 셋 모두는 하나의 절대자이다.","r":"0:11.15"},{"x":"아(亞)무한 수준에서는 세 절대자가 따로 존재하지만, 무한에서는 하나로 보인다.","r":["56:9.1"]}]},{"h":"신 절대자","items":[{"x":"신 절대자는 우주 실체의 인과적이고 잠재적으로 인격적인 가능성들, 곧 모든 신 잠재력의 총체이다.","r":["105:3.6"]},{"q":"신 절대자는 절대자를 제한하는 자요 제한된 것을 절대화하는 자, 곧 운명의 창시자이다.","r":"105:3.6"},{"x":"신 절대자는 어떤 상황에도 아절대적으로 반응하지 않으며, 언제나 전체 창조와 모든 미래 영원의 안녕이라는 관점에서 반응하는 듯하다.","r":["0:11.5"]},{"x":"영의 존재적 가치는 우주 아버지, 아들-영, 신 절대자로 이루어진 삼자일체에서 기원과 운명을 찾는다.","r":["104:4.20","104:4.21"]},{"x":"영원 아들은 실제적 영 가치를 지배하고, 신 절대자는 아직 잠재적인 영 가치의 방대한 영역에 스며 있는 듯하다.","r":["7:1.10"]},{"x":"절대 하나님은 지금 신 절대자로 존재하며, 절대 삼위일체의 기능을 통해 체험적으로 인격화될 가능성이 상정된다.","r":["0:2.18","106:6.6"]},{"q":"나는 아버지 하나님을 사랑하고 예배하며, 신 절대자를 존중하고 공경한다.","r":"10:8.5"}]},{"h":"무제한 절대자","items":[{"x":"무제한 절대자는 비인격적이고 신성이 없으며, 사실·진리·체험·계시 그 무엇도 그 본질을 꿰뚫지 못한다.","r":["0:11.7"]},{"q":"무제한 절대자는 무한에서의 적극적 우주 상위통제이다.","r":"0:11.8"},{"x":"그것은 범신론적 개념이나 옛 과학의 에테르 가설 같은 막연한 영향력이 아니라, 대우주와 그 너머 공간에 걸친 실제 현존이다.","r":["0:11.8","0:11.9"]},{"x":"무제한 절대자는 파라다이스와 동격이며, 모든 공간에서 오직 그 현존만이 고요하다.","r":["105:3.4","105:3.7"]},{"x":"아직 파라다이스 중력에 반응하지 않는 에너지인 우주적 힘은 무제한 절대자로부터 유래한다.","r":["0:6.5"]}]},{"h":"우주 절대자","items":[{"x":"우주 절대자는 신화된 것과 신화되지 않은 것을 통일하고, 절대적인 것과 상대적인 것을 상관시킨다.","r":["105:3.8"]},{"q":"유한자는 우주에서 무한자와 같이 존재할 수 있다.","r":"0:11.13"},{"x":"그것이 가능한 까닭은 우주 절대자가 시간과 영원, 유한과 무한, 인간과 하나님 사이의 긴장을 고르게 해 주기 때문이다.","r":["0:11.13"]},{"x":"무제한 절대자와 신 절대자 사이의 무한 잠재력 차이가 물질 우주와 시간 속 유한 인격의 존재를 가능하게 한다.","r":["0:11.12"]},{"x":"마음 회로와 나란히 작용하는 예측할 수 없는 현존은 부분적으로 우주 절대자의 기능에서 비롯된다고 여겨진다.","r":["9:6.8"]}]},{"h":"잠재성의 삼극일체와 운명","items":[{"x":"세 절대자의 연합은 삼위일체가 아니라 잠재성의 삼극일체이다. 셋 모두가 신은 아니기 때문이다.","r":["104:5.7","106:5.4"]},{"x":"잠재성의 삼극일체는 영적·마음적·우주적인 모든 잠복 에너지 실체를 상호 연관시키며, 잠재성에서 무한하다.","r":["104:5.11"]},{"x":"잠재자는 부분적으로는 시간 속에서 실현되지 못할 수 있어도 총체적으로는 실패하지 않으며, 하나님의 뜻은 결국 우세하다.","r":["115:3.13"]},{"x":"세 절대자 안에는 어떤 체험적 발달로도 다 소진될 수 없는 미지의 가능성이 언제나 남아 있다.","r":["106:7.1"]},{"q":"하나님을 찾는 여정은 끝이 없다!","r":"106:7.5"},{"x":"절대자는 범신론적 비인격 신이 아니며, 우주 인격에 관련된 모든 것에서 엄격히 삼위일체에 제한되고 신의 지배를 받는다.","r":["0:11.16"]}]}],"see":["파라다이스 삼위일체","우주 아버지","파라다이스","궁극 하나님","실체","에너지와 물질"],"n":10,"en":"The Three Absolutes"},{"t":"세라핌","sum":"세라핌은 지역 우주 어머니 영이 창조한 천사로, 체루빔·사노빔과 함께 지역 우주의 봉사 영 군단을 이룬다. 물질 몸은 없지만 개별적 인격을 지닌 영 존재로서 인간을 이해하고 사랑하며, 최상 세라핌부터 미래의 세라핌까지 일곱 계층으로 나뉘어 행정·교육·수송·기록·행성 감독 등 지역 우주의 거의 모든 일을 돕는다. 그들 자신도 세라핑턴을 거쳐 파라다이스에 이르는 운명을 지닌 상승 존재이다.","sections":[{"h":"기원과 본성","items":[{"x":"세라핌은 우주 어머니 영이 한 번에 41,472씩 투사하여 창조하며, 네바돈은 아직 만들어지는 중이므로 지금도 주기적으로 창조된다.","r":["38:1.1","38:1.3"]},{"x":"중앙 우주의 수퍼나핌, 초우주의 세코나핌처럼 지역 우주에서는 세라핌이 체루빔·사노빔과 함께 천사 군단을 이룬다.","r":["38:0.2"]},{"q":"천사는 물질적 육체를 지니지 않지만, 분명하고 개별적인 존재이며, 영의 본성과 기원을 지닌다.","r":"38:2.1"},{"x":"인간의 도덕적 투쟁과 영적 어려움을 충분히 알고, 음악과 예술과 진정한 유머를 즐기며, 인간을 사랑한다.","r":["38:2.1"]},{"x":"성 감정의 창조체는 아니지만 애정이 깊으며, 음성과 양성의 짝을 이루어 살고 대부분의 임무를 둘이서 수행한다.","r":["38:2.2","38:4.3"]},{"q":"천사들은 인류를 심판하는 자리에 앉지 않으며, 개별 필사자들도 동료 창조체들을 미리 판단해서는 안 된다.","r":"38:2.4"},{"x":"천사를 사랑하는 것은 좋지만 경배해서는 안 된다. 천사는 하나님께 예배하는 인간의 동료 종이다.","r":["38:2.5"]}]},{"h":"훈련과 조직","items":[{"x":"첫 천 년은 샐빙턴 학교들의 관찰자로, 둘째 천 년은 세라핌 세계에서 보내고, 별자리와 체계를 거친 뒤 시간의 봉사 영으로 임관된다.","r":["38:5.1","38:5.3"]},{"q":"우주에서 그들의 일은 끝도 한계도 없다.","r":"38:5.4"},{"x":"열두 쌍의 집단에서 중대, 대대, 단위, 군단, 무리, 천사 군대로 열두 배씩 커지는 조직을 이루며, 천사 군대는 찬란한 저녁별 등이 지휘한다.","r":["38:6.1","38:6.2"]},{"x":"예수가 겟세마네에서 말한 “열두 군단 이상의 천사”는 바로 이 세라핌 군단 단위를 가리킨다.","r":["38:6.1"]},{"x":"미가엘의 유란시아 증여 이후 세라핌과 모든 지역 우주 계층은 주(主) 아들의 주권 아래 들게 되었다.","r":["38:6.3"]},{"x":"체루빔과 사노빔은 세라핌과 기원이 같은 가장 낮은 계층의 천사로, 짝을 이루어 세라핌의 충직한 조력자로 일한다.","r":["38:7.1","38:7.3"]}]},{"h":"일곱 계층과 그 일","items":[{"x":"계시된 세라핌은 최상, 우수, 감독, 행정 세라핌과 행성 조력자, 전환 사역자, 미래의 세라핌의 일곱 계층으로 나뉜다.","r":["39:0.1","39:0.2","39:0.8"]},{"q":"자비는 세라핌 봉사와 천사 사역의 기조이다.","r":"39:2.5"},{"x":"수송 세라핌은 상승자를 감싸 세계에서 세계로 나르며, 감싸인 이는 정해진 시간 동안 잠들었다가 목적지에서 깨어난다.","r":["39:2.10","39:2.12"]},{"x":"감독 세라핌의 사회 건축가들은 진실된 사회적 접촉을 북돋우고, 효율적이고 조화로운 작업 집단이 이루어지도록 돕는다.","r":["39:3.4","39:3.5"]},{"x":"행정 세라핌의 도덕 촉진자들은 자유와 충성의 상호작용을 가르치고, 필사의 삶을 끊기지 않은 긴 사슬의 첫 고리로 그려 보인다.","r":["39:4.10","39:4.13"]},{"q":"하늘 왕국의 열쇠는 성실함, 더 많은 성실함, 그리고 더 많은 성실함이다.","r":"39:4.14"},{"x":"전환 사역자들은 맨션 세계에서 생존자의 모론시아 진보를 도우며, 모든 세라핌 가운데 인간에게 가장 가까이 다가서는 계층에 속한다.","r":["48:6.1","48:6.34"]}]},{"h":"행성에서의 천사 사역","items":[{"x":"아담 체제의 실패 뒤에도 행성 조력자 가운데 형제애의 영, 평화의 혼, 신뢰의 영은 유란시아에서 일을 계속하고 있다.","r":["39:5.4","39:5.5","39:5.8"]},{"x":"천사가 날개를 가졌다는 생각은 수송을 준비하는 세라핌을 관찰한 옛 체험의 전승에서 크게 비롯되었다.","r":["39:5.12"]},{"x":"진리의 영이 부어질 때 행성 감독의 주(主) 세라핌 열두 군단이 와서 시대, 진보, 종교, 국가, 인종, 교육, 건강, 가정, 산업, 오락 등을 돌본다.","r":["114:6.1","114:6.4"]},{"x":"진보 천사들이 새로운 진보를 촉진하는 동안 종교 수호자들은 낡은 형태 속의 불멸의 가치를 다음 세대로 옮겨 서로 균형을 이룬다.","r":["114:6.6","114:6.7"]},{"q":"이 천사 집단 중 어느 것도 그들이 배정된 영역에서 직접적이거나 임의적인 통제를 행사하지 않는다.","r":"114:6.18"}]},{"h":"세라핌의 운명","items":[{"x":"세라핌은 전문 봉사의 완전 성취, 세라핑턴으로의 소환, 진화 필사자의 수호 등 여러 길로 파라다이스에 이를 수 있다.","r":["39:8.2","39:8.3","39:8.4"]},{"x":"천사들은 세라핑턴에 이르기 전까지 자기의 영원한 미래를 확신하지 못하며, 세라핑턴에 도달한 천사가 이탈한 일은 알려진 적이 없다.","r":["39:8.9"]},{"x":"체루빔과 사노빔도 오랜 봉사와 우주 어머니 영의 거듭된 포용을 거쳐 완전한 세라핌으로 다시 태어날 수 있다.","r":["38:8.6"]},{"x":"완성 세라핌에게는 많은 길이 열려 있지만, 그들은 육신화된 파라다이스 아들의 증여 수행원으로 봉사하기를 가장 바란다.","r":["39:9.3"]},{"q":"모론시아 상승과 그 이후의 영 상승 전체에 걸쳐 세라핌과의 형제 관계는 이상적일 것이며, 너희의 동반 관계는 뛰어날 것이다.","r":"38:2.6"}]}],"see":["천사 무리","수호 세라핌","지역 우주 어머니 영","중도자","맨션 세계","모론시아"],"n":27,"en":"Seraphim"},{"t":"수호 세라핌","sum":"수호 세라핌은 개별 필사자를 돌보는 세라핌이다. 사람이 셋째 원에 이르거나, 하나님처럼 되기로 최상의 결정을 내리거나, 운명 예비 군단에 들면 개인 수호자, 곧 운명의 수호자가 배정된다. 그들은 인간 의지를 침범하지 않고 바깥 환경을 통해 일하며, 죽음 뒤에는 혼의 생존 가치를 보관했다가 맨션 세계에서 재인격화를 돕고 상승 여정에 동반한다. 세라핌에게 이 임무는 파라다이스로 가는 가장 확실한 길이다.","sections":[{"h":"수호 천사는 어떻게 배정되는가","items":[{"q":"수호 천사에 관한 가르침은 신화가 아니다.","r":"113:1.1"},{"x":"미가엘의 증여 이후 세라핌은 인종이 아니라 인간의 지성과 영성과 운명에 따라 배정된다.","r":["113:1.2"]},{"x":"보통 사람들은 원 달성에 따라 일곱째 원에서는 천 명, 여섯째 원 오백 명, 다섯째 원 백 명, 넷째 원 열 명 단위로 수호 세라핌의 돌봄을 받는다.","r":["113:1.6","113:1.7"]},{"x":"셋째 원에 이르면 한 개인 천사(실제로는 둘)가 그 필사자에게 온전히 헌신한다.","r":["113:1.8"]},{"x":"운명 예비 군단에 등록되거나 조절자와의 참된 약혼인 최상의 결정을 내리면, 어느 원에 있든 곧바로 개인 수호자가 배정된다.","r":["113:1.5"]},{"x":"행성 운명의 수호자로 선택된 예비 군단원에게는 행성 세라핌 우두머리가 개인 운명 수호자를 임명한다.","r":["114:7.2"]}]},{"h":"운명의 수호자","items":[{"x":"세라핌은 인간이 최상의 결정, 셋째 원 진입, 운명 예비 군단 편입 가운데 하나 이상을 이루기 전에는 운명의 수호자라 불리지 않는다.","r":["113:2.1"]},{"x":"유란시아에서 처음으로 개인 수호자를 받은 필사자는 오래전 홍인의 현자 란토웍이었다.","r":["113:2.2"]},{"x":"배정은 언제나 자원한 세라핌 가운데 체험 많고 검증된 이들에게서 이루어지며, 한 사람의 수호자 자리에 백 명이 넘는 세라핌이 지원한 일도 있다.","r":["113:2.3","113:2.7"]},{"x":"한 쌍 가운데 하나는 늘 임무 중에 있고, 보완자는 그 사람의 기록 천사가 되며 기록은 연결된 체루빔과 사노빔이 보관한다.","r":["113:2.7","113:2.9"]},{"x":"세라핌은 육신화한 아들의 수행과 운명 수호자 배속을 똑같이 갈망하는데, 후자는 파라다이스로 가는 가장 확실한 통행권이다.","r":["39:1.6"]},{"x":"천사들은 인간 동료에게 지속적인 애정을 품지만, 사람의 신앙마저 지배하는 동물적 공포만은 이해하기 어려워한다.","r":["113:2.5"]}]},{"h":"안이 아니라 바깥에서 돕는다","items":[{"x":"수호자는 무한 영의 여러 비인격적 영향을 인격적으로 조율하고, 그것을 아버지와 아들의 영 현존과 상관시킨다.","r":["113:3.1","113:3.2"]},{"q":"천사 봉사자들은 필사 창조체들에 대한 사역에서 아버지의 사랑과 아들의 자비를 결합하는 재능이 있다.","r":"113:3.3"},{"x":"조절자가 혼을 통해 안에서 일한다면, 세라핌은 인간의 사회적·윤리적·도덕적 환경을 통해 바깥에서 안으로 작용한다.","r":["113:4.1"]},{"q":"조절자는 인간의 영원한 본성의 본질이며, 세라핌은 인간의 진화하는 본성의 교사이다.","r":"113:4.2"},{"x":"세라핌의 인도를 받아들인다고 삶이 편해지지는 않으며, 오히려 도덕적 선택과 영적 진보의 험한 언덕을 만나게 된다.","r":["113:4.3"]},{"x":"하나님을 의식하는 사람의 기도 충동은 종종 세라핌의 영향에서 생기며, 수호자는 조절자가 가장 덜 활동적일 때 가장 활발하다.","r":["113:4.4","113:4.5"]}]},{"h":"인간의 의지를 존중하는 사역","items":[{"q":"천사들은 인간 마음의 성역을 침범하지 않으며, 필사자의 의지를 조작하지도 않고, 내주하는 조절자와 직접 접촉하지도 않는다.","r":"113:5.1"},{"x":"세라핌은 물리적 눈물도 몸도 날개도 없지만, 인간의 감정과 어느 정도 비슷한 영적 감정을 체험한다.","r":["113:5.2"]},{"x":"그들은 기도에 직접 응하지 않고 상관의 명령에 따라 일하므로, 사람의 변덕이나 기분과 상관없이 기능한다.","r":["113:5.3"]},{"q":"그들은 지배자도 감독자도 아니다. 그들은 단지 수호자일 뿐이다.","r":"113:5.4"},{"x":"사람이 스스로 항로를 정하면 천사는 그 항로를 최대한 좋게 활용하도록 돕고, 비상시에만 대개 상관의 명령으로 개입한다.","r":["113:5.4"]}]},{"h":"죽음 이후와 상승 생애","items":[{"x":"죽음 때 수호자는 그 사람의 기록과 정체성 명세, 혼의 모론시아 실체를 보존하고, 첫째 맨션 세계에서 피보호자가 깨어나기를 기다린다.","r":["113:6.1","113:6.2"]},{"q":"조절자는 너희를 식별할 것이다. 수호 세라핌은 너희를 재인격화하고, 그런 다음 너희를 너희 지상 시절의 신실한 관찰자에게 다시 소개할 것이다.","r":"113:6.6"},{"x":"개인 수호자가 없던 낮은 원의 사람들은 섭리 시대가 끝날 때 집단 수호자들이 맨션 구체의 부활 전당에서 다시 모은다.","r":["113:6.7"]},{"x":"모든 필사자는 맨션 세계를 떠나기 전에 영구 수호자를 얻으며, 그 수호자는 하보나로 떠나기 위해 세코나핌에 감싸일 때까지 함께한다.","r":["113:7.4"]},{"q":"세라핌에게 파라다이스 신들에 도달하는 가장 확실한 길은 진화적 기원의 한 혼을 파라다이스의 문까지 성공적으로 인도하는 것이다.","r":"113:7.7"},{"x":"운명의 수호자 쌍만이 영적 통일을 이루고 1차 곧 필사 최종자 군단에 들어가, 인간의 영원한 동료가 될 수 있다.","r":["113:7.8"]}]}],"see":["세라핌","천사 무리","생각 조절자","맨션 세계","죽음","생존"],"n":28,"en":"Guardian Seraphim"},{"t":"시간과 공간","sum":"유란시아서에서 시간과 공간은 유한한 창조체가 무한자와 함께 존재할 수 있도록 마련된 주 우주의 결합된 기제이다. 공간은 파라다이스의 증여로서 호흡하듯 팽창과 수축을 거듭하고, 시간은 운동과 마음의 연속 인식에서 생겨난다. 파라다이스에는 시간도 공간도 없으며, 성숙한 인격은 과거와 미래를 현재에 통합함으로써 점차 시간의 제약을 넘어 영원한 목적에 참여하게 된다.","sections":[{"h":"유한한 창조체를 위한 장치","items":[{"q":"시간과 공간은 주(主) 우주의 결합된 기제이다.","r":"118:9.1"},{"x":"시간과 공간은 유한한 창조체를 절대 수준에서 절연해 주며, 이것 없이는 어떤 필사자도 존재할 수 없다.","r":["118:9.1"]},{"x":"시간과 공간은 일곱 초우주의 시공간 창조계 안에서만 분리될 수 없게 묶여 있다.","r":["12:5.3","65:8.1"]},{"q":"대우주는 유기체일 뿐 아니라 기제이며, 기계적이면서 살아 있다.","r":"118:9.4"}]},{"h":"공간","items":[{"x":"공간은 파라다이스의 증여이지만 무한하지도 절대적이지도 않으며, 우리는 그 절대적 한계를 알지 못한다.","r":["12:5.2","11:7.4"]},{"q":"파라다이스의 표면 어디에도 공간은 존재하지 않는다.","r":"11:7.1"},{"x":"충만 공간과 비충만 공간 사이에는 비교적 고요한 중간공간 지대가 있어 둘을 나눈다.","r":["11:7.2","11:7.3"]},{"x":"모든 공간은 호흡하듯 교대로 수축하고 팽창하며, 우주 공간이 팽창하면 저장소 공간은 수축한다.","r":["11:6.1","11:6.2"]},{"x":"공간은 비어 있지 않으며, 사람이 아는 것 가운데 절대에 가장 가까운 비절대적 실체이다.","r":["130:7.6","118:3.5"]},{"x":"공간은 물체의 한 속성처럼 생각할 수 있어, 물체가 움직일 때 그 안의 공간도 함께 가져간다.","r":["118:3.6"]}]},{"h":"시간","items":[{"x":"시간도 파라다이스의 간접적 증여로, 운동과 마음이 연속성을 인식하는 데서 생겨난다.","r":["12:5.1"]},{"q":"시간은 창조체 의식이 인식하는, 흘러가는 일시적 사건들의 흐름이다.","r":"130:7.4"},{"x":"시간은 마음으로 지각하는 지속, 영으로 지각하는 하나님을 향한 운동, 인격이 지닌 독특한 현존 의식이라는 세 수준으로 인식된다.","r":["12:5.6","12:5.9"]},{"x":"사람이 내적으로 진보할수록 사건들의 연속은 점차 하나의 연관된 전체로 보이게 된다.","r":["130:7.5"]},{"x":"개별 창조체에게 시간의 기준은 자기 수명이며, 시간에 묶이지 않은 이들에게 진화는 그리 긴 과정이 아니다.","r":["65:8.3"]}]},{"h":"시간과 성숙","items":[{"x":"어떤 지성이든 성숙의 정도와 시간 의식의 단위 사이에는 직접적 관계가 있다.","r":["118:1.3"]},{"q":"인내는 시간 단위가 짧은 필사자들에 의해 발휘된다.","r":"118:1.6"},{"x":"진정한 성숙은 참된 이해에서 태어난 관용으로 인내를 넘어선다.","r":["118:1.6"]},{"x":"성숙한다는 것은 현재를 더 강렬하게 살면서도 과거의 체험과 미래의 가치를 함께 품어 현재의 한계를 넘는 것이다.","r":["118:1.5","118:1.7"]},{"x":"영이 내주하는 사람은 앞을 내다보는 통찰을 가지며, 앞을 향한 진보적 태도만이 인격적으로 실제적이다.","r":["12:5.10"]}]},{"h":"진리와 영원","items":[{"q":"사물은 시간에 의해 조건 지어지지만, 진리는 시간을 초월한다.","r":"118:3.2"},{"x":"진리를 더 많이 알수록 우리는 과거를 더 잘 이해하고 미래를 더 많이 파악할 수 있다.","r":["118:3.2"]},{"x":"진화하는 우주들에서 영원은 일시적 영속성, 곧 영속하는 지금이다.","r":["118:1.1"]},{"x":"무한하고 절대적인 수준에서는 현재의 순간이 모든 과거와 모든 미래를 포함한다.","r":["118:1.9"]},{"x":"영원은 시간의 유한한 마음으로 이해할 수 없지만, 일직선보다는 끝없는 원으로 생각하는 편이 더 알맞다.","r":["32:5.4","32:5.6"]}]},{"h":"시간을 넘어서는 인격","items":[{"x":"필사 인격은 아버지의 뜻을 행하기로 선택하여 내주하는 영과 하나 됨으로써 영원해질 수 있다.","r":["118:1.2"]},{"x":"절대자로서의 하나님께는 영원한 결정을 내린 상승 필사자가 이미 파라다이스 최종자이다.","r":["118:1.10"]},{"x":"파라다이스 순례자들은 시간에서 영원으로 건너가는 중간공간 지대를 지날 때 무의식 상태가 된다.","r":["12:5.4"]},{"x":"영적 가치가 인정되면 인격은 점차 시간의 제약에서 자유로워지고 공간의 한계를 초월하게 된다.","r":["65:8.6"]}]}],"see":["파라다이스","대우주와 주(主)우주","실체","최상 존재","체험","완전을 향한 여정"],"n":97,"en":"Time and Space"},{"t":"신앙","sum":"신앙은 하나님과 영적 가치에 대한 살아 있는 신뢰로서, 단순히 어떤 교리를 참이라고 받아들이는 믿음과 구별된다. 믿음이 삶을 실제로 이끌고 형성할 때 비로소 신앙이 되며, 신앙은 철학의 개연성의 하나님을 체험의 확실성의 하나님으로 바꾼다. 신앙은 하나님의 가족에 들어가는 대가이자 하보나에 이르는 열쇠이며, 예수는 그 가장 높은 본보기를 살아 보였다.","sections":[{"h":"믿음과 신앙의 차이","items":[{"x":"가르침을 진리로 받아들이는 것은 믿음일 뿐이며, 믿음이 삶의 방식을 실제로 지배할 때 신앙이 된다.","r":["101:8.1"]},{"q":"믿음은 고정시키고, 신앙은 해방시킨다.","r":"101:8.2"},{"x":"믿음은 집단의 소유물이 될 수 있지만 신앙은 반드시 개인적이어야 한다.","r":["101:8.2"]},{"x":"신앙은 하나님을 알고 사람을 섬기는 삶이며, 영적 의미와 최상 가치를 다루는 살아 있는 체험이다.","r":["101:8.2"]},{"q":"믿음은 의심과 두려움을 이겨낼 수 없을지 모르지만, 신앙은 항상 의심을 극복한다.","r":"102:6.7"},{"q":"가르침을 진리로 받아들이는 것은 신앙이 아니라 단순한 믿음일 뿐이다.","r":"101:8.1"}]},{"h":"신앙과 확실성","items":[{"x":"신앙은 철학의 개연성의 하나님을 개인적 종교 체험에서 확실성의 구원하시는 하나님으로 바꾼다.","r":["102:6.4"]},{"q":"하나님에 대한 확신은 현명한 추론을 통해 도달할 수 있지만, 개인은 신앙을 통해, 개인적 체험을 통해서만 하나님을 알게 된다.","r":"102:6.5"},{"x":"과학에서 하나님은 가능성이고 철학에서는 개연성이지만, 종교에서는 확실성이다.","r":["102:6.8"]},{"x":"하나님은 기적이나 물질적 증명으로 드러나지 않으며, 우리는 그를 신뢰함으로써 알게 된다.","r":["102:1.5"]},{"x":"과학을 더 알수록 확신할 것이 줄지만, 종교를 더 가질수록 더욱 확신하게 된다.","r":["102:1.3"]}]},{"h":"참된 신앙의 표지","items":[{"x":"참된 신앙은 쓰라린 실망과 패배 속에서도 하나님의 선하심을 신뢰하고, 재난 속에서도 깊은 용기를 낳는다.","r":["101:3.6","101:3.7"]},{"x":"신앙은 질병과 고통, 학대와 부당함 속에서도 설명할 수 없는 평정과 고요를 지킨다.","r":["101:3.8","101:3.9"]},{"x":"참된 신앙은 어떤 상황에서도 하나님을 예배하며 “그분께서 나를 치신다 해도 나는 그분을 섬길 것이다”라고 선언한다.","r":["101:3.16"]},{"x":"신앙은 지적 정직성을 해치거나 편협과 박해를 조장하지 않으며, 과학적 발견을 외면하지도 않는다.","r":["101:8.3","101:8.4"]},{"x":"신앙은 종교에 생명을 불어넣고 종교인이 황금률을 영웅적으로 실천하게 한다.","r":["101:8.4"]},{"q":"신앙은 종교에 생명을 불어넣고, 종교인이 황금률을 영웅적으로 실천하도록 이끈다.","r":"101:8.4"}]},{"h":"신앙과 구원","items":[{"x":"신앙은 도덕적 의식과 지속하는 실체에 대한 영적 개념을 이어 주며, 종교를 구원의 기법이 되게 한다.","r":["101:9.9"]},{"x":"신앙은 하나님의 가족에 들어가는 대가이며, 용서는 그 신앙을 받아들이시는 하나님의 행위이다.","r":["170:3.3"]},{"x":"신앙은 사람 안에 사는 신성한 불꽃, 곧 영원한 생존의 잠재력을 풀어놓는다.","r":["132:3.6"]},{"x":"조절자가 생존을 이루는 데 성공하느냐는 믿음의 이론보다 결정과 결심과 굳건한 신앙에 달려 있다.","r":["110:3.2"]},{"q":"기꺼이 믿으려는 마음은 하보나에 이르는 열쇠이다.","r":"26:4.15"}]},{"h":"예수의 신앙","items":[{"x":"예수는 신앙을 고난 속의 위로나 절망 속의 위안으로 쓰지 않았고, 하나님에 대한 의문 없는 신뢰 속에서 평온을 누렸다.","r":["196:0.3"]},{"x":"예수의 큰 공헌은 하나님에 대한 새 관념보다, 새롭고 더 높은 유형의 살아 있는 신앙을 인간적으로 보여 준 데 있다.","r":["196:0.3"]},{"x":"예수는 자신을 믿으라기보다 자신과 함께 믿으라고, 그가 믿은 대로 믿으라고 요구한다.","r":["196:0.13"]},{"x":"예수는 어린아이 같은 단순한 신앙이 왕국의 문을 여는 열쇠라고 가르쳤다.","r":["170:3.2"]}]}],"see":["종교 체험","개인적 종교","진리","하나님 나라","생존","예수의 성품"],"n":51,"en":"Faith"},{"t":"실체","sum":"유란시아서에서 실체는 우주 아버지의 무한한 의지에서 비롯되어 여러 우주 수준에서 분화되고 실제화하는 모든 존재의 총체이다. 실체는 실제와 잠재, 절대와 아절대, 존재적인 것과 체험적인 것, 인격적인 것과 비인격적인 것으로 나뉘며, 그 총체는 무한이어서 유한한 마음은 온전히 이해할 수 없다. 사람은 과학·철학·종교를 통해 사실과 의미와 가치를 인식하며, 영은 모든 인격 체험의 근본 실체이다.","sections":[{"h":"실체의 근원","items":[{"x":"실체는 우주 아버지의 무한한 의지 안에서 그 의지에 의해 기원하며, 여러 우주 수준에서 분화되어 실제화한다.","r":["0:4.1"]},{"x":"우주 철학자들은 무한 안의 절대적 원초 인과를 스스로 계신 이로서 기능하는 우주 아버지께 돌린다.","r":["105:1.1"]},{"q":"스스로 계신 이는 무한자이며, 스스로 계신 이는 또한 무한이다.","r":"105:1.3"},{"x":"모든 절대 실체, 곧 세 신과 파라다이스 섬과 세 절대자는 영원으로부터 있으며 시작이 없다.","r":["105:2.1"]},{"x":"실체의 근원적 분화는 신화된 것과 비신화된 것, 곧 신 절대자와 무제한 절대자이며, 그 긴장은 우주 절대자가 해소한다.","r":["0:4.5"]}]},{"h":"실체의 분화","items":[{"x":"실체는 신화되지 않은 실체, 신화된 실체, 그리고 둘 사이의 상호 연관된 실체로 나타난다.","r":["0:4.2","0:4.3","0:4.4"]},{"x":"시간과 공간의 관점에서 실체는 실제와 잠재, 절대와 아절대, 존재적인 것과 체험적인 것, 인격적인 것과 비인격적인 것으로 나뉜다.","r":["0:4.7","0:4.8","0:4.10"]},{"x":"파라다이스 신은 존재적이지만, 출현하는 최상 존재와 궁극 존재는 체험적이다.","r":["0:4.9"]},{"x":"대우주와 출현하는 주 우주는 불완전한 유한자부터 여러 수준의 실체로 이루어져 있으며, 유란시아 필사자는 그 첫 수준에 있다.","r":["106:0.2","106:0.3"]},{"x":"절대적이고 영원한 수준에서는 잠재 실체도 실제 실체만큼 의미가 있으며, 오직 시간에 묶인 창조체에게만 둘이 크게 달라 보인다.","r":["118:1.10"]}]},{"h":"유한한 마음의 한계","items":[{"x":"높은 지성체에게도 무한은 부분적으로만, 실체의 최종성은 상대적으로만 이해될 수 있다.","r":["105:0.1"]},{"q":"실체의 총체성은 무한이며, 따라서 개념 능력이 아(亞)무한인 어떤 마음도 이를 완전히 이해할 수 없다.","r":"105:0.2"},{"x":"실체에 대한 개념은 필사자의 이해 수준으로 옮겨지면서 심각한 왜곡을 겪을 수밖에 없다.","r":["105:0.3"]},{"x":"필사 마음은 일곱 수준의 상대적 우주 실체를 거의 이해할 수 없지만, 유한 실체의 세 기능 수준은 상당 부분 파악할 수 있다.","r":["12:8.9"]}]},{"h":"사실, 의미, 가치","items":[{"q":"우주적 실체에는 오직 세 요소, 곧 사실, 관념, 관계만 있다.","r":"196:3.2"},{"x":"우리는 이 세 실체를 사물, 의미, 가치라 부르며, 과학과 철학과 종교가 각각 이를 인식한다.","r":["196:3.2"]},{"x":"우주 마음에 내재한 인과·의무·예배라는 세 통찰이 과학적·도덕적·영적 실체 인식을 가능하게 한다.","r":["16:6.6","16:6.7","16:6.8"]},{"x":"물리적 확실성은 과학의 논리에, 도덕적 확실성은 철학의 지혜에, 영적 확실성은 참된 종교 체험의 진리에 있다.","r":["196:3.5"]},{"x":"궁극의 분석에서 물질은 감각에서 사라지고 마음도 사라지지만, 영의 통찰은 여전히 영적 실체와 최상 가치를 인식한다.","r":["112:2.11"]}]},{"h":"영, 근본 실체","items":[{"q":"영은 우주들에서 기본적인 인격적 실체이며, 인격은 영적 실체에 대한 모든 점진적 체험의 기초이다.","r":"12:9.1"},{"x":"하나님은 영이시므로, 변치 않는 영은 체험적 변수인 마음과 물질을 넘어 모든 인격 체험의 근본 실체이다.","r":["12:8.14"]},{"x":"물질을 기본 실체로 보고 마음과 영을 물질에 뿌리를 둔 것으로 보는 것은 오류이다.","r":["8:2.3"]},{"q":"영은 창조적 실체이다.","r":"42:12.14"},{"x":"물리적인 것은 영 실체의 시간-공간 반영이며, 물질은 모론시아의 골격이고 둘 다 영 실체의 그림자이다.","r":["42:12.14","189:1.3"]}]},{"h":"실체와 하나님","items":[{"x":"혼은 내주하는 영을 아버지로, 물질적 마음을 어머니로 하여 체험 속에서 태어나는 새로운 모론시아 실체이다.","r":["0:5.10"]},{"q":"실체에 대한 점진적 이해는 하나님께 더 가까이 다가가는 것과 같다.","r":"196:3.3"},{"x":"전체 실체를 체험하는 것은 하나님을 완전히 깨닫는 것이며, 하나님을 아는 체험의 최종성이다.","r":["196:3.3"]},{"x":"상승하는 사람은 내면으로는 하나님 체험을 향해, 바깥으로는 에너지 이해를 향해 함께 나아간다.","r":["103:7.3"]}]}],"see":["세 절대자","우주 아버지","최상 존재","체험","과학과 종교","철학"],"n":98,"en":"Reality"},{"t":"아담과 이브","sum":"아담과 이브는 예루셈의 물질 아들과 딸로, 약 삼만 팔천 년 전 반란으로 고립된 유란시아에 생물학적 고양자로 왔다. 그들은 에덴 동산에서 백십칠 년 동안 일했으나, 결과를 서두른 이브의 조급함과 아담의 판단 착오로 신성한 계획에서 벗어나 불이행에 빠졌다. 그들은 필사 지위로 강등되었지만 반란죄는 면했고, 보라색 인종을 통해 인류의 생물학적·문화적 진보에 큰 공헌을 남겼다.","sections":[{"h":"생물학적 고양자의 파견","items":[{"x":"물질 아들과 딸은 창조자 아들의 자손이며, 진화 세계에서 물리적 고양자로 일하도록 운명 지어진 존재이다.","r":["51:1.1"]},{"x":"타바만시아의 시찰과 추천이 있은 뒤, 반란으로 지체되고 고립된 유란시아에 아담과 이브가 파견되었다.","r":["73:0.3"]},{"x":"그들은 예루셈 물질 아들 상급 군단의 일원으로, 생명 형태 변형 연구를 이끌던 체험 많은 부부였다.","r":["74:1.1","74:1.2"]},{"x":"상급 군단 전체가 자원했고, 루시퍼 반란 때 충성을 지킨 아담과 이브가 선택되었다.","r":["74:1.3","74:1.4"]},{"x":"그들은 서기 1934년으로부터 37,848년 전, 동산이 한창 꽃피는 계절에 도착했다.","r":["74:0.1"]}]},{"h":"에덴 동산의 문화","items":[{"x":"에덴의 학교들은 건강, 황금률, 개인과 집단의 권리, 놀이와 경쟁을 가르치며 사회화를 목표로 했다.","r":["74:7.2","74:7.3"]},{"x":"아담은 정해진 기도를 막고, 효과적인 기도는 개인적인 혼의 소망이어야 한다고 가르쳤다.","r":["74:7.21"]},{"x":"아담은 여성도 남성과 동등하게 새 생명에 기여한다고 가르치며 성 평등을 일깨우려 했다.","r":["74:7.22"]},{"x":"엿새 창조와 갈비뼈 이야기 같은 전승은 동산 시절의 사건들이 후대에 혼동되고 압축된 것이다.","r":["74:8.1","74:8.3"]},{"q":"“황금시대”는 신화이지만, 에덴은 실제였고, 동산 문명은 실제로 전복되었다.","r":"74:8.14"}]},{"h":"어려운 과업과 조급함","items":[{"x":"그들은 형제단을 전혀 받아들일 준비가 안 된, 영적 어둠 속의 세계에서 깊은 외로움과 마주했다.","r":["75:1.3","75:1.4"]},{"q":"그들은 길고 긴 인내의 시험에 기꺼이 안주하려 하지 않았다.","r":"75:1.6"},{"x":"칼리가스티아는 동산을 자주 찾아와 손쉬운 길을 권했지만, 처음에 그들은 모든 타협 제안을 단호히 물리쳤다.","r":["75:2.1"]},{"x":"세라파타티아는 진심으로 세상을 돕고자 했으나, 자신이 칼리가스티아의 도구가 된 줄을 끝내 몰랐다.","r":["75:3.6"]}]},{"h":"불이행과 그 결과","items":[{"x":"이브는 카노와의 비밀 만남에서 선과 악을 뒤섞으라는 오랜 경고를 어겼다.","r":["75:4.4","75:4.5"]},{"q":"그것이 의로운 목적을 달성하기 위한 그릇된 방식을 나타냈기 때문에, 그리고 그것이 올바른 길, 곧 신성한 계획에서 벗어났기 때문에 악을 구성했다.","r":"75:4.6"},{"x":"실패를 깨달은 아담도 절망 속에서 이브와 같은 어리석음을 범했고, 격분한 주민들이 놋족 정착지를 멸했다.","r":["75:5.2","75:5.3"]},{"x":"그들은 동산을 떠나 둘째 동산으로 갔으며, 스무 살이 된 자녀들은 예루셈으로 가는 길을 선택할 수 있었다.","r":["75:6.2","75:6.3"]},{"x":"가브리엘은 그들을 불이행으로 판정했으나, 우주 정부에 대한 반란의 혐의는 면제했다.","r":["75:7.1","75:7.2"]},{"q":"그들이 행한 것은 참으로 악이었지만, 그들은 결코 진리를 모독하는 죄를 짓지 않았고, 우주 아버지와 그의 창조자 아들의 의로운 통치에 대항하는 반란에 알면서 가담하지도 않았다.","r":"75:7.7"}]},{"h":"인간의 타락은 없었다","items":[{"q":"“인간의 타락”은 없었다.","r":"75:8.2"},{"x":"아담의 증여는 인류를 이전보다 생물학적으로 크게 향상시켰으며, 아담은 인류에 대한 저주의 원인으로 여겨져서는 안 된다.","r":["75:8.2","75:8.3"]},{"x":"필사자로 강등된 뒤 진심으로 회개한 그들에게 생각 조절자가 내주하게 되었다.","r":["76:5.2"]},{"x":"둘째 동산에서 아담은 자신의 생명 원형질을 남겨 1,570명의 우수한 남녀가 세상에 더해지게 했다.","r":["76:4.8"]},{"x":"아담은 530년을 살았고, 죽은 뒤 특별 부활로 깨어나 예루셈 시민권을 얻었다.","r":["76:5.5","76:6.2","76:6.3"]},{"q":"지름길이나 개인적 고안, 또는 다른 방책으로 확립된 신성한 계획을 우회하려고 조급하게 시도함으로써는 아무것도 얻지 못할 것이다.","r":"75:8.5"}]}],"see":["물질 아들과 딸","칼리가스티아","인종","유란시아","계시","루시퍼 반란"],"n":78,"en":"Adam and Eve"},{"t":"아름다움","sum":"아름다움은 진리·선함과 함께 사람이 신성을 이해하는 세 가지 길 가운데 하나로, 다양한 실체가 조화롭게 통일된 것을 인지하는 일이다. 물리적 우주에서 우리는 신성한 아름다움을 보며, 그 정점은 사람이 하나님을 찾고 하나님이 사람을 찾는 우주의 드라마이다. 예술과 아름다움의 감상은 윤리와 영적 동기와 이어질 때 종교의 일부가 되며, 예수는 아름다움이 예배로 이끄는 힘을 높이 평가했다.","sections":[{"h":"신성의 한 얼굴","items":[{"x":"창조체는 신성을 진리와 아름다움과 선함으로 이해할 수 있다.","r":["0:1.17"]},{"x":"물리적 우주에서 신성한 아름다움을 보고, 지성 세계에서 진리를 분별하며, 선하심은 종교 체험에서 발견된다.","r":["2:6.1"]},{"x":"아버지는 하보나가 보이는 신성한 아름다움의 응답을 즐기시며, 진화 우주들에 조화의 원형을 주시는 것을 기뻐하신다.","r":["14:6.8"]},{"x":"아름다움과 진리도 그것이 사랑의 아버지의 속성이 아니라면 생존에 대한 희망과 분리될 것이다.","r":["1:7.3"]}]},{"h":"아름다움이란 무엇인가","items":[{"x":"아름다움, 곧 예술은 대체로 대비의 통일에 관한 문제이며, 다양성은 아름다움 개념에 필수적이다.","r":["56:10.3"]},{"x":"아름다움은 흩어진 현상 실체의 다양성이 영원한 단일성에서 나와 조화롭게 종합된 것을 지적으로 인지하는 것이다.","r":["56:10.11"]},{"q":"최상의 아름다움을 분별하는 것은 실체의 발견이자 통합이다.","r":"2:7.8"},{"q":"영원한 진리 속에서 신성한 선하심을 식별하는 것, 그것이 궁극적인 아름다움이다.","r":"2:7.8"},{"x":"보편적 아름다움은 물질 창조 안에서 파라다이스 섬의 반영을 인지하는 것이다.","r":["56:10.17"]},{"q":"아름다움, 리듬, 조화는 지성적으로 연합되어 있고 영적으로 친족이다.","r":"44:7.2"}]},{"h":"우주 예술의 정점","items":[{"x":"유한 예술의 정점은 창조자와 창조체라는 두 극이 하나로 통일되는 드라마, 곧 사람이 하나님을 찾고 하나님이 사람을 찾는 일이다.","r":["56:10.3"]},{"q":"그러므로 유물론과 무신론은 추함의 극대화요, 아름다움에 대한 유한한 반정립의 절정이다.","r":"56:10.4"},{"x":"아름다움의 존재는 그것을 감상할 줄 아는 창조체 마음의 존재를 시사한다.","r":["56:10.11"]},{"x":"우주론적 사고에는 조화를 향한 호기심, 미적 감상, 그리고 하나님 의식으로 이끄는 윤리적 감수성이 따른다.","r":["56:10.6","56:10.7","56:10.8"]}]},{"h":"예술과 종교","items":[{"x":"아름다움을 추구하는 일은 윤리적이고 도덕적 개념을 풍요롭게 할 때만 종교의 일부가 된다.","r":["101:9.4"]},{"q":"예술은 높은 영적 동기에서 비롯된 목적이 스며들 때에만 종교적이다.","r":"101:9.4"},{"x":"모든 예술의 높은 사명은 더 높은 실체를 미리 보여 주고 시간의 감정을 영원의 사유로 결정화하는 것이다.","r":["48:7.23"]},{"x":"예술은 물질 환경의 아름다움 부족에서 벗어나려는 시도에서 비롯되며, 모론시아 수준을 향한 몸짓이다.","r":["196:3.30"]},{"x":"진리와 아름다움과 선함이 예술가나 철학자의 체험 속에서 통합되지 않으면 표현의 참된 혼이 결여된다.","r":["44:7.3"]},{"x":"모론시아 세계의 천상 예술가들은 파라다이스 창조자들의 신성한 아름다움을 예술로 묘사한다.","r":["44:8.6"]}]},{"h":"아름다움과 예수","items":[{"x":"예수는 플라비우스의 예술품을 보고, 아버지가 창조하고 사람이 빚은 것들의 아름다움을 감상하는 것을 책망할 이유가 없다고 했다.","r":["142:4.2","142:4.3"]},{"x":"예수는 아름다움이 특히 아이들에게 예배 충동으로 이끄는 큰 가치를 지닌다고 가르쳤다.","r":["167:6.5"]},{"x":"예수와 아버지가 보내는 영은 진리의 영일 뿐 아니라 이상적 아름다움의 영이다.","r":["155:6.11"]},{"x":"히브리인은 선에, 그리스인은 아름다움에 종교를 세웠지만, 예수가 계시한 사랑은 진리와 아름다움과 선을 모두 포괄한다.","r":["5:4.6","196:3.19"]},{"x":"신성한 사랑의 아름다움은 사람의 심정에 온전히 받아들여지면 죄의 매력과 악의 힘을 영원히 파괴한다.","r":["188:5.3"]},{"q":"그리하여 너희 자신을 위해 너희 자신 안에 아름다움과 선함과 예술적 장엄함의 예비 화랑을 세우라.","r":"160:4.12"}]}],"see":["진리","선함","사랑","예배","철학","빛과 생명"],"n":58,"en":"Beauty"},{"t":"아보날 아들","sum":"아보날 아들, 곧 치안 아들은 영원 아들과 무한 영에게서 나온 둘째 계층의 파라다이스 아들이다. 진화 세계들에서 섭리 시대를 심판하는 재판관으로, 행성 시대를 한 단계 끌어올리는 치안관으로, 그리고 여인에게서 태어나 필사자로 사는 증여 아들로 일한다. 창조자 아들의 권능을 온전히 뒷받침받는 이 ‘작은 그리스도들’을 통해 거의 모든 거주 세계가 진리의 영과 생각 조절자를 받게 되지만, 유란시아는 아직 치안 임무를 받은 적이 없다.","sections":[{"h":"둘째 계층의 파라다이스 아들","items":[{"x":"영원 아들의 절대적 개념이 무한 영의 새로운 사랑의 봉사 이상과 결합할 때마다 새로운 파라다이스 치안 아들이 나타난다.","r":["20:2.1","20:1.11"]},{"x":"대우주의 치안 아들은 약 십억으로 추정되며, 파라다이스 최상 평의회의 지휘를 받다가 지역 우주에 배정되면 창조자 아들 밑에서 봉사한다.","r":["20:2.2"]},{"q":"각 아보날 아들은 고유한 인격을 지니므로, 어떤 두 아들도 서로 같지 않으며,","r":"20:2.3"},{"q":"그리고 이 “작은 그리스도들”은 그들의 행성 증여에서, 창조자이자 주(主) 아들이 유란시아에서 그랬던 것처럼 똑같이 효과적이고 전능하다.","r":"35:0.1"},{"x":"창조자 아들이 아버지의 성품을 드러낸다면, 자비의 증여 아들인 아보날들은 무한한 긍휼을 지닌 영원 아들의 본성을 계시한다.","r":["20:10.3","20:10.4"]}]},{"h":"섭리 시대의 심판자","items":[{"x":"아보날들은 잠자는 생존자들을 깨우고, 한 섭리 시대를 끝맺으며, 행성 사역자들을 새 시대의 과제에 다시 배치하는 영역의 치안관이다.","r":["20:3.1"]},{"q":"비록 인격적 창조체들의 정체성을 소멸시키는 판결을 내릴 수는 있어도, 그들은 그러한 선고들을 집행하지는 않는다.","r":"20:3.2"},{"x":"오직 섭리 시대 심판을 위해 오는 ‘형식상의’ 방문에서는 육신화하지 않고 물질 창조체에게 보이지 않는 영적 존재로 온다.","r":["20:3.3","52:4.3"]},{"x":"섭리 시대의 마감 점호는 아보날을 수행하는 천사장이 공포하며, 잠든 이들의 세라핌 수호자들이 그 “천사장의 음성”에 응답한다.","r":["37:3.6"]},{"x":"빛과 생명에 정착한 세계에서도 이들의 사법 행위는 이어지지만, 그때는 행성의 사건 흐름을 바꾸지 않는 형식적인 것이 된다.","r":["55:0.2"]}]},{"h":"치안 임무","items":[{"x":"인종 갈등과 국가 적대가 사라진 세계적 평화는 행성이 치안 아들을 맞을 만큼 성숙했다는 표지이다.","r":["52:3.12"]},{"x":"첫 치안 임무에서 아보날은 출생을 거치지 않고 그 종족의 다 자란 성인으로 육신화하여, 사람들이 보고 만질 수 있는 존재로 나타난다.","r":["20:4.1","20:2.6"]},{"q":"각각의 새로운 섭리 시대는 계시 종교의 지평을 확장하며,","r":"52:4.4"},{"x":"치안 아들의 첫 방문 뒤 인류는 곧 경제적 해방을 이루어, 자립에 필요한 하루 노동이 두 시간 반 정도로 줄어든다.","r":["52:4.5"]},{"x":"한 번의 치안 임무로 증여 아들을 맞을 준비가 되지 않으면, 둘째나 그 이후의 치안 아들들이 와서 인류를 한 시대씩 진전시킨다.","r":["52:4.9"]}]},{"h":"증여 임무","items":[{"x":"모든 아보날은 적어도 한 번 어떤 필사 종족에게 자신을 증여하며, 각 행성에는 오직 한 증여 아들이 여인에게서 태어나 나타난다.","r":["20:2.7","20:5.4"]},{"q":"그러나 증여된 아보날은 “나를 본 자는 곧 하나님의 영원 아들을 본 것이다”라고 선언한다.","r":"20:6.5"},{"x":"치안 아들은 아버지의 뜻이 아니라 언제나 파라다이스 영원 아들의 의지에 따라 자신을 증여한다.","r":["20:6.5"]},{"x":"증여 아들은 죽어야 하지만 폭력적 죽음은 신성한 계획의 요구가 아니며, 대부분의 세계는 그들을 더 사려 깊게 대한다.","r":["20:6.6","20:6.7"]},{"q":"그들은 증여 임무의 목표를 성취하는 데 결코 실패하지 않는다.","r":"20:5.7"},{"x":"증여를 마친 아보날과 창조자 아들이 진리의 영을 함께 보내면, 그 세계의 정상적인 의지 창조체들은 생각 조절자를 받게 된다.","r":["52:5.6","20:5.3"]}]},{"h":"조력자들, 그리고 유란시아","items":[{"x":"행성 임무에서 아보날들은 멜기세덱과 천사장의 도움을 받고, 증여 임무에서는 찬란한 저녁별들과 144명의 증여 수행원이 동행한다.","r":["20:2.9","39:1.4"]},{"x":"대개 일곱 번의 임무를 거친 아보날은 다른 아들들에게 기회를 넘기고 창조자 아들의 높은 평의회에서 우주 행정에 참여한다.","r":["20:2.8"]},{"q":"유란시아는 치안 임무를 띤 아보날 아들의 방문을 받은 적이 없다.","r":"20:4.4"},{"x":"유란시아의 증여 아들은 아보날이 아닌 미가엘 자신이었으나, 어떤 증여 아들이라도 영적 재활에는 똑같이 충분했을 것이다.","r":["49:5.26","20:5.6"]},{"x":"미가엘 증여의 세계는 주(主) 아들의 피보호 세계이므로, 유란시아에 치안 아들이 언제 올지는 오직 시간만이 드러낼 것이다.","r":["20:4.5"]}]}],"see":["창조자 아들 미가엘","삼위일체 교사 아들","멜기세덱","영원 아들","진리의 영","빛과 생명"],"n":25,"en":"Avonal Sons"},{"t":"악","sum":"악은 하나님이 창조하신 것이 아니라, 불완전한 유한 세계에서 미성숙한 창조체가 빛을 거부하거나 잘못 선택할 때 드리우는 그림자이다. 악은 아버지의 뜻을 의도치 않게 어기는 것이어서 죄와 구별되며, 고의로 받아들일 때 죄가 된다. 잠재적 악은 자유 의지와 도덕적 선택에 필수적이지만 실제 악을 체험할 필요는 없으며, 하나님은 시간 속의 악에서도 궁극적 선을 이끌어 내신다.","sections":[{"h":"악의 본질","items":[{"x":"하나님은 너무나 적극적으로 선하셔서 부정적인 악이 끼어들 자리가 없으며, 악을 창조하지도 않으신다.","r":["130:1.5","54:0.2"]},{"q":"악은 현명하지 못한 빛의 거부가 초래하는 피할 수 없는 어둠이다.","r":"130:1.5"},{"q":"악은 신성한 법, 곧 아버지의 뜻을 무의식적으로 또는 의도치 않게 어기는 것이다.","r":"148:4.3"},{"x":"악은 우주 실체에 대한 부분적 인식이나 부적응이며, 지혜의 결핍을 나타낸다.","r":["67:1.4","67:1.5"]},{"x":"악은 계획을 잘못 적용하고 기법을 부적절하게 조정하여 우주 부조화와 행성의 혼란을 낳는 것이다.","r":["75:4.3"]}]},{"h":"상대적인 그림자","items":[{"q":"악은 상대적인 개념이다.","r":"130:4.13"},{"x":"악은 유한한 우주가 무한자의 살아 있는 빛을 가릴 때 생기는 그림자 속의 불완전함을 관찰한 데서 생겨난다.","r":["130:4.13"]},{"x":"오류는 파라다이스 완전을 향한 상승 길에 드리울 수밖에 없는 미완성의 그림자이며, 실제적 우주 특질이 아니다.","r":["130:4.11"]},{"x":"상대적 선이 드러나려면 비교상의 악, 곧 죄가 아닌 불완전함과의 대조가 늘 필요하다.","r":["4:3.6"]},{"x":"우주 척도를 오를수록 선은 늘고 악은 줄지만, 악을 체험할 가능성은 최종 영 수준에 이를 때까지 남는다.","r":["132:2.6"]}]},{"h":"자유 의지와 잠재적 악","items":[{"x":"진화하는 사람이 자유로우려면 오류를 범할 수 있어야 하며, 오류의 가능성이 없는 세계는 자유로운 지성이 없는 세계뿐이다.","r":["3:5.15"]},{"x":"아버지는 진리와 오류 사이의 선택 능력을 주심으로써 잠재적 부정을 만드셨지만, 악은 창조체가 그것을 선택할 때에야 실제로 존재한다.","r":["130:1.6"]},{"q":"악의 가능성은 도덕적 선택에 필수적이지만, 실제 악이 반드시 존재해야 하는 것은 아니다.","r":"132:2.10"},{"x":"유한한 마음이 무한을 불완전하게 이해하는 것 자체가 잠재적 악이며, 그것을 바로잡지 못해 오류가 커지면 실제 악이 된다.","r":["130:4.14"]},{"x":"악을 의도적으로 선택하면 죄가 되고, 죄와 오류를 지속적으로 추구하면 불법이 된다.","r":["54:0.2","130:1.6"]}]},{"h":"악이 드러나는 모습","items":[{"q":"악은 순전히 개인적인 평가가 절대적 수준으로 높아질 때 항상 생긴다.","r":"100:1.1"},{"q":"악은 붕괴와 최종적 파괴로 향하는, 치우친 창조성이다.","r":"111:4.11"},{"x":"모든 내적 갈등은 창조적 기능을 방해하므로 악하며, 인격 안에서 벌어지는 일종의 내전이다.","r":["111:4.11"]},{"x":"고난은 악에 잠재해 있지만 많은 고난은 죄와 불법에서 왔으며, 아버지는 벌로 고난을 보내지 않으신다.","r":["148:5.3"]},{"x":"사람은 자신의 선택이 낳은 결과를 하나님 탓으로 돌리지 말고, 지성적인 노력으로 지상의 고통을 극복해야 한다.","r":["148:5.3"]}]},{"h":"악을 허용하시는 지혜","items":[{"x":"창조체가 참으로 자유롭기 위해 악과 죄의 가능성은 불가피하며, 통치자들은 어떤 존재의 자유도 빼앗지 않는다.","r":["54:3.1"]},{"x":"아버지는 밀과 가라지처럼 선과 악이 생명이 다하는 날까지 함께 자라도록 허락하신다.","r":["130:1.6"]},{"x":"멜기세덱들은 사타니아 반란에서 생겨난 선이 모든 악을 합친 것보다 천 배 이상 많다고 가르친다.","r":["54:6.6"]},{"x":"상승하며 지혜가 자라면, 시간에 제한된 악에서 어떻게 궁극적 선이 생겨나는지 더 잘 이해하게 된다.","r":["54:6.10"]},{"x":"사람이 겪는 악의 체험도 시간의 자녀들 속에서 이루어지는 하나님의 끝없는 자기 실현의 일부이다.","r":["2:2.7"]}]}],"see":["죄","자유 의지","선함","루시퍼 반란","역경과 시련","지혜"],"n":67,"en":"Evil"},{"t":"에너지와 물질","sum":"에너지는 모든 실존의 기초로서 파라다이스에서 나와 파라다이스로 돌아가는, 영원하지만 무한하지 않은 실체이다. 공간 잠재력에서 시원적 힘과 창발 에너지를 거쳐 우주 동력과 물질에 이르기까지 힘 조직자와 동력 감독자들이 이를 변성하며, 빛·열·전기·물질은 기원과 운명에서 하나이다. 그러나 우주는 기계적이지 않으며, 마음이 물질을 지배하고 영이 마음을 다스리는 질서 안에 있다.","sections":[{"h":"파라다이스에서 나오는 에너지","items":[{"x":"에너지는 모든 실존의 기초이며 순수 에너지는 우주 아버지가 통제하신다. 파라다이스에서 발원하는 에너지의 흐름은 결코 멈춘 적이 없다.","r":["42:0.1"]},{"q":"우주의 기반은 물질적이지만, 생명의 본질은 영이다.","r":"42:1.1"},{"x":"비영적 현상으로 볼 때 하나님은 에너지이시며, 모든 물리적 에너지는 그분에게서 비롯된다.","r":["3:2.3"]},{"x":"에너지의 창조와 생명의 증여는 아버지와 창조자 인격들의 특권이며, 과학자는 아무리 진보해도 원자 하나를 창조하거나 물질에 생명을 더할 수 없다.","r":["42:1.4","42:1.5"]},{"q":"에너지는 영원하지만 무한하지 않다.","r":"42:1.8"},{"x":"힘-에너지는 불멸하고 파괴되지 않으며, 끝없이 변성될 수는 있어도 결코 소멸하지 않는다.","r":["42:1.7"]}]},{"h":"변성의 단계","items":[{"x":"공간 잠재력(앱솔루타)은 무제한 절대자의 자유 공간 현존으로, 우주 아버지의 인격적 붙듦에만 반응한다.","r":["42:2.3","42:2.5"]},{"x":"파라다이스 힘 조직자들은 공간 잠재력을 시원적 힘(세그리가타)으로 바꾸고, 다시 유력 에너지와 중력 에너지(얼티마타)로 변성한다.","r":["42:2.7","42:2.10","42:2.13"]},{"x":"에너지가 파라다이스 중력에 반응하는 단계에 이르면 동력 감독자들이 이어받아 우주 동력(그라비타)을 다룬다.","r":["42:2.12","42:2.14"]},{"x":"하보나 에너지는 이중이 아니라 삼중(트리아타)이며, 파라다이스 에너지인 모노타는 파라다이스 영과 이름으로만 구별된다.","r":["42:2.16","42:2.19","42:2.20"]},{"x":"우주적 힘, 솟아나는 에너지, 우주 동력은 파라다이스 중력과 선형 중력에 어떻게 반응하느냐로 구분된다.","r":["0:6.5","0:6.6","0:6.7"]}]},{"h":"물질의 구조","items":[{"q":"빛, 열, 전기, 자기, 화학 작용, 에너지, 물질은 유란시아에서 아직 발견되지 않은 다른 물질적 실체들과 함께 기원과 본성과 운명에서 하나이며 같은 것이다.","r":"42:4.1"},{"x":"물질적 실존의 으뜸 단위는 극자이며, 정확히 백 개의 극자가 하나의 전자를 이룬다.","r":["42:3.3","42:6.5"]},{"x":"지역 우주는 십진법 구조를 지녀, 원자는 하나에서 백 개까지의 궤도 전자를 가진 백 가지 형태로만 존재한다.","r":["42:7.4"]},{"x":"원자핵은 전자보다 180배 무거운 중간자가 양성자와 중성자 사이에서 전하를 왕복시킴으로써 온전히 유지된다.","r":["42:8.3","42:8.4"]},{"x":"공간은 비어 있지 않으며, 네바돈에서 알려진 가장 빈 공간도 입방인치마다 약 백 개의 극자를 지닌다.","r":["42:4.6"]},{"x":"원소의 성질이 일곱 개마다 되풀이되는 것은 물질 세계에 남은 칠중 영적 기원의 모반이다.","r":["42:9.2","42:9.3"]}]},{"h":"에너지의 순환과 균형","items":[{"x":"물질은 시간의 변성을 겪으면서도 언제나 영원의 원을 돌며, 자신을 내보낸 근원에 늘 반응한다.","r":["42:4.2"]},{"x":"작열하는 태양은 물질을 에너지로 바꾸고, 차가운 공간과 암흑 세계는 에너지를 다시 물질로 늦춘다.","r":["42:4.9"]},{"x":"물질의 온전성은 에너지가 오직 양자 단위로만 흡수되거나 방출된다는 사실로 보장된다.","r":["42:4.13"]},{"x":"에테르는 존재하지 않으며, 빛과 에너지는 직선으로 나아가는 입자의 흐름으로서 공간의 저항 때문에 파동처럼 보일 뿐이다.","r":["42:5.14","42:5.16"]},{"q":"물리적 에너지는 보편 법칙에 대한 그 순종에 있어서 참되고 확고한 유일한 실체이다.","r":"12:8.3"},{"x":"살아 있는 동력 감독자와 힘 조직자들은 우주를 만들고 부수고 다시 만드는 끝없는 변태를 지성적으로 지휘한다.","r":["15:8.10"]}]},{"h":"마음과 우주 기제","items":[{"x":"우주는 기계적이지도 마법적이지도 않으며, 마음의 창조물이자 법칙의 기제이다.","r":["42:11.1"]},{"x":"우주들의 우주는 마음이 계획하고 만들고 관리하지만, 그 기제가 너무 완전하여 과학의 방법으로는 무한한 마음의 흔적을 분별할 수 없다.","r":["42:11.2"]},{"x":"비영적 에너지들은 전보조 영 마음, 보조 영 마음, 모론시아 마음, 우주 마음 같은 살아 있는 마음 체계 속에서 다시 연합된다.","r":["42:10.2","42:10.6"]},{"q":"마음은 항상 창조적이다.","r":"42:12.9"},{"q":"영은 건축가이고 마음은 건설자이며 몸은 물질적 건물이다.","r":"42:12.12"},{"x":"마음은 물질을 지배하고 영의 상위통제에 반응하며, 영의 인도를 자유롭게 따르는 마음만이 필사 실존을 넘어 생존할 수 있다.","r":["42:12.15"]},{"x":"파라다이스에서는 물리적·마음의·영적 에너지가 동격이고 하보나에서는 조율되며, 절대 수준에서는 영이 확실히 지배한다.","r":["42:12.13"]}]}],"see":["중력","파라다이스","우주 마음","세 절대자","시간과 공간","실체"],"n":17,"en":"Energy and Matter"},{"t":"역경과 시련","sum":"유란시아의 혼란과 시련은 하나님의 무관심이 아니라, 필요의 모루와 고통의 망치 사이에서 강하고 고귀한 품성을 단련하려는 신성한 계획의 일부이다. 용기·이타심·희망·신앙 같은 덕은 역경과 불확실성이 있는 세계에서만 자랄 수 있다. 예수는 고난이 하나님의 벌이라는 미신을 바로잡고, 신자를 어려움에서 면제해 주지는 않지만 모든 고난을 함께 통과하겠다고 약속했다.","sections":[{"h":"왜 역경이 있는가","items":[{"x":"삶의 불확실성과 부침은 하나님의 우주 주권과 결코 모순되지 않는다.","r":["3:5.5"]},{"q":"용기, 곧 품성의 강인함은 바람직한가? 그렇다면 사람은 역경과 씨름하고 실망에 반응해야 하는 환경에서 자라야 한다.","r":"3:5.6"},{"x":"이타심은 불평등을, 희망은 불안정을, 신앙은 아는 것보다 더 믿어야 하는 처지를 필요로 한다.","r":["3:5.7","3:5.8","3:5.9"]},{"x":"행복의 만족도 아픔과 괴로움의 가능성이 열려 있는 세계에서만 참으로 체험된다.","r":["3:5.14"]},{"x":"하보나의 완전한 존재들은 고통의 잠재성에서 벗어나는 즐거움의 달콤함도, 구원하는 신앙도 알지 못한다.","r":["3:5.17"]}]},{"h":"품성을 단련하는 모루와 망치","items":[{"x":"창조자들은 유란시아를 낙원으로 만들 수 있지만, 그런 에덴은 강하고 고귀한 품성을 길러 내지 못한다.","r":["23:2.12"]},{"q":"너희의 불안과 슬픔, 시련과 실망은, 중앙의 완전한 우주의 세계들에서 모든 것이 최상 목적에 맞게 정교하게 완성되고 무한히 적응하는 것과 마찬가지로, 너희 영역에서 신성한 계획의 일부이다.","r":"23:2.12"},{"q":"너희가 기원한 우주는 정의의 모루와 고난의 망치 사이에서 만들어지고 있다. 그러나 그 망치를 드는 존재들은 자비의 자녀들, 곧 무한 영의 영 자손들이다.","r":"9:1.8"},{"q":"너희는 영적 진리를 느낌으로 체험하기 전에는 그것을 지각할 수 없으며, 많은 진리는 역경 속에서가 아니면 참으로 느껴지지 않는다.","r":"48:7.18"},{"x":"하나님은 때로 우리의 유익을 위해 징계하시지만, 불같은 시련 속에서 우리와 함께 고통받으신다.","r":["2:5.3"]}]},{"h":"고난은 벌이 아니다","items":[{"x":"예수는 번영이 하나님의 승인이고 역경이 하나님의 불만이라는 믿음을 미신이라고 선언했다.","r":["166:4.3"]},{"x":"실로암 탑에 깔려 죽은 이들은 더 큰 죄인이 아니라 시간의 사고로 희생된 무고한 사람들이었다.","r":["166:4.4"]},{"x":"욥의 이야기가 보여 주듯, 물질적 번영은 하나님의 은총의 증거가 아니며 아버지는 가난한 자도 똑같이 사랑하신다.","r":["148:6.2"]},{"x":"사람은 시간의 사고와 불완전함, 죄의 결과, 반역의 결실로 고통받을 뿐, 고통은 신성한 심판의 방문이 아니다.","r":["148:6.11"]},{"x":"욥은 고난 속에서도 신앙으로 구름을 뚫고 위로와 구원의 하나님을 발견했다.","r":["148:6.11","148:6.10"]}]},{"h":"시련을 대하는 신자의 자세","items":[{"q":"나는 너희를 고난의 물에서 건져내겠다고 약속하지 않지만, 너희와 함께 그 모든 고난을 통과하겠다고 약속한다.","r":"159:3.13"},{"x":"복음을 믿는다고 사고나 재난에서 면제되지는 않지만, 어려움이 올 때 두려워하지 않게 된다.","r":["159:3.13"]},{"q":"그는 피할 수 없는 고난을 용감하게 견디며, 피할 수 없는 어려움 앞에서 불평하지 않는다.","r":"156:5.20"},{"x":"시험의 때에 사람의 혼이 드러나며, 시련을 견딘 충성된 이들이 왕국의 일을 맡게 된다.","r":["165:6.2"]},{"x":"역경과 미움의 홍수가 혼을 덮쳐도, 내주하는 영에게 혼을 맡긴 사람에게는 무너지지 않는 영의 성채가 있다.","r":["100:2.7"]},{"x":"참된 종교는 자연적 역경과 육체적 재난 속에서도 깊은 용기와 확신을 낳는다.","r":["101:3.7","34:6.13"]}]},{"h":"예수가 보여 준 길","items":[{"x":"예수는 고난을 신앙과 용기, 아버지의 뜻을 행하려는 결단으로 맞아 삶과 죽음을 정복했다.","r":["194:3.3"]},{"x":"명백한 패배와 절망의 고통 앞에서도 예수는 신성한 현존 안에서 두려움 없이 고요히 서 있었다.","r":["196:0.5"]},{"x":"예수는 두려움에 짓눌린 젊은이에게 고난은 활력을, 실망은 박차를, 장애물은 자극을 줄 것이라고 격려했다.","r":["130:6.4"]},{"x":"예수는 벳세다에 모인 무리에게 ‘역경의 사명과 실망의 영적 가치’를 한 시간 넘게 가르쳤다.","r":["151:0.1"]},{"x":"결혼 전 두 해의 힘든 시기는 예수의 지상 생애에서 진정한 시련의 시간이었다.","r":["126:0.1"]}]}],"see":["악","두려움과 걱정","신앙","성장","기쁨과 행복","예수의 성품"],"n":71,"en":"Adversity and Trials"},{"t":"열두 사도","sum":"열두 사도는 예수가 하늘 왕국의 복음을 전하도록 몸소 부르고 훈련하여 임명한 평범한 갈릴리 사람들이다. 그들은 무지한 이들이 아니라 회당 교육을 받은 다양한 기질의 사람들이었고, 각자의 강점과 약점을 지닌 채 예수와 함께 살며 바뀌어 갔다. 예수가 그들의 세상적 기대를 거듭 무너뜨렸는데도 오직 한 사람만 그를 버렸다는 사실은 예수의 생애가 지닌 매력을 증언한다.","sections":[{"h":"부르심과 훈련","items":[{"x":"예수는 처음 여섯을 직접 뽑았고, 그들이 각자 한 사람씩 추천하여 열둘이 되었다.","r":["139:6.1","138:5.1"]},{"x":"첫 여섯 사도는 둘씩 짝지어 나가 개인적 접촉으로 복음을 전하며, 종교가 순전히 개인적 체험임을 깨달았다.","r":["138:1.1","138:2.1"]},{"x":"고기잡이와 개인 사역을 번갈아 하던 단조로운 시기는 가혹한 시험이었지만, 그들은 주님에 대한 충성으로 견뎌 냈다.","r":["138:9.1"]},{"x":"예수는 서기 27년 1월 12일 열두 사도를 왕국 복음의 공개 설교자로 임명했다.","r":["140:0.1"]},{"x":"이른바 산상수훈은 복음 자체가 아니라 열두 사도에게 준 예수의 임명 훈시였다.","r":["140:4.1"]}]},{"h":"평범하고 다양한 사람들","items":[{"q":"사도들을 전혀 무지하고 배우지 못한 사람들로 여기는 잘못을 저지르지 말라.","r":"139:0.3"},{"x":"‘배우지 못했다’는 말은 그들이 랍비 전승과 성서 해석법을 훈련받지 않은 평신도였다는 뜻이다.","r":["139:0.4"]},{"x":"사도들은 예수에게서 하늘 왕국을 배웠고, 예수는 그들에게서 사람의 본성에 대해 많은 것을 배웠다.","r":["139:0.2"]},{"x":"모든 사도가 예수를 사랑했지만, 각자는 자기에게 특별히 호소하는 예수의 어떤 성품에 끌렸다.","r":["139:1.11"]}]},{"h":"네 핵심 사도","items":[{"x":"가장 연장자인 안드레는 사도단의 대장이 되어 끝까지 그 자리를 지켰으며, 뛰어난 설교자는 아니었지만 유능한 개인 전도자였다.","r":["139:1.2","139:1.3","139:1.4"]},{"x":"베드로는 충동적이고 낙천적이었으며, 웅변에 능한 타고난 지도자였으나 생각보다 말이 앞서곤 했다.","r":["139:2.3","139:2.4"]},{"x":"야고보 세베데는 격한 분노를 지녔지만 문제를 여러 면에서 보는 능력이 있어, 예수 가르침의 참뜻에 가장 가까이 갔다.","r":["139:3.2","139:3.4"]},{"x":"가장 어린 요한은 예수의 개인 대리인으로 많은 일을 맡았지만, ‘예수가 사랑한 제자’라는 표현은 정확하지 않다.","r":["139:4.2","139:4.4"]},{"x":"베드로·야고보·요한은 안드레가 지명하여 예수 곁에서 그를 돌보는 개인 보좌관이 되었다.","r":["139:4.3"]},{"q":"안드레는 분명한 통찰, 논리적 사고, 그리고 확고한 결단력을 지닌 사람이었고,","r":"139:1.10"}]},{"h":"나머지 사도들","items":[{"x":"‘보여 달라’고 하던 빌립은 상상력이 부족했지만, 작은 일을 크게 잘 해내는 충실한 청지기였다.","r":["139:5.2","139:5.3","139:5.4"]},{"x":"나다니엘은 ‘속임이 없는’ 정직한 사람이자 사도단의 철학자였고, 약점은 편견으로 흐르는 자존심이었다.","r":["139:6.3","139:6.4"]},{"x":"세리 출신 마태는 사도단의 재정을 맡았고, 주님의 용서하는 성품에 가장 깊이 감사했다.","r":["139:7.2","139:7.4"]},{"x":"도마는 사도단의 진짜 과학자로 분석적 마음과 흔들리지 않는 용기를 지녔으나, 평생 의심과 싸웠다.","r":["139:8.2","139:8.4"]},{"x":"알패오 쌍둥이는 특별한 강점도 약점도 없는 평범한 이들이었지만, 그들 덕분에 수많은 소심한 신자가 왕국에 들어왔다.","r":["139:9.4","139:9.5"]},{"x":"시몬 젤로테스는 영감을 주는 충성심으로 망설이는 이들을 왕국으로 이끌었으나, 민족주의적 사고를 다 벗지 못했다.","r":["139:11.3","139:11.4"]},{"q":"그들은 “모든 사도 중 가장 작은 자들”이었으며, 그들은 그것을 알고 기쁘게 여겼다.","r":"139:9.5"}]},{"h":"유다 이스가리옷","items":[{"x":"유다는 사도 가운데 유일한 유대 사람이자 가장 교육을 많이 받은 이로, 재무를 정직하고 유능하게 맡았다.","r":["139:12.2","139:12.3"]},{"q":"유다는 자신을 참으로 이해하지 못했으며, 자신을 대하는 데 참으로 진실하지 못했다.","r":"139:12.2"},{"x":"그는 갈릴리 동료들에 대한 편견을 끝내 넘지 못했고, 예수가 소심하다고 속으로 비판했다.","r":["139:12.4"]},{"q":"예수는 배반자를 오직 불쌍히 여길 뿐이었다.","r":"139:12.14"}]},{"h":"왕국의 대사","items":[{"x":"예수는 사도들이 이제 다른 하늘 나라의 시민으로서 이전보다 더 나은 삶을 살아야 한다고 일렀다.","r":["140:3.1"]},{"x":"그는 사도들에게 무엇을 해야 하는지보다 무엇이 되어야 하는지를 길게 가르쳤다.","r":["140:10.1"]},{"q":"예수가 사도들의 희망을 거듭 산산이 부수고 개인적 높임을 바라는 그들의 모든 야망을 갈기갈기 찢었음에도, 오직 한 사람만 그를 버렸다는 사실은 예수의 지상 생애의 매력과 의로움에 대한 웅변적 증언이다.","r":"139:0.1"}]}],"see":["예수의 가르침","예수의 성품","오순절","예수의 부활","예수의 십자가 죽음","하나님 나라"],"n":89,"en":"Twelve Apostles"},{"t":"영원 아들","sum":"영원 아들은 우주 아버지의 첫 번째 인격적이고 절대적인 개념이 완전하게 표현된 둘째 근원이며 중심이다. 그는 살아 있는 신성한 말씀이자 아버지의 영과 인격에 대한 최종적 계시이며, 영 인력 회로로 모든 영 실체를 붙드는 영적 행정자이다. 아버지의 사랑을 자비로 펼치는 그는 파라다이스 아들들의 증여를 통해 창조체들에게 가까이 다가온다.","sections":[{"h":"정체성과 본성","items":[{"x":"영원 아들은 아버지의 첫 번째 인격적·절대적 개념이 완전히 표현된 존재로, 아버지가 인격적으로 자신을 표현하실 때는 언제나 아들을 통해 하신다.","r":["6:0.1"]},{"x":"‘첫 번째 생각’이라는 말은 시간에 묶인 마음을 위한 표현일 뿐이며, 아들은 시작이 없고 아버지와 동격으로 영원하다.","r":["6:0.2","6:0.4"]},{"q":"첫째 근원이며 중심은 의지의 절대자이시며, 둘째 근원이며 중심은 인격의 절대자이시다.","r":"6:1.2"},{"x":"아버지는 아들과 함께하시거나 아들의 동격 활동과 결합하지 않고서는 결코 인격적으로 창조자로 기능하지 않으신다.","r":["6:1.3"]},{"x":"유란시아에서는 기원 아들이 증여 아들인 네바돈의 미가엘과 혼동되어 왔으나, ‘영원 아들’이라는 칭호는 기원 아들에게만 쓴다.","r":["6:1.5","6:1.6"]}]},{"h":"자비의 사역자","items":[{"x":"아들은 아버지처럼 변함없고 무한히 신뢰할 수 있으며, 우리에게는 다가가기에 한 걸음 더 가까워 더 인격적으로 보인다.","r":["6:2.1"]},{"q":"하나님이 사랑이신 것처럼, 아들은 자비이시다.","r":"6:3.1"},{"x":"아들은 아버지께 자비를 베풀어 달라고 간청하는 중재자가 아니다. 아들이 베푸는 모든 자비는 아버지 사랑의 직접적 계시이다.","r":["6:3.4"]},{"x":"자비는 적용된 사랑이다. 비유하자면 하나님의 사랑은 아버지의 사랑에, 영원 아들의 사랑은 어머니의 애정에 더 가깝다.","r":["6:3.5"]},{"x":"아버지는 우주 자녀들을 아버지로서 사랑하시고, 영원 아들은 모든 창조체를 아버지이자 형제로서 바라보신다.","r":["6:2.8"]}]},{"h":"영 인력 회로","items":[{"x":"아들은 오직 영적 영역에서만 전능하시며, 물리 영역에서나 공동 행위자를 거치지 않은 마음 사역에서는 인격적으로 기능하지 않으신다.","r":["6:4.2","6:5.1"]},{"x":"영 인력은 시간 지연이 없고 공간에 의해 줄지 않으며, 거리의 제곱에 따라 약해지지도 않는다.","r":["7:1.2"]},{"x":"영적 실체는 그 질적 가치에 따라 영 인력에 반응하며, 그 반응은 물질이 중력에 반응하듯 신뢰할 수 있고 예측 가능하다.","r":["7:1.3","7:1.8"]},{"q":"죄와 반역은 지역 우주 회로의 기능을 방해할 수는 있어도, 영원 아들의 영 인력을 중지시킬 수는 없다.","r":"7:1.7"},{"q":"영 인력 회로는 사람의 혼을 문자 그대로 파라다이스를 향해 끌어당긴다.","r":"7:3.2"}]},{"h":"기도와 개인과의 관계","items":[{"x":"영원 아들의 영은 우리를 감싸고 있지만, 신비의 관찰자처럼 우리 안에 내주하거나 우리의 일부가 되지는 않는다.","r":["6:4.6"]},{"x":"진실한 기도에 담긴 영적 내용은 영 인력 회로를 타고 관련된 모든 신성한 인격에게 즉시 전달된다.","r":["7:3.3"]},{"x":"순전히 물질적이고 자기중심적인 청원은 영 회로에 들어가지 못하고 죽은 채 떨어진다.","r":["7:3.6"]},{"q":"필사자의 청원을 유효하게 만드는 것은 동기가 되는 생각, 곧 영적 내용이다. 말 자체에는 아무런 가치가 없다.","r":"7:3.7"}]},{"h":"증여와 완전 계획","items":[{"x":"아들은 아버지의 점진적 달성 계획을 유보 없이 받아들였고, 스스로는 하나님의 아들들을 진화 세계에 보내는 증여 계획을 제안했다.","r":["7:4.4","7:4.5"]},{"x":"영원 아들은 아버지가 맡기신 창조체 상승 계획의 인격적 수탁자이자 신성한 보호자이다.","r":["7:4.7"]},{"x":"아들의 인격은 단편화될 수 없으므로, 그는 파라다이스 아들들의 육신화를 통해 창조체의 체험에 참여하신다.","r":["7:5.3","7:5.4"]},{"x":"영원 아들은 하보나의 일곱 회로에 자신을 일곱 번 증여하셨고, 이 사실은 하보나를 지나는 모든 순례자에게 영원한 격려가 된다.","r":["7:5.5","7:5.9"]},{"q":"파라다이스 아들을 본 자는 누구든 하나님의 영원 아들을 본 것이라는 말은 문자 그대로 참이다.","r":"7:5.11"}]},{"h":"아버지의 최상 계시","items":[{"x":"영원 아들은 아버지의 영과 인격에 대한 완전하고 최종적인 계시이며, 아버지에 대한 모든 지식은 아들과 그의 아들들에게서 나온다.","r":["7:7.1"]},{"x":"아버지는 영원 아들의 신성한 아들들을 통해서만 인격으로 우리에게 다가오시며, 우리도 그 살아 있는 길을 통해 아버지께 상승한다.","r":["7:7.4"]},{"x":"하보나 회로를 지나는 순례자는 아버지를 분별할 준비가 되기 훨씬 전에 아들에게 도달할 능력을 갖춘다.","r":["7:7.5"]},{"x":"아들의 인격은 물질 마음이나 모론시아 마음에서는 밝게 빛나지 않으며, 영 상승을 시작해야 비로소 점점 더 실재하게 된다.","r":["6:8.5","6:8.6"]},{"q":"하나님이 우주 아버지이신 것과 같은 의미에서, 아들은 우주 어머니이시다.","r":"6:8.1"}]}],"see":["우주 아버지","무한 영","파라다이스 삼위일체","창조자 아들 미가엘","기도","자비"],"n":4,"en":"Eternal Son"},{"t":"예배","sum":"예배는 창조자와의 친밀한 관계를 인식하고 기뻐하는 행위로, 모든 지성 존재의 가장 높은 특권이자 첫째 의무이다. 자기 이익이 섞인 기도와 달리 예배는 아무것도 구하지 않고 하나님을 그분 자체로 인해 경배한다. 원시인의 자연 숭배에서 시작된 예배 충동은 보조 영들의 인도로 자연의 하나님을 향하게 되었고, 파라다이스에서는 가장 높은 기쁨이 된다.","sections":[{"h":"예배의 본질","items":[{"q":"예배는 모든 창조된 지성체의 가장 높은 특권이자 첫째 의무이다.","r":"27:7.1"},{"x":"예배는 창조자들이 창조체와 맺는 친밀하고 인격적인 관계를 의식적으로 기쁘게 인정하는 행위이다.","r":["27:7.1"]},{"x":"가장 높은 의미에서 예배를 받으시는 분은 직접이든 간접이든 우주 아버지이시다.","r":["5:3.1"]},{"x":"예배는 신성하게 실제적인 것, 곧 실체의 근원과 나누는 개인적 교통이며 헛된 독백이 아니다.","r":["196:3.22"]},{"x":"예배는 부분이 전체와, 유한이 무한과, 아들이 아버지와 발을 맞추는 행위이다.","r":["143:7.8"]}]},{"h":"예배와 기도","items":[{"q":"예배는 그 자체를 위한 것이다. 반면에 기도는 자기 이익 또는 창조체 이익의 요소를 포함한다.","r":"5:3.3"},{"x":"참된 예배는 아무것도 요청하거나 대가를 기대하지 않고, 아버지의 사랑스러운 본성에 대한 자연스러운 반응으로 드려진다.","r":["5:3.3"]},{"x":"예배에 자기 이익이 끼어들면 그것은 곧 기도로 바뀐다.","r":["5:3.4"]},{"q":"기도는 자기를 상기시키는 고상한 사고이다. 예배는 자기를 잊는 초월적 사고이다.","r":"143:7.7"},{"x":"기도는 영적으로 지탱해 주지만 예배는 신성하게 창조적이며, 기도는 삶을 풍요롭게 하고 예배는 운명을 비춘다.","r":["143:7.5","102:4.5"]},{"x":"현대 종교들은 기도를 지나치게 강조하여 더 본질적인 예배의 교통을 소홀히 했다.","r":["102:4.5"]}]},{"h":"혼과 조절자의 예배","items":[{"x":"진지한 예배는 진화하는 혼의 주도 아래 조절자의 방향에 따라 인격의 모든 힘을 결집하는 것이다.","r":["5:3.7"]},{"x":"필사자의 마음은 예배에 동의하고, 혼은 그것을 갈망하며, 조절자는 그 예배를 아버지께 인도한다.","r":["5:3.8"]},{"x":"아버지의 단편들은 대상자의 진정한 찬미를 우주 아버지 앞에 등록할 권한을 지닌다.","r":["5:3.2"]},{"x":"아버지의 영은 사람의 마음이 참된 예배의 태도를 취할 때 가장 잘 말씀하신다.","r":["146:2.17"]},{"q":"필사자의 마음은 예배에 동의하고, 불멸의 혼은 그것을 갈망하며 시작하고, 신성한 조절자의 현존은 필사자 마음과 진화하는 불멸의 혼을 대신하여 그러한 예배를 인도한다.","r":"5:3.8"}]},{"h":"예배 충동의 기원","items":[{"x":"원시인은 이해할 수 없는 자연의 힘을 두려워하며 땅과 하늘의 거의 모든 것을 숭배했다.","r":["85:0.4"]},{"x":"여섯째 보조 영인 예배의 영이 원시적 마음 속에서 예배 충동을 끊임없이 자극했다.","r":["85:7.1"]},{"x":"예배의 영은 혼을 지닐 수 있는 존재와 그렇지 않은 존재를 가르는 영적 상승 후보의 표지이다.","r":["36:5.11"]},{"x":"지혜의 영이 예배 충동을 인도할 때 사람은 자연의 대상에서 돌아서서 자연의 하나님을 향하기 시작한다.","r":["85:7.3"]},{"q":"예배는 영적 상승 후보 자격의 휘장이다.","r":"36:5.11"}]},{"h":"예배하는 삶","items":[{"x":"예배, 곧 영적 사색은 물질적 현실과 맞닿는 봉사와 번갈아 이루어져야 한다.","r":["143:7.3"]},{"q":"예배는 다수에 대한 봉사의 영감을 얻기 위해 하나를 바라보는 기법이다.","r":"143:7.6"},{"x":"예배는 노력 없는 주의 집중이자 혼의 참된 안식이며, 휴식이 되는 영적 활동이다.","r":["143:7.7"]},{"x":"시간 속에서 사고는 지혜로, 지혜는 예배로 이어진다.","r":["112:2.13"]},{"x":"파라다이스에서 예배는 가장 높은 기쁨이자 새 힘을 주는 놀이이며, 모든 예술이 예배에 쓰인다.","r":["27:7.2","27:7.5"]},{"x":"일곱째 맨션 세계에서 상승자는 보이지 않는 아버지에 대한 새롭고 더 영적인 예배를 시작한다.","r":["47:9.2"]}]}],"see":["기도","우주 아버지","생각 조절자","보조 마음 영","종교 체험","봉사"],"n":53,"en":"Worship"},{"t":"예수의 가르침","sum":"예수의 가르침은 하나님이 모든 사람의 아버지이시며, 사람은 신앙으로 그 아들임을 깨닫고 서로 형제가 된다는 단순한 복음에 뿌리를 둔다. 하늘 왕국은 정치적 나라가 아니라 각 사람 안에서 시작되는 영적 체험이며, 신앙이 그 문을 연다. 예수는 이웃을 자신처럼 사랑하는 것을 넘어 그가 사랑한 것처럼 사랑하라는 새 계명을 주었고, 전통과 권위의 종교에서 하나님을 직접 아는 영의 종교로 사람들을 불러냈다.","sections":[{"h":"복음의 중심","items":[{"q":"하나님은 너희 아버지시며, 종교, 곧 나의 복음은 너희가 그의 아들이라는 진리를 신앙으로 인식하는 것일 뿐이다.","r":"141:4.2"},{"x":"예수는 하나님이 죄를 장부에 적어 두는 심판자가 아니라, 각 사람을 사랑하는 아버지라는 새로운 개념을 가르쳤다.","r":["141:4.1"]},{"x":"하늘 왕국은 하나님의 아버지됨과 사람의 형제단이라는 진리 위에 세워지며, 이 가르침은 사람을 오래된 동물적 두려움에서 해방한다.","r":["170:2.1","170:2.2"]},{"x":"예수는 복음이 왕국이라는 말보다 가족 관계의 말로 제시될 때 다른 시대 사람들이 더 잘 이해할 것이라 했다.","r":["142:7.4"]},{"x":"그의 복음은 사람이 마귀의 자식이라는 미신에서 사람을 건져 하나님의 신앙 아들이라는 존엄으로 높였다.","r":["194:2.1"]}]},{"h":"하늘 왕국","items":[{"x":"예수는 하늘 왕국이 지상 왕국이나 현세 정부와 무관하다고 했지만, 유대인의 마음에 깊이 박힌 현세적 왕 관념은 쉽게 뽑히지 않았다.","r":["170:0.1"]},{"q":"왕국에 관해 그의 마지막 말은 항상 “왕국은 너희 안에 있다”였다.","r":"170:1.13"},{"x":"단순하고 어린아이 같은 신앙이 왕국의 문을 여는 열쇠이고, 들어간 뒤에는 의로움의 단계를 따라 자라야 한다.","r":["170:3.2"]},{"x":"하나님의 용서는 사람이 동료를 용서하는 만큼 실제로 체험된다.","r":["170:3.3","170:3.4"]},{"x":"왕국은 이 땅에서 시작해 연속적인 삶의 단계를 거쳐 파라다이스로 발전하는 진화적 체험이다.","r":["142:7.3"]}]},{"h":"사랑과 새 계명","items":[{"x":"형제의 사랑은 이웃을 자신처럼 사랑하는 것이지만, 아버지의 사랑은 예수가 사랑한 것처럼 사람을 사랑하는 것이다.","r":["140:5.1"]},{"x":"제자들은 하나님이 사람을 보시는 눈으로 사람을 보도록 힘써, 아버지 같은 애정을 드러내기 시작해야 한다.","r":["140:5.3"]},{"q":"곧 내가 너희를 사랑한 것처럼 너희가 서로 사랑하라.","r":"180:1.1"},{"x":"새 계명은 새로운 짐이 아니라, 동료에게 애정을 나누는 새로운 기쁨을 주려는 것이다.","r":["180:1.2"]},{"x":"‘악을 대적하지 말라’는 말은 죄를 묵인하라는 뜻이 아니라, 자기 인격에 대한 모욕에 앙갚음하지 말고 용서하라는 뜻이었다.","r":["141:3.8"]}]},{"h":"영의 종교","items":[{"x":"예수는 새 가르침을 옛것 위에 덧대려 하지 말고, 어린아이처럼 거듭나 새로 시작하라고 했다.","r":["140:6.2"]},{"x":"그가 요구한 의로움은 자선·기도·금식으로 호의를 사려는 것이 아니라, 사랑과 자비와 진리로 아버지의 뜻을 행하려는 열망이다.","r":["140:6.3"]},{"x":"인간 혼이 이룰 가장 위대한 발견은 자기 안에서 하나님을 발견하고, 그것을 개인적 체험으로 사실화하는 것이다.","r":["155:6.3"]},{"q":"마음의 종교는 너희를 과거에 절망적으로 묶어 두지만, 영의 종교는 점진적 계시로 이루어지며,","r":"155:6.4"},{"x":"예수는 모두가 같은 생각을 하라고 가르치지 않았으니, 신자들은 다양성 속에서도 아버지의 뜻을 행하려는 동기와 목표로 하나 된다.","r":["141:5.1","141:5.3"]},{"q":"나는 세상에 영적 자유를 선포하러 왔으며, 이는 필사 존재들이 하나님 앞에서 독창성과 자유의 개인적인 삶을 살 수 있도록 힘을 부여하기 위함이다.","r":"141:5.1"}]},{"h":"가르침을 전하는 길","items":[{"x":"늘 사람의 인격을 존중하고, 논리나 웅변, 두려움이나 감상으로 사람을 압도해 왕국으로 끌어들이지 말라.","r":["159:3.2"]},{"x":"복음은 자기 존중을 잃은 이에게 그것을 되찾아 주고, 지나친 이에게는 절제하게 한다.","r":["159:3.3"]},{"x":"하나님을 신뢰하라는 가르침은 수동적 운명론이 아니며, 예수가 반대한 것은 앞일을 생각하는 것이 아니라 걱정과 불안이었다.","r":["140:8.2","140:8.3"]},{"x":"그의 가르침은 온순한 신비가의 말이 아니라 역동적이었고, 그는 선한 뜻을 품었을 뿐 아니라 실제로 선을 행했다.","r":["141:3.6"]}]},{"h":"예수의 종교","items":[{"q":"예수에 대한 종교를 설교할 수는 있지만, 반드시 예수의 종교를 살아야 한다.","r":"196:2.1"},{"x":"왕국의 복음은 예수 자신의 종교 체험에 기초하지만, 그리스도교는 주로 바울의 체험에 기초한다.","r":["196:2.1"]},{"x":"왕국의 메시아가 교회의 구속자로 바뀌면서 예수의 가르침은 유대 토양에서 이방 토양으로 옮겨 갔다.","r":["170:5.3"]},{"x":"진리의 영은 각 세대에게 예수의 메시지를 새롭게 다시 진술하여, 그의 가르침을 기억하고 이해하도록 돕는다.","r":["194:2.1","194:2.5"]}]}],"see":["하나님 나라","하나님의 아들됨","사람의 형제됨","비유","예수의 성품","신앙"],"n":86,"en":"Teachings of Jesus"},{"t":"예수의 부활","sum":"예수는 서기 30년 4월 9일 일요일 새벽, 육신이 아니라 맨션 세계의 부활 전당에서 상승자들이 깨어나는 것과 같은 모론시아 인격의 모습으로 무덤에서 나왔다. 그의 육체는 무덤에 그대로 남았다가 천사장들의 요청으로 해체되었다. 부활한 예수는 사십 일 동안 열아홉 번 신자들에게 나타나며 상승 필사자의 모론시아 생애를 체험했고, 그의 부활은 모든 신자가 죽음 뒤에 일어날 것을 보증하는 생명의 선물을 드러냈다.","sections":[{"h":"부활의 아침","items":[{"q":"서기 30년 4월 9일 일요일 새벽 세 시 이 분에 부활한 나사렛 예수의 모론시아 형태와 인격이 무덤에서 나왔다.","r":"189:1.1"},{"x":"그가 나온 뒤에도 육신은 리넨에 싸인 채 그대로 누워 있었고, 무덤의 돌과 빌라도의 봉인도 그대로였다.","r":["189:1.2"]},{"x":"파라다이스의 일곱 인격이 무덤을 둘러쌌지만, 이 지역 우주의 어떤 창조체도 그 깨어남에 관여하지 않았다.","r":["189:1.4","189:1.5"]},{"x":"부활한 예수는 모론시아 집단들에게, 상승 창조체들의 생애를 더 온전히 알고 아버지의 뜻을 더 계시하려고 잠시 머물겠다고 말했다.","r":["189:1.10"]},{"x":"같은 아침 모론시아 미가엘은 가브리엘에게 행성 부활의 점호를 시작하라고 명했다.","r":["189:3.1"]},{"x":"아담 시대 이래 잠들어 있던 유란시아의 생존자들이 맨소니아의 부활 전당에서 깨어났으니, 이것이 셋째 섭리 시대적 부활이었다.","r":["189:3.2","189:3.3"]}]},{"h":"어떤 몸으로 일어났는가","items":[{"q":"그의 물질적 또는 육체적 몸은 부활한 인격의 일부가 아니었다.","r":"189:1.7"},{"x":"그는 영으로서도, 육신화 이전의 창조자 미가엘의 모습으로서도 무덤에서 나오지 않았다.","r":["189:1.8"]},{"x":"그는 첫째 맨션 세계의 부활 전당에서 깨어나는 상승자들과 같은 모론시아 인격의 모습으로 나왔다.","r":["189:1.9"]},{"x":"천사장들은 창조자의 인간 형태가 서서히 썩는 것을 보지 않도록 그의 몸을 맡아 시간을 가속하는 과정으로 해체했다.","r":["189:2.1","189:2.3"]},{"x":"무덤의 돌을 굴린 것은 2차 중도자들이었고, 이를 본 경비병들은 공포에 질려 달아났다.","r":["189:2.4"]}]},{"h":"모론시아 출현","items":[{"x":"예수는 승천까지 열아홉 번 신자들에게 나타났다.","r":["190:2.1"]},{"q":"그는 그의 적들이나 그의 눈에 보이는 형태의 현시를 영적으로 이용할 수 없는 사람들에게는 나타나지 않았다.","r":"190:2.1"},{"x":"빈 무덤의 막달라 마리아는 예수를 동산 관리인으로 여기고 주님을 어디로 옮겼느냐고 물었다.","r":["189:4.10"]},{"q":"나를 만지지 말라, 마리아야. 나는 네가 육신으로 알던 그런 내가 아니다.","r":"189:4.12"},{"x":"사람의 눈이 그의 모론시아 모습을 볼 수 있었던 것은 변형자와 중도자들의 특별한 사역 덕분이었다.","r":["189:4.11"]},{"x":"주님을 부인한 죄책에 짓눌리던 베드로에게 예수가 홀로 나타나 그의 신앙이 의심을 이기게 했다.","r":["191:1.1","191:1.2"]},{"q":"다가올 시대에 육신의 눈으로 보지 않고 필사자의 귀로 듣지 않고도 믿을 자들은 복이 있다.","r":"191:5.5"}]},{"h":"더디게 믿은 사도들","items":[{"x":"사도들은 죽음과 부활에 관한 예수의 말을 가볍게 여겼고, 부인할 수 없는 체험 앞에서야 믿었다.","r":["190:1.1"]},{"x":"여인들의 보고를 들은 사도들 가운데 요한만이 부활을 어렴풋이 믿으려 했고, 다른 이들은 유대인들이 시신을 옮겼다고 여겼다.","r":["190:1.2","190:1.3"]},{"x":"예수는 사도들에게 아버지께서 자신을 보내신 것처럼 그들을 보낸다며, 신성한 사랑을 날마다의 삶으로 계시하라고 했다.","r":["191:5.3"]}]},{"h":"부활의 의미","items":[{"q":"예수 안에 내재한 이 모든 권능, 곧 그가 죽음에서 일어날 수 있게 한 생명의 부여는 그가 왕국 신자들에게 증여하는 바로 그 영원한 생명의 선물이다.","r":"190:0.2"},{"x":"필사자들도 부활의 아침에 예수가 입었던 것과 같은 모론시아 몸으로 일어날 것이며, 그 몸은 피가 돌지 않지만 실재한다.","r":["190:0.3"]},{"x":"물질은 모론시아의 골격이며, 둘 다 영속하는 영 실체의 반사된 그림자라는 것을 사람은 더디게 깨닫는다.","r":["189:1.3"]},{"x":"오순절에 제자들이 전한 가장 큰 소식은 부활한 주님이었고, 이것이 그리스도교가 부활한 그리스도와의 교제를 중심으로 자라나는 계기가 되었다.","r":["194:0.3","194:0.4"]}]},{"h":"승천","items":[{"x":"올리브산에서 예수가 사라진 이른바 승천은 사십 일 동안 시야에서 사라졌던 다른 경우들과 다르지 않았다.","r":["193:5.3"]},{"x":"그는 예루셈과 에덴시아를 거쳐 모론시아 상태에서 풀려나, 파라다이스 아들됨과 샐빙턴의 최상 주권으로 돌아갔다.","r":["193:5.4"]},{"x":"예수가 열한 사도의 시야에서 사라져 네바돈에 대한 완성된 주권을 확인받으러 아버지께 오르기 시작한 것은 그날 아침 일곱 시 사십오 분쯤이었다.","r":["193:5.5"]}]}],"see":["예수의 십자가 죽음","모론시아","오순절","생존","맨션 세계","열두 사도"],"n":91,"en":"Resurrection of Jesus"},{"t":"예수의 성품","sum":"유란시아서가 그리는 예수의 성품에서 가장 독특한 점은 흠 없음보다 대칭, 곧 모든 자질이 절묘하게 균형을 이룬 통일성이다. 그는 열정적이면서 광신적이지 않았고, 용감하면서 무모하지 않았으며, 기쁨에 차 있으면서도 겸손했다. 그 중심에는 하나님을 향한 아이 같은 신뢰와 사람에 대한 깊은 사랑이 있었고, 그는 따르는 이들에게 자신을 믿으라기보다 자신과 함께 믿으라고 청했다.","sections":[{"h":"균형과 통일성","items":[{"q":"주님의 인격의 독특한 점은 완전성이라기보다 대칭성, 즉 절묘하고 균형 잡힌 통일성에 있었다.","r":"100:7.1"},{"x":"보통 사람이 예수의 완전한 성품에 이를 수는 없어도, 그의 인격을 따라 강하고 통합된 인격을 기르는 것은 충분히 가능하다.","r":["100:7.1"]},{"x":"그는 감정이 풍부하되 가볍지 않았고, 동정심이 있되 감상적이지 않았으며, 경건하되 경건한 체하지 않았다.","r":["100:7.4"]},{"x":"그의 계획은 성별된 상식을 띠었고, 별나거나 변덕스럽거나 히스테릭한 데가 전혀 없었다.","r":["100:7.3"]},{"x":"예수는 완벽하게 통합된 인격으로서 오늘도 사람의 체험을 통합하고 삶을 단순하게 만든다.","r":["100:7.18"]},{"q":"예수는 선했기 때문에 위대했으며, 그러면서도 어린아이들과 어울렸다.","r":"100:7.17"}]},{"h":"진실함과 용기","items":[{"x":"그는 꾸밈이나 위선이 없었고 가르친 대로 살았으며, 때로 그 성실함이 고통을 불렀어도 진리에 충실했다.","r":["100:7.2"]},{"x":"그는 솔직했지만 늘 친절했고, 죄는 미워했으나 죄인은 사랑했으며 그 모든 정직함 속에서 공정했다.","r":["100:7.11"]},{"q":"그의 용기는 위대했으나 무모하지 않았다. 그의 표어는 “두려워하지 말라.”였다.","r":"100:7.15"},{"x":"사람들이 재촉해도 ‘아직 나의 때가 이르지 않았다’며 서두르지 않았고, 악에 분개해도 그 분노가 죄인에게 향하지 않았다.","r":["100:7.14"]},{"x":"그는 대중의 지지를 구하지 않고 사람들의 의견에 흔들리지 않았으며, 용감하되 교만하지 않았다.","r":["161:2.8"]}]},{"h":"기쁨과 친절","items":[{"q":"갈릴리의 이 사람은 슬픔의 사람이 아니라 기쁨의 사람이었다.","r":"100:7.13"},{"x":"그는 맹목적 낙관주의자가 아니었지만, 하나님에 대한 신뢰와 사람에 대한 확신으로 늘 ‘기운을 내라’고 격려했다.","r":["100:7.9"]},{"x":"예수는 기쁨의 아이요 보기 드문 유머의 사람이었으며, 동시에 슬픔을 아는 사람이었다.","r":["129:4.4"]},{"x":"은혜로움은 사랑으로 가득한 혼에서 풍기는 우정의 향기이며, 예수는 가는 곳마다 그 기쁨을 퍼뜨렸다.","r":["171:7.1","171:7.2"]},{"x":"그는 늘 관대하여 주는 것이 받는 것보다 복되다고 되풀이했지만, 낭비하거나 사치하지는 않았다.","r":["100:7.10"]}]},{"h":"사람을 대하는 방식","items":[{"x":"예수는 사람들을 참으로 이해했기에 진정한 공감을 보였지만, 동정에 빠지거나 상대의 자기 연민을 키우지 않았다.","r":["171:7.3"]},{"x":"그는 결코 서두르지 않고 ‘지나가며’ 사람들을 위로했으며, 상대는 고백하기보다 그와 의논한다고 느꼈다.","r":["171:7.5"]},{"x":"그는 사람을 지시하거나 관리하려 하지 않았고, 그의 미소를 받은 이는 자기 문제를 풀 힘이 커짐을 느꼈다.","r":["171:7.6"]},{"x":"사람들이 그를 믿었을 뿐 아니라 그 역시 사람들을 크게 믿었기에 위대한 일들이 일어났다.","r":["171:7.8"]},{"q":"“그는 두루 다니며 선을 행했다”는 말이 문자 그대로 사실이었다.","r":"171:7.9"},{"x":"사도들은 그를 아첨하지 않으면서 모두를 똑같이 친절하게 대하는 충실한 친구, 죄인과 원수까지 사랑하는 이로 기억했다.","r":["161:2.3"]}]},{"h":"아이 같은 신앙","items":[{"x":"예수의 신앙은 전통이나 지적 신념이 아니라 내주하는 조절자와의 체험에서 태어난 전적으로 개인적이고 영적인 것이었다.","r":["196:0.1","196:0.5"]},{"x":"그는 신앙을 고난 속 위안으로 붙든 것이 아니라, 아버지 현존 안에서 사는 평온과 전율로 누렸다.","r":["196:0.3"]},{"q":"예수는 아이가 부모를 신뢰하듯 하나님을 신뢰했다.","r":"196:0.11"},{"x":"그의 강한 신앙은 결코 광신으로 흐르지 않았고, 가족 사랑과 사회적 의무, 경제적 필요에 대한 균형 잡힌 판단과 늘 조화를 이루었다.","r":["196:0.6","196:0.7"]},{"x":"선한 선생이라 불리자 ‘어찌하여 나를 선하다 하느냐’고 답한 데서 그의 빛나는 자기 망각이 드러난다.","r":["196:0.9"]}]},{"h":"그를 따른다는 것","items":[{"x":"예수는 제자들에게 자신을 믿으라고 하지 않고, 자신과 함께 하나님의 사랑을 믿으라고 요구했다.","r":["196:0.13"]},{"x":"예수를 따른다는 것은 그의 신앙을 함께 나누고, 사람을 위한 이기심 없는 봉사의 영에 참여하는 것이다.","r":["196:1.3"]},{"x":"신학 전통 속에 묻힌 인간 예수가 살아 있는 예수로 다시 드러나는 것이 이 계시의 큰 봉사가 될 것이다.","r":["196:1.1","196:1.2"]}]}],"see":["예수의 증여","예수의 가르침","신앙","사랑","기쁨과 행복","열두 사도"],"n":85,"en":"Character of Jesus"},{"t":"예수의 십자가 죽음","sum":"예수는 서기 30년 금요일 골고다에서 십자가에 못 박혀 죽었다. 유란시아서는 이 죽음이 하나님의 진노를 달래거나 인류의 빚을 갚기 위한 속죄 제물이 아니었으며, 아버지가 요구한 것도 아니고 사람이 계획하고 실행한 일이었다고 밝힌다. 십자가의 참된 의미는 죽음의 사실이 아니라 그가 죽음을 맞이한 방식과 영, 곧 원수까지 용서한 사랑의 최상 표현에 있으며, 그로써 십자가는 이기심 없는 봉사의 영원한 상징이 되었다.","sections":[{"h":"체포에서 골고다까지","items":[{"x":"체포될 때 예수는 육신으로서의 일이 끝났음을 알았고, 이른바 재판의 세부에는 거의 관심을 두지 않았다.","r":["186:2.1"]},{"x":"그는 위증에 답하지 않았지만, 자신이 하나님의 아들이냐는 질문에는 언제나 대답했다.","r":["186:2.2"]},{"x":"그는 보통 사람처럼 자연스러운 사건의 흐름을 따르는 것이 아버지의 뜻이라 확신하여, 자신의 웅변으로 결과를 바꾸려 하지도 않았다.","r":["186:2.3"]},{"x":"그는 금요일 아침 아홉 시 반쯤 십자가에 달렸고, 보이지 않는 우주의 무리는 창조자가 창조체의 죽음을 맞는 광경을 침묵 속에 지켜보았다.","r":["187:3.1"]}]},{"h":"십자가 위의 시간","items":[{"q":"그들이 그를 십자가 가로대에 못 박을 때, 예수의 유일한 말은 “아버지여, 저들을 용서하소서. 저들은 자기들이 하는 일을 알지 못합니다”였다.","r":"187:2.4"},{"x":"목이 말랐어도 예수는 고통을 덜어 주려는 마약 탄 포도주를 거절했다.","r":["187:2.3"]},{"x":"그를 조롱한 강도와 달리 다른 강도는 마지막 시간에 온 마음으로 돌아서 구원을 얻었다.","r":["187:4.1","187:4.2"]},{"x":"모래 폭풍으로 하늘이 어두워진 가운데, 예수는 ‘다 이루었다’고 외치고 아버지께 영을 맡긴 뒤 숨을 거두었다.","r":["187:5.1","187:5.5"]},{"x":"그가 죽는 모습을 본 로마 백부장은 그가 참으로 하나님의 아들이었다고 고백했다.","r":["187:5.5"]},{"q":"예수는 그가 살았던 대로 왕처럼 죽었다.","r":"187:5.6"}]},{"h":"속죄 제물이 아니었다","items":[{"x":"예수는 인종의 죄책을 속죄하거나, 노여워하는 하나님께 다가갈 길을 마련하려고 죽은 것이 아니다.","r":["188:4.1"]},{"x":"그의 죽음은 사람을 타락한 통치자들에게서 되사기 위한 몸값도, 인류가 하나님께 진 빚을 갚는 희생도 아니었다.","r":["188:4.3"]},{"x":"몸값과 속죄라는 관념 전체는 예수가 가르치고 보여 준 사랑의 아버지 하나님 개념과 양립할 수 없다.","r":["188:4.8"]},{"x":"죄는 부모에게서 자녀로 전해지지 않으며, 개별 의지 창조체가 의식적으로 저지르는 반역이다.","r":["188:4.5"]},{"x":"정의의 군주라 해도, 죄인 대신 무고한 이를 세우는 유치한 방책에 만족할 리 없다.","r":["188:4.11"]}]},{"h":"누가 그를 죽였는가","items":[{"q":"십자가에서의 예수의 죽음을 계획하고 실행한 것은 하나님이 아니라 사람이었다.","r":"186:5.2"},{"x":"그의 죽음과 유대인의 유월절 희생 제도 사이에는 직접적인 관계가 없다.","r":["186:5.1"]},{"x":"증여에 필요한 체험은 세례 때 이미 완료되었고, 그 뒤의 삶과 죽음의 방식은 창조체들을 위한 그의 개인적 사역이었다.","r":["186:5.3"]},{"x":"신앙으로 하나님의 아들임을 깨닫는다는 복음은 그의 죽음에 의존하지 않으며, 죽음보다 삶으로 더욱 밝혀졌다.","r":["186:5.4"]},{"x":"아버지는 예수가 살고 죽기 전에도 이후와 똑같이 사람을 사랑하셨다.","r":["186:5.6"]}]},{"h":"십자가의 참된 의미","items":[{"q":"예수의 죽음이 인간의 체험을 풍요롭게 하고 구원의 길을 확장하는 것과 관련하여 중요한 것은 그의 죽음의 사실이 아니라, 그가 죽음을 맞이한 탁월한 방식과 비길 데 없는 영이다.","r":"188:4.12"},{"q":"십자가는 하나님과 인간 사이의 모든 관계를 가족이라는 기반 위에 영원히 올려놓는다.","r":"188:5.1"},{"x":"신성한 사랑은 잘못을 용서하는 데 그치지 않고 그것을 흡수하여 실제로 파괴하니, 사랑의 용서는 자비의 용서를 넘어선다.","r":["188:5.2"]},{"x":"예수는 이십오 년 넘게 필사 실존이라는 십자가를 졌고, 골고다는 그 사랑의 최종 표현이었다.","r":["188:5.4"]},{"q":"예수를 희생을 바치는 자, 몸값을 치르는 자, 구속자로 부르는 것은 적절하지 않을지 모르지만, 그를 구원자라고 부르는 것은 전적으로 옳다.","r":"188:4.7"},{"x":"그는 이 세상만이 아니라 온 우주를 위해 살고 죽었으며, 그의 죽음은 육신의 죽음 뒤 생존의 확실성을 밝혔다.","r":["188:4.6"]}]},{"h":"봉사의 상징","items":[{"x":"원수를 위해 목숨을 버린 그의 사랑은 그때까지 지상에 알려진 어떤 사랑보다 컸다.","r":["188:5.7"]},{"x":"십자가는 진노를 달랜 대속의 상징이 아니라, 선한 이가 자신을 악한 이에게 바쳐 사랑으로 구원하는 이기심 없는 봉사의 상징이다.","r":["188:5.9"]},{"x":"수많은 세계의 창조체들이 십자가의 예수를 바라보며 신앙의 싸움을 포기하지 않고 다시 앞으로 나아갔다.","r":["188:5.5"]},{"x":"십자가에는 아버지가 요구한 것이 하나도 없었고, 오직 예수가 기꺼이 내주고 피하기를 거부한 것만 있었다.","r":["188:5.11"]},{"x":"그 죽음은 사람을 하나님과 화해시키려는 것이 아니라, 하나님의 영원한 사랑과 아들의 자비를 깨닫게 하려는 것이었다.","r":["188:5.13"]}]}],"see":["예수의 증여","예수의 부활","사랑","용서","죽음","봉사"],"n":90,"en":"Death on the Cross"},{"t":"예수의 증여","sum":"예수의 증여는 네바돈의 창조자 아들 미가엘이 일곱째이자 마지막 증여로 유란시아에 필사자의 아기로 태어나 사람의 삶을 끝까지 산 사건이다. 이 증여로 미가엘은 체험을 통해 우주 주권을 완성했고, 루시퍼 반란을 종결했으며, 무엇보다 사람에게 하나님을 계시하고 하나님께 완전해진 사람을 보여 주었다. 유란시아서는 이 증여의 최상 목적이 하나님의 계시를 높이는 데 있었다고 강조한다.","sections":[{"h":"일곱 증여와 체험으로 얻은 주권","items":[{"x":"창조자 아들은 자기가 만든 존재들의 모습으로 그들과 같은 삶을 살아야 하니, 이것이 우주 주권을 위해 치르는 대가의 일부이다.","r":["120:0.1"]},{"x":"미가엘은 멜기세덱·라노난덱·아담·세라핌·필사자·모론시아 필사자로 여섯 번 증여한 뒤, 일곱째로 유란시아에서 살과 피를 지닌 필사자가 되었다.","r":["119:8.4","120:0.2"]},{"q":"미가엘은 창조자로 태어났고, 행정가로 교육받았으며, 집행자로 훈련되었지만, 체험을 통해 자신의 주권을 획득해야 했다.","r":"119:8.2"},{"x":"증여마다 미가엘은 파라다이스 신들의 서로 다른 뜻에 자신을 종속시켰고, 유란시아에서는 우주 아버지의 뜻에 전적으로 복종했다.","r":["120:0.4","120:1.2"]},{"x":"일곱 증여의 총합은 최상 존재에 대한 네바돈의 새로운 계시가 되었고, 최상위의 주권을 확장하는 데도 기여했다.","r":["119:8.3","119:8.5"]},{"x":"영원 아들은 파라다이스 아들들의 육신화를 통해 창조체의 체험에 참여하며, 그렇게 미가엘 안에서 실제로 필사 인간에게 오셨다.","r":["7:5.3","7:5.4"]}]},{"h":"임마누엘의 당부","items":[{"x":"이전 증여와 달리 미가엘은 완전히 성장한 존재가 아니라 무력한 아기로 유란시아에 나타나야 했다.","r":["120:1.1"]},{"x":"미가엘은 행성 밖의 모든 도움을 내려놓고, 오직 파라다이스 아버지만을 의지하여 필사 생애를 살아야 했다.","r":["120:1.3"]},{"q":"너의 유란시아 증여 내내 너는 오직 한 가지, 곧 너와 너의 파라다이스 아버지 사이의 끊어지지 않는 교제에만 관심을 가지면 된다.","r":"120:1.4"},{"x":"임마누엘은 그가 주로 교사가 되어, 먼저 사람의 영적 본성을 해방하고 마음을 밝히며 오래된 두려움에서 풀어 주라고 권했다.","r":["120:2.5"]},{"x":"경제·정치 문제에 얽히지 말고, 조직화된 종파를 만들지 말며, 글이나 초상을 남기지 말라는 충고도 받았다.","r":["120:3.4","120:3.6","120:3.7"]},{"x":"증여 아들은 행성에 인간 후손을 남기지 않으므로, 예수는 결혼 관계에 들어가지 않을 것이었다.","r":["120:3.8"]}]},{"h":"증여의 목적","items":[{"x":"사람의 아들로서 사타니아의 루시퍼 반란을 형식상 끝내고, 유란시아의 행성 영주로 인정받는 것이 증여의 한 목표였다.","r":["120:2.2","120:2.3"]},{"x":"그의 삶은 유란시아 사람들의 모범이 되기보다 온 네바돈의 모든 세대에 영감을 주도록 의도되었다.","r":["120:2.7"]},{"x":"그는 육신의 창조체들에게 아버지를 계시하는 동시에, 하나님께 인간에 대한 새로운 계시를 보여 주었다.","r":["120:2.8"]},{"x":"증여를 마치며 진리의 영을 부어 모든 정상적인 필사자가 조절자의 봉사에 곧바로 접근할 수 있게 하라는 당부를 받았다.","r":["120:2.6"]},{"q":"미가엘 증여의 최상의 영적 목적이 하나님의 계시를 높이는 것이었다는 사실을 결코 잊지 말라.","r":"120:4.4"},{"x":"자기를 잊은 봉사의 생애는 창조자가 이기적으로 권력을 쥐고 있다고 비난하던 자들을 영원히 침묵시켰다.","r":["120:4.1"]}]},{"h":"하나님이며 사람","items":[{"q":"그는 인간과 연합한 하나님이 아니라 오히려 인간 안에 육신화한 하나님이었다.","r":"120:4.2"},{"x":"예수는 점차 하나님이 된 것도, 어느 순간 사람이 된 것도 아니라 언제나 하나님이자 사람이었으며, 자라난 것은 그 사실에 대한 자각이었다.","r":["120:4.2","120:4.3"]},{"x":"파라다이스 아들이 자연스러운 과정으로 세상에 나타나는 증여는 지역 우주 시민들에게도 가장 흥미로운 기적이다.","r":["120:4.5","120:4.6"]}]},{"h":"충만한 인간의 삶","items":[{"x":"예수는 유아기부터 죽음까지 인간의 모든 시기를 거쳤고, 기쁨에서 깊은 슬픔까지 넓은 감정을 몸소 겪었다.","r":["129:4.4","129:4.5"]},{"x":"그는 모든 사람이 흉내 낼 세부적 본보기를 세우려 한 것이 아니라, 각자가 자기 시대에 자기답게 살 수 있도록 참된 인간의 삶을 살았다.","r":["129:4.7"]},{"x":"그의 삶은 사람에게 하나님을 충만히 계시하고, 하나님께 완성된 인간 인격을 바친 것으로 아버지에게 온전히 받아들여졌다.","r":["129:4.6"]},{"q":"그는 사람에게 드러날 하나님의 충만함으로 땅에 왔으며, 이제 하나님께 드러날 기회를 기다리는 사람의 완전함이 거의 되었다.","r":"129:4.8"},{"x":"요단강 세례 때 그는 마음의 정복에서 정점에 이른 완전해진 필사자였고, 조절자는 융합 대신 인격화된 조절자로 그의 곁에 섰다.","r":["136:2.2","136:2.3"]}]},{"h":"증여의 완성","items":[{"x":"유란시아 증여를 마친 미가엘은 옛적부터 늘 계신 이들과 우주 아버지에게서 네바돈의 확정된 통치자로 인정받았다.","r":["119:8.1"]},{"x":"너희의 작은 세계는 창조자 아들이 주권에 필요한 체험을 완성한 곳으로 네바돈 전역에 알려지게 되었다.","r":["119:8.2"]},{"q":"예수 안에서 우주는 사랑의 영이 시간의 물질적 장애를 극복하고 물리적 기원의 사실을 극복한 필사 인간을 만들어 냈다.","r":"195:10.2"}]}],"see":["창조자 아들 미가엘","예수의 성품","예수의 가르침","예수의 십자가 죽음","예수의 부활","루시퍼 반란"],"n":84,"en":"Bestowal of Jesus"},{"t":"옛적부터 늘 계신 이","sum":"옛적부터 늘 계신 이들은 파라다이스 삼위일체에서 나온 스물한 분의 최상 통치자로서, 세 분씩 짝을 이루어 일곱 초우주를 하나씩 맡아 다스린다. 의지 창조체의 영원한 생사에 대해 최종 집행 판결을 내리는 것은 오직 이들뿐이며, 반영의 기법으로 위로는 파라다이스를, 아래로는 지역 우주들을 한꺼번에 보고 듣는다. 필사자가 지역 우주를 졸업한 뒤 상승 여정에서 만나는 초우주 정부의 정점이다.","sections":[{"h":"삼위일체에서 나온 통치자","items":[{"x":"옛적부터 늘 계신 이들은 최상 삼위일체 인격 일곱 계층 가운데 셋째이며, 그 수가 정해져 있어 더 이상 새로 생겨나지 않는다.","r":["18:0.4","18:0.9"]},{"q":"옛적부터 늘 계신 이들은 모두 근본적으로 동일하며, 삼위일체의 결합된 성품과 통일된 본성을 드러낸다.","r":"18:3.2"},{"x":"일곱 주(主) 영은 서로 성질이 다르지만, 옛적부터 늘 계신 이들은 개별성은 지니되 한결같은 삼위일체의 초완벽한 자손이다.","r":["18:3.2"]},{"x":"스물한 분 모두 동시에 삼위일체화되었으며, 파라다이스의 인격 기록 첫머리에 바로 이들의 삼위일체화가 적혀 있다.","r":["18:3.4"]},{"q":"그들은 우주들의 우주의 인격 기록의 시작을 나타낸다. 그러므로 그들의 이름이 옛적부터 늘 계신 이들이다.","r":"18:3.4"},{"x":"삼위일체 기원의 존재에게는 실패나 반란의 위험이 없으며, 이들은 완전한 인격 행위의 길에서 벗어난 적이 없다.","r":["18:0.11"]}]},{"h":"세 분이 함께 다스리는 초정부","items":[{"q":"각 초우주는 세 분의 옛적부터 늘 계신 이들이 주재하며, 그들은 초정부의 공동 최고 집행자들이다.","r":"15:10.3"},{"x":"높은 행정에서는 언제나 세 분이 함께 활동한다. 본부 세계를 떠나지 않아도 그곳이 반영력 체계의 초점이어서 다스림에 막힘이 없다.","r":["18:3.5"]},{"x":"주(主) 영들이 초우주의 성질을 좌우한다면, 옛적부터 늘 계신 이들은 그 행정을 좌우하여 서로 다른 초우주들에 균일한 다스림을 베푼다.","r":["18:3.3"]},{"x":"지혜의 완성자·신성한 조언자·우주 검열자와, 영화롭게 된 상승 필사자 출신의 삼위일체화 아들들이 이들을 보좌한다.","r":["15:10.11","15:10.12"]},{"x":"대구역과 소구역의 늘 계신 이들이 모은 관찰 보고와 추천은 차례로 올라가 마침내 옛적부터 늘 계신 이들의 법정에 이른다.","r":["15:13.6"]},{"q":"독창성의 지혜와 개별성의 주도권이 옛적부터 늘 계신 이들의 모든 법령과 판결을 특징짓는다.","r":"18:3.9"}]},{"h":"영원한 생사에 대한 최종 심판","items":[{"x":"이들은 시공 창조계의 직접 통치자들 가운데 가장 막강하며, 의지 창조체의 영원한 소멸을 최종 판결할 권능은 이들에게만 있다.","r":["18:3.7"]},{"q":"지역 우주의 아들들은 필사 인간의 생존을 명할 수 있지만, 오직 옛적부터 늘 계신 이들만이 영원한 생사의 문제에 대해 집행 판결의 자리에 앉을 수 있다.","r":"15:12.2"},{"x":"창조자 아들들의 회복하려는 사랑의 노력이 끝내 거부될 때, 소멸의 판결은 이들의 관할 아래 있는 세력들이 집행한다.","r":["2:3.6","2:3.3"]},{"q":"이 최고 최상 법정들의 포고령에는 의견 불일치나 소수 의견이 없다.","r":"15:12.3"},{"x":"초우주의 판결에는 상소가 없다. 그것이 옛적부터 늘 계신 이들과 그 초우주를 주재하는 주(主) 영의 일치된 의견이기 때문이다.","r":["15:12.4"]},{"q":"옛적부터 늘 계신 이 세 분이 활동할 때, 파라다이스 삼위일체가 활동한다.","r":"19:3.5"},{"x":"이들과 삼위일체 기원의 동료들은 일곱 초우주 전역에 최상 공평의 정의로운 심판을 내린다.","r":["10:6.17"]}]},{"h":"모든 것을 보고 듣는 반영의 통치","items":[{"q":"거주 세계들과 파라다이스 사이, 곧 사람과 하나님 사이 중간에 자리한 옛적부터 늘 계신 이들은 즉시 양쪽을 보고, 양쪽을 듣고, 양쪽을 알 수 있다.","r":"28:4.1"},{"x":"1차 세코나핌은 살아 있는 거울이 되어 무한 영과 창조자 아들들, 천사 무리의 마음과 목소리를 이들 앞에 그대로 비춰 준다.","r":["28:4.4","28:4.6","28:4.11"]},{"x":"위에서 오는 영의 음성과 아래 미가엘들의 음성을 맞추어 아버지의 뜻을 추론하는데, 이 일에 세 분이 함께해야 하므로 초우주는 늘 셋이 주재한다.","r":["28:4.10"]},{"x":"초우주들은 서로 고립되어 있어, 다른 초우주의 통치자들과 직접 인격적으로 교신하려면 단독 사자를 통해야 한다.","r":["23:2.15","15:10.23"]}]},{"h":"지역 우주와의 관계, 그리고 미래","items":[{"x":"창조자 아들은 일곱 창조체 증여가 옛적부터 늘 계신 이들에게 인증받을 때까지 완전한 주권을 떠맡지 않겠다고 삼위일체에게 서약한다.","r":["119:0.3"]},{"x":"이들은 창조자 아들이 창조체로 실제 살아 보며 그들의 관점을 얻기 전에는 그를 우주 주권자로 인증하지 않는다.","r":["119:0.6"]},{"x":"미가엘의 청원에 따라 이들은 루시퍼 반란에 연루된 인격들의 억류를 허락했고, 대반역자들의 최종 처분도 이들의 손에 남아 있다.","r":["53:9.3","53:9.6"]},{"x":"이들의 통치 특권은 체험으로 얻은 것이 아니므로, 언젠가 체험적 주권자인 최상 존재에게 대체되고 그분의 대리 통치자가 될 것이다.","r":["18:3.8"]},{"x":"필사자의 하나님 발견 여정은 창조자 아들에서 시작해 초우주의 옛적부터 늘 계신 이와 주(主) 영을 거쳐 우주 아버지께 이른다.","r":["0:8.9"]}]}],"see":["파라다이스 삼위일체","일곱 초우주","칠중 하나님","최상 존재","일곱 주(主) 영","창조자 아들 미가엘"],"n":21,"en":"Ancients of Days"},{"t":"오순절","sum":"오순절은 예수가 떠난 뒤 진리의 영이 예루살렘 다락방의 백스무 신자를 비롯해 온 세상의 진실한 모든 이에게 부어진 날이다. 두려움에 숨어 있던 사도들은 새 권능을 입고 나와 담대히 복음을 전했고, 그날 이천 명이 넘는 이가 세례를 받았다. 유란시아서는 오순절이 감정의 분출이 아니라 예수의 종교를 민족과 인종과 성별의 굴레에서, 그리고 물리적 힘에 대한 의존에서 풀어 준 영적 사건이라고 설명한다.","sections":[{"h":"그날 일어난 일","items":[{"x":"기도하던 백스무 신자는 방 안의 낯선 현존을 느끼며, 영적 기쁨과 안전과 확신이라는 새롭고 깊은 감정을 의식하게 되었다.","r":["194:0.1"]},{"x":"베드로는 이것이 주님이 약속한 진리의 영의 오심이라 선언하고, 사원으로 가서 기쁜 소식을 전하자고 제안했다.","r":["194:0.2"]},{"x":"사십 일 동안 숨어 지내던 사도들이 오순절 축제로 붐비는 사원에 담대하게 나타났다.","r":["194:1.1"]},{"x":"베드로가 주님이 마지막으로 가르친 자리에서 열정적으로 호소하여 이천 명이 넘는 혼을 얻었다.","r":["194:1.2"]},{"x":"그날 저녁 새 신자들은 실로암 못에서 주님의 이름으로 세례를 받았고, 신자들은 한동안 유대교 안의 한 종파로 남았다.","r":["194:1.4","194:1.5"]}]},{"h":"모든 이에게 부어진 영","items":[{"q":"진리의 영이 진실한 모든 신자에게 증여되었다는 사실을 놓치지 말라.","r":"194:3.6"},{"x":"영의 선물은 사도들만이 아니라 다락방의 모든 남녀와 온 세상의 정직한 이들에게 왔다.","r":["194:3.6"]},{"x":"같은 시각 필라델피아와 알렉산드리아 등 참된 신자가 있는 모든 곳에서도 영이 임했다.","r":["194:3.17"]},{"x":"예수의 어머니와 형제도 그 자리에 있었지만 남보다 더 큰 선물을 받지 않았으니, 오순절은 거룩한 가문과 특별한 사제직에 대한 믿음의 끝이었다.","r":["194:3.15"]},{"x":"영은 어떤 형식이나 의식이나 거룩한 장소와도 무관하게, 조용히 기도하고 앉아 있던 이들에게 임했다.","r":["194:3.10"]}]},{"h":"감정이 아닌 영적 사건","items":[{"x":"후대에 오순절은 걷잡을 수 없는 감정주의와 혼동되었지만, 부어진 영의 주된 임무는 아버지의 사랑과 아들의 자비라는 진리를 가르치는 것이었다.","r":["194:3.1"]},{"q":"오순절 날에 영을 가져온 것은 기도가 아니었다.","r":"194:3.20"},{"x":"기도는 하나님을 움직여 후하게 주시게 하지는 않지만, 각 신자가 받아들일 수 있는 수용력의 크기를 정하는 데 큰 몫을 했다.","r":["194:3.20"]},{"x":"‘영의 세례’라는 말은 진리의 영의 선물을 의식적으로 받아들이고 그 새 권능을 인정하는 것을 뜻할 뿐이었다.","r":["194:2.10"]},{"x":"사도들은 자아를 잃고 영을 찾았으며, 그것은 감정의 체험이 아니라 자기를 하나님께 드린 데 대한 응답이었다.","r":["194:3.16"]}]},{"h":"굴레에서 풀린 종교","items":[{"q":"오순절 날에 예수의 종교는 모든 국가적 제한과 인종의 족쇄를 깨뜨렸다.","r":"194:3.5"},{"x":"여러 민족이 사도들의 설교를 받아들인 일은 복음이 어떤 인종이나 문화나 언어와도 동일시되지 않아야 함을 보여 주었다.","r":["194:3.9"]},{"x":"오순절 이후 왕국의 형제단 안에서 여자는 하나님 앞에 남자와 동등하게 섰다.","r":["194:3.14"]},{"x":"오순절은 주님의 종교를 물리적 힘에 대한 모든 의존에서 풀어, 용서와 선의와 사랑이라는 영적 무기를 갖추게 했다.","r":["194:3.11"]},{"q":"인류는 오직 영적 접근으로만 하나가 될 수 있고, 진리의 영은 보편적인 세계적 영향력이다.","r":"194:3.18"}]},{"h":"하나님이 사람을 찾으시다","items":[{"q":"오순절까지 종교는 사람이 하나님을 찾는 것만을 드러냈다.","r":"194:3.13"},{"x":"오순절 이후로는 하나님도 사람을 찾으시고, 찾으셨을 때 자기 영을 그 안에 거하도록 보내신다는 광경이 빛난다.","r":["194:3.13"]},{"x":"진리의 영의 증여는 모든 정상적인 사람의 마음을 뒤이은 조절자의 보편적 증여에 대비시켰다.","r":["194:2.3"]},{"x":"그 뒤로 사람은 아버지의 영인 조절자, 아들의 영인 진리의 영, 영의 영인 성령이라는 삼중의 인도를 받는다.","r":["194:2.11"]},{"x":"영이 임한 지 한 달도 못 되어 사도들은 예수와 함께한 사 년 동안보다 더 큰 영적 진보를 이루었다.","r":["194:2.9"]}]},{"h":"새 메시지와 교회의 시작","items":[{"x":"그들의 메시지는 하나님의 아버지됨과 사람의 형제단에서 부활한 그리스도를 선포하는 쪽으로 옮겨 갔다.","r":["194:0.3","194:4.4"]},{"q":"왕국의 복음, 곧 예수의 메시지는 갑자기 주 예수 그리스도의 복음으로 바뀌었다.","r":"194:4.5"},{"x":"신자들은 서로를 형제자매라 부르며 빵을 떼고 기도하고 가난한 이를 돌보는, 예배와 삶의 교제를 이루었다.","r":["194:4.3","194:4.7"]},{"x":"스테반의 순교는 초기 교회가 공식으로 조직되는 계기가 되었고, 이어진 박해로 교사들이 제국 끝까지 흩어졌다.","r":["194:4.12","194:4.13"]},{"x":"예수의 지상 생애는 시간의 닻이 되고, 진리의 영은 그가 산 종교가 영원히 자라나게 하는 원천이 된다.","r":["194:3.8"]}]}],"see":["진리의 영","예수의 부활","열두 사도","제도 종교","생각 조절자","성령"],"n":92,"en":"Pentecost"},{"t":"완전을 향한 여정","sum":"“내가 완전한 것처럼 너희도 완전하라”는 아버지의 명령은 시간과 공간의 모든 창조체를 파라다이스로 향하는 길고 매혹적인 상승으로 부르는 초대이다. 유란시아의 필사자는 무한한 의미의 완전에는 이를 수 없지만, 자기 수준에서 신성한 완전에 도달하는 것은 전적으로 가능하다. 이 여정은 조절자가 일깨우는 완전에 대한 갈망에서 시작해, 신앙으로 다져진 목적의 완전함을 품고 하보나를 거쳐 아버지께 이르며, 그 너머의 최종자 생애로 이어진다.","sections":[{"h":"완전하라는 명령","items":[{"x":"온 우주의 의지 창조체들은 아버지 하나님께 도달하려는 영원한 모험, 곧 파라다이스로 가는 길고 긴 여행을 시작했다.","r":["1:0.3"]},{"x":"신성의 완전을 이루려는 노력은 모든 분투하는 창조체의 첫째 의무이자 가장 높은 열망이어야 한다.","r":["1:0.4"]},{"x":"필사자는 무한이라는 뜻에서 완전할 수는 없지만, 자기 출발점에서 하나님이 세운 신성한 목표에 이르는 것은 전적으로 가능하다.","r":["1:0.5"]},{"q":"우주들의 하나님을 찾는 이 숭고한 탐구는 시간과 공간 모든 세계 거주민들의 최상의 모험이다.","r":"1:0.6"},{"x":"영원 아들은 아버지와 함께 이 명령을 모든 창조계에 방송했고, 그것이 모든 생존 계획과 증여 계획에 동기를 주어 왔다.","r":["7:5.1"]}]},{"h":"완전에 대한 갈망","items":[{"x":"내주하는 조절자는 사람의 혼에 탐구적인 완전에 대한 갈망을 어김없이 일깨우며, 그 갈망은 하나님과의 교통으로만 채워진다.","r":["102:1.6"]},{"q":"인간의 굶주린 혼은 살아 계신 하나님에 대한 인격적 실현 외에는 어떤 것에도 만족하지 않는다.","r":"102:1.6"},{"x":"인류의 첫 부모인 안돈과 폰타의 이름은 인간적 완전함을 향한 갈망을 처음으로 나타낸 창조체라는 뜻이다.","r":["63:0.3"]},{"x":"영적 진보는 영적 빈곤의 자각, 완전에 대한 갈망, 하나님을 닮으려는 열망, 아버지의 뜻을 행하려는 목적 위에 세워진다.","r":["100:2.1"]},{"x":"모든 창조체와 창조주가 함께 신성한 완전을 추구하는 데서 생기는 우주적 긴장은 최상 존재 안에서 해소된다.","r":["116:7.6"]}]},{"h":"불완전한 세계의 의미","items":[{"x":"용기를 기르려면 역경이, 이타심을 기르려면 불평등이, 희망을 기르려면 불확실성이 있는 환경이 필요하다.","r":["3:5.6","3:5.7","3:5.8"]},{"x":"신앙은 아는 것보다 믿을 수 있는 것이 언제나 많은 처지에서, 충성은 이탈의 가능성 가운데서 자란다.","r":["3:5.9","3:5.12"]},{"x":"아버지가 모든 필사자를 처음부터 완전하게 만들었다면, 길고 점진적인 상승의 모험과 훈련을 빼앗았을 것이다.","r":["32:3.11"]},{"x":"시간의 창조체가 마침내 이루는 완전함은 개인적 노력으로 얻은 참된 인격적 소유이다.","r":["32:3.9"]}]},{"h":"목적의 완전함과 신앙","items":[{"x":"순례자는 하보나에 도착할 때 단 하나의 완전함, 곧 목적의 완전함만 지니고 온다.","r":["26:4.12","26:4.13"]},{"x":"신앙이 목적의 완전함을 얻어 주었고, 이제 순례자는 이해의 완전함을 발달시켜야 한다.","r":["26:4.14"]},{"q":"이해하는 능력은 파라다이스로 가는 필사자의 여권이다.","r":"26:4.15"},{"x":"상승자들은 하보나에 이르기 오래전부터 불확실성을 잔칫상으로 삼고 실망을 먹고 자라는 법을 배웠다.","r":["26:5.3"]},{"q":"“하나님과 연결되어 있으면, 아무것도, 절대로 아무것도 불가능하지 않다.”","r":"26:5.3"}]},{"h":"하보나와 아버지 도달","items":[{"x":"유란시아의 짧은 시험, 맨션 세계와 지역 우주의 모론시아 단계, 초우주의 영적 훈련을 거쳐 순례자는 하보나로 간다.","r":["14:5.1"]},{"x":"하보나의 회로에서 상승자들은 최상 하나님, 무한 영, 영원 아들을 차례로 이해하며 안쪽으로 나아간다.","r":["26:6.2","26:8.1"]},{"x":"신 달성에 실패한 이들도 위로를 받으며 다시 시도하니, 그 실망은 혼돈에서 영광으로 오른 많은 체험과 크기만 다를 뿐이다.","r":["26:10.2"]},{"x":"우주 아버지에게 도달하는 것은 영원으로 가는 여권이며, 그로써 완전하라는 명령의 공의가 영원히 입증된다.","r":["26:9.2","26:9.3"]},{"q":"시간의 시험은 거의 끝났다. 영원을 위한 경주도 거의 끝났다.","r":"26:9.3"}]},{"h":"끝없는 여정","items":[{"q":"우리 유버사의 존재들은 시간의 상승 필사자들의 “최종성 운명”을 알지 못한다.","r":"31:3.2"},{"x":"최종자는 여섯째 단계의 영으로만 기록되어 있어, 그들 앞에 또 다른 단계가 남아 있음을 시사한다.","r":["31:3.3"]},{"x":"빛과 생명에 정착된 세계의 찬란한 발전조차 끝없는 상승 생애의 첫 단계일 뿐이다.","r":["55:6.7"]},{"x":"몸은 흙에서 왔어도, 참으로 원한다면 사람은 최상 하나님의 자녀요 파라다이스 아버지의 신성한 아들이 될 것이다.","r":["112:7.19"]}]}],"see":["필사자의 상승 여정","하보나","최종자 군단","성장","신앙","우주 아버지"],"n":100,"en":"Quest for Perfection"},{"t":"용서","sum":"하나님의 용서는 무한한 이해에서 저절로 흘러나오는 것으로, 사람이 구하기 전에 이미 주어져 있으며 중재자나 희생을 요구하지 않는다. 그러나 이 용서는 사람이 동료를 용서할 때에야 개인의 종교 체험에서 실제가 된다. 예수는 일흔 번씩 일곱 번이라도 용서하라고 가르쳤고, 남을 용서하지 못하는 것은 이해와 사랑에 이르지 못한 미성숙의 표지라고 했다.","sections":[{"h":"아버지의 본성에 깃든 용서","items":[{"q":"하나님께서는 자신의 자녀들을 모두 아시므로, 그들을 용서하시는 것이 어렵지 않다.","r":"2:4.2"},{"x":"하나님의 선하심 바탕에는 사랑하고 자비를 보이며 인내하고 용서를 베푸는 보편적 성향이 있다.","r":["2:6.9"]},{"x":"아버지는 정의와 자비로 나뉜 인격이 아니며, 용서를 위해 중재자를 요구하지 않으신다.","r":["2:6.6"]},{"x":"신성한 용서는 자녀의 잘못과 선택을 완전히 아는 하나님의 무한한 이해 안에 본래 들어 있는 필연이다.","r":["174:1.3"]},{"x":"지혜로운 부모의 이해하는 사랑은 회개와 용서가 필요한 소원함 자체를 대개 미리 막는다.","r":["174:1.2"]}]},{"h":"용서를 받아들이는 길","items":[{"x":"신성한 용서는 끊어졌던 충성 관계가 새로워지는 것이며, 구할 필요 없이 그 회복을 깨닫고 받아들이면 된다.","r":["89:10.6"]},{"q":"하늘에 계신 아버지께서는 너희가 그분께 구하려는 생각을 하기도 전에 이미 너희를 용서하셨지만,","r":"146:2.4"},{"x":"하나님의 용서는 사실상 조건이 없지만, 체험상으로는 사람이 동료를 용서할 때에야 실제가 된다.","r":["146:2.4","170:3.4"]},{"x":"형제를 용서할 때 사람은 자기 잘못에 대한 하나님의 용서를 받아들일 능력을 혼 안에 만든다.","r":["170:2.23"]},{"x":"신앙은 하나님 가족에 들어가는 값이고, 용서는 그 신앙을 받아들이시는 하나님의 행위이다.","r":["170:3.3"]},{"x":"예수는 고행이나 희생 없이 하나님에 대한 신앙으로 죄의 용서를 받는다고 가르쳤다.","r":["138:8.2","150:5.2"]}]},{"h":"서로 용서하라","items":[{"q":"하늘에 계신 아버지는 너희의 죄를 용서하신다. 그러므로 너희도 서로 용서하는 법을 배워야 한다.","r":"159:1.3"},{"x":"베드로가 일곱 번이면 되느냐고 묻자, 예수는 일흔 번씩 일곱 번까지라도 용서하라고 답했다.","r":["159:1.4"]},{"x":"왕에게 큰 빚을 탕감받고도 동료의 작은 빚을 용서하지 않은 청지기의 비유로 용서받은 자의 도리를 가르쳤다.","r":["159:1.4","159:1.5"]},{"x":"이웃을 깊이 이해할수록 용서하기 쉬워지며, 형제를 사랑할 때 이미 그를 용서한 것이다.","r":["2:4.2","174:1.4"]},{"q":"사람은 자신을 사랑하듯이 그의 동료를 사랑하지 않으면 진정으로 그들을 용서하지 않을 것이다.","r":"170:3.5"}]},{"h":"용서하지 못하는 미성숙","items":[{"q":"네 동료를 용서할 수 없거나 용서하지 않으려는 것은 네 미성숙함의 척도이며, 어른다운 공감과 이해와 사랑에 이르지 못한 것이다.","r":"174:1.5"},{"x":"사람은 상대의 내적 본성과 갈망을 모르는 만큼 앙심을 품고 복수심을 키운다.","r":["174:1.5"]},{"x":"모든 죄는 용서받을 수 있지만, 굳어진 불법자가 진심으로 슬퍼하거나 용서를 받아들일지는 의문이다.","r":["67:1.6"]},{"x":"하나님의 일을 알면서 고의와 악의로 악의 세력에 돌리는 자는 용서를 얻기 어렵다.","r":["153:4.3","165:3.6"]},{"x":"아버지는 무엇이든 눈감아 주는 방임적 부모가 아니어서, 자녀의 자멸적인 행위를 용납하지 않으신다.","r":["147:5.9"]}]},{"h":"역사 속의 용서와 예수의 본","items":[{"x":"원시 종교의 고백과 용서는 다음 주에 지을 죄까지 미리 용서받는 의미 없는 의식이었다.","r":["89:2.5"]},{"x":"호세아는 희생이 아닌 회개를 통한 용서를 설교하며 사랑과 신성한 자비의 복음을 되살렸다.","r":["97:4.5"]},{"x":"예수 이전에도 회개한 죄인을 용서하는 하나님은 알려졌지만, 잃은 양을 먼저 찾아 나서는 하나님은 새로웠다.","r":["159:5.16"]},{"q":"그들이 그를 십자가 가로대에 못 박을 때, 예수의 유일한 말은 “아버지여, 저들을 용서하소서. 저들은 자기들이 하는 일을 알지 못합니다”였다.","r":"187:2.4"},{"x":"주님을 부인한 베드로는 부활한 예수에게 다시 받아들여진 뒤에야 자신이 용서받았음을 온전히 믿었다.","r":["184:2.13","139:2.10"]}]}],"see":["자비","죄","사랑","사람의 형제됨","예수의 가르침","하나님의 아들됨"],"n":68,"en":"Forgiveness"},{"t":"우주 마음","sum":"우주 마음은 일곱 주(主) 영이 일곱 초우주에 저마다 사역하는, 시간과 공간 속의 칠중으로 다양화된 마음이다. 무한 영의 절대 마음이 유한 수준에 나타난 것으로, 지역 우주에서는 어머니 영과 보조 마음-영을 거쳐 필사자에게 이르며, 모든 의지 창조체에게 인과·의무·예배라는 세 가지 실체 반응을 부여한다. 과학과 철학과 종교, 그리고 강한 성품의 바탕이 여기에 있다.","sections":[{"h":"칠중으로 다양화된 마음","items":[{"x":"우주 마음은 시간과 공간의 칠중으로 다양화된 마음이며, 일곱 주 영이 각각 한 초우주에 그 한 국면을 사역한다.","r":["42:10.6"]},{"x":"주 영들은 우주 마음의 칠중 근원이자 대우주의 지성적 잠재력이며, 우주 마음은 셋째 근원이며 중심의 마음이 아절대적으로 현시된 것이다.","r":["16:6.1"]},{"x":"일곱 초우주에 대한 마음의 증여는 일곱 주 영에게서 나오며, 네바돈은 오르본톤 유형 우주 마음의 네바돈 변형으로 충만하다.","r":["9:4.3"]},{"q":"무한 마음은 시간을 무시하며, 궁극 마음은 시간을 초월하고, 우주 마음은 시간에 의해 조건 지어진다.","r":"9:4.4"},{"x":"우주 마음은 일곱 초우주에서 저마다 다르게 기능하지만, 최상 존재 안에서 알려지지 않은 연합 기법으로 조율된다.","r":["116:1.4"]},{"x":"파라다이스에서 마음은 절대적이고, 하보나에서는 아절대이며, 오르본톤에서는 유한하다.","r":["42:10.7"]}]},{"h":"무한 영과 지역 우주를 거쳐","items":[{"x":"하나님의 마음의 현존은 유한한 창조계에서 파라다이스 주 영들의 우주 마음이 어디서나 기능하는 데서 가장 잘 분별된다.","r":["3:1.8"]},{"x":"그러나 인간 계층의 마음은 공동 행위자의 딸들, 곧 지역 우주의 신성한 사역자들이 주는 증여물이다.","r":["3:1.8"]},{"x":"유란시아 사람들은 주 영의 직접 영향이 아니라 네바돈 창조 영의 영향 아래 살지만, 주 영들은 모든 창조체 마음의 기본 반응을 지배한다.","r":["16:6.2","16:5.3"]},{"x":"인간의 마음은 창조적 딸이 지역 우주에 증여한 우주 마음의 개별화된 회로이자 비인격적 일부이다.","r":["9:5.4"]},{"x":"우주 마음은 보조 영들의 원시적 사역에서 우주 최고 집행자의 마음에 이르기까지 확장되며, 일곱 주 영의 감독 아래 통일되어 있다.","r":["56:2.3"]}]},{"h":"세 가지 실체 반응","items":[{"x":"우주 마음의 모든 인격 연합에는 ‘실체 반응’이 있어, 의지 창조체가 과학·철학·종교의 선험적 가정에 무력하게 휘둘리지 않게 해 준다.","r":["16:6.4"]},{"x":"우주 마음은 인과관계(수학적 분별), 의무(사법적 분별), 예배(영적 분별)라는 세 실체 수준에서 틀림없이 반응한다.","r":["16:6.5","16:6.6","16:6.7"]},{"q":"이것은 우주 마음의 가장 높은 통찰이며, 우주적 분별의 경건하고 예배적인 형태이다.","r":"16:6.8"},{"x":"이 세 직관이 인격 안에서 통일되면 사실적 과학, 도덕적 철학, 참된 종교 체험이 어우러진 강한 성품이 된다.","r":["16:6.10"]},{"q":"인간 마음의 이러한 타고난 천부 능력들을 개발하고 예리하게 하는 것이 교육의 목적이며, 그것들을 표현하는 것이 문명의 목적이고, 그것들을 실현하는 것이 삶의 체험의 목적이며, 그것들을 고귀하게 하는 것이 종교의 목적이고, 그것들을 통일하는 것이 인격의 목적이다.","r":"16:6.11"},{"x":"그러나 유란시아에는 이러한 용기 있고 독립적인 우주적 사고를 계발하기를 기뻐하는 사람이 너무 적다.","r":["16:6.9"]}]},{"h":"혈족인 마음과 도덕적 인격","items":[{"q":"혈족인 영들이 서로에게 끌릴 뿐만 아니라, 혈족인 마음들 또한 매우 형제애가 깊으며 서로 협력하려는 경향이 있다.","r":"16:6.3"},{"x":"성운이 공간의 우주 에너지에서 기원하듯, 지적 자아들은 우주 마음에서 기원한다.","r":["111:1.2"]},{"x":"오직 인격만이 행하기 전에 자신이 무엇을 하는지 알며, 체험에 앞서 통찰을 지닌다.","r":["16:7.3"]},{"x":"미덕은 코스모스와 일치하는 의로움이며, 미덕은 그 이름을 대는 것이 아니라 그것을 살아야 알 수 있다.","r":["16:7.6"]},{"x":"도덕성은 법이나 힘으로 증진될 수 없으며, 도덕적으로 향기로운 사람들과의 접촉이라는 전염으로 퍼져야 한다.","r":["16:7.9"]},{"q":"그러므로 최상의 미덕은, 하늘에 계신 아버지의 뜻을 행하기로 진심으로 선택하는 것이다.","r":"16:7.10"}]},{"h":"상승 속의 우주 마음","items":[{"x":"첫째 우주적 원을 정복하면 보조 마음-영의 배타적 영향이 끝나고, 마음은 우주 마음과 창조 영의 초보조 부여물에 점점 더 가까워진다.","r":["110:6.21"]},{"x":"모론시아 단계에서 상승 필사자는 오르본톤 주 영이 부여한 우주 마음의 네바돈 수정형을 받는다.","r":["112:6.4"]},{"x":"지역 우주를 떠나 영적 수준에 이른 상승자는 오르본톤 우주 마음의 직접적인 사역에 조율된다.","r":["112:6.10"]},{"x":"진화하는 마음이 우주 마음 회로에 조율될 때마다 최상위의 실제성은 우주 안에서 한 단계 더 실체가 된다.","r":["117:0.3"]},{"q":"우주 마음이 자신의 근원인 무한 영의 무한한 마음을 자의식적으로 인식하는 동시에, 멀리 펼쳐진 우주들의 물리적 실체, 영원 아들의 영적 실체, 그리고 우주 아버지의 인격 실체를 의식한다는 것이 이상한 일인가?","r":"16:9.15"}]}],"see":["일곱 주(主) 영","무한 영","마음","보조 마음 영","지역 우주 어머니 영","최상 존재"],"n":19,"en":"Cosmic Mind"},{"t":"우주 아버지","sum":"우주 아버지는 모든 사물과 존재의 첫째 근원이며 중심이신 하나님이다. 그는 창조주이자 통제자이며 무한한 유지자이고, 보이지 않는 영이면서도 참된 인격으로서 모든 창조체를 아버지로서 사랑하신다. 그의 단편인 생각 조절자가 사람 안에 내주하기에, 누구든지 아버지를 찾아 그와 같아지는 영원한 모험에 나설 수 있다.","sections":[{"h":"첫째 근원이며 중심","items":[{"x":"아버지는 모든 창조의 하나님이자 모든 사물과 존재의 첫째 근원이며 중심으로, 먼저 창조주로, 다음에 통제자로, 마지막으로 무한한 유지자로 생각해야 한다.","r":["1:0.1"]},{"x":"아버지는 파라다이스와 중앙 우주를 직접 창조하셨고, 시간과 공간의 우주들은 창조자 아들들이 만든다. 네바돈은 그의 아들 미가엘의 창조이다.","r":["1:2.9"]},{"x":"아버지는 물리적으로는 파라다이스 섬의 중력을 통해, 마음으로는 무한 영 안에서, 영으로는 영원 아들 안에서 기능하시면서도 창조체와 직접 접촉을 유지하신다.","r":["1:2.10"]},{"q":"하나님은 사람 같지도, 기계 같지도 않다.","r":"1:2.1"},{"x":"하나님께는 과거·현재·미래가 따로 없고 모든 시간이 현재이며, 어떤 우주적 사건도 그분께 놀라움이 되지 않는다.","r":["2:1.5"]}]},{"h":"이름과 실체","items":[{"x":"첫째 근원이며 중심은 스스로 이름을 밝힌 적이 없으며, ‘아버지’라는 이름은 창조체가 그와 맺는 개인적 관계에서 자라난 것이다.","r":["1:1.1"]},{"x":"그를 어떤 이름으로 부르는지는 크게 중요하지 않다. 중요한 것은 그를 알고 그와 같아지기를 열망하는 것이다.","r":["1:1.6"]},{"x":"하나님은 이상화된 실체나 의인화된 자연법칙, ‘인간의 최고의 산물’ 같은 개념보다 무한히 더 크신 초월적 실체이다.","r":["1:2.2"]},{"x":"하나님의 존재는 과학 실험이나 순수 논리로는 증명되지 않으며, 오직 인간 체험의 영역 안에서 실현된다.","r":["1:2.7"]},{"q":"하나님을 아는 자는 그의 현존을 체험한 자이다.","r":"1:2.8"}]},{"h":"보이지 않는 영, 참된 인격","items":[{"q":"“하나님은 영이시다.” 그는 우주적 영적 현존이시다.","r":"1:3.1"},{"x":"아버지가 보이지 않는 것은 숨으시기 때문이 아니라, 물질 존재가 그 영적 광채 앞에서 존재를 보존할 수 없기 때문이다. 그러나 신앙의 눈으로는 그를 분별할 수 있다.","r":["1:3.3"]},{"x":"무한함이 그의 인격을 가리게 해서는 안 된다. 아버지는 신성한 인격의 절정이며, 모든 인격의 기원이자 운명이시다.","r":["1:5.1"]},{"x":"지역 우주에서 아버지는 창조자 아들들의 인격 안에서 나타나시므로, 아들을 본 자는 곧 아버지를 본 것이다.","r":["1:5.5","3:0.2"]}]},{"h":"사랑하시는 아버지","items":[{"q":"하나님은 아버지처럼 사랑하시는 것이 아니라, 아버지로서 사랑하신다.","r":"2:6.4"},{"x":"아버지의 사랑은 아들들의 희생이나 중재로 얻어 낸 것이 아니다. 그분은 처음부터 친히 자녀들을 사랑하신다.","r":["2:5.2"]},{"x":"히브리 선지자들은 하나님을 이스라엘의 아버지로 선포했지만, 예수는 그를 각 사람의 아버지로 계시했다.","r":["2:6.4"]},{"x":"아버지는 완전에 이르려 애쓰는 모든 혼의 투쟁에 직접 참여하시며, 우리의 고통 속에서 함께 고통받고 우리의 승리 안에서 함께 승리하신다.","r":["1:5.15","1:5.16"]},{"x":"아버지 하나님은 인류를 사랑하시고, 아들 하나님은 인류에게 봉사하시며, 영 하나님은 자녀들이 아버지를 찾아 상승하도록 영감을 주신다.","r":["3:6.8"]}]},{"h":"아버지께 이르는 길","items":[{"x":"아버지는 형식적 예배나 노예 같은 봉사를 강요하지 않으신다. 아버지의 뜻을 행하려는 자원한 헌신이 사람이 드릴 수 있는 유일하게 참된 선물이다.","r":["1:1.2"]},{"q":"“내가 완전한 것처럼 너희도 완전하라.”","r":"1:0.3"},{"x":"사람이 아버지께 곧바로 다가가지 못하는 것은 그분이 멀리 떨어져 계셔서가 아니라 창조체의 유한함 때문이며, 그 길은 모두에게 열려 있다.","r":["5:1.1","5:1.8"]},{"q":"우주 아버지의 영이 바로 너희의 마음속에 살고 있는데, 멀리 하늘에 계신 하나님을 꿈꾸는 것은 얼마나 잘못된 일인가!","r":"5:2.3"},{"x":"지적·사회적 처지가 아무리 달라도 모든 사람은 같은 신성한 현존을 받았으므로, 영적 진보의 가능성은 누구에게나 동일하다.","r":["5:1.4","5:1.5"]},{"x":"시간이 아무리 오래 걸려도, 조절자와 융합한 상승자는 언젠가 신성한 중심 앞에 서서 아버지를 얼굴과 얼굴을 마주하여 보게 된다.","r":["5:1.9"]}]}],"see":["하나님의 속성","하나님의 인격","파라다이스 삼위일체","생각 조절자","하나님의 아들됨","예배"],"n":1,"en":"Universal Father"},{"t":"유란시아","sum":"유란시아는 우리가 사는 지구의 우주 이름으로, 네바돈 지역 우주의 놀라시아덱 별자리에 속한 사타니아 체계의 606번 거주 세계이다. 유란시아는 생명 운반자들이 독자적인 생명을 조성한 생명 변형 세계이자, 칼리가스티아의 배반과 아담의 불이행으로 영적으로 격리된 고립 세계이다. 그러나 동시에 창조자 아들 미가엘이 마지막 증여를 이룬 ‘십자가의 세계’로서 우주 전역에 알려져 있다.","sections":[{"h":"우주 속의 위치","items":[{"q":"너희의 세계는 유란시아라고 불리며, 사타니아의 행성 집단, 즉 체계에서 606번째이다.","r":"15:14.5"},{"x":"유란시아는 네바돈 지역 우주의 백 개 별자리 중 하나인 놀라시아덱에 속하며, 네바돈은 오르본톤 초우주의 일부이다.","r":["43:0.1","0:0.5"]},{"x":"사타니아는 거주 세계가 619개뿐인 미완성 체계이며, 606이라는 번호는 이곳에서 606번째로 인간이 출현했다는 뜻이다.","r":["49:0.3"]},{"x":"유란시아는 10억 년 전쯤 현재의 크기에 이르러 네바돈의 물리적 등록부에 이 이름으로 올랐다.","r":["57:8.1"]}]},{"h":"생명 변형 세계","items":[{"x":"유란시아는 너희 태양에서 기원했고, 태양은 안드로노버 성운의 수많은 자손 가운데 하나이다.","r":["57:1.1"]},{"x":"사타니아 전체에 유란시아 같은 생명 변형 행성은 예순한 개뿐이며, 유란시아는 생명 설계를 수정할 수 있는 십진 행성이었다.","r":["58:0.1","58:1.1"]},{"q":"유란시아의 생명은 독특하며 이 행성 고유의 것이다.","r":"58:4.1"},{"x":"고대 내륙 바다는 생명의 기록을 돌 페이지에 새긴 진화의 요람이었다.","r":["57:8.26"]},{"x":"사람이 즐겁게 살 수 있는 것은 오존층처럼 우연해 보이는 마흔 가지가 넘는 보호 작용 덕분이다.","r":["58:2.4"]},{"x":"유란시아는 993,408년 전 인간 거주 행성으로 공식 인정받았고, 그 첫 부모는 안돈과 폰타였다.","r":["62:7.7","63:0.2"]}]},{"h":"고립된 세계","items":[{"q":"유란시아 필사자들이 하나님을 이해하는 데 있어서 겪는 많은, 참으로 많은 어려움은 루시퍼 반란과 칼리가스티아의 배반이 초래한 심대한 결과 때문이다.","r":"4:3.3"},{"x":"칼리가스티아의 배반 이래 유란시아는 놀라시아덱의 고립 세계 가운데 하나로, 지고자 관찰자가 주둔해 왔다.","r":["43:5.17"]},{"x":"생명 운반자들은 칼리가스티아의 배반과 아담의 불이행이 지적 생명을 향상시키려는 노력을 크게 방해한 것을 유감으로 여긴다.","r":["65:5.1"]},{"x":"행성의 영적 격리도 영원 아들의 영 인력 회로의 현존과 기능에는 아무 영향을 주지 못했다.","r":["7:1.7"]},{"x":"유란시아는 아직 부분적 영적 격리 아래 있어 반영 천사들이 자유롭게 기능하지 못한다.","r":["28:7.4"]}]},{"h":"고립이 주는 기회","items":[{"q":"그러나 이러한 구체들의 고립은 그 인종들에게 신앙을 발휘하고, 보는 것이나 다른 어떤 물질적 고려에 의존하지 않는, 우주적 신뢰성에 대한 독특한 성질의 확신을 발달시킬 특별한 기회를 제공한다.","r":"50:7.1"},{"x":"반란으로 격리된 세계 출신 필사자들이 결국 매우 운이 좋은 이들로 드러날 수도 있다.","r":["50:7.1"]},{"x":"유란시아 필사자들의 기회와 자질은 서로 달라도, 모두가 같은 내주하는 신성한 영을 누린다는 점에서 영적 자질은 동일하다.","r":["5:1.5"]}]},{"h":"증여의 세계","items":[{"x":"너희의 작은 세계는 미가엘이 주권에 필요한 체험을 완성한 곳으로 네바돈 전역에 알려지게 되었다.","r":["119:8.2"]},{"q":"유란시아가 이웃한 다른 거주 행성들 사이에서 “십자가의 세계”로 알려지게 된 것은 사실이다.","r":"188:4.1"},{"x":"미가엘은 유란시아 증여를 마치고 유란시아의 행성 영주라는 직함을 받아 칼리가스티아의 배반이 남긴 혼란을 바로잡으려 했다.","r":["120:2.3"]},{"x":"유란시아의 생애는 이 행성만이 아니라 모든 네바돈 세계의 생명들에게 영감이 되도록 의도되었다.","r":["120:2.7"]}]},{"h":"유란시아의 미래","items":[{"x":"유란시아가 빛과 생명에 이르는 데 가장 큰 장애는 질병, 퇴행, 전쟁, 다색 인종, 다언어의 문제이다.","r":["55:3.21"]},{"x":"그때가 오면 대리 행성 영주인 마키벤타 멜기세덱이 행성 주권자의 자리를 맡을 것이다.","r":["55:7.3"]},{"x":"유란시아가 체계 회로로 복구되더라도 사타니아 전체가 격리된 탓에 한동안 어려움은 남을 것이다.","r":["46:8.2"]},{"q":"나사렛 예수는 사람들 가운데 한 사람으로서 천구백여 년 전 유란시아에서 빛과 생명의 지위를 인격적으로 달성했다.","r":"55:11.7"}]}],"see":["지역 우주 네바돈","별자리와 지역 체계","진화","루시퍼 반란","칼리가스티아","예수의 증여"],"n":95,"en":"Urantia"},{"t":"인격","sum":"인격은 우주 아버지가 물질과 마음과 영의 살아 있는 에너지 체계에 독점적으로 부여하는 독특한 선물이다. 몸도 마음도 영도 혼도 아니며, 끊임없이 변하는 체험 속에서 유일하게 변하지 않고 다른 모든 요소를 통일하는 실체이다. 인격은 자의식과 상대적 자유 의지로 드러나며, 모든 인격은 아버지의 인격 회로로 그분께 이어지고, 혼의 생존과 함께 죽음을 넘어 살아남는다.","sections":[{"h":"아버지의 선물","items":[{"x":"아버지 하나님은 모든 인격의 증여자이자 보존자이며, 신성한 뜻을 택하는 유한 인격들의 운명이시다.","r":["5:6.1"]},{"q":"아버지 하나님을 떠나서는 인격이 없으며, 아버지 하나님을 위한 것이 아니고서는 어떤 인격도 존재하지 않는다.","r":"5:6.4"},{"x":"인격은 저절로 생기지 않으며, 비인격적인 것은 아버지의 직접 행위 없이는 결코 인격적인 것이 되지 못한다.","r":["0:5.4","5:6.3"]},{"x":"인격은 점진적으로 이루는 것이 아니어서, 있든지 없든지 둘 중 하나이다.","r":["5:6.3"]},{"x":"인격은 우주 아버지가 직접, 또는 그를 대신하는 공동 행위자가 부여하며 마음이나 영을 지닌 살아 있는 에너지 체계에 주어질 수 있다.","r":["112:0.3","112:0.4"]}]},{"h":"인격이란 무엇인가","items":[{"q":"인격은 그렇지 않으면 늘 변하는 창조체 체험 안에서 유일하게 변하지 않는 실체다.","r":"0:5.11"},{"x":"인간의 인격은 몸, 마음, 영, 혼 그 어느 것도 아니며, 개체성의 다른 모든 요소를 통일한다.","r":["0:5.11"]},{"x":"인격은 우주의 풀리지 않은 신비 가운데 하나로, 그 구성 요소는 알아도 실제 본성은 온전히 이해되지 않는다.","r":["5:6.2"]},{"x":"인격은 스스로 정체성을 갖지는 않지만 살아 있는 에너지 체계의 정체성을 통일할 수 있다.","r":["112:0.7"]},{"x":"인간 체계에서 인격은 모든 활동을 통일하여 정체성과 창의성의 특성을 부여한다.","r":["112:1.19"]}]},{"h":"유일함과 변하지 않음","items":[{"x":"인격들은 비슷할 수 있지만 결코 같지 않으며, 계열과 유형이 같아도 동일하지 않다.","r":["16:8.4"]},{"x":"인격 덕분에 우리는 형태나 영적 지위가 아무리 변해도 그 존재를 이전에 알던 바로 그 사람으로 알아볼 수 있다.","r":["16:8.4"]},{"q":"인격들은 연합할 수 있으나 총합될 수는 없다.","r":"112:0.12"},{"x":"조절자들은 아버지에게서 나올 때 본성이 같지만, 인격은 다양하고 독창적이며 배타적이다.","r":["16:8.3"]},{"x":"모든 진화 단계를 거치는 동안에도 너희 안에는 변화 가운데 영속하는 인격이라는 변하지 않는 부분이 있다.","r":["112:0.1"]}]},{"h":"자의식과 자유 의지","items":[{"x":"창조체 인격은 자의식과 그에 연관된 상대적 자유 의지라는 두 현상으로 구별된다.","r":["16:8.5"]},{"x":"자의식은 자신의 인격 실재를 아는 것이며, 다른 인격들의 실체를 인식하는 능력도 포함한다.","r":["16:8.6"]},{"x":"인간의 자유 의지는 도덕적 결정, 영적 선택, 이기심 없는 사랑, 예배 등 일곱 영역과 관련된다.","r":["16:8.7","16:8.8","16:8.14"]},{"q":"인격은 하나님께 선물을 드릴 수 있다. 즉, 자유 의지를 하나님의 뜻을 행하는 데 헌신하는 것이다.","r":"112:0.10"},{"x":"아버지는 혼의 성장을 마련하신 뒤 한 걸음 물러나시며, 영원한 생존에 관해서는 필사 의지의 주권을 절대적으로 정하셨다.","r":["5:6.8"]}]},{"h":"인격 회로와 관계","items":[{"x":"모든 인격은 우주 아버지의 인격적 현존 안에 회로로 연결되어 있으며, 아버지는 모든 인격을 인격적으로 의식하신다.","r":["5:6.10","5:6.11"]},{"x":"이 인격 회로는 생각 조절자의 사명과는 별개로 존재하며, 조절자가 내주하지 않는 인격들도 그 안에 포용된다.","r":["5:6.10","5:6.12"]},{"x":"인격은 다른 인격의 현존에 직접 반응하며, 다른 이들과의 관계의 상대성을 인식하는 도덕성으로 특징지어진다.","r":["112:0.11","112:0.13"]},{"q":"인격은 고립된 상태에서는 잘 기능할 수 없다.","r":"112:1.16"},{"x":"하나님을 창조주 아버지로 의식하기 때문에 우리는 사람을 창조체 형제로 의식하게 된다.","r":["16:9.14"]}]},{"h":"인격의 생존과 운명","items":[{"x":"물질 자아는 시간적 정체성을, 조절자는 영원한 정체성을 지니며, 이 둘이 함께 불멸 혼의 살아남는 정체성을 낳는다.","r":["5:6.7"]},{"q":"인격 정체성은 혼의 생존 안에서 그리고 혼의 생존에 의해 살아남는다.","r":"16:9.3"},{"x":"인간의 인격은 영원하지만 정체성에 관해서는 조건적이어서, 운명 성취의 자리에 있을지를 스스로 선택해야 한다.","r":["112:5.2"]},{"x":"인격 간 관계는 발판이 아니어서, 인격 관계에 대한 필사 기억은 우주적 가치를 지니고 맨션 세계에서도 지속된다.","r":["112:5.22"]},{"x":"하나님이 인간이 되신 사실은 인간 인격의 모든 의미와 가치를 영원히 바꾸었다.","r":["112:2.7"]}]}],"see":["우주 아버지","혼","마음","자유 의지","생존","하나님의 인격"],"n":36,"en":"Personality"},{"t":"인종","sum":"유란시아의 인류는 약 백만 년 전 안돈과 폰타에게서 시작되었고, 약 오십만 년 전 한 산긱 가족에게서 홍·오렌지·황·녹·청·남색의 여섯 유색 인종이 한꺼번에 나타났다. 뒤이어 아담과 이브의 보라색 인종이 더해져 안드족을 이루었고, 오늘날 순수한 인종은 남아 있지 않다. 인종은 정신적 관점과 능력이 서로 다르지만, 모든 인종은 하늘 앞에서 같은 지위를 가지며 같은 영에 의해 내주된다.","sections":[{"h":"안돈과 폰타","items":[{"x":"유란시아는 최초의 두 인간인 쌍둥이가 열한 살이 되었을 때 거주 행성으로 등록되었다.","r":["63:0.1"]},{"q":"“사타니아의 606번 행성에 인간 마음이 출현하였으며, 이 새로운 인종의 부모는 안돈과 폰타라 불릴 것이다.","r":"63:0.2"},{"x":"인류는 거의 백만 년의 역사를 지니며, 안돈족은 숲을 피하고 트인 땅과 높은 위도에서 진보했다.","r":["64:0.2","64:1.3"]},{"x":"우수한 혈통이 열등한 혈통과 섞여 퇴보하는 일은 유란시아 역사에서 되풀이되었다.","r":["64:1.7","64:1.8"]}]},{"h":"여섯 산긱 인종의 출현","items":[{"x":"약 오십만 년 전 인도 북서부 고지대에서 한 산긱 가족이 유달리 지능이 뛰어난 자녀들을 낳았다.","r":["64:5.1","64:5.2"]},{"q":"이 열아홉 명의 자녀 중 다섯 명은 적색, 두 명은 오렌지색, 네 명은 황색, 두 명은 녹색, 네 명은 청색, 두 명은 남색이었다.","r":"64:5.3"},{"x":"보통 행성에서는 홍인부터 차례로 인종이 나타나지만, 유란시아에서는 여섯 인종이 한 가족에서 동시에 나왔다.","r":["64:6.1"]},{"x":"홍·황·청인은 1차 인종이고 오렌지·녹·남색 인종은 2차 인종이며, 지적·영적 능력이 서로 교차한다.","r":["51:4.3","82:6.2"]},{"x":"여러 유색 인종으로의 분화는 다른 방식으로는 얻을 수 없는 바람직한 변이를 인류에게 준다.","r":["51:4.4"]}]},{"h":"인종들의 역사","items":[{"x":"홍인은 아시아에서 황인에게 밀려나 약 팔만 오천 년 전 북아메리카로 건너갔고, 오나모날론톤이 한때 평화를 회복시켰다.","r":["64:6.4","64:6.5","64:6.7"]},{"x":"황인은 처음으로 정착 농경과 사회 협력을 이루었고, 싱랑톤의 지도 아래 ‘하나의 진리’를 예배했다.","r":["64:6.14","64:6.15"]},{"x":"오렌지색 인종과 녹색 인종은 끝없는 싸움 끝에 다른 인종에 흡수되어 사라졌다.","r":["64:6.13","64:6.20"]},{"x":"청인은 창을 발명하고 현대 기예의 기초를 놓았으며, 이른바 백인은 주로 이 청인의 후손이다.","r":["64:6.21","64:6.24"]},{"x":"아담과 이브의 보라색 인종은 둘째 동산에서 퍼져 나가 놋족·산긱 인종과 섞여 안드족이 되었다.","r":["78:0.1","78:1.3"]}]},{"h":"인종의 다양성과 혼합","items":[{"x":"다양성은 자연 선택과 건강한 경쟁을 자극하며, 인종 간 차이는 관용과 이타심을 길러 준다.","r":["64:6.31","64:6.33","64:6.34"]},{"q":"인류의 동질성은 진화하는 세계의 민족들이 비교적 높은 영적 수준에 도달하기 전까지는 바람직하지 않다.","r":"64:6.35"},{"q":"오늘날 세계에는 순수한 인종이 존재하지 않는다.","r":"82:6.1"},{"x":"우수하고 서로 다른 계통의 혼합은 새롭고 강건한 혈통을 만들며, 혼혈의 위험은 크게 과장되었다.","r":["82:6.5","82:6.8"]},{"x":"혼혈에 대한 반대의 대부분은 생물학이 아니라 사회적·문화적 편견에 기반한다.","r":["82:6.7","82:6.8"]}]},{"h":"하늘 앞에서 같은 지위","items":[{"q":"그들의 후진성에도 불구하고, 이 남색 민족들은 천상의 권능들 앞에서 다른 어떤 지상 인종과도 정확히 같은 지위를 가진다.","r":"64:6.27"},{"q":"인종적 마음은 다를 수 있지만, 모든 인류는 같은 신성하고 영원한 영에 의해 내주된다.","r":"155:6.8"},{"x":"인류의 통일과 형제단은 권위의 종교가 아니라 개인적 체험인 영의 종교를 통해서만 이루어질 수 있다.","r":["155:6.8"]},{"x":"부활한 예수는 하나님의 아버지됨과 사람의 형제단의 복음을 모든 나라와 인종에게 지혜롭게 전하라고 명했다.","r":["191:4.4"]},{"x":"오순절은 인종과 문화, 카스트와 성에 근거한 모든 종교적 차별을 지워 버렸다.","r":["194:3.14"]}]}],"see":["진화","아담과 이브","유란시아","문명","사람의 형제됨","칼리가스티아"],"n":80,"en":"Races"},{"t":"일곱 주(主) 영","sum":"일곱 주(主) 영은 무한 영의 1차 인격들로서, 아버지·아들·영이라는 세 신이 이룰 수 있는 일곱 가지 연합 가능성을 각각 표현한다. 그들은 파라다이스 주변에서 일곱 초우주를 하나씩 감독하며, 우주 마음의 칠중 근원이자 동력 감독자들의 조상이다. 각 초우주의 창조체는 그 주 영의 개성을 영원히 지니며, 오르본톤을 감독하는 7번 주 영은 최상 존재를 대변한다.","sections":[{"h":"일곱 가지 연합 가능성","items":[{"x":"일곱 주 영은 무한 영의 1차 인격들이며, 세 신에게 내재한 연합 가능성이 일곱뿐이기에 우주는 일곱 큰 부분으로 운영된다.","r":["16:0.1"]},{"x":"그들은 아버지, 아들, 영, 아버지와 아들, 아버지와 영, 아들과 영, 아버지와 아들과 영이라는 일곱 유사성에서 저마다의 성격을 얻는다.","r":["16:0.2","16:0.9"]},{"q":"우리는 신의 삼중 인격화를 절대적 불가피성이라 말하게 되었고, 일곱 주(主) 영의 출현을 아(亞)절대적 불가피성으로 보게 되었다.","r":"16:1.1"},{"x":"무한 영의 첫 번째 신-창조 행위로 인격화된 그들은 무한 영을 우주들에 분배하는 이들이다.","r":["9:8.2"]},{"x":"영적 성품과 본성에서 일곱 영은 하나와 같지만, 그 밖의 모든 정체성 측면에서는 뚜렷이 다르다.","r":["16:0.11"]},{"q":"일곱 주(主) 영은 많은 기능을 가지나, 현재 그들의 특별한 영역은 일곱 초우주의 중앙 감독이다.","r":"16:0.12"}]},{"h":"무한 영의 목소리","items":[{"q":"파라다이스와 하보나 바깥에서 무한 영은 오직 일곱 주(主) 영들의 목소리로만 말한다.","r":"16:2.2"},{"x":"어떤 세계에 대한 무한 영의 초우주 현존은 그 구역을 감독하는 주 영의 고유한 본성에 의해 조건 지어진다.","r":["16:2.3"]},{"x":"전능·전지·전재의 속성은 그들이 함께할 때만 드러나며, 개별적으로는 각자 감독하는 초우주에 한정된다.","r":["16:2.4"]},{"x":"일곱 주 영이 공동 행위자 주위에 모이면, 그들은 진화 우주에서 삼위일체의 기능적 권능과 지혜와 권위를 집단적으로 대표한다.","r":["16:1.3"]},{"x":"그들은 칠중 하나님의 셋째 수준으로, 상승자는 옛적부터 늘 계신 이를 거쳐 한 주 영의 인격을 발견한 뒤 아버지께 나아간다.","r":["0:8.4","0:8.9"]}]},{"h":"일곱 분의 개성","items":[{"x":"1번 주 영은 아버지를 직접 표현하며 조절자들의 우두머리와 가까이 지내고, 평의회에서는 언제나 아버지를 위해 말한다.","r":["16:3.2"]},{"x":"2번은 영원 아들을, 3번은 무한 영을, 4번은 아버지와 아들의 결합된 본성을 각각 대변한다.","r":["16:3.4","16:3.6","16:3.8"]},{"x":"5번은 아버지와 영을 대변하며 동력 감독자와 물리적 통제자들의 조언자이고, 6번은 아들과 영을 대변한다.","r":["16:3.10","16:3.12"]},{"x":"오르본톤을 주재하는 7번 주 영은 아버지·아들·영을 동등하게 묘사하며, 최상 존재의 영 개인과 인격적이고 유기적인 관계를 지닌다.","r":["16:3.14","16:3.15"]},{"q":"최상 존재의 개인이 접촉 불가능한 현 우주 시대 동안, 7번 주(主) 영은 인격적 관계의 문제에 있어서 상승 창조체들의 하나님의 자리에서 기능한다.","r":"16:3.19"}]},{"h":"초우주 감독과 우주 마음","items":[{"x":"각 주 영은 자기가 감독하는 초우주의 반대편 파라다이스 주변에 본부를 두며, 그 초우주의 방사형 경계선은 그곳으로 수렴한다.","r":["16:0.12"]},{"x":"주 영들은 일곱 최상 집행자를 통해 초우주 정부와 접촉하고, 각 초우주 수도의 반영 영들과 늘 연락을 유지한다.","r":["17:1.2","16:3.20"]},{"q":"이 일곱 영이 삼자일체 신의 인격화된 물리적 권능, 우주 마음, 영적 현존, 즉 “온 우주에 보내진 하나님의 일곱 영”이라는 것은 문자 그대로 사실이다.","r":"16:4.1"},{"x":"그들은 우주 마음의 칠중 근원이자 우주 동력 감독자들의 조상이며, 지역 우주를 조직하는 창조자 아들들을 물질적으로도 돕는다.","r":["16:4.2","16:4.3","16:6.1"]},{"x":"물질과 영을 결합한 모론시아 본체와 모론시아 마음은 주 영들의 계시되지 않은 활동과 관련된 것으로 보인다.","r":["16:4.5"]},{"x":"그러나 그들은 조절자의 증여와 사역, 그리고 무제한 절대자의 기능에는 전혀 관여하지 않는다.","r":["16:4.16"]},{"x":"현 시대에 최상위의 마음 잠재성은 일곱 주 영에게 맡겨져 있으며, 특히 일곱째 주 영은 최상위를 알고 그와 인격적으로 접촉한다.","r":["116:1.3","116:4.2"]}]},{"h":"창조체에 새겨진 개성","items":[{"x":"각 세계는 일곱 주 영 모두의 연합된 지혜를 누리지만, 인격적 손길과 색채는 오직 한 분에게서 받는다.","r":["16:5.1"]},{"x":"주 영은 필사자의 물질 마음에 직접 들어오지 않으며, 그 영향은 그와 매우 닮은 지역 우주 창조 영의 사역을 통해 이루어진다.","r":["16:5.3"]},{"q":"온 영원을 통하여, 상승 필사자는 자신의 출생 초우주의 주재 영을 나타내는 특성들을 보일 것이다.","r":"16:5.5"},{"x":"그래서 최종자 군단도 진화 창조계와의 온전한 관계를 나타낼 때는 각 초우주에서 한 명씩 일곱 최종자를 소집한다.","r":["16:5.5"]},{"x":"상승자는 하보나 일곱째 회로에서 자기 초우주 주 영의 정체성을 파악해야 여섯째 회로로 나아간다.","r":["14:5.4"]},{"x":"우주 아버지께 이르는 일곱 가지 큰 길이 있으며, 각 상승은 일곱 주 영 가운데 한 분의 신성을 통해 이루어진다.","r":["117:6.15"]}]}],"see":["무한 영","우주 마음","일곱 초우주","칠중 하나님","최상 존재","옛적부터 늘 계신 이"],"n":20,"en":"Seven Master Spirits"},{"t":"일곱 초우주","sum":"일곱 초우주는 하보나 너머 첫째 공간 수준을 일곱 구역으로 나눈, 시간과 공간 속에서 진화하는 창조계이다. 각 초우주는 약 일조 개의 거주 가능 세계를 품으며, 세 분의 옛적부터 늘 계신 이가 건축 본부 세계에서 다스리고 일곱 주(主) 영 가운데 한 분이 파라다이스에서 감독한다. 유란시아가 속한 일곱째 초우주 오르본톤은 사랑과 자비의 우주적 실증으로 알려져 있다.","sections":[{"h":"거대한 바퀴","items":[{"x":"파라다이스 삼위일체에 관한 한 하보나 바깥의 거주 우주는 일곱 개뿐이며, 이들이 하보나 너머 첫째 공간 수준을 관할한다.","r":["15:0.1"]},{"q":"그 바퀴의 중심축은 영원한 파라다이스 섬이며, 일곱 바큇살은 일곱 주(主) 영의 방사(放射)이고, 테두리는 대우주의 외곽 영역들이다.","r":"15:0.1"},{"x":"초우주 조직의 칠중 계획은 우주 창조계가 물질화되던 초기에 세워졌고, 현재의 행정 체계는 거의 영원부터 존재했다.","r":["15:0.2"]},{"x":"일곱 초우주는 거대한 타원 경로를 따라 파라다이스와 하보나 주위를 시계 반대 방향으로 돈다.","r":["15:1.2","15:3.14"]},{"x":"유란시아는 미지의 공간으로 맹목적으로 돌진하는 것이 아니라, 초우주 공간 수준의 질서 있고 예정된 경로를 따르고 있다.","r":["15:1.3"]}]},{"h":"조직의 단위","items":[{"q":"오직 우주 아버지만이 공간에 있는 거주 세계들의 위치와 실제 숫자를 알고 계신다.","r":"15:2.1"},{"x":"거주 가능한 약 천 개의 세계가 한 체계, 백 개의 체계가 한 별자리, 백 개의 별자리가 한 지역 우주를 이룬다.","r":["15:2.3","15:2.4","15:2.5"]},{"x":"백 개의 지역 우주가 소구역, 백 개의 소구역이 대구역, 열 개의 대구역이 한 초우주를 이루어 약 일조 개의 거주 가능 행성을 품는다.","r":["15:2.6","15:2.7","15:2.8"]},{"x":"대우주 전체로는 약 칠조 개의 거주 가능 세계가 계획되어 있지만, 이 수치들은 어디까지나 근사치이다.","r":["15:2.9","15:2.25"]},{"x":"소구역은 최근으로 늘 계신 이들이, 대구역은 완전으로 늘 계신 이들이, 초우주는 옛적부터 늘 계신 이들이 각각 셋씩 다스린다.","r":["15:2.6","15:2.7","15:2.8"]}]},{"h":"오르본톤과 우리의 위치","items":[{"x":"유란시아에서 육안으로 보이는 거의 모든 별은 일곱째 초우주 오르본톤에 속하며, 은하수는 오르본톤의 중앙 핵이다.","r":["15:3.1"]},{"x":"우리 소구역의 회전 중심은 궁수자리 별구름 속에 있고, 오르본톤의 모든 구역은 본부 유버사 주위를 돈다.","r":["15:3.5","15:3.7"]},{"x":"유란시아는 사타니아 체계의 606번째 세계이며, 사타니아·놀라시아덱·네바돈·엔사·스플랜돈을 거쳐 오르본톤에 속한다.","r":["15:14.5","15:14.6","15:14.7"]},{"q":"너희는 거의 무한한 세계 가족에 속하지만, 너희의 구체는 마치 온 실존에서 유일하게 거주하는 세계인 것처럼 똑같이 정밀하게 행정되고 똑같이 사랑으로 양육된다.","r":"15:14.9"}]},{"h":"물리적 형성과 에너지 통제","items":[{"x":"파라다이스 힘 조직자들은 성운의 기원자로서, 공간의 힘을 동원해 태양과 체계를 낳는 거대한 어미 바퀴를 일으킨다.","r":["15:4.4"]},{"x":"에너지는 성운이 아니라 보편적으로 분산되므로, 각 지역 우주는 그 초우주 총 에너지의 정확히 십만분의 일을 지닌다.","r":["15:4.6"]},{"x":"건축 구체를 제외한 모든 공간체는 진화적 기원을 가지며, 우리 태양계는 중력 폭발 과정에서 생긴 행성들로 이루어졌다.","r":["15:5.5","15:6.7"]},{"x":"빛은 무게를 지닌 실제 물질이며, 혜성의 꼬리가 태양 반대쪽을 향하는 것이 그 증거이다.","r":["15:6.13"]},{"q":"성운들은 흩어질 수 있고, 태양들은 타버릴 수 있으며, 체계들은 사라지고, 행성들은 멸망할 수 있지만, 우주들은 쇠퇴하지 않는다.","r":"15:8.10"}]},{"h":"초우주 정부","items":[{"x":"초우주 본부는 특별히 건설된 건축 세계로, 열 없는 빛을 내며 각 초우주의 천문학적 중심 가까이에 있다.","r":["15:7.1"]},{"q":"실상, 모든 본부 세계는 파라다이스와 같다.","r":"15:7.3"},{"x":"초우주 정부의 집행부는 옛적부터 늘 계신 이들과 지혜의 완성자·신성한 조언자·우주 검열자, 그리고 영화롭게 된 상승 필사자인 막강한 사자·고등 권위자·무명 무수자로 이루어진다.","r":["15:10.3","15:10.12"]},{"x":"각 초우주는 파라다이스의 주 영 한 분이 그 수도에 자리한 반영 영들을 통해 감독한다.","r":["9:8.3","116:4.4"]},{"x":"지역 우주의 아들들은 필사자의 생존을 명할 수 있지만, 영원한 생사에 관한 집행 판결은 오직 옛적부터 늘 계신 이들이 내린다.","r":["15:12.2"]},{"x":"유버사의 심의회는 하보나로 갈 자격을 얻은 상승 졸업생 가운데 선출된 대표들로 구성되며, 집행부와 의견이 어긋난 적이 없다.","r":["15:11.2","15:11.3"]}]},{"h":"연방 가입과 목적","items":[{"x":"지역 우주는 물리적 안정과 주권자 아들에 대한 영적 충성을 이루어야 초우주 연방에 가입할 수 있다.","r":["15:9.16","15:9.17"]},{"x":"네바돈은 아직 초우주의 안정된 물리적 질서에도 속하지 못했지만, 초우주 정부는 그 온전한 가입을 열망하며 돕고 있다.","r":["15:9.18"]},{"x":"초우주들은 서로 고립되어 있어 파라다이스 정보 교환소를 통해서만 서로의 일을 알며, 이 고립은 최상 존재의 주권이 사실화될 때까지 이어진다.","r":["15:10.23"]},{"x":"초우주 진화의 일곱 주요 목적은 각각 한 초우주에서 가장 완전하게 표현된다.","r":["15:14.1"]},{"q":"오르본톤은 사랑과 자비의 우주적 실증이다.","r":"15:14.2"},{"x":"오르본톤에서는 다른 여섯 초우주의 목적이 하나로 연결되고 있어, 언젠가 최상 하나님이 유버사에서 완성된 일곱 초우주를 다스릴지도 모른다고 추측된다.","r":["15:14.3","117:7.16"]}]}],"see":["옛적부터 늘 계신 이","일곱 주(主) 영","지역 우주 네바돈","대우주와 주(主)우주","하보나","최상 존재"],"n":14,"en":"The Seven Superuniverses"},{"t":"자비","sum":"자비는 창조체의 약함과 한계를 온전히 아는 지혜가 정의를 누그러뜨린 것이다. 하나님은 본성적으로 자비로우셔서 누가 설득할 필요가 없으며, 영원 아들은 자비 그 자체이고 무한 영은 그 자비를 우주 곳곳에 사역한다. 자비는 정의를 어기는 것이 아니라 정의를 이해심 있게 적용하는 것이며, 사람은 공의·공정·인내·친절을 거쳐 참된 자비를 배워 간다.","sections":[{"h":"지혜로 누그러진 정의","items":[{"q":"자비는, 완전한 지식과, 유한한 창조체의 본성적 약점과 환경적 한계에 대한 충분한 인식에서 자라난 지혜로 누그러진 정의일 뿐이다.","r":"2:4.1"},{"x":"잘못의 결과를 거두게 하는 신성한 정의조차 언제나 자비로 부드러워지며, 그 비율은 무한한 지혜가 정한다.","r":["2:3.2"]},{"x":"자비는 정의를 위반하는 것이 아니라, 진화하는 유한한 창조체에게 맞게 최상의 정의를 이해심 있게 해석한 것이다.","r":["2:4.5"]},{"x":"영원한 정의와 신성한 자비가 함께 어우러질 때, 사람의 체험에서 공정함이라 부르는 것이 생겨난다.","r":["2:4.4","10:6.3"]},{"x":"하나님은 정의와 자비 사이에서 찢기는 분이 아니며, 전지하심으로 두 요구를 동시에 온전히 채우신다.","r":["2:4.3","2:6.6"]}]},{"h":"아버지의 본성에서 흘러나오는 자비","items":[{"q":"창조체의 필요만으로도 아버지의 부드러운 자비와 구원의 은혜가 온전히 흘러나오기에 충분하다.","r":"2:4.2"},{"x":"자비는 선하심과 사랑에서 저절로 태어나는 자식이어서, 사랑하는 아버지는 자녀들에게 자비를 거둘 수 없다.","r":["2:4.4"]},{"x":"영원 아들이 아버지께 자비를 간청한다는 생각은 잘못이다. 아들의 모든 자비는 아버지 사랑을 그대로 드러낸 것이다.","r":["6:3.4"]},{"x":"하나님은 진노나 복수의 감정을 품지 않으시며, 그런 태도는 아버지의 자비로운 품성과 맞지 않는다.","r":["4:3.2","2:6.7"]},{"x":"반역자라도 의로움으로 돌아서면 자비로 받아들여지며, 하나님은 그 허물을 기억하지 않으신다.","r":["2:5.4"]}]},{"h":"아들은 자비, 영은 사역","items":[{"q":"하나님은 사랑이시고, 아들은 자비이시다. 자비는 적용된 사랑, 곧 아버지의 사랑이 영원 아들이라는 개인 안에서 행동으로 나타난 것이다.","r":"6:3.5"},{"x":"무한 영은 아들의 자비 속성 쪽으로 기울어, 대우주 전체에서 파라다이스 신들의 자비 사역자가 된다.","r":["8:2.6","8:4.7"]},{"q":"너희가 기원한 우주는 정의의 모루와 고난의 망치 사이에서 만들어지고 있다. 그러나 그 망치를 드는 존재들은 자비의 자녀들, 곧 무한 영의 영 자손들이다.","r":"9:1.8"},{"x":"정의는 삼위일체의 집단적 태도이고, 자비는 그 의로움을 인격적으로 표현한 것이다.","r":["10:6.2","10:6.18"]},{"x":"창조자 아들들은 본래 자비롭지만, 증여 체험을 거치며 새로운 방식으로 이해심 있는 자비를 더 얻게 된다.","r":["119:0.4"]},{"x":"우리 초우주 오르본톤은 자비로 부드러워진 정의와 인내로 조건 지어진 권능으로 이름난, 사랑과 자비의 실증이다.","r":["15:14.2"]}]},{"h":"자비의 기록과 한계","items":[{"x":"자비의 기억은 개인에게 베풀어진 자비 사역의 살아 있는 기록으로, 생존 판정 때 증언으로 낭독된다.","r":["28:6.5","28:6.6"]},{"q":"자비를 업신여기는 자들에게 자비를 억지로 떠안겨서는 안 되며, 자비는 시간의 끈질긴 반역자들에게 발밑에 짓밟히도록 둘 선물이 아니다.","r":"28:6.7"},{"x":"그러나 목적이 진실하고 마음이 정직한 사람에게는 자비의 신용이 그가 다 써 버릴 수 있는 것보다 언제나 훨씬 크다.","r":["28:6.7"]},{"x":"끝없는 자비와 인내가 소진된 뒤에는 정의가 이기며, 자비가 회복시킬 수 없는 것을 정의가 마침내 소멸시킨다.","r":["21:5.7","2:3.5"]}]},{"h":"사람이 배우는 자비","items":[{"x":"자비는 성장의 자질이다. 먼저 공의롭고 공정하며 참을성 있고 친절해진 뒤에야 참으로 자비로울 수 있다.","r":["28:6.8"]},{"q":"후원이나 생색이나 자선, 심지어 동정은 있을 수 있지만 자비는 아니다.","r":"28:6.8"},{"q":"자비의 사역은 언제나 개인의 일이지만, 정의의 처벌은 사회·정부·우주 행정 집단의 기능이다.","r":"133:1.2"},{"x":"예수가 말한 자비는 수동적 동정이 아니라 능동적이고 역동적인, 최상의 아버지다운 인자한 사랑이다.","r":["140:5.17"]},{"x":"제자들은 사람을 심판하는 자가 아니라 구원하는 자이므로, 자신도 바랄 자비를 형제에게 먼저 보여야 한다.","r":["140:3.17","140:3.16"]},{"x":"자비가 판단을, 사랑이 행동을 결정하는 것이 왕국의 규칙이며, 주고받는 계산은 그 규칙이 아니다.","r":["140:6.9"]}]}],"see":["정의","사랑","용서","영원 아들","무한 영","선함"],"n":61,"en":"Mercy"},{"t":"자유 의지","sum":"자유 의지는 우주 아버지가 인격과 함께 주시는 선택의 능력이다. 하나님 자신이 절대적 자유 의지를 지닌 원초적 인격이시며, 사람은 그 의지를 상대적이고 유한한 수준에서 나누어 받는다. 특히 영원한 생존에 관한 한 필사자의 선택은 어떤 존재도 침범할 수 없는 주권을 지니므로, 자유 의지는 사람이 자기 운명을 스스로 짓는 열쇠가 된다.","sections":[{"h":"하나님의 자유 의지","items":[{"x":"하나님은 법칙에 묶인 자동적 힘이 아니라 자유 의지를 지닌 원초적 인격이시다.","r":["12:7.6"]},{"x":"하나님의 자유 의지는 오직 그분 자신의 신성한 본성과 완전한 속성에 의해서만 조건 지어진다.","r":["4:4.3"]},{"x":"인격과 선하심은 창조체와 나누시지만, 의지의 무한성은 오직 하나님만의 것이다.","r":["4:4.4"]},{"x":"하나님이 자녀들의 행위를 미리 아신다 해도 그 예지가 그들의 자유를 없애지는 않는다.","r":["3:3.4","118:7.1"]}]},{"h":"인격에 주어진 선택의 선물","items":[{"x":"창조체 인격을 구별하는 두 표지는 자의식과 그에 따르는 상대적 자유 의지이다.","r":["16:8.5","16:8.6"]},{"x":"사람의 상대적 자유 의지는 도덕적 결정, 영적 선택, 이타적 사랑, 예배 같은 높은 기능에 관련된다.","r":["16:8.7","16:8.13","16:8.14"]},{"x":"인격의 증여는 살아 있는 유기체에 자기 결정과 자기 진화라는 특권을 더해 준다.","r":["118:7.6"]},{"q":"필사자는 자유 의지, 즉 선택의 능력을 부여받았으며, 이러한 선택이 절대적이지는 않지만, 유한한 수준에서는 그리고 선택하는 인격의 운명과 관련하여 상대적으로 최종적이다.","r":"118:6.4"},{"q":"인간은 자신의 영원한 운명을 스스로 설계하는 가장 진실한 건축가이다.","r":"103:5.10"}]},{"h":"아무도 침범하지 않는 의지","items":[{"x":"영원한 생존에 관해서는 어떤 존재나 힘도 필사자의 자유 의지에 간섭할 수 없도록 하나님이 정하셨다.","r":["5:6.8"]},{"q":"어떤 인격적 창조체도 영원한 모험으로 강제될 수 없다.","r":"5:6.12"},{"x":"조절자는 이상적 삶의 계획을 가져오지만 결코 사람의 선택을 임의로 움직이지 않고 언제나 그 의지를 존중한다.","r":["110:2.1"]},{"q":"어떤 인간도 자신의 의지에 반하여 신성한 관찰자에 의해 영성화되지는 않는다.","r":"110:2.2"},{"x":"천사들도 인간 마음의 성역을 침범하거나 의지를 조작하지 않으며, 선택의 특권을 줄일 권한이 없다.","r":["113:5.1"]},{"x":"칼리가스티아 같은 반역자도 정상적인 사람에게 그 의지에 반하는 일을 강요할 수는 없었다.","r":["66:8.6"]}]},{"h":"참된 자유와 거짓 자유","items":[{"x":"참된 자유는 진화적 진보의 보상이며, 거짓 자유는 시간의 오류가 만든 교묘한 기만이다.","r":["54:1.2"]},{"q":"참된 자유는 자기 통제의 열매이며, 거짓 자유는 자기 주장의 전제이다.","r":"54:1.6"},{"x":"자기 정복이 따르지 않는 자유는 환상이며, 자유의 탈을 쓴 방종은 속박의 전조가 된다.","r":["54:1.5"]},{"x":"루시퍼 반란은 자유를 내세웠지만 실제로는 창조체들의 자유 의지 참여를 빼앗으려는 위협이었다.","r":["54:2.3"]},{"x":"죄는 의지의 자유에 현혹되어 우주 시민의 의무를 깨닫지 못한 미성숙함에서 나온다.","r":["118:7.4"]}]},{"h":"선택의 책임과 운명","items":[{"x":"에너지 체계는 선택의 여지가 없지만, 사람은 자유 의지의 선택으로 자기 운명을 결정하는 데 전적으로 관여한다.","r":["112:5.3"]},{"x":"선택의 힘은 가장 큰 기회인 동시에 최상의 책임이며, 그 충실함에 조절자와 아버지와 최상 존재가 의존한다.","r":["112:5.5"]},{"x":"하위 수준에서는 선택의 범위가 좁지만, 우주를 올라갈수록 선택은 점점 더 자유로워진다.","r":["118:7.8"]},{"x":"하나님의 뜻을 택하는 것은 의지의 포기가 아니라 의지의 봉헌이자 확장이며 완성이다.","r":["111:5.5"]},{"q":"영원의 문은 오직 자유 의지의 하나님의 자유 의지 아들들이 행하는 자유 의지 선택에 응답해서만 열린다.","r":"5:6.12"}]}],"see":["인격","하나님의 뜻","생존","생각 조절자","죄","루시퍼 반란"],"n":41,"en":"Free Will"},{"t":"정부와 사회","sum":"정부는 누가 설계한 것이 아니라, 사람들 사이의 적대감을 조율하고 평화를 지키려는 시행착오 속에서 진화해 온 제도이다. 유란시아서는 원로 평의회에서 근대 대의 정부에 이르는 발전을 더듬고, 행정·입법·사법의 분리를 정부의 유일한 신성한 특징으로 꼽는다. 국가의 수준은 결국 시민의 도덕적 가치를 넘지 못하며, 참된 세계 평화는 인류 전체의 정부가 설 때 온다고 가르친다.","sections":[{"h":"정부의 진화적 기원","items":[{"x":"생계 문제를 어느 정도 푼 사람은 곧 인간관계를 규제하는 과제를 만났고, 사유재산이 정부를 필요하게 만들었다.","r":["70:0.1"]},{"q":"정부는 무의식적 발달이다. 그것은 시행착오를 거쳐 진화한다.","r":"70:0.3"},{"q":"전쟁은 진화하는 사람의 자연 상태요 유산이며, 평화는 문명의 진보를 재는 사회적 잣대이다.","r":"70:1.1"},{"x":"평화 집단은 가족에서 씨족, 부족, 나라를 거쳐 영토 국가로 넓어졌고, 이제 혈연을 넘어 여러 나라를 품게 되었다.","r":["70:4.1"]},{"x":"최초의 정부 기구는 원로 평의회였으며, 그 안에 이미 행정·입법·사법 기능의 씨앗이 들어 있었다.","r":["70:5.2","70:5.3"]}]},{"h":"권리, 정의, 사회의 선물","items":[{"x":"자연은 사람에게 아무 권리도 주지 않으며, 사회가 사람에게 주는 최고의 선물은 안전이다.","r":["70:9.1"]},{"x":"자연적 정의는 사람이 만든 이론일 뿐이고, 자연이 주는 정의는 원인과 결과의 어김없는 일치뿐이다.","r":["70:10.1","70:10.2"]},{"x":"자유는 법의 집행으로 가능해지는 문명의 선물이며, 한 사람이 절대적으로 자유로우려면 다른 이는 노예가 되어야 한다.","r":["134:6.1"]},{"x":"정부의 으뜸 임무는 옳은 것을 정의하고, 계급 차이를 공정하게 규제하며, 법 아래 기회의 평등을 집행하는 것이다.","r":["81:5.6"]}]},{"h":"대의 정부와 권력 분립","items":[{"x":"우주 행정가들은 진화 민족들이 세 부문의 균형이 잡힌 대의 정부 아래서 가장 잘 다스려진다는 것을 체험으로 배웠다.","r":["70:12.1","70:12.2"]},{"q":"어떤 인간 정부든지 유일하게 신성한 특징은 국가 체제가 행정, 입법, 사법이라는 세 영역으로 나뉘는 것이다.","r":"71:8.1"},{"x":"필사자는 자기 정부와 헌법을 스스로 만들고, 가장 유능하고 가치 있는 이들을 지도자와 재판관으로 골라야 한다.","r":["70:12.5"]},{"q":"민주주의는 이상이지만, 진화의 산물이 아니라 문명의 산물이다.","r":"71:2.1"},{"x":"민주주의는 평범함의 미화, 무지한 통치자 선택, 여론에 대한 예속 같은 위험을 안고 있다.","r":["71:2.2","71:2.6"]},{"x":"여론을 교육하는 것이 문명을 가속하는 유일하고 안전한 길이며, 투표는 틀린 일을 할 때조차 올바른 방식이다.","r":["71:2.7","71:2.8"]}]},{"h":"이상적인 국가","items":[{"x":"정부의 형태보다 국가가 무엇을 하는가가 중요하며, 어떤 국가도 시민의 도덕적 가치를 넘어설 수 없다.","r":["71:3.1"]},{"x":"이상적인 국가는 형제단을 깨달은 사랑의 충성, 현명한 애국심, 우주적 통찰이라는 세 충동으로 움직인다.","r":["71:3.3","71:3.6"]},{"q":"가장 좋은 국가는 가장 적게 통치하면서도 가장 많이 조율하는 국가이다.","r":"71:3.9"},{"x":"선진 국가에서는 정치적 봉사가 시민의 최고 헌신으로 존중받고, 공직은 짐이 아니라 영예로 여겨진다.","r":["71:3.10","71:3.12"]},{"x":"오래가는 국가는 문화에 기초하고 이상으로 다스려지며 봉사로 움직이고, 그 교육은 지혜와 영적 가치를 목표로 한다.","r":["71:7.1","71:7.2"]},{"x":"이윤 동기만의 경제는 봉사 동기로 보완되지 않으면 파멸하지만, 더 높은 동기가 자리 잡기 전에 갑자기 없애서는 안 된다.","r":["71:6.1","71:6.3"]},{"x":"이웃 행성의 한 대륙 국가는 백 개 주의 연방과 세 부문의 대의 정부로 유란시아보다 앞선 사회를 이루고 있다.","r":["72:2.1","72:2.3"]}]},{"h":"주권과 세계 평화","items":[{"x":"상대적 주권은 개인의 영적 자유의지와 인류 전체의 집합적 주권, 두 수준뿐이며 그 사이의 집단은 모두 일시적이다.","r":["134:5.2"]},{"q":"전 세계적 주권만이 전 세계적인 전쟁을 막을 수 있다.","r":"134:6.4"},{"x":"무기를 모두 없애도 국가 주권의 망상을 붙드는 한 나라들은 주먹과 돌로라도 싸울 것이다.","r":["134:6.6"]},{"x":"지고자들은 특정 선민이 아니라 모든 사람에게 가장 큰 선을 이루도록 사람들의 왕국을 다스린다.","r":["134:5.3","134:5.4"]}]},{"h":"신자와 국가","items":[{"x":"왕국의 아들됨은 신자를 세상 나라의 더 나은 시민으로 만들어야 하며, 신자는 하나님과 사람에 대한 이중의 의무를 진다.","r":["178:1.4","178:1.5"]},{"x":"신자는 현세 통치자를 예배하거나 현세 권력으로 영적 왕국을 넓히려 해서는 안 된다.","r":["178:1.6"]},{"x":"복음의 끈질긴 전파는 결국 정치와 종교를 갈라놓고 모든 민족에게 지적·종교적 자유를 가져올 것이다.","r":["178:1.9"]}]}],"see":["문명","결혼과 가정","사람의 형제됨","정의","봉사","하나님 나라"],"n":83,"en":"Government and Society"},{"t":"정의","sum":"정의는 법을 적용하는 일로서, 어느 한 신의 인격적 태도가 아니라 파라다이스 삼위일체의 집단적 기능이다. 옛적부터 늘 계신 이들과 삼위일체 기원 아들들이 그 판결을 맡고, 무한 영의 인격들이 증거를 제공하며, 정의는 언제나 자비로 누그러진다. 사람의 정의 관념은 피의 복수에서 국가의 사법으로 진화해 왔으며, 예수는 정의를 집단에 맡기고 개인은 자비를 베풀라고 가르쳤다.","sections":[{"h":"삼위일체의 집단적 기능","items":[{"x":"법은 아버지에게서 나오고, 그 행정은 아들에게, 계시와 해석은 영에게 있으며, 법의 적용인 정의는 삼위일체에 속한다.","r":["10:6.1"]},{"q":"정의는 결코 인격적 태도가 아니며, 언제나 복수적 기능이다.","r":"10:6.2"},{"x":"공평을 위한 증거는 무한 영의 인격들이 제출하고, 판결은 삼위일체의 고정 아들들이 내린다.","r":["10:6.3","10:6.4"]},{"x":"옛적부터 늘 계신 이들은 일곱 초우주에서 최상 공평의 판결을 내리지만, 완전한 하보나에서는 그 기능이 이론으로만 존재한다.","r":["10:6.17"]},{"x":"최상 삼위일체 인격들은 대우주 곳곳에서 정의를 대표하며 삼위일체의 집행적 판결로 기능한다.","r":["18:0.10"]}]},{"h":"하나님의 정의와 공정함","items":[{"q":"우주 아버지의 정의는 그분의 창조체들의 행위나 성과에 의해 좌우되지 않는다.","r":"2:3.1"},{"x":"하나님께 떼를 써서 자연법과 영적 명령의 정당한 결과를 피하려는 것은 헛되다. 심은 대로 거두기 때문이다.","r":["2:3.2"]},{"x":"자비는 개인을 향한 하나님의 태도를, 공정성은 전체를 향한 하나님의 태도를 이끈다.","r":["12:7.1"]},{"q":"정의는 의로움에 대한 집단적 생각이며, 자비는 그 인격적 표현이다.","r":"10:6.18"},{"x":"온전히 이해되면 삼위일체의 의로운 정의와 아버지의 자비로운 사랑은 하나로 일치한다.","r":["10:6.18","2:4.4"]}]},{"h":"정의의 집행과 그 기다림","items":[{"x":"고의로 죄와 하나가 된 존재의 최종 결과는 소멸이지만, 그 집행은 정해진 정의의 절차가 다 지켜질 때까지 늦춰진다.","r":["2:3.2","2:3.3"]},{"x":"죄와 동일시하는 시점과 판결 집행 사이에는 모든 관계자와 죄인 자신까지 수긍할 만큼 충분한 시간이 있어야 한다.","r":["54:3.2","54:3.3"]},{"q":"우주에는 정의의 기본 법칙이 있으며, 자비는 이를 우회할 수 없다.","r":"146:2.5"},{"x":"세라핌 법정 조언자는 필사자의 변호자로서, 정의에 내재한 자비의 요소, 곧 동기와 성향을 아는 공정함을 대변한다.","r":["39:1.8"]},{"x":"생존 판정 때에는 자비의 기억이 낭독되며, 자비가 소진되었을 때에만 공의가 우세해진다.","r":["28:6.6","28:6.7"]}]},{"h":"사람 사회에서 진화한 정의","items":[{"q":"자연적 정의는 사람이 만든 이론이지, 현실이 아니다.","r":"70:10.1"},{"x":"사람이 생각하는 정의는 자기 권리를 얻는 것이며, 영이 부여된 마음에 잠재해 있어도 진화를 거쳐 자라났다.","r":["70:10.2"]},{"x":"원시 사회는 시련 재판과 피의 복수로 정의를 대신했으며, 동기는 무시하고 입힌 상해만으로 판결했다.","r":["70:10.3","70:10.5","70:10.9"]},{"x":"참된 정의의 집행은 복수를 개인과 친족에게서 거두어 국가에 맡긴 때부터 시작된다.","r":["70:10.13"]},{"x":"처벌의 혹독함보다 확실성과 신속성이 범죄를 막는 데 더 효과적임이 차츰 드러났다.","r":["70:10.15"]}]},{"h":"예수가 가르친 정의","items":[{"q":"민간 정부는 정의에 기초하니, 이는 참된 종교가 자비에 기초하는 것과 같다.","r":"132:4.8"},{"x":"재판관의 의무는 죄인을 벌하는 것만이 아니라 무고한 자를 풀어 주는 것이며, 가장 비천한 시민도 부당함을 당하지 않게 해야 한다.","r":["132:4.8"]},{"x":"개인은 자비를 베풀되, 벌을 정하는 일은 사정을 모두 아는 집단과 그 대표에게 맡겨야 한다.","r":["133:1.2","159:1.6"]},{"x":"예수는 확고한 정의감을 지녔으나 그것은 언제나 자비로 누그러져 있었고, 사회가 범죄자를 처벌하는 것도 인정했다.","r":["140:8.12","140:8.4"]},{"q":"신앙을 가지라—신성한 정의와 영원한 선함이 마침내 승리한다는 확신을 가지라.","r":"140:8.8"}]}],"see":["자비","파라다이스 삼위일체","옛적부터 늘 계신 이","정부와 사회","죄","선함"],"n":62,"en":"Justice"},{"t":"제도 종교","sum":"제도 종교는 개인의 종교 체험이 사회적으로 모여 형성된 교회와 종교 조직이다. 사람들이 신앙을 나누면 종교 집단이 생기는 것은 자연스럽고, 그것은 예배와 교육과 교제를 북돋우는 실제적 쓸모가 있다. 그러나 종교가 제도화될수록 선을 행할 힘은 약해지고 교의주의, 교파주의, 세속 권력과의 결탁 같은 위험이 커진다. 유란시아서는 교회가 예수의 영적 왕국을 대체한 것을 비극으로 본다.","sections":[{"h":"종교가 사회화되는 까닭","items":[{"x":"종교는 하나님을 아버지로 아는 개인 체험이지만, 그 결과 사람을 형제로 인식하게 되어 사회적 측면이 따른다.","r":["99:5.1"]},{"x":"사람들이 종교적 믿음을 나누면 공통 목표를 지닌 어떤 형태의 종교 집단이 필연적으로 생긴다.","r":["99:5.7"]},{"x":"종교 집단의 목적은 충성을 드러내고, 진선미의 매력을 키우며, 교제와 가정과 종교 교육과 집단 예배를 북돋우는 데 있다.","r":["99:6.2"]},{"x":"기도는 조만간 모든 종교를 제도화하는 기법이 되어, 사제와 경전과 의식 같은 부차적 매개체를 낳는다.","r":["91:5.6"]},{"q":"신조가 아니라 목표가 종교인들을 하나로 묶어야 한다.","r":"99:5.7"}]},{"h":"제도화의 위험","items":[{"q":"교파주의는 제도화된 종교의 병이며, 교의주의는 영적 본성의 속박이다.","r":"99:6.1"},{"q":"교회 없는 종교가, 종교 없는 교회보다 훨씬 낫다.","r":"99:6.1"},{"q":"그러나 종교가 제도화될수록 선을 행할 힘은 약화되고, 악으로 변질될 가능성은 크게 증가한다.","r":"99:6.3"},{"x":"형식 종교의 위험에는 믿음의 고착, 진리의 화석화, 하나님 봉사에서 교회 봉사로의 전환, 억압적 권위가 있다.","r":["99:6.3"]},{"q":"형식적 종교는 사람들이 하늘 왕국 건설자로서 고양된 봉사를 하도록 해방시키는 대신, 그들의 개인적인 영적 활동을 억제한다.","r":"99:6.4"}]},{"h":"제도 종교와 사회","items":[{"x":"제도화된 종교는 재건되어야 할 사회 질서의 일부가 되어 버려, 다가오는 사회 재건을 이끌 수 없다.","r":["99:2.1","99:2.2"]},{"x":"종교인은 집단이 아니라 개인으로서 사회와 정치에 참여해야 하며, 종교 집단이 정치적으로 움직이면 정당이나 경제 조직이 되어 버린다.","r":["99:2.3","99:3.15"]},{"x":"초기 그리스도교는 모든 시민적·경제적 얽힘에서 독립되어 있었으나 후대의 제도 그리스도교는 서방 문명 구조의 일부가 되었다.","r":["99:3.1"]},{"x":"종교가 세속적 동맹에서 자유로우려면 비판적 철학, 정치·경제적 독립, 사랑의 교제, 과학적 태도가 필요하다.","r":["99:3.9","99:3.10","99:3.11","99:3.14"]},{"x":"종교적 평화는 모든 종교가 교회 권위와 영적 주권 주장을 버리지 않는 한 오지 않으니, 하나님만이 영적 주권자이시다.","r":["134:4.4"]},{"q":"종교인들은 집단으로서 종교 외의 어떤 일에도 관여해서는 안 된다.","r":"99:3.15"}]},{"h":"권위의 종교","items":[{"x":"전통적 권위의 종교는 두려운 혼에게 쉬운 피난처가 되지만 그 대가로 영적 자유와 종교적 자유를 잃게 한다.","r":["155:5.9","155:6.5"]},{"x":"권위의 종교는 믿음의 일치를 요구해 사람들을 분열시키지만, 영의 종교는 체험의 일치만 요구한다.","r":["155:6.9"]},{"x":"참된 종교는 처벌의 위협이나 신비한 보상의 약속을 노예처럼 믿는 것이 아니다.","r":["99:5.2"]},{"x":"예수는 정형화된 신조를 암송하라고 하지 않고, 함께 모여 그의 생애를 기념하는 만찬을 나누라고 했다.","r":["99:5.10"]}]},{"h":"교회와 하늘 왕국","items":[{"x":"교회가 생긴 것 자체는 자연스럽고 바람직했지만, 그것이 예수의 왕국 개념을 거의 완전히 대체한 것이 문제였다.","r":["170:5.7"]},{"x":"형식적이고 제도화된 교회가 영의 인도를 받는 개인들의 왕국 형제단을 대신하게 되었다.","r":["170:5.9"]},{"x":"교회 회원 자격이 곧 왕국의 교제를 뜻하지는 않으니, 하나는 영적이고 다른 하나는 주로 사회적이다.","r":["170:5.18"]},{"x":"현재의 교회는 좌절된 영적 왕국의 유충 단계로서 물질 시대를 거쳐 왕국을 운반하는 고치와 같다.","r":["170:5.21"]},{"x":"살아 계신 하나님을 예배하고 사람의 형제단을 확증하며 신조의 압박을 걷어 내는 교회라면 큰 희망이 있다.","r":["103:5.12"]}]}],"see":["개인적 종교","하나님 나라","종교 체험","사람의 형제됨","정부와 사회","예수의 가르침"],"n":56,"en":"Institutional Religion"},{"t":"조절자 융합","sum":"조절자 융합은 진화하는 불멸의 혼이 내주하는 생각 조절자와 영원히 하나 되는 사건이다. 대개 죽음 뒤 맨션 세계에서 일어나지만, 드물게 육신의 삶 동안 변환으로 이루어지기도 한다. 융합은 필사자가 아버지의 뜻을 행하기로 한 최종 선택을 우주에 알리며, 이로써 상승자의 영원한 생애는 보장되고 파라다이스 최종자 군단으로 가는 길이 열린다.","sections":[{"h":"융합이란 무엇인가","items":[{"q":"이 융합은 하나님과 인간을 하나로 만드는 신비, 유한한 창조체 진화의 신비를 이루지만, 그것은 영원히 진실하다.","r":"112:7.2"},{"x":"조절자는 불멸의 영이므로, 그와의 연합은 융합된 필사자의 혼에 영원한 생명을 부여한다.","r":["40:7.1"]},{"x":"융합하면 조절자와 혼은 서로의 모든 체험과 가치를 공유하여 실제로 하나의 실체가 된다.","r":["110:7.4","110:7.5"]},{"x":"융합된 존재는 하나의 인격이어서, 어떤 우주 지성도 인간과 조절자를 따로 식별할 수 없다.","r":["112:7.8"]},{"x":"융합된 조절자는 존재적 신성 본성을 유지하면서도 유한 체험 수준으로 변환되어 상승 인격과 불가분하게 연결된다.","r":["107:2.7"]}]},{"h":"언제 일어나는가","items":[{"x":"융합은 대개 지역 체계에 머무는 동안 일어나며, 때로는 별자리나 지역 우주 수도에 이를 때까지 늦어진다.","r":["112:7.3"]},{"x":"실제로 작동하는 융합은 다섯째나 여섯째 맨션 세계에 머물 때에야 이루어지는 경우가 많다.","r":["47:8.3"]},{"x":"일곱 우주적 원을 성취하고 의지의 최종 선택이 더해지면, 육신의 삶 동안 융합하여 몸이 즉시 소멸되기도 한다.","r":["110:7.2"]},{"x":"대다수 유란시아인의 경우 조절자는 죽음의 해방이 올 때까지 인내하며 기다려야 한다.","r":["110:7.6"]},{"q":"자연적·물리적 죽음은 필사자의 불가피한 숙명이 아니다.","r":"55:2.1"},{"x":"빛과 생명에 정착한 세계에서는 융합 변환이 점점 늘어, 넷째 단계에 이르면 필사자의 절반 이상이 산 채로 변환된다.","r":["55:2.2","55:2.8"]}]},{"h":"융합의 조건","items":[{"q":"조절자와의 융합은 인간 본성이 영원한 생애를 위해 최종적이고 돌이킬 수 없는 선택을 했다고 초우주의 명령이 선언하기 전에는 결코 일어나지 않는다.","r":"112:7.5"},{"x":"융합 전까지 상승자는 언제라도 아버지의 뜻을 저버릴 수 있지만, 융합은 그가 아버지의 뜻을 유보 없이 택했음을 알린다.","r":["111:3.1"]},{"x":"최상 결정을 내린 대상자의 조절자는 융합의 때를 미리 내다보며 그 결합을 이미 실재하는 사실로 여긴다.","r":["109:2.4"]},{"x":"조절자 융합이 최종 선택을 우주에 선포할 때 인간의 영원한 운명은 보장된다.","r":["5:1.11"]}]},{"h":"융합의 장면","items":[{"q":"그러고 나서 그러한 생존자의 모론시아 동료들이 있는 자리에서 이 확인의 사자들이 말한다. “이는 내가 기뻐하는 사랑하는 아들이다.”","r":"47:8.4"},{"x":"새 존재는 새 이름으로 소개되고 사십 일 영적 은둔을 하며 하보나로 가는 경로를 고른다.","r":["47:8.5"]},{"x":"정착된 세계에서는 융합 후보가 사원에 모인 가족과 친구들 앞에서 생명 섬광 속에 떠난다.","r":["55:2.3","55:2.4"]},{"q":"이러한 장면을 목격할 수 있는 인간들은 변환되는 필사자가 “불의 수레 안에서” 사라지는 것만을 볼 것이다.","r":"110:7.2"},{"x":"육신의 삶 중에 융합한 이들은 죽음을 거치지 않고 조절자 직접 이주로 더 높은 모론시아 구체로 간다.","r":["49:6.18","49:6.19"]}]},{"h":"융합하지 않는 경우","items":[{"x":"필사자는 조절자와의 관계에 따라 일시 내주형, 비융합형, 융합 잠재형의 세 계열로 나뉜다.","r":["40:5.4","40:5.5","40:5.7"]},{"x":"원시 시대의 필사자들은 조절자의 사역을 받아 생존할 수는 있어도 조절자와 영원히 결합하지는 못한다.","r":["40:5.9","40:5.10"]},{"x":"비융합 유형의 필사자에게도 조절자가 평생 내주하지만, 생존하면 그 혼은 영과 융합한다.","r":["40:5.13","40:5.14"]},{"x":"생존이 인정되고도 조절자와 끝내 하나 되지 못한 소수는 조사 법정의 판결을 거쳐 아들과 융합하는 길로 간다.","r":["40:8.1","40:8.3"]},{"q":"융합 체험에는 중복이 없다.","r":"40:9.1"}]},{"h":"융합의 결과","items":[{"q":"조절자와의 융합이 이루어지면 그러한 인격의 영원한 생애에 더 이상 위험은 없다.","r":"112:7.4"},{"x":"융합은 신성의 특질 고정, 과거 영원의 체험과 기억, 불멸성 같은 잠재적이던 실제성을 인격에 부여한다.","r":["112:7.1"]},{"x":"융합된 상승자는 인격 문제에서 인간이 앞서며, 본부는 디비닝턴이 아니라 어쎈딩톤이다.","r":["112:7.12"]},{"x":"융합된 조절자의 번호는 초우주 기록에서 지워지고, 그 운명은 상승 필사자와 같은 최종자 군단이 된다.","r":["112:7.11","112:7.13"]},{"x":"융합으로 우주 아버지는 물질 창조체에게 자신을 선물하겠다는 약속을 완성한다.","r":["112:7.14"]},{"x":"조절자 융합 필사자만이 하보나 회로를 지나 파라다이스에서 하나님을 발견하는 인간 계층이다.","r":["40:7.5"]}]}],"see":["생각 조절자","혼","최종자 군단","맨션 세계","생존","빛과 생명"],"n":34,"en":"Adjuster Fusion"},{"t":"종교 체험","sum":"종교 체험은 사람이 내주하는 영의 인도 아래 하나님과 최상 가치를 살아서 아는 개인적 체험이다. 그것은 이성으로 추론한 신념 체계도, 신비적 황홀경도 아니며, 도덕적 의식에서 싹터 신앙과 통찰로 자라난다. 신학이 아무리 잘못되었어도 체험 자체는 참될 수 있으며, 그 확신은 논박될 수 없다. 종교 체험은 하나님에 대한 확실한 의식과 생존의 확신으로 귀결된다.","sections":[{"h":"종교 체험의 본질","items":[{"x":"참된 종교는 이성이 입증하는 철학 체계도, 소수만 누리는 신비한 황홀경도 아니다.","r":["101:1.1"]},{"q":"너희를 하나님께로 이끄는 것은 너희의 느낌이 아니라 너희의 생각이다.","r":"101:1.3"},{"x":"종교는 새로운 사실을 찾는 것이 아니라 이미 알려진 사실들 속에서 새로운 영적 의미를 발견하는 것이다.","r":["101:1.4"]},{"x":"종교적 성향은 선천적이고 보편적이며, 예배의 영이 후원하고 지혜의 영이 검열한다.","r":["103:0.1","103:0.2"]},{"x":"영적 가치를 깨닫는 체험은 초관념적이어서 인간 언어로 가리키기 어려우며, 이를 하나님 의식이라 부른다.","r":["103:1.6"]}]},{"h":"체험의 출발점","items":[{"x":"모든 사람은 일찍부터 이기적 충동과 이타적 충동 사이의 갈등을 겪으며, 그 해결에서 처음 하나님 의식을 체험하기도 한다.","r":["103:2.4"]},{"x":"도덕적 존재가 이기적 충동을 거슬러 비이기적 선택을 할 때 그것이 종교 체험의 원초적 형태이다.","r":["103:2.8"]},{"x":"이타적 욕망을 자기 밖의 영향, 곧 하나님과 동일시하는 것은 옳으니, 그것은 내주하는 조절자에게서 온다.","r":["103:2.10"]},{"x":"종교의 ‘출생’은 대개 점진적이지만 영으로 거듭나는 날이 있으며, 위기 없이 자란 이와 위기를 겪은 이를 서로 낮추어 보지 말아야 한다.","r":["103:2.1","103:2.2"]},{"q":"도덕적 존재가 이기적 충동에 맞서 비이기적 선택을 할 때, 그것이 종교 체험의 원초적 형태이다.","r":"103:2.8"}]},{"h":"회심과 신비주의","items":[{"x":"종교적 성장은 정체에서 조율로, 불안에서 신앙으로, 두려움의 속박에서 아들됨의 자유로 나아간다.","r":["100:5.2"]},{"x":"하나님 의식은 점진적으로 자랄 수도 있고, 바울의 다마스커스 길처럼 극적인 순간에 올 수도 있다.","r":["100:5.3"]},{"q":"그러나 감정만으로는 거짓 회심이다. 감정과 더불어 신앙이 있어야 한다.","r":"100:5.5"},{"x":"회심을 좇기보다 살아 있는 신앙과 성실한 예배와 이기심 없는 기도가 조절자에게 다가가는 더 나은 길이다.","r":["100:5.7"]},{"x":"무아지경이나 환상을 종교 체험으로 추구해서는 안 되며, 예수는 그런 방법에 결코 의지하지 않았다.","r":["100:5.8","100:5.11"]}]},{"h":"체험과 신학","items":[{"x":"종교는 가치 추구에서 시작되고 해석적 믿음 체계는 나중에 생기므로, 사람들은 신조보다 가치에서 더 쉽게 합의한다.","r":["103:1.4"]},{"q":"누군가의 신학이 아무리 환상적이고 잘못된 것일지라도, 그 사람의 종교는 완전히 진실하고 영원히 참될 수 있다.","r":"103:9.2"},{"q":"신학이 종교를 지배하면, 종교는 죽는다. 종교가 삶이 아니라 교리가 되어 버린다.","r":"103:9.6"},{"x":"다른 이들의 다양한 종교 체험을 아는 것은 자기 종교가 이기적이고 편협해지지 않도록 막아 준다.","r":["103:1.3"]}]},{"h":"체험의 열매와 확실성","items":[{"x":"참된 종교는 살아 있는 사랑이자 봉사의 삶이며, 사람에게서 아무것도 빼앗지 않고 모든 삶에 새 의미를 준다.","r":["100:6.5"]},{"x":"종교적 삶의 놀라운 특징은 어떤 실망에도 흔들리지 않는, 모든 이해를 초월하는 평화이다.","r":["100:6.6"]},{"x":"종교는 하나님을 알 수 있고 도달할 수 있다는, 조절자에게서 오는 가정 위에 서 있다.","r":["103:9.8"]},{"x":"종교 체험의 실체는 그 영적 내용에 비례하며, 그 확신은 논박될 수 없고 그 헌신은 의심할 여지가 없다.","r":["103:9.12"]},{"x":"종교 체험은 하나님에 대한 확실한 의식과 신앙인의 생존에 대한 의심 없는 확신으로 귀결된다.","r":["101:1.6"]},{"q":"그러나 진정한 종교는 살아 있는 사랑이며, 봉사의 삶이다.","r":"100:6.5"}]}],"see":["개인적 종교","신앙","예배","생각 조절자","보조 마음 영","철학"],"n":54,"en":"Religious Experience"},{"t":"죄","sum":"죄는 단순한 불완전이나 실수가 아니라, 아버지의 뜻과 신성한 실체를 알면서 고의로 거스르는 인격의 태도, 곧 하나님에 대한 의도적 불충성이다. 죄의 도덕적 책임은 전적으로 개인의 것이어서 유전되지 않으며, 누구도 남의 죄 때문에 생존을 잃지 않는다. 모든 죄는 용서받을 수 있지만, 죄와 완전히 하나가 되어 버린 인격은 비실체가 되어 결국 소멸에 이른다.","sections":[{"h":"죄란 무엇인가","items":[{"q":"죄는 신성한 법, 곧 아버지의 뜻을 의식적으로, 알고도, 고의로 어기는 것이다.","r":"148:4.4"},{"x":"오류는 실체의 오해, 악은 실체에 대한 부분적 부적응이며, 죄는 신성한 실체에 대한 의도적 저항이다.","r":["67:1.4"]},{"x":"오류는 지적 예리함의 결여, 악은 지혜의 결핍, 죄는 영적 빈곤, 불법은 무너져 가는 인격 통제를 드러낸다.","r":["67:1.5"]},{"x":"선은 신성한 계획을 수행하는 것이고, 죄는 신성한 뜻을 고의로 거역하는 것이다.","r":["75:4.3"]},{"q":"죄는 신에 대한 의도적인 불충성으로 재정의되어야 한다.","r":"89:10.2"}]},{"h":"불완전함은 죄가 아니다","items":[{"x":"다시 태어나기 전의 사람이 지닌 자연적 악한 성향과 불완전함은 죄도 불법도 아니며, 상승 여정의 출발점일 뿐이다.","r":["148:4.6"]},{"x":"유한하다는 사실 자체는 악도 죄도 아니며, 유한한 것을 오용하고 왜곡할 때 악과 죄가 생긴다.","r":["111:6.3"]},{"x":"죄책감은 도덕률을 어겼다는 자각일 뿐 반드시 죄를 뜻하지는 않으며, 하나님께 대한 자각적 불충성이 있을 때만 참된 죄다.","r":["89:10.3"]},{"x":"죄책감을 느낄 수 있다는 것은 사람을 비천하게 하는 표지가 아니라, 잠재적 위대함을 지닌 존재라는 표지이다.","r":["89:10.4"]},{"x":"죄는 자기 의지의 자유에 현혹되어 우주 시민의 의무를 깨닫지 못한 미성숙을 드러낸다.","r":["118:7.4"]}]},{"h":"죄의 결과와 책임","items":[{"x":"죄의 영향은 결코 국지적이지 않지만, 생존에 치명적인 것은 죄가 마음과 혼의 전 존재적 태도가 될 때뿐이다.","r":["67:7.4"]},{"q":"죄는 그 도덕적 죄책이나 영적 결과에 있어서 전적으로 인격적인 것이다.","r":"67:7.7"},{"x":"어떤 존재의 죄도 다른 존재의 생존을 막지 못하며, 영원한 생존은 자기 자신의 선택으로만 위태로워진다.","r":["67:7.5"]},{"q":"동물적 본성, 즉 악행에 대한 경향은 유전될 수 있지만, 죄는 부모로부터 자식에게 전해지지 않는다.","r":"188:4.5"},{"x":"되풀이된 죄는 습관이 되고, 습관적 죄인은 쉽게 불법에 빠져 우주에 맞서는 전심의 반란자가 될 수 있다.","r":["67:1.6"]}]},{"h":"하나님과 죄","items":[{"x":"하나님은 죄인을 영원한 인격 실체로 보아 사랑하시지만, 죄는 인격도 영적 실체도 아니므로 오직 정의만이 그것을 다룬다.","r":["2:6.8"]},{"q":"하나님의 사랑은 죄인을 구원하고, 하나님의 법은 죄를 멸한다.","r":"2:6.8"},{"x":"죄와 완전히 동일시된 존재는 비실체가 되어 스스로를 파괴하며, 소멸 판결이 확정되면 마치 존재하지 않았던 것처럼 된다.","r":["2:3.2","2:3.4"]},{"q":"죄는 창조체의 의식 속에서의 체험이지, 하나님의 의식의 일부가 아니다.","r":"174:1.4"}]},{"h":"죄 개념의 진화와 바로잡힘","items":[{"x":"원시인에게 죄는 귀신이 재가한 금기를 어기는 행위였고, 죽음은 그 벌로 여겨졌다.","r":["89:2.2","70:11.4"]},{"x":"원시적 죄는 생각이 아닌 행위이자 의례적인 것이었으며, 완전한 시작에서 타락했다는 믿음을 낳았다.","r":["89:2.3"]},{"x":"개인의 죄를 위한 희생은 점차 인종의 죄를 위한 속죄 희생 교리로 발전했다.","r":["89:4.5"]},{"x":"예수는 인류의 죄책을 속죄하거나 하나님의 진노를 달래려고 죽은 것이 아니다.","r":["188:4.1"]},{"x":"죄의 고백은 그 시간적 결과를 없애지는 않지만, 종교적 성장과 영적 진보에 꼭 필요하다.","r":["89:10.5","156:2.7"]}]}],"see":["악","용서","자유 의지","정의","루시퍼 반란","도덕성"],"n":66,"en":"Sin"},{"t":"죽음","sum":"유란시아서에서 죽음은 끝이 아니라 물질적 생애에서 모론시아 생애로 넘어가는 문이다. 원시인에게 죽음은 가장 큰 충격이자 두려움이었고 종교 발달의 계기가 되었지만, 계시는 죽음에 영적·지적·물리적 세 종류가 있으며 생존하는 혼은 잠든 뒤 맨션 세계에서 다시 깨어난다고 밝힌다. 진보한 세계에서는 자연적 죽음조차 점점 드물어진다.","sections":[{"h":"원시인과 죽음의 두려움","items":[{"q":"죽음은 진화하는 인간에게 가장 큰 충격이었으며, 우연과 신비의 가장 당혹스러운 결합이었다.","r":"86:3.1"},{"x":"생명의 신성함보다 죽음의 충격이 불러일으킨 두려움이 초기 종교를 키웠다.","r":["86:3.1"]},{"x":"원시인들은 죽음으로 풀려난 귀신을 두려워해 죽은 이의 집을 허물고 장례에서 돌아올 때 길을 바꾸었다.","r":["87:1.1","87:1.3","87:1.5"]},{"x":"꿈에서 비롯된 미래 삶의 개념은 자기 보존 본능과 결부된 죽음의 두려움을 누그러뜨리기 시작했다.","r":["86:4.2"]},{"x":"원시 종교의 기본 신념은 죽음 이후의 생존이었다.","r":["92:6.1"]}]},{"h":"세 종류의 죽음","items":[{"x":"인격 생존과 관련해 죽음에는 영적(혼의) 죽음, 지적(마음의) 죽음, 물리적(몸과 마음의) 죽음의 세 가지가 있다.","r":["112:3.1"]},{"x":"생존을 최종적으로 거부한 사람은 몸이 살아 있어도 우주적 관점에서는 이미 죽은 것이다.","r":["112:3.2"]},{"x":"의지적 행동을 가능하게 하는 마음 회로가 돌이킬 수 없이 파괴되면 조절자는 떠나며, 이것도 죽음이다.","r":["112:3.3"]},{"x":"물리적 죽음에서 조절자는 마음이 기능을 멈출 때까지 머물다가, 뇌의 생명 맥박이 그치면 디비닝턴으로 떠난다.","r":["112:3.4"]}]},{"h":"죽음 뒤에 일어나는 일","items":[{"x":"몸은 원소로 돌아가지만, 조절자와 모론시아 혼이라는 두 비물질적 요소는 계속된다.","r":["112:3.5"]},{"q":"죽음이 오면 생각 조절자는 인격을 일시적으로 잃지만 정체성은 잃지 않는다. 인간 대상자는 정체성을 일시적으로 잃지만 인격은 유지된다.","r":"112:3.7"},{"x":"생존하는 혼은 죽음에서 재인격화까지 완전히 무의식 상태로 운명의 수호자의 보호 아래 있다.","r":["112:5.13"]},{"x":"맨션 세계로 간 이들은 지상의 사랑하는 이들에게 메시지를 보낼 수 없으며, 그런 소통은 금지되어 있다.","r":["112:3.7"]},{"x":"부활 전당에서 모론시아 형태와 돌아온 조절자와 보관된 혼이 결합해 정체성이 재조립된다.","r":["112:5.16","112:5.18","112:5.19"]},{"q":"맨션 세계에서 둘은 영원한 현시로 다시 결합한다.","r":"112:3.7"}]},{"h":"죽음을 바라보는 신앙의 눈","items":[{"x":"모험심과 단조로움에 대한 두려움은 죽음이 끝없는 모험 생애의 시작일 뿐임을 시사하려고 사람 안에 놓였다.","r":["14:5.10"]},{"x":"죽음 이후의 삶은 본질적으로 필사 실존과 다르지 않으며, 지금 행하는 선한 일이 미래 생명을 향상시킨다.","r":["103:5.7"]},{"x":"참된 종교는 죽음의 문을 지나기만 하면 고귀한 덕을 얻는다는 헛된 희망으로 영적 게으름을 조장하지 않는다.","r":["103:5.7"]},{"x":"예수는 믿는 이들이 늘 임박한 자연적 죽음을 염두에 두고 자기 생애를 이어 가듯 살아야 한다고 가르쳤다.","r":["176:3.3"]},{"q":"이 선물은 지금도 자연적 죽음의 속박으로부터 그들의 부활을 확실히 보장한다.","r":"190:0.2"},{"q":"죽음은 지적 소유에도 영적 부여에도 아무것도 더하지 않았으나, 체험적 지위에는 생존의 의식을 더하였다.","r":"48:7.25"}]},{"h":"죽음이 사라져 가는 세계","items":[{"q":"자연적·물리적 죽음은 필사자의 불가피한 숙명이 아니다.","r":"55:2.1"},{"x":"빛과 생명에 정착한 세계에서는 많은 이들이 조절자와 융합하여 살아 있는 채로 모론시아 상태로 변환된다.","r":["55:2.1","55:2.2"]},{"x":"그런 세계의 ‘장례식’은 울음 대신 기쁨과 깊은 만족, 형언할 수 없는 희망의 자리가 된다.","r":["55:2.5"]},{"x":"덜 진보한 필사자들도 자연적 죽음을 그처럼 명랑하고 가벼운 마음으로 바라보는 법을 배운다면 도움이 될 것이다.","r":["55:2.6"]},{"x":"그러나 오래 정착된 세계에서도 육체에서 벗어나는 길로서 자연적 죽음이 완전히 사라진 체계는 없다.","r":["55:2.8"]}]}],"see":["생존","맨션 세계","모론시아","혼","두려움과 걱정","빛과 생명"],"n":43,"en":"Death"},{"t":"중도자","sum":"중도자(중도 창조체)는 필사자와 천사 사이의 중간 수준에 존재하는 행성 토착 존재이다. 유란시아의 1차 중도자는 칼리가스티아 영주의 유형 참모진에게서, 2차 중도자는 아담손과 라타의 독특한 자녀들에게서 나왔다. 반란으로 많은 수가 이탈했지만 충성한 이들은 연합 중도자로서 세라핌을 돕고 행성의 기억을 지키며, 빛과 생명의 시대에 이르면 상승하는 하나님의 아들로서 파라다이스 여정에 오른다.","sections":[{"h":"인간과 천사 사이의 존재","items":[{"x":"필사자와 천사 계층 사이의 생명 기능 수준에 존재하므로 중도 창조체라 불리며, 대부분의 거주 행성과 모든 십진 행성에 나타난다.","r":["77:0.1","38:9.2"]},{"x":"그들은 진화의 우연한 산물이 아니라 우주 건축가들이 미리 정하고 생명 운반자들이 설계한 계획의 필수 요소이다.","r":["38:9.5"]},{"x":"기원상 상승하는 아들이고, 사실상 영구 시민이며, 기능상 시간의 봉사 영들과 함께 헤아려지는 세 겹의 분류를 지닌다.","r":["38:9.1"]},{"q":"중도자들은 인간도 아니고 천사도 아니지만, 2차 중도자들은 본질적으로 인간에 더 가깝다.","r":"77:8.4"},{"q":"물질 세계와 영적 세계 사이의 간격은 필사 인간, 2차 중도자, 1차 중도자, 모론시아 체루빔, 중간 단계 체루빔, 세라핌의 연속적인 연결로 완벽하게 이어진다.","r":"38:9.9"}]},{"h":"1차 중도자의 기원","items":[{"q":"이와 같은 계층의 창조체가 필사자와 천사 사이의 중간 수준에 존재하여 영주의 본부 업무를 수행하는 데 크게 기여할 수 있음이 곧바로 발견되었으며,","r":"77:1.3"},{"x":"칼리가스티아 영주의 유형 참모진 부부들에게 허가가 주어져 첫 쉰 명이 태어났고, 이어 50,000명의 원래 군단이 생겨났다.","r":["77:1.3","77:1.4"]},{"x":"그들은 영주 행정의 정보 집단으로서 세계의 인종들을 연구하고, 본부에서 먼 인간 사회에 영향을 주는 일을 도왔다.","r":["77:1.6"]},{"x":"행성 반란 때 원래 50,000명 가운데 40,119명이 칼리가스티아의 분리에 가담했다.","r":["77:7.1"]},{"x":"충성한 1차 중도자들은 멜기세덱 수탁자들의 봉사로 들어갔고, 그 지도자 1-2-3 첫째는 반란의 날 반과 아마돈과 함께 굳게 섰다.","r":["77:1.7","77:9.5"]}]},{"h":"2차 중도자의 기원","items":[{"x":"2차 중도자는 아담과 이브의 장남 아담손과, 영주 참모진의 마지막 순수 혈통 후손 라타 사이의 자녀들에게서 나왔다.","r":["77:5.1","77:5.5"]},{"x":"아담손의 자녀 가운데 독특한 열여섯이 여덟 쌍을 이루어 칠십 일마다 2차 중도자를 낳았고, 그 수는 모두 1,984명이 되었다.","r":["77:6.2","77:6.4"]},{"q":"이러한 현상은 그 이전에도, 그 이후에도 지상에서 결코 일어난 적이 없다.","r":"77:6.2"},{"x":"아담손이 죽은 뒤 조직 없이 떠돌던 2차 중도자 가운데 873명이 미가엘의 통치를 따르지 않아 오순절 판결과 함께 억류되었다.","r":["77:6.6","77:7.2"]},{"x":"오순절 이전에는 반란 중도자들이 열등한 필사자의 마음에 영향을 줄 수 있었으나, 진리의 영이 부어진 뒤로는 어떤 불충한 영도 인간 마음에 침입할 수 없다.","r":["77:7.5","77:7.8"]}]},{"h":"연합 중도자의 봉사","items":[{"x":"현재 유란시아의 두 계층은 10,992명으로 이루어진 하나의 집단으로 기능하며, 각 계층의 최고 구성원이 번갈아 다스린다.","r":["77:8.1"]},{"x":"그들은 잠을 자지 않고 생식하지 않는 비물질적 존재이지만, 인간의 유머와 예배를 즐기고 따를 수 있다.","r":["77:8.3"]},{"x":"중도 사자, 행성 파수꾼, 접촉 인격, 진보 조력자로 조직되어 행성 세라핌과 함께 봉사한다.","r":["77:8.5","77:8.7","77:8.8"]},{"x":"2차 중도자는 물질적인 것과 물리적으로 접촉할 수 있어, 천사의 행적으로 돌려진 문자적 현상들 가운데 많은 것이 그들의 일이었다.","r":["77:8.11","77:8.12"]},{"x":"오늘날 그들의 주된 임무는 운명 예비 군단을 이루는 남녀의 인식되지 않는 동료가 되는 것이다.","r":["77:8.13"]},{"q":"그들의 결단력은 그들의 모토인 “연합 중도자들이 맡은 일은, 연합 중도자들이 해낸다”라는 구절에서 드러난다.","r":"77:9.3"}]},{"h":"행성의 영구 시민과 그 운명","items":[{"q":"세라핌들은 오고 가지만, 중도 창조체들은 남아 있으며,","r":"77:9.2"},{"x":"그들은 우주 권위자들이 해방할 때까지 행성을 떠나지 않기로 맹세했으며, 빛과 생명의 시대까지 행성에 머문다.","r":["77:9.4"]},{"q":"인간의 세대들은 잊어버리지만, 중도자 군단은 기억하며, 그 기억은 너희의 거주 세계의 전통을 담은 보물 창고이다.","r":"77:9.9"},{"x":"유란시아 문명은 필사자와 중도자의 공동 산물이며, 두 문화 수준의 차이는 빛과 생명의 시대 이전에는 메워지지 않는다.","r":["77:9.8"]},{"x":"행성이 빛과 생명에 이르면 두 집단은 행성 봉사에서 풀려나 상승하는 하나님의 아들로 등록되고, 지상 형제들과 함께 파라다이스 상승을 시작한다.","r":["40:3.1","38:9.13"]},{"x":"2차 중도자들은 모두 결국 조절자와 융합하여 필사 최종자 군단에 편입된다.","r":["31:6.2"]}]}],"see":["칼리가스티아","아담과 이브","루시퍼 반란","세라핌","유란시아","빛과 생명"],"n":29,"en":"Midwayers"},{"t":"중력","sum":"중력은 파라다이스의 물리적 현존이 모든 공간의 세계를 붙드는 전능한 끌어당김이다. 우주에는 아버지의 인격 인력, 아들의 영 인력, 공동 행위자의 마음 인력, 파라다이스 섬의 우주 중력이라는 네 가지 절대 회로가 있으며, 이들은 시간과 공간에 매이지 않고 작용한다. 물질은 파라다이스 중력과 선형 중력에 붙들리지만, 사람의 마음은 영적일수록 물질 중력에 덜 반응하고 영 인력에 더 이끌려 파라다이스로 나아간다.","sections":[{"h":"파라다이스의 전능한 붙들음","items":[{"q":"중력은 파라다이스의 물리적 현존이 발휘하는 전능한 붙들음이다.","r":"11:8.1"},{"x":"절대적 물질 중력의 중심은 파라다이스 섬이며, 하보나를 도는 암흑 중력체와 위아래의 공간 저장소가 이를 보완하고 평형을 이룬다.","r":["11:8.2"]},{"x":"우주 통제자는 파라다이스 섬의 중력 회로 안에 잠재적으로 현존하시며, 그 현존은 질량에 따라 우주의 모든 부분에 같은 정도로 미친다.","r":["3:1.7"]},{"x":"창조계 끝에서 오는 중력선들이 아버지의 거처에 수렴하므로, 그분이 그 자리를 옮기신다면 즉시 우주적 대혼란이 일어날 것이다.","r":["11:1.4"]},{"x":"새 우주가 창조될 때마다 중력의 새로운 조정이 필요하지만, 파라다이스의 통제 권능은 무한한 우주에도 넉넉하다.","r":["3:4.2"]}]},{"h":"네 가지 절대 회로","items":[{"x":"우주에는 아버지의 인격 인력, 아들의 영 인력, 공동 행위자의 마음 인력, 파라다이스 섬의 우주 중력이라는 네 절대 회로가 있으며, 아버지는 그 모두에 걸쳐 활동하신다.","r":["12:3.1","12:3.5"]},{"q":"그것들은 절대 현존 회로이며, 하나님처럼 시간과 공간에 독립적이다.","r":"12:3.6"},{"x":"모든 중력은 파라다이스 섬에, 모든 마음은 공동 행위자에, 모든 영은 영원 아들에, 모든 인격은 아버지의 인격적 현존에 회로로 연결되어 있다.","r":["5:6.11"]},{"x":"아버지가 모든 인격을, 아들이 모든 영적 실체를 끌어당기듯, 공동 행위자는 모든 마음 위에 인력을 행사한다.","r":["9:6.2"]},{"x":"인격 인력의 작용은 언제나 우주 아버지의 의지적 행위이며, 그 회로에 반응하는 실체는 측정할 수 없다.","r":["9:6.4","12:3.12"]}]},{"h":"물리적 중력의 단계","items":[{"x":"절대 중력은 파라다이스 중력이며, 지역적 또는 선형 중력은 에너지와 물질의 전기적 단계에 속한다.","r":["11:8.3"]},{"x":"에너지는 중력 이전 단계(힘), 중력 단계(에너지), 중력 이후 단계(우주 동력)로 나뉘어 파라다이스 중력에 반응한다.","r":["11:8.4","11:8.5","11:8.7"]},{"x":"선형 중력은 물질의 원자 조직이 나타날 때 온전히 작용하며, 결합되지 않은 극자는 원형 파라다이스 중력에만 반응한다.","r":["42:6.2","42:6.3"]},{"q":"중력이 에너지-물질의 유일한 통제자이다.","r":"0:6.11"},{"x":"선형 중력은 대우주의 단거리 응집력이며, ‘거리의 제곱에 반비례한다’는 표현은 공간의 영향 때문에 대략적인 근사치일 뿐이다.","r":["42:11.5"]},{"x":"이론적인 절대 영도가 실제로 나타나지 않는 것은 중력의 현존과 작용 때문이다.","r":["42:4.6"]}]},{"h":"균형과 반중력","items":[{"q":"공간은 중력에 반응하지 않지만, 중력에 대해 평형력으로 작용한다.","r":"11:8.3"},{"x":"무한 영은 아버지나 아들에게서 관찰되지 않는 반중력의 권능을 지니며, 이를 상위 인격들에게 전달할 수 있다.","r":["9:3.2"]},{"x":"공간 수준들이 번갈아 반대 방향으로 도는 배치는 중력 압력이 파괴적인 지점까지 커지는 것을 막는다.","r":["11:7.9"]},{"x":"하보나의 암흑 중력체들은 안팎의 띠가 서로 반대 방향으로 공전하여 중앙 우주를 완벽하게 안정시킨다.","r":["14:1.15"]},{"x":"현재 조직된 우주들은 파라다이스 절대 중력의 약 5퍼센트만 쓰고 있으며, 나머지는 바깥 공간의 물질 체계를 붙드는 데 쓰인다.","r":["12:3.8"]}]},{"h":"영 인력과 상승","items":[{"x":"영 인력은 시간 지연이 없고 공간에 의해 줄지 않으며, 물질 질량에 의해 지연되지도 않는다.","r":["7:1.2"]},{"x":"영적 실체는 질적 가치에 따라 영 인력에 반응하는데, 이는 물질이 양에 따라 물리적 중력에 반응하는 것과 같다.","r":["7:1.3"]},{"q":"어떤 인격의 마음이 더 영적으로, 곧 하나님 같아질수록 그것은 물질 중력에 덜 반응하게 된다.","r":"12:8.5"},{"x":"물리적 중력 작용은 비영적 에너지의 양적 척도이고, 영 인력 작용은 신성의 살아 있는 에너지의 질적 척도이다.","r":["12:8.5"]},{"x":"시간과 공간에서의 영성은 선형 중력에 대한 반응에 반비례하여 측정된다.","r":["42:11.4"]},{"q":"영 인력 회로는 사람의 혼을 문자 그대로 파라다이스를 향해 끌어당긴다.","r":"7:3.2"}]}],"see":["파라다이스","에너지와 물질","영원 아들","무한 영","세 절대자","우주 아버지"],"n":18,"en":"Gravity"},{"t":"지역 우주 네바돈","sum":"네바돈은 창조자 아들 미가엘과 우주 어머니 영이 조직하고 다스리는 지역 우주로, 유란시아가 속한 곳이다. 백 개의 별자리와 만 개의 체계로 이루어질 이 우주는 오르본톤에서 비교적 젊은 창조계이며, 수도 샐빙턴에서 미가엘이 아버지와 아들을 대표하여 다스리고 가브리엘이 최고 집행자로 일한다. 지역 우주는 진화적이어서, 창조체들은 아래에서부터 단계적으로 올라가며 완전함을 획득한다.","sections":[{"h":"진화하는 지역 우주","items":[{"x":"지역 우주는 미가엘 계층 창조자 아들의 작품으로, 백 개의 별자리로 이루어지며 각 별자리는 백 개의 체계를 품는다.","r":["32:0.1"]},{"x":"시간과 공간의 우주들은 모두 진화적이며, 창조자 아들의 계획은 언제나 창조체들이 점진적으로 발달하는 길을 따른다.","r":["32:0.2"]},{"x":"지역 우주는 주 우주의 파라다이스 건축가들이 구상하고, 동력 감독자들이 공간 에너지를 결집한 뒤에야 창조자 아들이 조직을 시작한다.","r":["32:0.4","32:1.2"]},{"x":"네바돈의 범위는 샐빙턴 어머니 영의 공간 현존이 스며 있는 곳까지이며, 그 너머는 네바돈 바깥이다.","r":["41:0.1"]},{"q":"중앙 우주를 제외하면, 완전함은 점진적으로 달성하는 것이다.","r":"32:3.3"}]},{"h":"조직과 우리의 자리","items":[{"x":"네바돈에서 처음 완료된 물리적 창조는 본부 세계 샐빙턴이며, 이어 별자리 본부 백 개와 체계 본부 만 개가 지어졌다.","r":["32:2.3"]},{"x":"샐빙턴은 지역 우주의 정확한 에너지-질량 중심에 자리한다.","r":["32:2.4"]},{"x":"마지막 등록 때 네바돈에는 거주 행성이 3,840,101개 있었으며, 행성 거처의 조직은 지금도 진행 중이다.","r":["32:2.9"]},{"x":"네바돈은 오르본톤의 가장자리 쪽으로 치우쳐 있고, 사타니아는 다시 네바돈의 변두리에 있다.","r":["32:2.11"]},{"x":"네바돈은 엔사 소구역에서 여든네 번째 우주이며, 샐빙턴이 그 수도이다.","r":["15:14.6"]}]},{"h":"미가엘: 주권자 아들","items":[{"x":"네바돈의 미가엘은 아버지와 영원 아들에게서 기원한 611,121번째 본래 개념의 인격화이며, 파라다이스의 영원 아들 자신은 아니다.","r":["33:1.1","33:1.2"]},{"q":"우리 우주와 그 모든 거주 세계에게 주권 아들은 사실상 모든 면에서 하나님이다.","r":"33:1.4"},{"x":"미가엘은 일곱 창조체 증여를 마친 뒤 이해심 있는 자비를 지닌 주권자로 네바돈을 다스린다.","r":["119:0.4","119:0.7"]},{"x":"그의 권능은 파라다이스 중력 회로와, 인격 소멸에 관한 최종 판결을 유보한 옛적부터 늘 계신 이들에 의해서만 제한된다.","r":["33:2.2"]},{"x":"아버지는 지역 우주 행정에서는 창조자 아들을 통해서만 기능하시지만, 내주하는 조절자로서 필사자 안에 친밀하게 현존하신다.","r":["33:0.1","32:3.4"]}]},{"h":"아들과 영의 공동 통치","items":[{"x":"우주 어머니 영은 미가엘과 함께 우주를 창조하고 다스리며, 아들은 영에게 모든 사안에서 동격의 지위와 동등한 권위를 부여한다.","r":["33:3.2","33:3.3"]},{"x":"미가엘이 유란시아 증여를 마치고 돌아왔을 때, 우주 영은 처음으로 아들에 대한 종속을 공개적으로 인정했다.","r":["33:3.5"]},{"x":"이어 아들은 ‘평등 선언’으로 영이 인격의 모든 자질에서 자신과 동등함을 공포했으며, 이것이 가족과 결혼의 높은 이상이 된다.","r":["33:3.6"]},{"q":"아들과 영은 이제 마치 아버지와 어머니가 아들딸로 이루어진 가족을 지켜보고 그들에게 사역하듯이 우주를 주재한다.","r":"33:3.7"},{"x":"반란에 맞설 때는 오직 아들이 구원자로 기능하지만, 어떤 아들도 신성한 사역자의 끊임없는 협력 없이는 성공할 수 없다.","r":["33:3.4"]}]},{"h":"행정과 법정","items":[{"x":"아들과 영의 첫 공동 창조로 태어난 찬란한 새벽별 가브리엘이 네바돈의 최고 집행자이다.","r":["32:2.6","33:4.5"]},{"x":"삼위일체의 대사인 샐빙턴의 임마누엘은 미가엘에 대한 종속을 인정하지 않는 네바돈의 유일한 인격이며, 요청받을 때만 조언한다.","r":["33:5.1","33:5.2"]},{"x":"체계는 주로 생물학적 문제를, 별자리는 사회적 통일과 안정을, 우주 통치자들은 영역들의 영적 상태를 돌본다.","r":["33:6.3"]},{"x":"미가엘은 창조, 유지, 사역에만 관심을 두며, 창조자들은 결코 자기 창조체를 재판하지 않는다.","r":["33:7.1"]},{"q":"너희는 질서가 잘 잡힌 우주에 살고 있으며, 조만간 공의롭게, 심지어 자비롭게 다루어지리라고 믿어도 된다.","r":"33:7.8"}]},{"h":"창조체의 상승과 목적","items":[{"q":"창조자 아들을 본 자는 아버지를 본 것이다.","r":"32:3.6"},{"x":"생명의 척도에서 낮은 창조체일수록 창조자 아들 안에서 아버지를 알아보기 어렵지만, 아버지가 아들들 안에 현존한다는 진리를 붙드는 것이 가장 확실한 안전장치이다.","r":["32:3.6"]},{"x":"동물적 진화 기원은 오점이 아니며, 밑바닥부터 생명의 사다리를 오른 이들은 더 큰 영예와 온전한 체험을 얻는다.","r":["32:3.10"]},{"x":"지역 우주는 불완전한 인격들이 자신의 미래를 공동 창조하는 참된 진화의 출발점이며, 그 안에서 창조자들조차 진화한다.","r":["116:4.8"]},{"x":"하나님의 마음속에는 모든 창조체를 포용하는 무한한 기회와 끝없는 생명의 영원한 계획이 있다.","r":["32:5.7"]},{"q":"영원의 목표가 앞에 있다!","r":"32:5.8"}]}],"see":["창조자 아들 미가엘","지역 우주 어머니 영","별자리와 지역 체계","일곱 초우주","예수의 증여","유란시아"],"n":15,"en":"Local Universe of Nebadon"},{"t":"지역 우주 어머니 영","sum":"지역 우주 어머니 영은 무한 영이 각 지역 우주에 개별화한 창조적 딸로, 창조자 아들과 함께 우주를 짓고 생명을 낳으며 다스리는 동격의 동반자이다. 네바돈에서는 신성한 사역자라 불리며, 생명의 숨결과 일곱 보조 마음 영, 성령을 통해 모든 창조체에게 마음과 영을 베푼다. 미가엘이 아버지로서 기능하듯 그녀는 어머니의 역할을 하며, 사람을 강요하지 않고 부드럽게 아들됨의 길로 인도한다.","sections":[{"h":"무한 영의 지역 우주 딸","items":[{"x":"창조자 아들이 인격화될 때 무한 영은 그와 함께 공간으로 나아갈 새롭고 독특한 표현을 개별화하여 그의 동반자로 삼는다.","r":["34:0.1","17:6.3"]},{"x":"우주 어머니 영들은 하보나 세계들에서 전(前)인격적 훈련을 받으며, 아버지의 뜻 아래 파라다이스 아들들과 협력하는 법을 배운다.","r":["14:6.32"]},{"q":"그녀는 미가엘이 파라다이스의 의무에서 풀려날 때 그와 동행하기를 자원했으며,","r":"33:3.2"},{"x":"네바돈의 어머니 영은 여섯째 최상 영 집단의 611,121번째 존재로, 미가엘과 함께 이 우주를 창조하고 다스려 왔다.","r":["33:3.2"]},{"x":"창조자 아들이 공간으로 떠날 때 우주 아버지가 두 존재의 영원한 연합을 공표하는 일은 파라다이스에서 가장 감동적인 사건 가운데 하나이다.","r":["17:6.5"]}]},{"h":"인격화와 생애 단계","items":[{"x":"미가엘이 생명 창조를 선포하면 파라다이스에서 ‘1차 분출’이 일어나고, 그 순간 창조 영이 인격적 존재인 신성한 사역자가 된다.","r":["34:1.1","17:6.7"]},{"x":"인격화된 어머니 영은 그 초우주를 관할하는 주(主) 영의 본성으로 물든 인격적 본성을 얻는다.","r":["34:1.3"]},{"x":"물리적 창조 단계에서 우주 아들이 원형을 주면, 우주 영은 그 에너지 창조물을 물리적 실질로 물질화한다.","r":["34:0.3"]},{"x":"미가엘이 일곱째 증여를 마치고 돌아오자 어머니 영은 그에게 종속을 서약했고, 미가엘은 그녀를 공동 통치자로 세웠다.","r":["33:3.5","33:3.6","17:6.8"]},{"q":"인격의 모든 자질과 신성한 성품의 속성에서 영이 자신과 동등하다는 사실을 세계들에 공포하였다.","r":"33:3.6"},{"x":"이 ‘평등 선언’은 가족 조직과 통치의 초월적 원형이며, 인간의 가정과 자발적 결혼의 높은 이상이 된다.","r":["33:3.6"]}]},{"h":"생명과 영 인격들의 어머니","items":[{"x":"생명 운반자들이 물리적 몸을 마련하면, 우주 영은 “생명의 숨결”을 기여하고 생명 없는 원형을 활성화하며 번식 능력을 전수한다.","r":["34:2.5","36:6.3"]},{"x":"미가엘과 어머니 영은 문자 그대로 모든 네바돈 토착 창조체의 아버지-아들이자 영-어머니이다.","r":["37:0.1"]},{"q":"그러한 신성한 사역자는 실제로 영들과 영 인격들의 어머니이며, 창조자 아들의 늘 곁에 있는 지극히 지혜로운 조언자이고,","r":"33:3.3"},{"x":"세라핌은 어머니 영의 첫 단독 영 번식으로 창조되었으며, 네바돈이 자라는 동안 그녀의 창조 활동은 결코 멈추지 않는다.","r":["38:1.1","38:1.3"]},{"x":"반란이 일어나면 구원자로 나설 수 있는 것은 아들뿐이지만, 영은 아들이 겪는 모든 일에서 언제나 그를 뒷받침한다.","r":["33:3.4"]}]},{"h":"마음과 영의 사역","items":[{"q":"그녀는 자신의 전 지역 우주에 걸쳐 동등하게 그리고 널리 퍼져 있으며, 따라서 어느 한 세계에나 다른 어느 세계에나 똑같이 문자 그대로 그리고 인격적으로 현존한다.","r":"34:3.3"},{"x":"일곱 보조 마음 영은 신성한 사역자가 창조한 것으로, 지혜·예배·상담·지식·용기·이해·직관의 영이라 불린다.","r":["34:4.10"]},{"x":"마음이 예배와 지혜의 보조자를 받아들일 수준에 이르면 곧바로 신성한 사역자의 영 회로, 곧 성령의 사역에 포함된다.","r":["34:5.3","36:5.15"]},{"x":"어머니 영은 샐빙턴을 결코 떠나지 않으며, 그녀가 그곳에 고정되어 있기에 진리의 영은 미가엘의 소재와 무관하게 기능한다.","r":["34:4.7"]},{"q":"우주 어머니 영은 그녀 자신의 인격적 영향력인 성령뿐만 아니라 진리의 영의 우주 초점이자 중심으로서 활동한다.","r":"34:4.7"},{"x":"성령, 진리의 영, 조절자가 한 필사자 안에 함께 현존함은 영적 부여의 대칭이며, 하나님의 아들됨을 의식하게 한다.","r":["34:5.7"]}]},{"h":"사람 안에서 일하는 영","items":[{"q":"영원한 영광의 높은 곳으로부터 신성한 영은, 있는 그대로의 너희를, 너희가 있는 곳에서 만나기 위해 긴 일련의 단계를 거쳐 내려오며,","r":"34:6.3"},{"x":"성령의 사역은 부분적으로 사람의 태도와 무관하지만, 신성한 인도를 더 온전히 따를수록 내면의 삶을 성화하는 데 더 효과적이 된다.","r":["34:5.5"]},{"q":"영은 결코 강요하지 않고, 오직 인도할 뿐이다.","r":"34:6.11"},{"x":"동물적 본성과 영적 충동 사이에서 결합된 영은 사람이 육체를 점점 더 영의 인도에 복종시키도록 평생 돕는다.","r":["34:6.9"]}]}],"see":["창조자 아들 미가엘","무한 영","보조 마음 영","성령","진리의 영","세라핌"],"n":23,"en":"Local Universe Mother Spirit"},{"t":"지혜","sum":"지혜는 지식을 넘어 사실과 이상, 사물의 관계와 의미를 아우르는 능력이다. 하나님의 지혜는 무한한 통찰 안에 완전히 존재하지만, 사람의 지혜는 체험과 시행착오, 특히 실패에 적응하는 가운데 진화한다. 지혜의 보조 영이 그 바탕을 놓고 조절자와 진리의 영이 진리에 이르게 하며, 시간 속에서 사고는 지혜로, 지혜는 예배로 나아간다.","sections":[{"h":"신성한 지혜와 체험의 지혜","items":[{"q":"인간의 지혜는 인간 체험의 시행착오에서 자라나지만, 하나님의 지혜는 그의 무한한 우주적 통찰의 제한 없는 완전성 안에 존재하며,","r":"4:3.4"},{"x":"무한한 지혜의 분별이 있기에 하나님은 어떤 상황에서도 정의와 자비를 동시에 베푸실 수 있다.","r":["2:4.3","2:3.2"]},{"x":"지혜에는 완전한 존재의 신성한 통찰과 진화 창조체의 인격적 체험이라는 두 기원이 있다.","r":["19:2.4"]},{"x":"초우주 행정은 신성한 통찰을 지닌 지혜의 완성자들과 체험으로 단련된 상승 인격들을 언제나 함께 묶는다.","r":["19:2.4"]},{"x":"무한한 지혜는 어떤 일이든 그 상황에서 가장 좋은 방법, 곧 올바른 방법으로 행해지도록 명한다.","r":["12:7.2"]}]},{"h":"마음 안에 놓인 지혜의 바탕","items":[{"x":"지혜의 영은 보조 마음 영 가운데 가장 높으며, 다른 보조자들의 일을 조율하는 영이다.","r":["36:5.12"]},{"q":"지혜는 지성적 수행의 정점이다. 지혜는 순전히 정신적이고 도덕적인 실존의 목표이다.","r":"36:5.12"},{"x":"동물도 지식은 가질 수 있지만, 기억에서 관념을 엮어 내는 지혜의 잠재력은 사람만이 지닌다.","r":["101:6.4"]},{"x":"지혜는 지식이 새로운 의미 수준으로 고양되어 지혜의 보조 영으로 활성화된 의식이다.","r":["180:5.3"]},{"q":"신성한 또는 영적 통찰은 선물이지만, 인간의 지혜는 진화해야 한다.","r":"101:4.2"}]},{"h":"지식·진리와 구별되는 지혜","items":[{"q":"지식은 사실을 다루고, 지혜는 관계를 다루며, 진리는 실체 가치를 다룬다.","r":"132:3.2"},{"x":"과학은 사실 의식으로, 종교는 가치 의식으로, 철학 곧 지혜는 그 둘을 아우르는 조율 의식으로 이끈다.","r":["102:3.5"]},{"x":"과학은 사람을 분류하고 종교는 사람을 사랑하지만, 지혜는 서로 다른 사람들에게 정의를 베푼다.","r":["102:3.7"]},{"x":"물질적 사실과 영적 가치의 두 관점이 조화될 때, 지혜는 우주 현상을 진보하는 인격 체험의 눈으로 해석한다.","r":["130:4.10"]},{"x":"지식은 교육으로 얻지만, 참된 문화에 필요한 지혜는 체험으로만 얻으며, 지성은 문명을 통제하고 지혜는 그것을 인도한다.","r":["81:6.13","81:6.27"]}]},{"h":"지혜를 얻는 길","items":[{"q":"성공은 용기를 불러일으키고 자신감을 증진시킬 수 있지만, 지혜는 자기 실패의 결과에 적응하는 체험에서만 얻을 수 있다.","r":"160:4.14"},{"x":"사실을 외면하는 이상주의자도, 영적 전망 없는 물질주의자도 아닌, 사실을 이상에 맞추는 사람만이 지혜롭다.","r":["160:4.14"]},{"x":"지식과 문화와 지혜는 서로 다르며, 지혜는 언제나 지식을 지배하고 문화를 영화롭게 한다.","r":["160:4.16"]},{"x":"지혜는 초지식이어서, 사람들이 마음을 모으면 서로의 통찰을 나누고 편견과 편협함을 피할 수 있다.","r":["160:2.7"]},{"x":"예수는 야고보에게 참된 지혜는 용기와 함께 신중함도 품는다고 일러 주었다.","r":["181:2.15"]}]},{"h":"지혜에서 신앙과 예배로","items":[{"x":"이성과 지혜와 신앙은 사람이 이룰 수 있는 가장 높은 세 성취이며, 높은 철학에서 지혜는 신앙과 결합한다.","r":["103:9.6","103:9.10"]},{"x":"지식과 이성이 해 줄 수 없는 일을 신앙이 이루도록 허락하라고 진정한 지혜는 충고한다.","r":["102:1.2"]},{"x":"깨우친 이들의 초철학적 지혜는 하나님을 의심하는 것이 내주하는 조절자에게 불성실한 일임을 깨닫는다.","r":["101:1.7"]},{"q":"시간 속에서 사고는 지혜로, 지혜는 예배로 이어진다. 영원 속에서 예배는 지혜로, 지혜는 사고의 최종성으로 이어진다.","r":"112:2.13"}]}],"see":["철학","진리","보조 마음 영","마음","과학과 종교","체험"],"n":64,"en":"Wisdom"},{"t":"진리","sum":"진리는 사실을 다루는 지식이나 관계를 다루는 지혜를 넘어 실체의 가치를 다루는, 영적으로 인식되는 살아 있는 실체이다. 하나님은 첫째 진리이며 모든 진리는 그에게서 나온다. 진리는 말이나 신조로 가둘 수 없고 오직 삶으로 정의되며, 정적인 진리는 죽은 진리이다. 진리의 영은 사람 안에서 이 살아 있고 자라나는 진리를 깨닫게 하며, 진리는 아름다움·선함과 함께 하나님 안에서 하나가 된다.","sections":[{"h":"진리란 무엇인가","items":[{"q":"진리는 말로 정의될 수 없고, 오직 삶을 통해서만 정의될 수 있다.","r":"132:3.2"},{"x":"지식은 과학에서, 지혜는 철학에서, 진리는 영적 생활의 종교 체험에서 나오며, 진리는 실체 가치를 다룬다.","r":["132:3.2"]},{"x":"지식은 증명할 수 있고 진리는 체험되며, 지식은 마음의 소유이고 진리는 혼의 체험이다.","r":["130:4.10"]},{"x":"하나님은 첫째 진리이자 마지막 사실이므로 모든 진리는 하나님에게서 기원한다.","r":["102:6.6"]},{"x":"진리는 언제나 계시이니, 조절자의 작업으로 오면 자체 계시이고 천상의 기관이 전하면 시대적 계시이다.","r":["101:4.3"]}]},{"h":"살아 있는 진리","items":[{"x":"물리적 사실은 균일하지만 진리는 우주의 철학 안에서 살아 있고 유연한 요소이다.","r":["2:7.2"]},{"x":"진리는 공식이나 법전이나 신조 속에 가둘 수 없으며, 형식화하려 하면 급속히 죽는다.","r":["180:5.2"]},{"q":"정적인 진리는 죽은 진리이며, 오직 죽은 진리만이 이론으로 간주될 수 있다.","r":"180:5.2"},{"x":"진리는 충격에 흔들리지 않고 모든 일시적 변동을 벗어나 있으나, 결코 형식화되지 않고 언제나 생동한다.","r":["118:3.3"]},{"x":"과거를 진리의 유일한 출처로 여기는 것은 어리석으니, 진리는 언제나 현재에 살아 각 세대에서 새로 표현된다.","r":["79:8.8"]},{"q":"진리는 상대적이고 확장하는 것이며, 항상 현재에 살아 있고, 각 세대의 사람들, 심지어 각 인간의 삶 속에서 새로운 표현을 이룬다.","r":"79:8.8"}]},{"h":"진리를 아는 길","items":[{"x":"진리는 신앙 없이는 사람의 소유가 될 수 없으니, 사람의 생각과 이상은 그의 신앙보다 높아질 수 없다.","r":["132:3.5"]},{"q":"계시된 진리, 곧 인격적으로 발견된 진리는 인간 혼의 최상의 기쁨이다.","r":"132:3.4"},{"x":"사람은 미지의 것을 두려워해 과학을 고정시키고 철학을 공식화하며 진리를 교리화하려 한다.","r":["132:3.3"]},{"x":"참된 지식과 진리 사이에는 갈등이 없으며, 갈등은 편견과 두려움에 물든 인간의 믿음과 지식 사이에서 생긴다.","r":["132:3.4"]},{"x":"진리를 알수록, 진리가 될수록 과거를 더 이해하고 미래를 더 파악할 수 있다.","r":["118:3.2"]}]},{"h":"진리의 영","items":[{"x":"진리의 영은 진리의 문자나 법이 아니라 실재하는 영 수준의 참된 의미에 대한 확신이며, 살아 있고 자라나는 교사이다.","r":["180:5.1"]},{"x":"하나님을 아는 이는 지혜를 살아 있는 진리 수준으로 높이지만, 영적으로 진보하지 못한 혼은 살아 있는 진리를 죽은 지혜로 끌어내린다.","r":["180:5.4"]},{"x":"황금률도 진리의 영의 통찰이 없으면 단지 윤리 규칙에 그치며, 살아냄으로써만 그 의미를 깨닫는다.","r":["180:5.5","180:5.11"]},{"x":"우주 관계와 영적 가치에 대한 이해인 진리는 진리의 영의 사역으로 가장 잘 얻어진다.","r":["103:7.8"]},{"q":"신성한 진리는 영적으로 인식된 살아 있는 실체이다.","r":"180:5.2"}]},{"h":"진리·아름다움·선함","items":[{"q":"진리는 충만하며 동시에 균형 잡혀 있기 때문에 아름답다.","r":"2:7.4"},{"x":"진리는 행동으로 옮기고 살아낼 수 있기에 진리를 인식하면 행복이 따르고, 오류에는 실망과 슬픔이 따른다.","r":["2:7.6"]},{"x":"모든 진리는 물질적이든 철학적이든 영적이든 아름답고 또한 선하다.","r":["2:7.11"]},{"x":"진리는 응집력이 있고 아름다움은 마음을 끌며 선하심은 안정시키니, 이것들이 조화를 이루면 높은 사랑이 된다.","r":["2:7.12"]},{"x":"진리는 과학과 철학의 기초이자 종교의 지적 토대이다.","r":["56:10.10"]}]}],"see":["아름다움","선함","진리의 영","지혜","신앙","계시"],"n":57,"en":"Truth"},{"t":"진리의 영","sum":"진리의 영은 창조자 아들이 증여 생애를 마친 뒤 세상의 모든 육체에 부어 주는 그 자신의 영, 곧 위로자이다. 유란시아에서는 미가엘의 영으로서 오순절에 부어졌으며, 모든 정상적인 마음을 조절자를 맞을 수 있게 준비시켰다. 이 영은 진리를 법이나 신조가 아니라 살아 있는 확신으로 가르치고, 자기 자신이 아니라 미가엘을 의식하게 하며, 신자의 삶 속에서 예수의 삶을 새롭게 드러낸다.","sections":[{"h":"창조자 아들의 증여 영","items":[{"x":"네바돈의 세 영 회로 가운데 첫째가 창조자 아들의 증여 영, 곧 위로자인 진리의 영이다.","r":["34:4.2","15:9.12"]},{"q":"이 증여된 위로자는 지역 우주에서 진리의 인격화인 그를 향해 모든 진리 추구자들을 언제나 이끄는 영적 힘이다.","r":"34:4.5"},{"x":"이 영은 아들의 인격에서 나오지만 기능적으로는 신성한 사역자에게 집중되어 있어, 아들이 어디에 있든 방해 없이 일한다.","r":["34:4.6","34:4.7"]},{"x":"어떤 의미에서 진리의 영은 우주 아버지와 창조자 아들 둘 다의 영이며, 흔히 우주 아들의 영으로 여겨진다.","r":["194:2.3","194:2.16"]},{"x":"아보날 증여 세계에는 증여 아보날과 창조자 아들의 공동 영으로 오지만, 미가엘의 최종 증여 뒤에는 더욱 문자 그대로 미가엘의 영이 된다.","r":["52:5.6","20:6.8","20:6.9"]}]},{"h":"약속과 오순절","items":[{"x":"예수는 떠나기 전, 아버지께서 허락하시면 진리의 영을 모든 육체 위에 부어 또 다른 교사로 보내겠다고 약속했다.","r":["180:4.1","180:4.2"]},{"q":"아주 짧은 시간 후, 나는 이 물질의 몸만 없을 뿐 나와 똑같은 내 영을 너희에게 보낼 것이다.","r":"180:4.5"},{"x":"다락방의 백스무 명만이 아니라 세상의 정직한 모든 이가 진리에 대한 사랑과 영적 이해 능력에 따라 이 교사를 받았다.","r":["194:3.6"]},{"x":"영의 증여는 형식이나 의식, 거룩한 장소와 무관했으며, 기도가 영을 가져온 것은 아니지만 받는 그릇의 크기를 정했다.","r":["194:3.10","194:3.20"]},{"x":"당시 ‘영의 세례’라는 말은 진리의 영이라는 선물을 의식적으로 받아들이고 인정하는 것을 뜻할 뿐이었다.","r":["194:2.10"]},{"q":"오순절 이후로 사람은 여전히 하나님을 찾고 있으나, 하나님도 사람을 찾으시고 그를 찾으셨을 때 자기 영을 그 안에 거하도록 보내신다는 광경이 세상 위에 빛난다.","r":"194:3.13"}]},{"h":"진리의 영이 하는 일","items":[{"q":"이 영의 첫째 임무는 물론 진리를 기르고 인격화하는 것인데, 진리를 이해하는 것이야말로 인간 자유의 가장 높은 형태를 이루기 때문이다.","r":"194:2.2"},{"x":"또한 신자의 고아 된 느낌을 없애고, 주님의 말을 기억하고 이해하며 그의 지상 생애를 다시 해석하도록 돕는다.","r":["194:2.2","194:2.5"]},{"x":"진리의 영은 사람 안에 살면서 새 세대마다 예수의 메시지를 그 시대에 맞게 다시 진술한다.","r":["194:2.1"]},{"x":"이 영은 아버지의 사랑과 아들의 자비라는 진리를 가르치며, 아버지의 영 본성과 아들의 도덕적 성품을 계시한다.","r":["194:3.1"]},{"q":"창조자 아들은 육신으로 사람들에게 하나님을 계시했고, 진리의 영은 심정에서 사람들에게 창조자 아들을 계시한다.","r":"194:3.1"},{"x":"이 영은 자기 자신에 대한 의식이 아니라 미가엘에 대한 의식만 만들어 내므로, 그 증거는 미가엘과의 교제가 깊어지는 데서 찾는다.","r":["194:2.4"]}]},{"h":"살아 있는 진리","items":[{"x":"진리의 영은 진리의 문자나 법이 아니라 영 수준의 참된 의미에 대한 확신이며, 스스로 자라고 펼쳐지는 영이다.","r":["180:5.1"]},{"q":"정적인 진리는 죽은 진리이며, 오직 죽은 진리만이 이론으로 간주될 수 있다.","r":"180:5.2"},{"x":"황금률은 진리의 영의 통찰이 없으면 윤리 규칙에 그치며, 아들의 영이 아버지의 영에게 행동의 법을 해석해 줄 때 참뜻이 드러난다.","r":["180:5.5","180:5.8"]},{"x":"사랑은 진리의 영의 인도에 따라 사랑받는 이의 최고선을 향해 끊임없이 다시 적응하는 해석을 거쳐야 한다.","r":["180:5.10"]},{"x":"증여된 진리의 영은 모든 존재가 하나님을 향해 조율되는 살아 있는 관계인 진리에 오류 없이 반응한다.","r":["56:10.13","2:7.6"]}]},{"h":"조절자를 위한 준비와 길잡이","items":[{"x":"증여 아들이 진리의 영을 해방하기 전에는 모든 정상적인 마음이 저절로 조절자를 맞을 준비가 되지는 않는다.","r":["34:5.4","20:5.3","194:2.3"]},{"x":"진리의 영은 모든 육체에 부어지지만, 그 기능과 권능은 사람이 그것을 인격적으로 받아들이는 정도에 거의 전적으로 달려 있다.","r":["34:5.5"]},{"x":"영적 철학, 곧 영 실체들의 지혜는 증여 아들들이 주는 진리의 영의 부여물이다.","r":["101:3.2"]},{"x":"상승자가 자기 지역 우주를 떠나도 진리의 영의 사역에서 완전히 벗어나지 않으며, 이 영은 상승의 모든 위기에서 길을 가리킨다.","r":["117:5.9"]},{"q":"모든 어두운 시간에, 앞으로 나아가는 투쟁의 모든 갈림길에서, 진리의 영이 항상 “이것이 길이다” 하고 말할 것이기 때문이다.","r":"34:7.8"}]}],"see":["창조자 아들 미가엘","오순절","성령","진리","예수의 증여","생각 조절자"],"n":39,"en":"Spirit of Truth"},{"t":"진화","sum":"유란시아서에서 진화는 우연한 과정이 아니라 시간과 공간의 우주들이 점진적으로 성장해 가는 신성한 기법이다. 생명 운반자들이 심은 생명은 물리적 통제자와 보조 마음 영의 사역 아래 바다의 원형질에서 의지를 지닌 인간에 이르렀고, 사회와 종교와 정부도 같은 진화의 길을 걸어 왔다. 이 모든 성장은 최상 존재의 진화와 맞물려 있으며, 마침내 빛과 생명의 시대를 향한다.","sections":[{"h":"진화하는 우주","items":[{"q":"시간과 공간의 이 우주들은 모두 진화적이다.","r":"32:0.2"},{"x":"완전하게 창조된 하보나와 달리, 성장은 대우주의 특징이며 체험적 신의 표식이다.","r":["116:0.3"]},{"x":"유란시아의 혼란과 불평등은 이 세계가 절대 이하이고 아직 완전하지 않은 창조주들의 작품임을 보여 준다.","r":["116:0.2"]},{"x":"계속되는 진화는 파라다이스 완전성의 몫을 늘리고 악과 오류와 부조화의 몫을 줄여 자연을 고쳐 간다.","r":["4:2.4"]},{"x":"우리는 최상 하나님 안에서 진화하고, 그분도 우리 안에서 진화한다.","r":["31:10.12"]}]},{"h":"우연이 아닌 계획","items":[{"q":"우주적 진화는 항상 이해할(예측할) 수 있는 것은 아니지만, 엄격하게 비우연적이다.","r":"49:1.1"},{"x":"유란시아는 생명 실험 세계였지만, 생명의 확립은 되는대로나 우연이라는 뜻의 실험이 아니었다.","r":["65:4.1","65:4.2"]},{"x":"상처를 스스로 치유하는 세포처럼 인간 존재의 여러 특성은 생명이 지능적으로 계획되었음을 보여 준다.","r":["65:4.3"]},{"q":"물리학과 화학만으로는 인간이 초기 바다의 원시 원형질에서 어떻게 진화했는지를 설명할 수 없다.","r":"65:6.8"},{"x":"모든 살아 있는 것 안에는 더 큰 완전함을 향한 채워지지 않는 타고난 열망이 깃들어 있다.","r":["65:6.2"]}]},{"h":"생명의 진화","items":[{"x":"물질 생명은 물리적 통제자, 일곱 주 영, 생명 운반자의 삼중 창조성이 협력하여 이루어진다.","r":["65:0.1"]},{"x":"생명의 발달은 물리적 에너지, 보조 영들의 마음 사역, 조절자 증여로 완성되는 영적 부여의 세 단계를 거친다.","r":["65:0.2","65:0.5"]},{"x":"인류의 원시 조상은 옛 내륙해의 따뜻한 만과 석호의 진흙이었고, 4억 5천만 년 전에 식물에서 동물로의 전환이 일어났다.","r":["65:2.1","58:6.1"]},{"x":"새로운 종은 미세한 변이의 축적이 아니라 완전히 갖추어진 새 계층으로 갑자기 나타난다.","r":["58:6.3"]},{"x":"약 백만 년 전 인류의 직계 조상은 여우원숭이 유형 포유류에서 잇따른 세 번의 갑작스러운 돌연변이로 나왔다.","r":["62:0.1"]},{"x":"생명 운반자들은 의지를 지닌 존재가 나타나면 일을 마치며, 그 뒤로는 의지에 간섭할 수 없다.","r":["36:3.8"]}]},{"h":"마음과 영의 진화","items":[{"x":"생명이 높아질수록 보조 마음 영들이 하나씩 작용하여, 마음은 점점 더 조정적이고 창조적이며 통합적이 된다.","r":["65:6.7","62:6.3"]},{"x":"생물학적 진화는 마침내 인간 의지의 존엄에 이르렀고, 유란시아는 993,408년 전 인간 거주 행성으로 인정받았다.","r":["62:7.7"]},{"q":"우주 진화의 실험실에서 마음은 언제나 물질을 지배하며, 영은 언제나 마음과 상관된다.","r":"65:8.5"},{"x":"영적 진보는 마음의 확장에 기대므로 지적 지체로 늦어지지만, 혼은 마음의 문화 수준과 무관하게 진화할 수 있다.","r":["65:8.4"]},{"x":"진화가 길게 보이는 것은 창조체가 자기 수명을 시간의 기준으로 삼기 때문이다.","r":["65:8.2","65:8.3"]}]},{"h":"사회와 종교의 진화","items":[{"x":"결혼과 산업과 종교처럼 시민 정부도 점진적 진화의 산물이다.","r":["70:5.1"]},{"x":"초기 진화는 적자생존으로 특징지어지지만, 후대 문명은 지적 협동과 영적 형제단으로 더 잘 나아간다.","r":["71:5.3"]},{"x":"행성 영주가 오기 전까지 종교는 전적으로 진화 과정이며, 그 뒤로는 진화와 계시가 함께 종교를 진보시킨다.","r":["52:2.3"]},{"x":"관습을 혁명으로 뒤엎으려는 시도는 문명에 치명적이니, 관습은 문명을 묶어 온 연속성의 실이다.","r":["68:4.6"]},{"q":"진화는 지연될 수는 있어도 멈출 수는 없다.","r":"81:0.1"}]},{"h":"진화의 목적","items":[{"x":"우주들의 행진에는 크고 영광스러운 목적이 있으며, 필사자의 모든 분투는 헛되지 않다.","r":["32:5.1"]},{"q":"시간의 사건들과 물질적 실존의 분투는 저편, 곧 영적 실체와 천상의 실존이라는 약속의 땅으로 건너가는 일시적 비계일 뿐이다.","r":"32:5.2"},{"x":"진화하는 세계의 최종 성취는 빛과 생명의 시대이며, 정착된 세계의 성취만으로도 인간 창조가 정당화된다.","r":["55:0.1","55:6.9"]}]}],"see":["생명 운반자","보조 마음 영","최상 존재","빛과 생명","유란시아","문명"],"n":94,"en":"Evolution"},{"t":"창조자 아들 미가엘","sum":"창조자 아들은 우주 아버지와 영원 아들이 함께 낳은 1차 파라다이스 아들로, 지역 우주를 설계하고 창조하며 다스린다. 우리 우주 네바돈의 창조자는 미가엘이며, 그는 일곱 번 자기 창조체의 모습으로 증여하여 체험으로 주권을 얻었고, 그 마지막 증여가 유란시아에서 나사렛 예수로 산 생애였다. 그는 우리에게 사실상 하나님이며, 아버지를 계시하는 길이다.","sections":[{"h":"기원과 본성","items":[{"x":"창조자 아들은 아버지의 절대 인격 개념과 영원 아들의 절대 영적 관념이 완전히 연합할 때 섬광처럼 태어나는 이중 기원의 존재이다.","r":["21:0.1","21:1.1"]},{"q":"그러나 각 창조자 아들은 다른 모든 아들과 다르다.","r":"21:0.1"},{"x":"네바돈의 미가엘은 무한한 정체성에 대한 611,121번째 본래 개념의 인격화이며, 영원 아들을 더 닮은 특징을 보인다.","r":["33:1.1","33:2.1"]},{"x":"미가엘은 파라다이스 삼위일체의 구성원은 아니지만, 자기 우주에서 영원 아들이 현존한다면 가질 모든 신성한 속성과 권능을 지닌다.","r":["33:1.2","33:1.3"]},{"q":"우리 우주와 그 모든 거주 세계에게 주권 아들은 사실상 모든 면에서 하나님이다.","r":"33:1.4"}]},{"h":"지역 우주의 창조자","items":[{"x":"창조자 아들은 공간 위치를 고르기 전, 같은 초우주에서 앞선 형제들이 세운 창조계를 오래 관찰하며 배운다.","r":["21:2.1"]},{"x":"파라다이스를 떠날 때 무한 영의 창조적 딸이 동반하며, 그녀는 훗날 지역 우주 어머니 영으로 인격화된다.","r":["21:2.2","21:2.9"]},{"x":"에너지-물질의 새 변형에는 무한 영의, 새 창조체 설계에는 영원 아들의 동의가 필요하며, 인격은 오직 아버지가 수여한다.","r":["21:2.4","21:2.5","21:2.6"]},{"x":"창조자가 서로 다르기에 그가 설계한 지역 우주의 생명 형태도 저마다 독창적이다.","r":["21:2.10"]},{"x":"미가엘이 자리를 비울 때는 찬란한 새벽별 가브리엘이 우주를 지휘하고, 어머니 영이 그의 영적 현존을 대신 감독한다.","r":["21:2.11","33:2.5"]}]},{"h":"일곱 증여와 주권","items":[{"x":"창조자 아들은 처음부터 주권을 주장할 수 있었지만, 일곱 증여를 마치기 전에는 최상 주권을 차지하지 않겠다고 삼위일체에 맹세한다.","r":["21:3.2","21:3.12"]},{"q":"그러나 그들 모두 그렇게 할 수도 있었으니, 그들은 참으로 자유 의지를 지닌 아들들이다.","r":"21:3.3"},{"x":"일곱 증여에서 그는 일곱 창조체 수준을 꿰뚫고, 일곱 주(主) 영에 인격화된 신의 칠중 뜻을 하나씩 드러낸다.","r":["21:3.17","21:3.18","119:8.4"]},{"q":"이 신성한 아들들은 본래 공정하지만, 이러한 연속적인 증여 체험의 결과로 이해심 있는 자비를 얻게 된다.","r":"119:0.4"},{"x":"증여를 마친 창조자 아들은 칠중 주(主) 아들이 되며, 창조체의 체험이 그의 본성에 더해져 영구한 변화가 일어난다.","r":["21:4.6"]},{"q":"미가엘은 창조자로 태어났고, 행정가로 교육받았으며, 집행자로 훈련되었지만, 체험을 통해 자신의 주권을 획득해야 했다.","r":"119:8.2"}]},{"h":"유란시아 증여","items":[{"x":"미가엘은 여섯 번의 증여 뒤, 의지 창조체 가운데 가장 낮은 필사 육신의 모습으로 유란시아에 내려왔다.","r":["120:0.2"]},{"x":"마지막 증여는 주권을 얻는 일을 넘어, 우주 아버지의 뜻에 자신을 종속시키는 최상위 계시의 계획이었다.","r":["120:0.7","120:0.8"]},{"q":"예수는 항상, 그리고 영원히 하나님이자 사람이었다.","r":"120:4.3"},{"q":"미가엘 증여의 최상의 영적 목적이 하나님의 계시를 높이는 것이었다는 사실을 결코 잊지 말라.","r":"120:4.4"},{"x":"유란시아에서의 죽음으로 증여 생애가 완성되었기에 그는 참으로 “다 이루었다”고 말할 수 있었다.","r":["21:4.5"]},{"x":"그래서 이 작은 행성은 주권자 그리스도 미가엘의 필사 고향이 되어 온 네바돈의 감성적 성소가 되었다.","r":["119:8.8"]}]},{"h":"주(主) 아들의 통치와 운명","items":[{"x":"유란시아 증여 뒤 미가엘은 옛적부터 늘 계신 이들과 우주 아버지에게서 네바돈의 확고한 주권자로 인정받았다.","r":["119:8.1"]},{"x":"어머니 영이 그에게 자신을 종속시키자, 미가엘은 하늘과 땅의 모든 권능을 지닌 신성의 인격적 저장소가 되었다.","r":["33:2.3","33:2.4"]},{"x":"주(主) 아들은 진리의 영을 “모든 육신 위에” 부어 자신이 머문 세계들과 끊임없이 교통한다.","r":["21:5.10"]},{"x":"일곱 증여의 총합은 최상 존재에 대한 새로운 네바돈 계시이며, 진화하는 최상 하나님의 주권도 증강시켰다.","r":["119:8.3","119:8.5"]},{"x":"미가엘들은 영원 안에서 글자 그대로 “길이요, 진리요, 생명”이 되도록 정해져 있다고 여겨진다.","r":["21:6.4"]}]}],"see":["지역 우주 어머니 영","지역 우주 네바돈","진리의 영","아보날 아들","최상 존재","옛적부터 늘 계신 이"],"n":22,"en":"Creator Son Michael"},{"t":"천사 무리","sum":"천사 무리는 무한 영에게서 비롯된 봉사 영들로, 중앙 우주의 수퍼나핌, 초우주의 세코나핌, 지역 우주의 세라핌과 체루빔·사노빔으로 이루어진다. 이들은 육체는 없지만 분명한 개별 인격을 지니며, 진화하는 의지 창조체들의 동료로서 사람의 일상과 죽음과 부활에 이르기까지 사역한다. 천사들은 사람의 의지를 결코 침범하지 않으면서, 사랑과 공감으로 필사자의 상승 여정을 돕는다.","sections":[{"h":"시간의 봉사 영들","items":[{"x":"무한 영의 인격에는 시간의 봉사 영인 천사, 공간의 사자 무리, 그리고 더 높은 영들의 세 계층이 있다.","r":["38:0.1"]},{"x":"중앙 우주에는 수퍼나핌이, 초우주에는 세코나핌이, 지역 우주에는 세라핌과 체루빔·사노빔이 천사 군단을 이룬다.","r":["38:0.2","28:0.1"]},{"x":"천사들은 진화하고 상승하는 의지 창조체의 동료이자 신성한 인격들의 협력자이며, 모두 고도로 개인화된 독특한 인격이다.","r":["26:1.1"]},{"x":"이 계시에서 ‘천사’라는 말은 주로 필사자 생존 계획에 관여하는 우주 어머니 영의 세라핌 자손을 가리킨다.","r":["38:3.1"]}]},{"h":"세라핌의 기원과 본성","items":[{"x":"세라핌은 우주 어머니 영이 한 번에 41,472씩 투사하여 창조하며, 네바돈이 아직 만들어지는 중이므로 지금도 창조되고 있다.","r":["38:1.1","38:1.3"]},{"q":"천사는 물질적 육체를 지니지 않지만, 분명하고 개별적인 존재이며, 영의 본성과 기원을 지닌다.","r":"38:2.1"},{"x":"천사는 사람에게 보이지 않지만, 육신 안의 우리를 그대로 지각하고 인간의 감정을 이해한다.","r":["38:2.1"]},{"x":"세라핌은 애정 깊고 동정심 많지만 성 감정의 창조체가 아니며, 맨션 세계에서 우리가 될 모습과 매우 닮았다.","r":["38:2.2"]},{"x":"무한 영은 균일하게 완전한 세라핌을 만들려 하지만, 그 자손은 알 수 없는 이유로 매우 다양하다.","r":["39:0.1"]},{"q":"세라핌은 지금도 주기적으로 창조되고 있다.","r":"38:1.3"}]},{"h":"천사의 계층","items":[{"x":"지역 우주의 세라핌은 최상·우수·감독·행정 세라핌, 행성 조력자, 전환 사역자, 미래의 세라핌이라는 일곱 계층으로 나뉜다.","r":["39:0.2","39:0.8"]},{"x":"어느 세라핌이 다른 집단보다 열등하다고 말하기는 어렵고, 높은 계층일수록 낮은 봉사에 배정되기를 더 원한다.","r":["39:0.9","39:0.11"]},{"x":"체루빔과 사노빔은 세라핌과 기원이 같은 가장 낮은 천사 계층으로, 다정하고 거의 인간과 같아 세라핌을 충직하게 돕는다.","r":["38:7.1","38:7.3"]},{"x":"체루빔은 양성의 선임 인격이고 사노빔은 음성의 보완 인격이며, 둘은 기능적으로 하나로 결합되어 있다.","r":["38:7.2"]},{"x":"세라핌은 저녁별로 높여지거나, 전문 봉사의 완성 등 여러 길로 파라다이스에 이를 수 있다.","r":["39:8.1","39:8.3"]}]},{"h":"사람 곁의 천사","items":[{"q":"수호 천사에 관한 가르침은 신화가 아니다.","r":"113:1.1"},{"x":"미가엘의 증여 이후 세라핌은 인종이 아니라 사람의 지성과 영성과 운명에 따라 배정된다.","r":["113:1.2"]},{"q":"천사들은 인간 마음의 성역을 침범하지 않으며, 필사자의 의지를 조작하지도 않고, 내주하는 조절자와 직접 접촉하지도 않는다.","r":"113:5.1"},{"x":"천사들은 우리 곁에 아주 가까이 있어 진심으로 돌보며, 물리적 눈물은 없지만 영적 감정을 지니고 있다.","r":["113:5.2"]},{"x":"세라핌은 우리의 요청이나 변덕과 상관없이 상관의 명령에 따라 우리를 위해 일한다.","r":["113:5.3"]}]},{"h":"죽음과 부활의 안내자","items":[{"x":"예수는 회개하는 한 죄인을 두고 하늘의 천사들 앞에 기쁨이 있다고 말했다.","r":["167:7.5"]},{"q":"천사들은 육신의 죽음과 영의 거처에서 누리는 새 생명 사이에 놓인, 그 미지의 불확정한 기간 동안 사람의 혼을 인도하는 확실한 하늘의 안내자들이다.","r":"167:7.6"},{"x":"맨션 세계에서 처음 깨어날 때, 우리는 지상에서 늘 곁에 있던 천사 동반자들을 실제로 처음 보게 된다.","r":["113:7.1"]},{"x":"모론시아 구체에서 두 수행 세라핌은 공개된 동반자로서 우리의 진보를 도우며 그들 자신도 배우며 자란다.","r":["113:7.2"]}]},{"h":"행성을 다스리는 세라핌","items":[{"q":"지고자들은 여러 천상의 세력과 매개체들을 통해 사람의 왕국을 다스리지만, 주로 세라핌의 사역을 통해 통치한다.","r":"114:0.1"},{"x":"어느 날 정오의 점호에서 유란시아의 행성 천사와 수호자는 5억 쌍이 넘는 세라핌으로 집계되었다.","r":["114:0.2"]},{"x":"진리의 영이 부어질 때 첫 상주 총독과 함께 행성 감독의 주 세라핌 열두 군단이 유란시아에 왔다.","r":["114:6.1","114:6.2"]},{"x":"한 세계가 다른 세계들과 접촉을 유지할 수 있는 것은 천사들의 사역 덕분이다.","r":["167:7.4"]}]}],"see":["세라핌","수호 세라핌","무한 영","지역 우주 어머니 영","맨션 세계","중도자"],"n":96,"en":"Angelic Hosts"},{"t":"철학","sum":"철학은 과학이 밝힌 사실과 종교가 체험한 가치를 하나의 일관된 우주관으로 엮으려는 인간 마음의 노력이며, 지혜의 영역이다. 그 기초는 물질적 사실에 두되 그 혼과 에너지는 영적 통찰에서 나온다. 사람이 이를 수 있는 가장 높은 철학은 과학의 이성, 종교의 신앙, 계시의 진리 통찰 위에 서며, 철학의 탐구는 파라다이스에 이르러서도 끝나지 않는다.","sections":[{"h":"통일을 찾는 지혜","items":[{"q":"철학은 인간 체험에서 통일성을 가장 잘 찾아내는 수단이다.","r":"102:2.6"},{"x":"철학적 사고의 기초는 물질적 사실에 두어야 하지만, 그 혼과 에너지는 필사자의 영적 통찰이다.","r":["102:2.6"]},{"x":"철학은 과학과 종교가 각각 발견한 것을 우주에 대한 합리적이고 통일된 태도로 조직하려는 노력에서 생겨났다.","r":["103:6.9"]},{"x":"과학은 지식의 영역, 종교는 신앙 체험의 영역이며, 철학은 지혜의 영역이다.","r":["101:5.2"]},{"x":"과학은 제1원인에, 종교는 최상 인격에, 철학은 통일성에 만족한다.","r":["102:3.15"]},{"q":"철학은 인간 체험을 통합하려는 인간의 시도이다.","r":"196:3.30"}]},{"h":"철학의 자리와 한계","items":[{"x":"과학에서 자아는 물질 세계를 관찰하고, 철학은 그 관찰을 관찰하며, 종교는 그 모두를 관찰하는 실체를 체험한다.","r":["112:2.12"]},{"q":"철학은 필연적으로 초과학적이다.","r":"195:7.9"},{"x":"철학이 물질에 기울면 자연주의가, 영에 치우치면 신비주의가, 형이상학에 기대면 회의와 혼란이 된다.","r":["103:6.14"]},{"x":"철학은 실체를 직선적 논리로만 투사하지 말고, 실체의 타원적 대칭과 관계 개념의 곡률을 고려해야 한다.","r":["103:6.14"]},{"x":"과학과 종교 모두에 유익한 철학은 유물론과 범신론의 극단을 피하고, 변화 속의 영속인 인격의 실체를 인정한다.","r":["103:8.6"]}]},{"h":"가장 높은 철학","items":[{"q":"필사자가 도달할 수 있는 가장 높은 철학은 과학의 이성, 종교의 신앙, 그리고 계시가 제공하는 진리의 통찰에 논리적으로 기초해야 한다.","r":"103:6.15"},{"x":"계시로 명확해진 철학은 모론시아 모타가 없고 형이상학이 실패한 가운데서도 충분히 기능할 수 있다.","r":["103:6.9","103:8.6"]},{"x":"참된 철학은 과학의 양적 관찰과 종교의 질적 관찰을 연결하려는 지혜에서 자란다.","r":["133:5.4"]},{"x":"모론시아 모타의 낮은 평면은 인간 철학의 가장 높은 수준과 직접 이어진다.","r":["48:7.1"]},{"x":"이상적인 인간 상태는 지혜·신앙·체험이 함께 작용해 철학과 종교와 과학이 의미 있게 하나로 융합되는 것이다.","r":["98:2.12"]}]},{"h":"종교 철학의 형성","items":[{"x":"개인의 종교 철학은 내적 체험과 환경, 기질, 교육, 사회적 조건 등 여러 요인에서 형성된다.","r":["101:7.1"]},{"q":"도덕적 겁쟁이는 높은 수준의 철학적 사고에 도달할 수 없다.","r":"101:7.2"},{"x":"종교 철학은 전통에 순응하는 단계부터 두려움 없이 진실하게 생각하고 사는 단계까지 네 수준으로 진화한다.","r":["101:7.4"]},{"x":"건전한 종교 철학은 물질과 영의 실체를 구별하면서도 지적 탐구와 사회 봉사 속에서 그 통일을 인식한다.","r":["101:7.5"]},{"x":"효과적인 삶의 철학은 우주적 통찰과 환경에 대한 감정적 반응을 하나로 엮는다.","r":["140:4.8"]}]},{"h":"역사 속의 철학과 영원한 탐구","items":[{"q":"그리스에서는 믿음이 사고에 종속되었고, 팔레스타인에서는 사고가 믿음에 종속되었다.","r":"98:2.8"},{"x":"그리스 철학자들은 높은 윤리 체계를 이루었지만 신 개념이 범신론적 안개로 흩어져 대중의 구원 갈망을 채우지 못했다.","r":["98:2.9","98:2.10"]},{"x":"종교는 철학 없이도 오래 지속되었지만, 종교와 아무 연관 없는 철학이 오래 지속된 경우는 거의 없었다.","r":["98:2.12"]},{"x":"파라다이스에서도 철학이 풀어야 할 신비는 끝없이 남으며, 철학의 고양감은 예배 다음가는 만족이다.","r":["27:6.1"]},{"x":"파라다이스의 철학의 대가들은 상승자들을 우주 문제를 푸는 신나는 탐구로 이끄는 것을 기뻐한다.","r":["27:6.2","27:6.5"]}]}],"see":["지혜","과학과 종교","계시","진리","실체","모론시아"],"n":74,"en":"Philosophy"},{"t":"체험","sum":"유란시아서에서 체험은 진화 우주가 살아가는 방식이자 성장의 원천이다. 파라다이스와 하보나는 존재적으로 완전하지만, 시간과 공간의 창조체와 최상 존재는 체험을 통해 완전해진다. 창조자 아들조차 체험으로 주권을 얻었고, 조절자도 사람과 함께 체험을 쌓는다. 무엇보다 하나님을 아는 개인적 종교 체험은 신학과 철학이 흔들려도 진실하고 유효하며, 사람을 바꾸고 섬김으로 이끈다.","sections":[{"h":"체험이란 무엇인가","items":[{"q":"그것은 활동적이고 질문하는 자아와 다른 어떤 활동적인 외부 실체 사이의 상호작용일 뿐이다.","r":"102:4.2"},{"x":"체험의 질량은 개념의 깊이와 외부 실체에 대한 인식의 총체가 정하고, 그 사실은 다른 사물·마음·영의 존재 속에서 발견된다.","r":["102:4.2"]},{"x":"사람은 마음에서 물질을, 혼에서 영적 실체를 체험하지만, 그 체험을 의식하는 것은 마음이다.","r":["103:6.6"]},{"q":"체험 없이는 진화 창조체 자체가 존재할 수 없다.","r":"106:9.2"}]},{"h":"존재적 완전과 체험적 완전","items":[{"x":"파라다이스 신은 존재적이지만, 출현하는 최상 존재와 궁극 존재는 체험적이다.","r":["0:4.9"]},{"x":"아버지는 아들과 영 안에서 존재적 표현을 이루었고, 이제 최상·궁극·절대 하나님으로서 체험적 표현을 이루어 가고 있다.","r":["0:7.6"]},{"x":"시간의 창조체들의 완전함은 은혜가 섞여 있어도 개인적 노력과 실제 삶을 통해 얻은 참된 인격적 소유이다.","r":["32:3.9"]},{"x":"진화 인격의 체험적 본성은 파라다이스-하보나 창조체들의 늘 완전한 본성을 보완하는 자연스러운 짝이다.","r":["32:3.12"]},{"x":"모든 진화하는 창조체 인격의 체험은 전능 최상위의 체험의 한 국면이다.","r":["116:1.1"]}]},{"h":"밑바닥에서 시작하는 행운","items":[{"x":"동물적 진화 기원은 어떤 인격에도 오점이 아니며, 맨 밑에서 생명의 사다리를 오른 이들에게 더 큰 영예가 있다.","r":["32:3.10"]},{"x":"아버지가 모든 필사자를 처음부터 완전하게 만드는 것도 쉬웠겠지만, 그러면 길고 점진적인 상승의 모험과 훈련을 빼앗게 될 것이다.","r":["32:3.11"]},{"q":"그것은 살아 있는 실존의 맨 밑바닥에서 시작하는 행운을 얻은 이들만 가질 수 있는 체험이다.","r":"32:3.11"},{"x":"필사자의 생애, 곧 혼의 진화는 시험 기간이라기보다 교육의 과정이다.","r":["111:3.5"]}]},{"h":"신성한 존재들의 체험","items":[{"x":"미가엘은 창조자로 태어났지만, 주권만은 일곱 증여의 체험을 통해 얻어야 했다.","r":["119:8.2"]},{"x":"예수가 겪은 모든 인간 체험은 우주 주권자의 영원한 소유가 되어, 그는 체험 많은 주권자가 되었다.","r":["127:6.13"]},{"x":"처녀 조절자들도 필사 창조체가 성장하는 동안 체험을 쌓아야 하며, 다음 생명 단계의 기술을 미리 연습한다.","r":["109:0.1"]},{"x":"인격화된 조절자는 여러 필사 마음에 내주하며 얻은 모든 체험을 영원한 부여물로 소유한다.","r":["109:6.2"]}]},{"h":"종교 체험","items":[{"q":"종교적 체험은 하나님을 발견했다는 의식의 실현이다.","r":"102:3.4"},{"q":"너희를 하나님께로 이끄는 것은 너희의 느낌이 아니라 너희의 생각이다.","r":"101:1.3"},{"x":"종교는 느낌을 동반할 수는 있으나 느낌 자체의 체험은 아니며, 신비 체험을 유발하는 조건들은 오히려 그 위험을 보여 준다.","r":["101:5.9","100:5.10"]},{"x":"신학과 철학이 왜곡되어도, 개인 종교의 영적 체험은 여전히 진실하고 유효하다.","r":["103:9.1"]},{"x":"하나님 의식의 체험은 세대마다 같지만, 하나님에 대한 철학적 개념과 신학적 정의는 지식과 함께 변해야 한다.","r":["5:5.12"]},{"x":"종교 체험은 하나님에 대한 확실한 의식과 인격 생존에 대한 의심 없는 확신으로 귀결된다.","r":["101:1.6"]}]},{"h":"체험의 열매","items":[{"q":"역동적인 종교 생활의 체험은 평범한 개인을 이상주의적인 권능의 인격으로 변모시킨다.","r":"100:0.1"},{"x":"하나님을 발견한 이는 넘치는 선함으로 동료를 섬기도록 이끌리니, 참된 종교는 더 많은 사회봉사로 이어진다.","r":["102:3.4"]},{"x":"감각은 사물의 존재를, 마음은 의미를 알려 주지만, 영적 체험은 삶의 참된 가치를 드러낸다.","r":["100:4.4"]},{"x":"신앙은 언제나 의심을 이기니, 체험은 이론보다, 영적 실체는 고립된 사실보다 우위에 있다.","r":["102:6.7"]},{"x":"조절자는 우주 생애에 필요한 기억과 체험만을 되살려 주며, 영적 의미가 없는 많은 기억은 뇌와 함께 사라진다.","r":["112:5.22"]}]}],"see":["종교 체험","최상 존재","성장","실체","신앙","완전을 향한 여정"],"n":99,"en":"Experience"},{"t":"최상 존재","sum":"최상 존재는 시간과 공간 속에서 진화하는 체험적 신이다. 그는 파라다이스 삼위일체에서 영 인격을 얻고 칠중 하나님의 첫 세 수준에서 전능 권능을 얻으며, 이 둘이 최상 마음 안에서 통일되어 간다. 그는 대우주의 대혼이요 유한 실체의 총합으로서 모든 창조체와 창조주의 체험이 그 안에 등록되며, 사람이 하나님의 뜻을 행할 때마다 한 걸음 더 실제화된다.","sections":[{"h":"진화하는 체험적 신","items":[{"x":"아버지·아들·영은 존재적 신이지만, 최상·궁극·절대 하나님은 하보나 이후 우주의 진화 속에서 현실화하고 있는 체험적 신이다.","r":["0:7.1","0:7.5"]},{"q":"하나님 아버지와의 관계에서는 아들됨이 위대한 관계이다. 최상 하나님과의 관계에서는 성취가 지위의 필수 조건이 된다.","r":"115:0.1"},{"x":"하보나는 성장하지 않고 그저 있을 뿐이지만, 성장은 대우주의 특징이며 체험적 신의 표식이다.","r":["116:0.3"]},{"x":"최상 존재는 중앙 우주에서는 영 인격으로, 대우주에서는 전능 하나님, 곧 권능의 인격으로 기능한다.","r":["116:0.5"]},{"x":"최상위의 운명은 완전성이지만, 그의 현재 체험에는 성장과 미완성의 요소가 들어 있다.","r":["116:0.4"]}]},{"h":"근원: 삼위일체와 칠중 하나님","items":[{"x":"최상위의 영 인격은 파라다이스 삼위일체에서 나오고, 그의 성장은 실제성과 잠재성의 두 삼극일체에서 비롯된다.","r":["115:4.2","115:4.7"]},{"x":"전능자의 권능은 칠중 하나님의 신성 성공에 근거하며, 공동 행위자가 최상위의 마음을 부여하여 권능과 영 인격을 결합한다.","r":["115:4.7"]},{"x":"최상 존재는 자신의 인격적·영적 본성의 실체를 위해 파라다이스 삼위일체에 절대적으로 의존한다.","r":["115:5.1"]},{"x":"최상 하나님은 창조자들에 의해 진화되고 삼위일체에서 파생될 뿐 아니라, 자신의 실제화에 스스로 참여하는 의지적 존재이기도 하다.","r":["117:3.7"]},{"q":"삼위일체가 최상 하나님에게 하는 역할은 조절자가 진화하는 인간에게 하는 역할과 같다.","r":"117:3.10"}]},{"h":"대우주의 대혼","items":[{"q":"최상위는 물리적 조화의 아름다움, 지성적 의미의 진리, 그리고 영적 가치의 선함이다.","r":"117:1.1"},{"x":"최상 존재 안에서 창조주와 창조체는 하나의 신으로 통일되며, 그 의지는 창조주나 창조체 어느 한쪽의 의지보다 더 큰 무엇이다.","r":["117:1.5"]},{"x":"그는 하나님을 계시하며 내려오는 창조자들과 하나님을 찾아 오르는 창조체들의 체험을 유한하게 종합한 존재이다.","r":["117:1.2"]},{"x":"생존하지 않은 자의 인격은 창조계의 대혼 속으로 흡수되어, 물방울이 바다로 돌아가듯 최상위에게 되돌아간다.","r":["117:4.2","117:4.4"]},{"x":"인간은 최상위와 통일되어도 인격적 정체성을 잃지 않으며, 그의 모든 체험이 남긴 반향이 최상위 체험의 일부가 된다.","r":["117:5.5"]},{"x":"대우주는 지성 회로와 에너지 통로로 관통된, 웅장하게 반응하는 살아 있는 유기체이다.","r":["116:7.1"]}]},{"h":"인간과 최상위의 상호 의존","items":[{"x":"우리가 어디에서든 하나님의 뜻을 행하는 만큼, 최상위의 전능 잠재성은 한 단계 더 실제화된다.","r":["117:0.1"]},{"x":"창조체는 최상위 없이 진화할 수 없고, 최상위의 진화도 모든 창조체의 완전한 진화 없이는 완성될 수 없다.","r":["117:4.9"]},{"x":"인간과 최상위의 이 관계가 체험적 신에 대한 체험적 의무를 인식하는 우주적 도덕성의 기초이다.","r":["117:4.8"]},{"q":"하나님은 매우 신뢰하시고 매우 사랑하시기 때문에, 자신의 신성한 본성의 일부를 인간의 손에 맡기시고 그것이 안전하게 보존되고 스스로 실현되도록 허락하신다.","r":"117:4.3"},{"x":"우리가 아버지를 찾을 때, 최상위도 우리 안에서 우리와 함께 만물의 파라다이스 창조주를 찾는다.","r":["117:4.6"]}]},{"h":"최상위를 찾는 길","items":[{"x":"하나님이 신성한 아버지이듯 최상위는 신성한 어머니이며, 우리는 우주 생애 내내 그 안에서 양육된다.","r":["117:6.2"]},{"q":"인간은 자신의 마음속에서 아버지를 발견할 수 있지만, 그는 다른 모든 사람들의 마음속에서 최상위를 찾아야 할 것이다.","r":"117:6.23"},{"x":"아버지는 각 개인이 발견할 수 있지만, 최상위는 모든 창조체가 우주적 성숙에 이르러 함께 발견할 먼 미래까지 개인적으로 발견되지 않는다.","r":["117:6.16","117:6.21"]},{"x":"아버지의 사랑은 동료에게 베풀 때에만 실제가 되며, 그렇게 흘러가는 형제적 애정이 최상위의 사랑의 본질이다.","r":["117:6.10"]},{"x":"사람은 지진처럼 갑자기가 아니라, 강물이 땅을 닳게 하듯 천천히 인내하며 최상위를 발견한다.","r":["117:6.25"]},{"q":"최상위보다 더 많이 이해하는 것은 유한 이상이 되는 것이다!","r":"117:6.19"},{"x":"하나님을 아는 필사자는 결코 외롭지 않다. 아버지가 모든 길을 동행하시며, 그가 걷는 길 자체가 최상위의 현존이다.","r":["117:6.27"]}]},{"h":"최상위의 미래","items":[{"x":"대우주가 빛과 생명 속에 정착하면 영 인격과 전능 권능이 최상 마음 안에서 통일되어, 최상 존재가 완성된 실제성으로 사실화될 것이다.","r":["117:0.2","117:7.14"]},{"x":"그때 최상위는 대우주의 실제 주권자가 되고, 일곱 초우주 사이의 구분은 점차 사라질 것으로 믿어진다.","r":["117:7.15"]},{"x":"완성된 우주의 시민들에게는 다시 궁극 하나님을 탐구하는 새로운 도전이 주어질 것이다.","r":["117:7.17"]}]}],"see":["칠중 하나님","파라다이스 삼위일체","궁극 하나님","하나님의 뜻","빛과 생명","진화"],"n":8,"en":"Supreme Being"},{"t":"최종자 군단","sum":"최종자 군단은 시간의 상승 필사자들이 하나님을 찾고 파라다이스에 이른 뒤 편입되는, 현재 알려진 그들의 목적지이다. 영화롭게 된 필사자를 중심으로 하보나 원주민, 중력 사자, 입양된 세라핌, 물질 아들, 중도 창조체가 함께하며, 지금은 빛과 생명에 정착한 세계들에서 봉사한다. 그들의 궁극적 운명은 계시되지 않았지만, 바깥 공간의 미래 우주들과 관련되리라고 추측된다.","sections":[{"h":"군단의 구성","items":[{"x":"1차 최종자 군단은 하보나 원주민, 중력 사자, 영화롭게 된 필사자, 입양된 세라핌, 영화롭게 된 물질 아들과 중도 창조체로 이루어진다.","r":["31:0.1","31:0.8"]},{"x":"군단은 천 명 단위 중대로 조직되며, 필사자와 세라핌이 990을 차지하고 나머지 존재들을 위한 자리는 열뿐이다.","r":["31:1.3","31:3.1"]},{"x":"모두가 평등하게 받아들여지지만 그 평등이 개체성과 인격적 정체성을 지우지는 않는다.","r":["31:0.9"]},{"x":"중력 사자는 인격화된 조절자로서 시간과 공간을 초월하며, 조절자와 융합한 필사자와 깊은 애정을 나눈다.","r":["31:2.2","31:2.4"]},{"q":"그들은 참으로 시간과 공간에서 시험받고 참됨이 입증되어 쌓여 가는 혼들, 곧 우주의 진화적 소금이며, 영원히 악에 굴하지 않고 죄로부터 안전하다.","r":"31:0.13"},{"x":"빛의 전도자들은 서약 없이 일시적으로 배속되며, 999 영구 단원 외의 한 빈자리는 아직 신비로 남아 있다.","r":["31:7.1","31:7.2"]}]},{"h":"누가 들어가는가","items":[{"x":"대우주의 창조체 가운데 아버지와 융합한 이들만 필사 최종자 군단에 편입되고 최종자 서약을 한다.","r":["30:4.31"]},{"x":"영 융합 필사자들은 대개 지역 우주 봉사에 머물며 파라다이스 최종자 군단의 운명을 함께하지 않는다.","r":["40:9.9"]},{"x":"많은 수호 세라핌이 맡은 필사자와 함께 상승하여 그들과 똑같이 최종자 서약을 하고 군단에 편입된다.","r":["31:4.1","40:1.1"]},{"x":"필사 생애의 체험을 빼앗긴 채 일찍 죽은 아이들은 파라다이스 시민이 되지만 최종자 군단에는 들지 않는다.","r":["47:2.8"]},{"q":"그리고 하나님을 아는 모든 필사자는 최종자가 되기를 갈망한다.","r":"14:6.39"}]},{"h":"파라다이스에 이르는 길","items":[{"x":"필사자는 영의 단계를 차례로 오르다가 최종성 군단의 서약을 할 때 여섯째 단계의 영이 된다.","r":["31:3.4"]},{"x":"일곱째 희년 축제는 필사 최종자 군단에 들어감과 영원한 봉사의 시작을 기념한다.","r":["27:7.8"]},{"x":"최종자 영접 원에서 초월자들의 우두머리가 영원의 삼위일체 서약을 집행한다.","r":["31:8.4"]},{"q":"진화 필사자들은 공간의 행성들에서 태어나, 모론시아 세계들을 거치고, 영 우주들을 오르고, 하보나 구체들을 건너고, 하나님을 찾고, 파라다이스에 이르러 1차 최종자 군단에 편입되며, 그곳에서 다음 우주 봉사 임무를 기다린다.","r":"31:10.20"}]},{"h":"지금의 봉사와 조직","items":[{"x":"최종자들은 다른 여섯 초우주에서 봉사하기 전에는 태어난 초우주에 배정되지 않아 최상 존재의 칠중 개념을 얻는다.","r":["31:0.10"]},{"q":"필사 최종자들의 한 중대 이상이 늘 유란시아에서 봉사하고 있다.","r":"31:0.11"},{"x":"최종자들은 지도자를 스스로 뽑는 자치 단체이며, 그들의 충성 서약은 오직 파라다이스 삼위일체에게 바쳐진다.","r":["31:0.12"]},{"x":"사타니아의 첫째 전환 세계는 십만이 넘는 최종자 중대의 본부이며, 최종자들은 참된 영 시각을 얻기 전에는 보이지 않는다.","r":["47:0.2","47:1.3"]},{"x":"필사 최종자 군단은 빛과 생명에 정착한 세계들에서 여러 역할로 봉사하지만 아직 확정된 직무는 없는 것 같다.","r":["30:4.32"]}]},{"h":"아직 끝나지 않은 운명","items":[{"x":"최종자들은 창조체 완전함의 현재 한계에는 이르렀으나 궁극적 영 지위와 창조체 봉사의 최종성에는 아직 이르지 않았다.","r":["31:3.6"]},{"q":"신들은 왜 생존한 필사자들을 우주 경영의 기법으로 그토록 철저히 훈련시키는 데 그토록 관심을 두시는가?","r":"31:3.8"},{"x":"예루셈의 최종자 원주 구역에는 ‘영의 일곱째 단계에 아직 봉헌되지 않음’이라 새겨진 봉인된 빈 사원이 있다.","r":["46:5.32"]},{"x":"아버지를 찾은 최종자들은 언젠가 초(超)유한 아버지를 향한 새로운 탐구를 시작해야 할 것이다.","r":["10:8.7"]}]},{"h":"바깥 공간을 향한 전망","items":[{"x":"일곱 최종성 군단은 선임 주(主) 건축가의 감독을 받으며, 그랜드판다가 최상 운명 평의회의 우두머리이다.","r":["31:10.1","31:10.9"]},{"x":"최상 존재의 진화에 참여하지 못할 바깥 우주들의 체험적 결핍을 최종자들이 보상하리라고 추측된다.","r":["31:10.11","31:10.13"]},{"q":"우리는 조절자 융합 필사자들이 그들의 최종자 동료들과 함께 첫째 외부 공간 수준의 우주들에서 행정적 기능을 수행하게 될 운명이라고 믿는다.","r":"112:7.17"},{"x":"설령 계시되지 않은 미래 운명이 없다 해도, 최종자들의 현재 임무만으로 상승 계획은 온전히 정당화된다.","r":["30:4.33"]}]}],"see":["필사자의 상승 여정","조절자 융합","하보나","파라다이스","최상 존재","완전을 향한 여정"],"n":32,"en":"Corps of the Finality"},{"t":"칠중 하나님","sum":"칠중 하나님은 유한한 창조체가 신에게 다가갈 수 있도록 우주 아버지가 마련한 일곱 단계의 신 연합이다. 지역 우주의 창조자 아들, 옛적부터 늘 계신 이, 일곱 주(主) 영, 최상 존재, 무한 영, 영원 아들, 우주 아버지로 이어지며, 상승하는 필사자는 이 순서로 신을 체험적으로 발견해 나간다. 그 첫 세 수준은 최상 존재가 지니는 전능 권능의 원천이기도 하다.","sections":[{"h":"신에게 다가가는 일곱 단계","items":[{"x":"유한한 지위와 개념의 한계를 보상하기 위해, 우주 아버지는 진화 창조체가 신에게 다가가는 칠중의 접근 방식을 세우셨다.","r":["0:8.1"]},{"x":"일곱 수준은 파라다이스 창조자 아들, 옛적부터 늘 계신 이, 일곱 주(主) 영, 최상 존재, 영 하나님, 아들 하나님, 아버지 하나님이다.","r":["0:8.2","0:8.8"]},{"q":"칠중 하나님은 공간의 진화 우주들에 있는 시간의 장벽을 파라다이스 신이 인식함을 의미한다.","r":"106:1.3"},{"x":"하나님을 발견하는 체험적 생애는 지역 우주 창조자 아들의 신성을 인식하는 데서 시작하여, 옛적부터 늘 계신 이와 주 영을 거쳐 파라다이스 아버지께 이른다.","r":["0:8.9"]},{"x":"칠중 하나님은 파라다이스 상승 생애에 있는 진화 필사자들에게 실제로 기능하는 신이다.","r":["0:8.9"]}]},{"h":"최상 창조자들과 파라다이스 신들","items":[{"x":"일곱 수준 가운데 처음 셋은 최상 창조자들이고 마지막 셋은 파라다이스 신들이며, 최상 존재는 그 사이에서 언제나 개입한다.","r":["116:2.4","116:2.12"]},{"x":"파라다이스 신은 파라다이스 밖의 신성 인격화를 약화하고 한정하여 최상 창조자들을 존재하게 했고, 이들은 생명의 빛을 진화 세계까지 나른다.","r":["116:2.3"]},{"x":"첫 세 수준의 행위를 합한다고 해서 파라다이스 신과 같아지지는 않는다. 그들은 체험적 신의 새로운 권능 잠재성을 이룬다.","r":["116:2.13"]},{"q":"칠중 하나님의 신 연합체 안에서 창조자 아들은 필사자가 불멸이 되고 유한자가 무한자의 품에 안길 방법을 제공한다.","r":"0:8.11"},{"x":"칠중의 신성 사역은 영원 아들을 거쳐 파라다이스 아버지께로 내향하고, 옛적부터 늘 계신 이를 거쳐 창조자 아들들에게로 외향한다.","r":["106:1.3"]}]},{"h":"최상 존재와의 관계","items":[{"x":"최상 하나님은 삼위일체에서 인격과 영 속성을 받지만, 그 권능은 창조자 아들·옛적부터 늘 계신 이·주 영들의 활동 안에서 실제화된다.","r":["0:8.10","116:2.2"]},{"x":"최상 하나님은 칠중 하나님의 첫 세 수준이 조율되어 기능할 때에만 권능의 인격으로 진화 창조체들에게 현시된다.","r":["116:2.14"]},{"q":"최상 존재는 일곱 초우주에 대한, 그리고 현재 우주 시대를 위한 신의 최대 계시이다.","r":"116:2.12"},{"x":"필사자의 체험에서 최상 존재는 칠중 하나님의 통일자이자, 유한 창조체가 실제로 이해할 수 있는 신의 최대치이다.","r":["56:8.1"]},{"x":"칠중 신의 여러 측면은 지금은 다양한 방식으로 통합되어 있지만, 모두 최상위 안에서 통일될 운명이다.","r":["106:1.4"]}]},{"h":"칠중 통제자와 우주적 기능","items":[{"x":"칠중 하나님에는 창조자들뿐 아니라 주 물리적 통제자, 최상 권능 중심, 최상 권능 감독자 등 대우주의 칠중 통제자들도 포함된다.","r":["116:5.1","116:5.9"]},{"x":"일곱 주 영 모임은 칠중 하나님의 광범위한 활동을 조율하는 듯하며, 창조자 아들과 창조 영의 연합이라는 마지막 수준에도 기여한다.","r":["17:8.3","17:8.8"]},{"q":"칠중 하나님의 기능은 일곱 초우주의 조직과 함께 시작되었으며, 아마도 외부 공간 창조계의 미래 진화와 관련하여 확장될 것이다.","r":"0:8.12"},{"q":"절대자들은 궁극자 안에서 조율되고, 최상자 안에서 조건화되며, 칠중 하나님 안에서 시간-공간으로 수정된다.","r":"56:9.1"},{"x":"칠중 하나님의 사역 덕분에 불완전한 존재는 시간 지연 속에서 완전한 것과 이어지고, 자기 진화에서 창조주의 동반자가 된다.","r":["106:1.2"]},{"x":"칠중 하나님의 성취에서 비롯한 권능은 획득되고 증명된 체험적 권능으로, 파라다이스 신들의 존재적 권능과 대조된다.","r":["106:2.3"]}]},{"h":"빛과 생명 속에서 드러남","items":[{"x":"시간과 공간의 진화는 칠중 하나님의 첫째 현시인 창조자 아들과 창조 영의 연합이 주관하는 행성에서 시작되며, 지역 우주가 정착할수록 칠중 하나님이 더 분명히 드러난다.","r":["56:7.2"]},{"x":"창조계가 정착함에 따라 첫 세 현시가 물러나고 최상 하나님의 더 충만한 활동이 나타나지만, 그 뒤의 일은 아직 계시되지 않았다.","r":["56:7.6"]},{"q":"그러나 우리는 시간과 공간의 우주들에서 칠중 하나님이 우주 아버지에게 나아가는 점진적 접근을 제공하며, 이 진화적 접근이 최상 하나님 안에서 체험적으로 통일된다는 것은 알고 있다.","r":"56:7.8"},{"x":"빛과 생명의 세계들은 창조자 아들에 대한 흠모에서 파라다이스 아버지에 대한 예배에 이르기까지 칠중 하나님의 실체를 잇달아 붙든다.","r":["56:10.1"]},{"x":"어느 신 수준에 이르든, 상승자는 매번 새로운 체험 수준에서 모든 인격의 파라다이스 아버지를 다시 발견하게 된다.","r":["56:9.10"]}]}],"see":["최상 존재","창조자 아들 미가엘","옛적부터 늘 계신 이","일곱 주(主) 영","파라다이스 삼위일체","필사자의 상승 여정"],"n":7,"en":"God the Sevenfold"},{"t":"칼리가스티아","sum":"칼리가스티아는 약 오십만 년 전 유란시아에 온 행성 영주로, 풍부한 체험과 빛나는 경력을 지닌 라노난덱 아들이었으나 루시퍼 반란에 가담해 자기에게 맡겨진 세계를 배반했다. 그의 이반으로 유란시아는 우주 회로에서 고립되었고, 행성 참모진 가운데 예순 명이 그를 따랐으며 달라마시아 문화는 무너졌다. 그는 뒤에 아담과 이브를 함정에 빠뜨렸고, 예수가 헤르몬산에서 그를 이긴 뒤에는 사람의 마음을 침범할 힘을 잃었다.","sections":[{"h":"빛나는 행성 영주","items":[{"x":"칼리가스티아는 2차 계층의 라노난덱 아들로, 지역 우주와 사타니아 행정에 체험이 풍부했다.","r":["66:1.1"]},{"x":"루시퍼는 그를 개인 참모로 승격시켰고, 그는 오래전부터 행성 영주 임관을 간절히 구했다.","r":["66:1.2","66:1.3"]},{"x":"그는 충성과 헌신의 기록을 지녔으나, 불안한 기질과 기존 질서에 반대하려는 경향도 있었다.","r":["66:1.4"]},{"q":"오십만 년 전 그 운명적인 날, 어느 행성 영주도 칼리가스티아보다 더 풍부한 준비 체험이나 더 나은 전망을 가지고 세계 통치의 생애에 오른 적이 없었다.","r":"66:1.5"},{"x":"그는 약 오십만 년 전 산긱 인종이 나타날 무렵 도착해 메소포타미아 지역에 본부를 세웠다.","r":["66:0.2"]}]},{"h":"달라마시아와 100인의 참모진","items":[{"x":"동료 보조자 달리가스티아가 참모진의 수장이었고, 예루셈 자원자 가운데 뽑힌 100인이 유형 참모진을 이루었다.","r":["66:2.2","66:2.4"]},{"x":"생명 운반자들은 안돈과 폰타 후손 남녀 백 명의 생명 원형질을 참모진의 물질적 몸에 이식했다.","r":["66:2.6","66:2.7"]},{"x":"참모진의 첫 가르침인 달라마시아 계시는 삼십만 년 넘게 이어지다 분리 이탈로 중단되었다.","r":["92:4.5"]}]},{"h":"배반과 고립","items":[{"x":"통치 삼십만 년째 사탄의 방문 때, 칼리가스티아는 반란이 선포되면 행성을 배반하기로 동의했다.","r":["67:1.1","67:1.2"]},{"q":"그리고 모든 악 중에서도, 신뢰의 배신과 자기를 믿는 친구들에 대한 불충보다 인격을 더 파괴하는 것은 없다.","r":"67:1.3"},{"x":"달리가스티아는 칼리가스티아를 ‘유란시아의 하나님’으로 선포했고, 그 순간 체계 회로가 끊겨 유란시아는 고립되었다.","r":["67:2.3","67:2.4"]},{"x":"반은 이를 행성 반란에 가까운 일로 규정하고 항변했으며, 칠 년 넘는 투쟁 끝에 충성자들의 정당성이 인정되었다.","r":["67:2.2","67:2.6"]},{"x":"참모진 가운데 마흔 명은 반역을 거부했고, 반역한 예순 명은 놋을 지도자로 삼았다가 필사 지위로 떨어졌다.","r":["67:3.2","67:4.2"]}]},{"h":"반란의 결과","items":[{"q":"칼리가스티아는 최대의 지성과 방대한 우주 체험을 가지고 있었지만 길을 잃고 죄를 받아들였다.","r":"67:3.9"},{"x":"지적으로 낮았던 아마돈은 끝까지 충성했으니, 영적 선택에서 지성보다 충성이 중요함을 보여 준다.","r":["67:3.8","67:3.9"]},{"x":"개인과 집단의 자유라는 그의 사상으로 사회를 즉시 재건하려던 계획은 실패해, 세상은 더 깊은 혼란에 빠졌다.","r":["67:5.3"]},{"x":"반란 뒤 백육십이 년 만에 달라마시아는 바다 밑으로 가라앉았다.","r":["67:5.4"]},{"x":"그 뒤 열두 멜기세덱 수탁자가 행성을 관리했고, 반은 세계 곳곳에 문명의 전초기지를 세웠다.","r":["67:6.5","67:6.6"]}]},{"h":"아담의 시대에서 예수의 시대까지","items":[{"x":"칼리가스티아와 달리가스티아는 에덴 동산 준비를 방해했고, 무제한의 자유라는 가르침으로 에덴 주민들을 혼란시켰다.","r":["73:2.5","74:5.6"]},{"q":"칼리가스티아는 아담과 이브를 함정에 빠뜨리는 데는 성공했지만, 그들을 우주 정부에 대한 공개적 반란으로 이끌려는 자기 목적을 달성하지는 못했다.","r":"75:7.7"},{"x":"선의를 지녔던 세라파타티아는 자신이 칼리가스티아와 달리가스티아의 손에 놀아나고 있음을 끝내 알지 못했다.","r":["75:3.6"]},{"x":"예수는 헤르몬산에서 칼리가스티아와 홀로 맞서 이겼고, 그 뒤 칼리가스티아의 이반은 사실상 해결되었다.","r":["134:8.6","134:8.9","136:3.1"]},{"x":"미가엘은 유란시아를 떠나기 전 칼리가스티아와 달리가스티아에게 자비를 베풀었으나, 그들은 그 제안을 거부했다.","r":["53:8.6"]},{"q":"그는 사람들의 마음속으로 침투할 힘이 전무하며, 그들이 진정으로 그의 사악한 현존에 저주받기를 원하지 않는 한 그들의 혼에 근접하여 유혹하거나 타락시킬 수도 없다.","r":"53:8.6"},{"q":"칼리가스티아는 그리스도의 십자가 이후 비교적 무력해졌다.","r":"53:8.9"}]}],"see":["루시퍼 반란","유란시아","아담과 이브","중도자","마키벤타 멜기세덱","문명"],"n":77,"en":"Caligastia"},{"t":"파라다이스","sum":"파라다이스는 우주들의 우주의 영원한 중심이자 아버지·아들·영이 거하시는 영원한 섬이다. 영적 거처이면서 동시에 절대소로 이루어진 물질적 구체로서, 모든 물리적 에너지와 중력의 근원이며 모든 원형의 절대이다. 시간 없이 존재하고 공간에 위치하지 않으며, 하나님을 아는 모든 필사자가 긴 상승 끝에 도달할 운명의 목적지이다.","sections":[{"h":"신의 거처","items":[{"x":"파라다이스는 우주들의 우주의 영원한 중심이며 아버지·아들·영과 그 동격자들이 거하는 곳으로, 주 우주에서 가장 거대한 조직체이다.","r":["11:0.1"]},{"x":"파라다이스는 영적 거처이면서 물질적 구체이기도 하며, 그 기원에 관해서는 아무 기록도 전승도 없이 영원부터 있었다.","r":["11:0.1","11:0.2"]},{"x":"아버지의 인격적 현존은 상부 파라다이스의 중심에 있고, 영원 아들의 현존이 이를 둘러싸며, 무한 영의 영광이 두 분을 감싼다.","r":["11:1.1"]},{"x":"중력선, 영 인력선, 마음 회로, 인격 회로 가운데 무엇을 따라가도 결국 아버지의 중앙 거처에 이르게 된다.","r":["11:1.4"]},{"q":"우주 창조체들의 아주 소수만이 파라다이스에 계신 하나님을 발견하였다는 사실이 그분 존재의 실체 혹은 만물의 중심에 계시는 그분의 영적 인격의 실제성을 결코 부정하지 못한다.","r":"11:1.3"}]},{"h":"영원한 섬의 본성","items":[{"x":"파라다이스는 구형이 아닌 납작한 타원체로, 남북 지름이 동서 지름보다 6분의 1 더 길어 주 우주에서 절대 방향을 정하는 기준이 된다.","r":["11:2.2","11:2.3"]},{"x":"섬은 상부·주변·하부 파라다이스로 나뉘며, 삼위일체는 인격적인 상부 평면을, 무제한 절대자는 비인격적인 하부 평면을 주관하는 듯하다.","r":["11:2.4","11:2.8"]},{"x":"파라다이스는 멜기세덱들이 절대소라 부르는, 우주 어디에도 없는 공간 잠재력의 균일한 조직으로 되어 있다.","r":["11:2.9"]},{"q":"파라다이스는 시간 없이 존재하며, 공간에 위치하지 않는다.","r":"11:2.10"},{"x":"대략 말해 공간은 하부 파라다이스 바로 아래에서, 시간은 상부 파라다이스 바로 위에서 기원하는 듯 보인다.","r":["11:2.11"]}]},{"h":"상부와 주변 파라다이스","items":[{"x":"상부 파라다이스에는 신 현존 지역, 예배와 삼위일체화를 위한 지성소, 거주 구역인 거룩한 지대가 있다.","r":["11:3.1"]},{"x":"거룩한 지대의 일곱 동심원 구역은 ‘아버지의 파라다이스 맨션들’이라 불리며, 둘째 구역은 일곱 초우주에서 온 상승자들을 위해 마련되어 있다.","r":["11:3.3"]},{"x":"상승자들을 위한 거주지는 배정된 거룩한 땅의 1퍼센트에도 못 미쳐, 미래에 올 존재들을 위한 자리도 넉넉히 남아 있다.","r":["11:3.4"]},{"x":"주변 파라다이스는 공간 횡단자들이 착륙하는 곳이며, 지역 우주들을 위한 거대한 역사·예언 전시 지역이 있다.","r":["11:4.1","11:4.3"]},{"q":"너희는 기다려야 하며, 기다리면서 상승해야 한다.","r":"11:4.5"}]},{"h":"하부 파라다이스와 공간","items":[{"x":"모든 물리적 에너지와 우주 힘 회로는 하부 파라다이스에서 기원하며, 그곳에는 인격이 머물지 않는다.","r":["11:5.1"]},{"x":"하부 파라다이스 힘 중심의 안쪽 지대는 거대한 심장처럼 박동하며 물리적 공간의 가장 바깥 경계까지 흐름을 보낸다.","r":["11:5.5"]},{"x":"바깥 지대는 무제한 절대자의 공간 현존의 중앙 초점으로 믿어지며, 그 발산은 십억 년 남짓한 주기로 밖과 안을 번갈아 향한다.","r":["11:5.7","11:5.8"]},{"x":"모든 공간은 교대로 팽창하고 수축하며, 한 번의 팽창-수축 주기는 유란시아 시간으로 이십억 년이 조금 넘는다.","r":["11:6.1","11:6.5"]},{"x":"공간은 파라다이스에 닿지 않으며, 파라다이스는 충만 공간과 비충만 공간 사이 정지 지대의 움직이지 않는 핵이다.","r":["11:7.1","11:7.2"]}]},{"h":"중력과 원형의 절대","items":[{"q":"중력은 파라다이스의 물리적 현존이 발휘하는 전능한 붙들음이다.","r":"11:8.1"},{"x":"절대 중력은 파라다이스 중력이며, 지역적·선형 중력은 물질화된 에너지의 전기적 단계에 속한다.","r":["11:8.3"]},{"x":"파라다이스는 우주들의 우주에 있는 모든 에너지-물질의 절대적 근원이자 영원한 초점이다.","r":["11:8.9"]},{"x":"파라다이스-하보나 체계는 주 우주의 영원한 핵이며, 일곱 초우주와 외부 공간은 모두 그 주위를 정해진 궤도로 공전한다.","r":["12:1.11"]},{"x":"파라다이스는 창조주도 신도 아니다. 그것은 원형들의 절대이며, 하보나는 그 잠재성이 실제로 펼쳐진 모습이다.","r":["11:9.4","11:9.5","0:4.13"]},{"x":"아버지가 영원 아들 안에서 영적 자아를 표현하실 때, 동시에 비인격적 자아의 무한한 잠재력을 파라다이스로 드러내셨다.","r":["11:9.3"]}]},{"h":"운명의 목적지","items":[{"x":"파라다이스는 모든 영 인격에게 시원적 기원의 영역이자 최종 운명의 목표이다.","r":["11:9.1"]},{"x":"파라다이스는 무한의 지리적 중심이지만, 하보나를 포함한 어떤 우주 창조의 일부도 아닌 영원하고 배타적인 실존이다.","r":["11:9.2"]},{"q":"파라다이스는 모든 창조계의 중심, 모든 에너지의 근원, 그리고 모든 인격의 시원적 기원의 장소이다.","r":"11:9.7"},{"x":"하보나 첫째 회로에서 시간의 마지막 잠에 든 순례자는 파라다이스에서 깨어나며, 그때 비로소 참된 파라다이스의 자녀가 된다.","r":["26:11.6"]},{"x":"파라다이스에는 감지할 수 있는 질서와 조화가 우세하며, 행동 지도자들이 새로 도착한 이들을 가르쳐 혼란 없이 지내도록 돕는다.","r":["27:4.2","27:4.3"]},{"x":"하나님의 거처는 모든 우주 본부 세계의 원형이며, 그가 거하시는 중앙 우주는 모든 우주의 이상과 운명의 원형이다.","r":["11:9.6"]},{"q":"아버지의 뜻을 행하는 생애를 받아들인, 하나님을 아는 모든 필사자는 신성 추구와 완전 성취의 길고 긴 파라다이스 여정을 이미 시작한 것이다.","r":"11:9.8"}]}],"see":["하보나","중력","세 절대자","우주 아버지","대우주와 주(主)우주","필사자의 상승 여정"],"n":11,"en":"Paradise"},{"t":"파라다이스 삼위일체","sum":"파라다이스 삼위일체는 아버지·아들·영이라는 동격의 세 인격이 이루는 나눌 수 없는 신의 연합이다. 삼위일체는 그 자체로 인격은 아니지만 참되고 절대적인 실체이며, 세 인격의 속성을 합한 것 이상의 기능을 한다. 우주에서 정의를 집행하고 전체에 대한 상위통제를 행하며, 아버지가 인격 절대주의에서 벗어나 자신을 아낌없이 나누어 주실 수 있게 하는 유일하게 필연적인 우주 사실이다.","sections":[{"h":"유일하게 필연적인 연합","items":[{"x":"삼위일체는 하나님의 무한한 인격적 의지의 표현을 신의 절대성과 연합시켜, 아버지가 인격 절대주의의 한계에서 벗어나게 한다.","r":["10:0.1"]},{"q":"우리는 우주의 일들 가운데 단 하나의 피할 수 없는 필연을 발견할 수 있으며, 그것은 바로 파라다이스 삼위일체이다.","r":"10:0.3"},{"x":"아버지는 위임할 수 있는 모든 권능과 권위를 아들들에게 넘겨주셨다. 신성한 인격은 자기중심적이지 않으며 나누기를 즐긴다.","r":["10:1.2","10:1.3"]},{"x":"아버지는 아들에게 절대 인격을 주심으로써 아들의 아버지가 되셨고, 아버지와 아들은 다시 공동 인격을 무한 영에게 주셨다.","r":["10:1.4","10:2.2"]}]},{"h":"세 인격, 한 신","items":[{"q":"오직 하나의 신이 존재하지만, 신의 확실하고 신성한 세 인격화가 존재한다.","r":"10:3.1"},{"x":"세 분은 각각 기원적이어서 어느 하나도 다른 이의 복제가 아니며, 그러면서도 모두가 연합되어 있다.","r":["10:2.6"]},{"x":"영원 아들만이 아버지에 대한 아들됨과 영에 대한 아버지됨을 함께 체험하여 신성한 인격 관계의 충만함을 안다.","r":["10:2.7"]},{"q":"하나님은 아들을 통해 말씀하시며, 아들과 함께 무한 영을 통해 활동하신다.","r":"10:3.3"},{"x":"아버지됨은 아들됨 없이는 실재하지 않으며, 아버지는 아들과 영 없이 홀로 존재하신 적이 한 번도 없다.","r":["10:3.5"]},{"x":"하보나 바깥에서 아버지는 창조자 아들들, 중력, 아들, 공동 창조자, 인격 회로, 조절자를 통해 일하시고, 전체 신으로서는 오직 삼위일체 안에서 기능하신다.","r":["10:3.9","10:3.16"]}]},{"h":"인격이 아닌 참된 실체","items":[{"x":"삼위일체는 무인격적 역할을 하되 인격과 어긋나지 않게 기능하는 무한한 개인들의 연합으로, 구성원의 인격적 의지를 따르는 법인에 비유된다.","r":["10:4.3"]},{"q":"삼위일체는 세 파라다이스 신들의 결합에서 창발하는 초합적(超合的) 신 실체이다.","r":"104:2.4"},{"x":"세 신은 개인으로서 원하는 대로 협력할 수 있지만, 그런 협력이 곧 삼위일체인 것은 아니다.","r":["10:4.4"]},{"x":"집단의 잠재력이 구성원 속성의 합을 넘어서듯, 삼위일체의 기능도 세 신의 속성을 단순히 더한 것 이상이다.","r":["10:5.2"]},{"x":"존재적 삼자일체는 여럿이지만 존재적 삼위일체는 오직 하나뿐이며, 삼위일체는 기능적 연합이 아니라 나눌 수 없는 신이다.","r":["104:3.15","104:3.16"]}]},{"h":"정의와 우주적 상위통제","items":[{"x":"법은 아버지에게서 나오고, 영적 법의 행정은 아들에게, 법의 계시는 영에게 있으며, 법의 적용인 정의는 삼위일체에 속한다.","r":["10:6.1"]},{"q":"정의는 결코 인격적 태도가 아니며, 언제나 복수적 기능이다.","r":"10:6.2"},{"x":"옛적부터 늘 계신 이들 같은 삼위일체의 고정 아들들이 무한 영의 인격들이 제출한 증거에 따라 초우주의 심판을 집행한다.","r":["10:6.4","10:6.17"]},{"x":"정의는 의로움에 대한 집단적 생각이고 자비는 그 인격적 표현이다. 온전히 이해되면 삼위일체의 정의와 아버지의 사랑은 일치한다.","r":["10:6.18"]},{"x":"삼위일체는 유한에 대해서는 최상위의 삼위일체로, 아절대에 대해서는 궁극위의 삼위일체로 태도를 취한다.","r":["10:5.4","10:5.5"]},{"x":"재난과 설명할 수 없는 삶의 변화들도 최상자의 기능과 삼위일체의 상위통제를 통해 의미 있는 원형 속에 짜여 있을 수 있다.","r":["10:7.5"]}]},{"h":"인류의 삼위일체 이해","items":[{"x":"진화 종교의 삼원 신 개념은 손가락 마디나 세 다리 걸상 같은 자연적 연상에서 나온 것으로, 계시된 삼위일체 개념과 구별해야 한다.","r":["104:0.1","104:0.3"]},{"q":"진정한 삼위일체 개념은 세 개의 독립된 신들의 단순한 집합이 아니다.","r":"104:1.7"},{"x":"유란시아에서 삼위일체는 칼리가스티아 참모진, 아담과 이브, 마키벤타 멜기세덱을 통해 차례로 제시되었다.","r":["104:1.1","104:1.2","104:1.3"]},{"x":"그리스도교의 삼위일체 개념은 사실에서는 오류가 있었으나 영적 관계에 관해서는 사실상 참되었다.","r":["104:1.13"]},{"x":"인격적 신은 다른 동등한 인격과의 관계를 필요로 하며, 그런 관계 없는 신 개념은 결국 범신론적 절대자로 축소되기 쉽다.","r":["104:2.2"]},{"x":"삼위일체 개념을 인식하면 시간-공간 창조계에서 사랑과 법이 맺는 상호 관계를 어느 정도 이해할 수 있다.","r":["104:2.3"]}]}],"see":["우주 아버지","영원 아들","무한 영","세 절대자","최상 존재","정의"],"n":6,"en":"Paradise Trinity"},{"t":"필사자의 상승 여정","sum":"필사자의 상승 여정은 동물 기원의 인간이 진화 행성에서 출발해 맨션 세계와 지역 우주의 모론시아 세계, 초우주의 영 훈련 세계, 중앙 우주 하보나를 거쳐 마침내 파라다이스에서 우주 아버지를 찾고 최종자가 되는 긴 길이다. “내가 완전한 것처럼 너희도 완전하라”는 명령이 이 여정의 출발점이자 목표이며, 그 길은 한 걸음 한 걸음 체험으로 걸어가야 한다.","sections":[{"h":"완전하라는 부르심","items":[{"x":"온 우주의 의지 창조체들은 아버지 하나님에게 도달하려는 영원한 모험, 파라다이스로 가는 긴 여행을 시작했다.","r":["1:0.3"]},{"x":"신성의 완전을 이루려고 노력하는 것은 모든 창조체의 첫째 의무이자 가장 높은 열망이어야 한다.","r":["1:0.4"]},{"x":"사람은 무한한 의미에서 완전할 수는 없어도, 하나님이 세워 주신 신성한 목표에는 충분히 도달할 수 있다.","r":["1:0.5"]},{"q":"우주들의 하나님을 찾는 이 숭고한 탐구는 시간과 공간 모든 세계 거주민들의 최상의 모험이다.","r":"1:0.6"}]},{"h":"일곱 단계의 개요","items":[{"x":"상승 생애는 행성의 필사자, 잠자는 생존자, 맨션 세계 학생, 모론시아 진보자, 초우주 피보호자, 하보나 순례자, 파라다이스 도착자의 일곱 단계로 요약된다.","r":["30:4.1","30:4.2","30:4.8"]},{"x":"잠자는 생존자에게는 시간의 흐름이 중요하지 않아, 오천 년을 잔 이도 닷새를 쉰 이와 다르지 않게 깨어난다.","r":["30:4.12"]},{"x":"상승자들은 한 구체 안에서는 개별적으로 나아가지만, 우주 공부의 단계와 단계 사이는 언제나 학급을 이루어 옮겨 간다.","r":["30:4.17"]},{"x":"지역 우주를 떠나기 직전 참된 영 정체성을 얻으며, 이때부터 상승자의 지위는 영원히 정해진다.","r":["30:4.20","30:4.21"]}]},{"h":"지역 우주와 초우주를 지나","items":[{"x":"맨션 세계에서 체계, 별자리, 우주 본부의 구체들을 거치는 동안 상승자는 모론시아 진보자로서 지성과 영과 형체를 발전시킨다.","r":["30:4.18","30:4.19"]},{"q":"마음과 인격과 성품은 그러한 진보로 변하지 않으며, 형체만 수정을 겪는다.","r":"30:4.20"},{"x":"초우주 훈련 세계에서 젊은 영들은 배운 것을 다른 이들에게 나누며 지역 우주와 초우주 행정을 익힌다.","r":["30:4.22","30:4.23","30:4.24"]},{"q":"초우주 피보호자가 길을 잃었다고 알려진 적은 한 번도 없다.","r":"30:4.21"}]},{"h":"하보나와 파라다이스","items":[{"x":"초우주 본부에서 하보나까지의 여정은 언제나 홀로 하며, 하보나의 가르침은 인격적이고 개별적이다.","r":["30:4.27"]},{"x":"순례자는 오직 목적의 완전함 하나만 지닌 채 하보나에 도착하며, 그 신앙은 이미 시험받았다.","r":["26:4.13"]},{"q":"이해하는 능력은 파라다이스로 가는 필사자의 여권이다. 기꺼이 믿으려는 마음은 하보나에 이르는 열쇠이다.","r":"26:4.15"},{"x":"하보나 셋째 회로에서 아버지 안내자들의 도움으로 우주 아버지를 달성하는 것이 영원으로 가는 여권이 된다.","r":["26:9.1","26:9.2"]},{"x":"파라다이스 거주는 하나님을 찾았다는 뜻이며, 아버지 융합 필사자는 필사 최종자 군단에 편입된다.","r":["30:4.31"]},{"q":"땅에서 너희는 살과 피를 지닌 창조체였고, 지역 우주를 거치는 동안 모론시아 존재였으며, 초우주를 거치는 동안 진화하는 영이었다.","r":"30:4.26"}]},{"h":"여정의 목적과 그 너머","items":[{"x":"한 걸음, 한 생애, 한 세계씩 상승 생애를 숙달하여 신이라는 목표에 이르며, 생존은 완전함 안에서 완결된다.","r":["26:9.4"]},{"x":"최종자들은 여섯째 단계 영으로 기록되어 있어, 아직 계시되지 않은 일곱째 단계의 운명이 남아 있다.","r":["31:3.3","31:3.5"]},{"x":"길고 엄청난 상승 훈련은 더 큰 신뢰의 시험과 더 숭고한 봉사를 감당하게 하려고 계획된 것이 틀림없다.","r":["31:3.2","48:8.3"]},{"x":"조절자·아들·영 융합 필사자의 운명은 서로 다를 뿐 더 크거나 작지 않으며, 하나님은 모든 아들을 똑같이 사랑하신다.","r":["40:10.5","40:10.13"]},{"x":"신성한 완전이라는 파라다이스 목표에 결국 이르도록 모든 편의와 권능이 마련되어 있다.","r":["40:10.14"]},{"q":"생존은 완전함 안에서 완결되고, 완전함은 신성의 최상위성 안에서 가득하다.","r":"26:9.4"}]}],"see":["맨션 세계","모론시아","최종자 군단","하보나","파라다이스","완전을 향한 여정"],"n":46,"en":"Mortal Ascension"},{"t":"하나님 나라","sum":"하나님 나라(하늘 왕국)는 예수가 전한 복음의 중심 개념으로, 무엇보다 신자의 심정 안에서 하늘 아버지의 뜻이 다스리는 개인적 영적 체험이다. 그것은 하나님의 아버지됨과 사람의 형제단 위에 세워지며, 신앙으로 지금 들어가고 사랑의 봉사로 열매를 맺는다. 후대에 왕국 개념은 제도 교회로 대체되었지만, 예수가 가르친 영적 왕국은 앞으로 다시 선포될 것이다.","sections":[{"h":"“왕국은 너희 안에 있다”","items":[{"x":"예수는 하늘 왕국과 하나님의 왕국을 같은 뜻으로 쓰며, 자신의 증여 사명을 나타내는 이름으로 삼았다.","r":["170:0.1"]},{"x":"예수는 사도들에게 왕국을 동료와 하늘 아버지와의 관계 속에서 겪는 개인적 체험으로 가르쳤다.","r":["170:1.13"]},{"q":"왕국에 관해 그의 마지막 말은 항상 “왕국은 너희 안에 있다”였다.","r":"170:1.13"},{"x":"예수는 왕국을 대신할 말로 하나님의 뜻을 쓰도록 설득하려 했고, 왕과 신민 대신 하늘 가족과 해방된 아들들의 개념을 세우고자 했다.","r":["170:2.11","170:2.12"]}]},{"h":"왕국의 기초와 선물","items":[{"x":"하늘 왕국은 하나님의 아버지됨의 진리와 사람의 형제단이라는 사실 위에 시작되고 중심을 잡는다.","r":["170:2.1"]},{"x":"이 가르침은 사람을 오랜 동물적 두려움에서 해방시키고 새 용기와 영적 권능을 준다.","r":["170:2.1","170:2.2"]},{"x":"왕국의 복음은 가난한 이들에게도 확신과 위로를 주며, 영적인 것이 물질적인 것보다 우월함을 가르친다.","r":["170:2.3","170:2.5"]},{"x":"아버지의 뜻이 법일 때는 간신히 왕국에 있지만, 아버지의 뜻이 나의 뜻이 될 때 참으로 왕국 안에 있다.","r":["141:2.2"]}]},{"h":"어떻게 들어가는가","items":[{"q":"예수는 신앙을 통해 신자는 지금 왕국에 들어간다고 가르쳤다.","r":"170:2.20"},{"x":"왕국에 들어가는 두 조건은 어린아이 같은 신앙과 진실함, 그리고 의로움에 대한 갈망이다.","r":["170:2.21","170:2.22"]},{"x":"단순하고 어린아이 같은 믿음이 문을 여는 열쇠이지만, 들어선 뒤에는 올라야 할 의로움의 단계들이 있다.","r":["170:3.2"]},{"q":"신앙은 하나님의 가족에 들어가는 대가이다.","r":"170:3.3"},{"x":"하나님의 용서는 사람이 동료를 용서하는 만큼 실제로 체험되며, 이웃 사랑이 가장 높은 윤리이다.","r":["170:3.4","170:3.6"]},{"q":"하나님의 용서는 사람이 그의 동료를 용서하는 한도 내에서 실제로 가능하며, 개인적으로 체험된다.","r":"170:3.4"}]},{"h":"왕국의 열매와 여러 단계","items":[{"x":"왕국의 내적 종교는 실천적 사회 봉사로 점점 드러나며, 예수는 종교를 원인으로, 윤리를 결과로 가르쳤다.","r":["170:3.8"]},{"q":"왕국의 종교는 개인적이고 개별적이다. 그 열매, 즉 결과는 가족적이고 사회적이다.","r":"170:3.10"},{"x":"예수는 이 세상에서의 왕국과 하늘에서의 왕국이라는 왕국의 두 단계를 가르쳤다.","r":["170:2.18","170:2.19"]},{"x":"왕국에는 개인의 내적 체험, 신자들의 형제단, 초인간적 형제단, 새 사회 질서, 빛과 생명의 시대라는 다섯 단계가 있다.","r":["170:4.2","170:4.4","170:4.6"]},{"x":"왕국은 사회적·경제적 질서가 아니라 하나님을 아는 개인들의 영적 형제단이다.","r":["99:3.2"]}]},{"h":"왕국과 교회","items":[{"x":"예수에게 왕국은 아버지됨을 신앙으로 고백하고 하나님의 뜻을 행하는 데 헌신한 개인들의 총합이었다.","r":["170:5.11"]},{"x":"교회가 생긴 것 자체는 자연스러웠지만, 그것이 예수의 왕국 개념을 거의 완전히 대체한 것이 비극이었다.","r":["170:5.7","170:5.10"]},{"x":"교회 회원 자격이 곧 왕국의 교제를 뜻하지는 않으니, 하나는 영적이고 다른 하나는 주로 사회적이다.","r":["170:5.18"]},{"x":"언젠가 더 위대한 세례자 요한이 나타나 신자의 심정을 다스리는 아버지의 뜻이라는 예수의 왕국 개념으로 돌아가자고 선포할 것이다.","r":["170:5.19"]},{"x":"외형적 교회는 좌절된 영적 왕국의 유충 단계일 뿐이며, 예수의 가르침은 결코 열매 없이 남지 않는다.","r":["170:5.21"]},{"q":"주님이 가르친 하늘 왕국, 즉 신자의 심정 속에 존재하는 이 왕국은 이 그리스도교 교회뿐만 아니라 지상의 모든 다른 종교, 인종, 국가, 그리고 각 개인에게도 여전히 선포될 것이다.","r":"170:5.8"}]}],"see":["하나님의 뜻","하나님의 아들됨","사람의 형제됨","신앙","예수의 가르침","제도 종교"],"n":49,"en":"Kingdom of Heaven"},{"t":"하나님의 뜻","sum":"하나님의 뜻은 첫째 근원이며 중심의 영원한 목적이자, 개인의 삶에서는 하나님의 길과 선택에 협력하는 것이다. 유란시아서는 하나님의 뜻을 행하는 것을 생존과 완전에 이르는 비밀로 보며, 그것은 의지를 버리는 일이 아니라 의지를 바치고 넓히는 일이라고 말한다. 예수는 일생 “내 뜻이 아니라 당신의 뜻”을 살아 그 길의 본보기가 되었다.","sections":[{"h":"하나님의 뜻이란 무엇인가","items":[{"x":"하나님의 뜻은 첫째 근원이며 중심의 목적으로, 영원 아들 안에서 인격화되고 무한 영 안에서 우주 행동으로 나타난다.","r":["117:0.1"]},{"q":"하나님의 뜻은 하나님의 길이며, 어떤 잠재적인 대안에 직면하여 하나님의 선택과 협력하는 것이다.","r":"130:2.7"},{"x":"그러므로 하나님의 뜻을 행하는 것은 선하고 아름답고 참된 모든 것의 원천이신 하나님을 점점 닮아 가는 체험이다.","r":["130:2.7"]},{"x":"하나님의 뜻을 행한다는 것은 자신의 내적 삶을 하나님과 기꺼이 나누려는 의지를 드러내는 것이며, 나눔은 신성한 일이다.","r":["111:5.1"]},{"x":"예수는 하나님의 모든 속성을 마음속에서 “하늘 아버지의 뜻”으로 통합했다.","r":["196:0.2"]}]},{"h":"의지를 바치는 선물","items":[{"x":"아버지의 뜻을 행하려는 인간 의지의 사랑 어린 헌신은 사람이 하나님께 드릴 수 있는 최고의, 유일하게 참된 선물이다.","r":["1:1.2"]},{"x":"하나님은 어떤 강요된 예배나 노예 같은 봉사도 요구하지 않으시며, 사람은 스스로 하나님을 사랑하고 예배해야 한다.","r":["1:1.2"]},{"q":"그러한 창조체의 선택은 의지의 포기가 아니다. 그것은 의지의 봉헌이며, 의지의 확장이고, 의지를 영화롭게 함이며, 의지를 완전하게 함이다.","r":"111:5.5"},{"x":"이 선택은 “내 뜻이 아니라 당신의 뜻”이라는 부정보다 “당신의 뜻이 이루어지는 것이 나의 뜻”이라는 적극적 확언에 있다.","r":["111:5.6"]},{"x":"하나님도 먼저 자신의 단편을 사람의 의지에 맡겨 그 안에 내주하기로 동의하셨다.","r":["111:5.3","111:5.4"]},{"q":"아버지의 뜻을 실천하기 위한 인간 의지의 사랑 어린 헌신은, 인간이 하나님께 드릴 수 있는 최고의 선물이다.","r":"1:1.2"}]},{"h":"뜻을 행하는 삶의 열매","items":[{"x":"하나님을 본받는 것이 완전에 이르는 열쇠이고, 그의 뜻을 행함은 생존과 완전에 이르는 비밀이다.","r":["111:5.2"]},{"x":"이생의 평화, 죽음 뒤의 생존, 다음 생의 완전, 영원의 봉사가 의지를 아버지의 뜻에 맡기기로 선택할 때 영 안에서 이미 성취된다.","r":["111:5.4"]},{"x":"아버지의 뜻을 행하기로 선택함으로써 필사 인격은 내주하는 영과 하나 되어 영원해질 수 있다.","r":["118:1.2"]},{"x":"아버지의 뜻을 사는 삶은 진리에 기초하고 아름다움에 민감하며 선함에 다스려지고, 밖으로는 사랑의 봉사로 드러난다.","r":["106:9.12"]},{"x":"많은 경우 사람이 아버지의 뜻을 행하겠다고 조용히 결심하는 순간 곧바로 생각 조절자가 보내진다.","r":["108:2.10"]},{"q":"하나님을 본받는 것이 완전에 이르는 열쇠이며, 그의 뜻을 행함은 생존과 생존 속의 완전에 이르는 비밀이다.","r":"111:5.2"}]},{"h":"뜻을 찾고 실천하는 모험","items":[{"q":"살아 있는 하나님의 뜻을 발견하려는 시도보다 더 만족스럽고 짜릿한 모험은 하나밖에 없으며, 그것은 그 신성한 뜻을 실천하려는 진실한 노력을 하는 최상의 체험이다.","r":"155:6.11"},{"x":"하나님의 뜻은 어떤 직업에서도 실현될 수 있으며, 영의 인도를 받는 이에게는 거룩한 소명과 세속적 소명의 구분이 없다.","r":["155:6.11"]},{"x":"아버지의 뜻에 완전히 헌신할 때 기도는 그 뜻과 일치하게 되어 모든 청원에 응답이 있다.","r":["146:2.7"]},{"x":"희생 제물의 관념은 자신의 의지를 바치는 대신 물질을 바치게 하여 참된 기도의 효능을 떨어뜨린다.","r":["91:2.4"]},{"x":"하나님의 뜻은 순간마다 이기지는 않지만, 생애 전체를 보면 영의 인도를 받는 이들의 열매 속에서 점점 뚜렷해진다.","r":["12:7.7"]}]},{"h":"예수, 아버지의 뜻을 산 본보기","items":[{"q":"“내가 누구이든, 내가 어떤 권능을 행사하든 행사하지 않든, 나는 항상 파라다이스 아버지의 뜻에 복종해 왔고 앞으로도 그럴 것이다.”","r":"128:7.2"},{"x":"예수의 마음은 삶의 모든 상황에서 “내 뜻이 아니라 당신의 뜻”을 지켰고, 이 봉헌이 신성한 달성으로 가는 참된 여권이다.","r":["109:6.5"]},{"x":"미가엘의 증여에서 큰 임무는 아버지의 뜻을 행하는 삶을 살아 육신의 창조체들에게 하나님을 계시하는 것이었다.","r":["120:2.8"]},{"x":"예수는 자기 의지를 신성한 뜻을 행하는 데 바쳐 사람이 하나님께 드릴 수 있는 가장 위대한 헌물을 드렸다.","r":["196:0.10"]},{"x":"예수는 왕국이라는 말 대신 하나님의 뜻을 쓰도록 제자들을 설득하려 했다.","r":["170:2.11"]}]}],"see":["자유 의지","하나님 나라","기도","예배","예수의 성품","최상 존재"],"n":50,"en":"Will of God"},{"t":"하나님의 속성","sum":"하나님의 속성은 무한하신 아버지가 창조계와 관계 맺는 방식을 보여 준다. 그는 어디에나 계시고, 모든 권능을 지니시며, 모든 것을 아신다. 자신을 아낌없이 나누어 주어도 조금도 줄지 않으시며, 아들들을 통해 다스리시되 최종 주권은 유보하신다. 이 모든 속성은 사랑과 지혜, 정의와 자비 안에서 하나로 조율되어 있다.","sections":[{"h":"창조성과 어디에나 계심","items":[{"x":"창조성은 하나의 속성이라기보다 하나님의 활동하는 본성 전체이며, 하나님의 아버지 되심이라는 진리 안에서 궁극에 이른다.","r":["3:0.3"]},{"x":"오직 하나님만이 동시에 무수한 장소에 계실 수 있으며, 그는 창조계의 모든 부분과 모든 가슴속에 계신다.","r":["3:1.1","3:1.2"]},{"q":"하나님은 우주 전체에 걸쳐 계시되지만, 우주는 결코 하나님의 무한 전체를 담거나 포괄할 수 없다.","r":"3:1.2"},{"x":"하나님은 파라다이스와 중앙 우주에서만 온전히 식별되게 현존하시고, 바깥 창조계에서는 동격 창조자들의 주권을 존중하여 직접 현존을 제한하신다.","r":["3:1.6"]},{"x":"사람 안에서 아버지의 효과적 현존은, 내주하는 조절자에게 그 마음이 얼마나 협력하느냐에 따라 정해진다.","r":["3:1.11","3:1.12"]}]},{"h":"무한한 권능","items":[{"x":"민족과 행성과 우주의 오랜 진화는 창조자들의 통제 아래 아버지의 영원한 목적에 따라 질서 있게 펼쳐진다.","r":["3:2.2"]},{"x":"비영적 현상으로 보면 하나님은 에너지이시다. 모든 물리적 에너지는 그분에게서 비롯되어 하부 파라다이스의 중력 통제 안에 붙들려 있다.","r":["3:2.3","3:2.4"]},{"q":"겉보기와 상관없이, 하나님의 권능은 결코 맹목적인 힘으로 작동하지 않는다.","r":"3:2.6"},{"x":"하나님의 행위가 때로 무정해 보이는 것은 유한한 시야 때문이며, 그 모든 행위는 관련된 모두의 최선의 선을 목적으로 한다.","r":["3:2.8","3:2.10"]},{"x":"하나님의 권능은 그의 본성(사랑·진리·아름다움·선하심), 그의 의지(자비), 그의 법(삼위일체의 정의)에 의해서만 제한된다.","r":["3:2.12","3:2.13","3:2.14"]}]},{"h":"모든 것을 아심","items":[{"x":"하나님은 모든 창조계의 생각을 의식하시며, 공간의 별과 행성의 수를 실제로 아는 유일한 인격이시다.","r":["3:3.1","3:3.2"]},{"x":"그의 지식은 모든 인격을 감싸는 인격 회로, 하강하는 신성한 아들들, 그리고 내주하는 생각 조절자를 통해 보충된다.","r":["3:3.3"]},{"x":"설령 하나님이 자녀들의 자유 의지에 따른 행위를 미리 아신다 해도, 그 사전 지식은 그들의 자유를 조금도 없애지 않는다.","r":["3:3.4"]},{"q":"한 가지 분명한 것은, 하나님은 결코 놀라지 않으신다는 점이다.","r":"3:3.4"},{"x":"전능은 하나님답지 않은 일을 할 능력을 뜻하지 않으며, 전지는 알 수 없는 것까지 아는 것을 뜻하지 않는다.","r":["3:3.5"]}]},{"h":"줄어들지 않는 무한함","items":[{"x":"아버지는 아들들과 창조계에 자신을 아낌없이 나누어 주신 뒤에도 권능과 지혜와 사랑의 잠재력이 조금도 줄지 않으신다.","r":["3:4.1","3:4.3"]},{"x":"창조가 끝없이 이어진다 해도 파라다이스의 통제 권능은 넉넉하며, 무한자는 여전히 같은 힘과 에너지로 가득 차 있을 것이다.","r":["3:4.2"]},{"x":"사람은 아버지의 무한성을 끝까지 생각해 낼 수 없지만 그 사랑의 충격은 실제로 체험할 수 있다. 체험의 질은 무제한이나 그 양은 영적 수용 능력에 달려 있다.","r":["3:4.6"]},{"q":"그러므로 사람이 하나님께 가장 가깝고 가장 소중하게 다가가는 길은 사랑에 의한, 사랑을 통한 길이다.","r":"3:4.7"}]},{"h":"최상 통치와 수위성","items":[{"x":"하보나 바깥 창조계에서 아버지는 아들들과 그 종속 인격들을 통해 권능을 행사하시며, 위임받은 자가 책무에 실패할 때에만 직접 행동하신다.","r":["3:5.1","3:5.2"]},{"x":"사람의 마음속에서는 아버지의 뜻이 늘 그대로 되지 않을 수 있으나, 한 행성의 행로와 운명에서는 신성한 계획이 우세하다.","r":["3:5.3"]},{"x":"역경, 불평등, 불확실성, 오류의 가능성은 용기·이타심·희망·신앙 같은 품성을 길러 내는 데 필요한 삶의 조건이다.","r":["3:5.6","3:5.7","3:5.9"]},{"x":"아버지는 권한을 아낌없이 위임하시지만, 창조계의 안녕과 운명에 관한 최종 결정과 거부권은 스스로 유보하신다.","r":["3:6.1"]},{"q":"하나님의 주권은 제한이 없으며, 이것은 모든 창조의 근본 사실이다.","r":"3:6.2"}]},{"h":"완전함, 정의, 자비","items":[{"x":"첫째 근원이며 중심의 계획과 목적은 그분처럼 영원하고 완전하며 변하지 않는다. 겉으로 달라지는 듯 보여도 그 밑의 목적은 불변이다.","r":["2:2.1","2:2.3"]},{"x":"아버지의 정의는 창조체의 행위에 좌우되지 않으며, 잘못의 결과를 거두게 할 때에도 언제나 자비로 누그러진다.","r":["2:3.1","2:3.2"]},{"q":"자비는, 완전한 지식과, 유한한 창조체의 본성적 약점과 환경적 한계에 대한 충분한 인식에서 자라난 지혜로 누그러진 정의일 뿐이다.","r":"2:4.1"},{"x":"무한한 지혜 덕분에 하나님은 정의와 자비를 동시에 베푸시며, 자녀를 향한 상충하는 태도로 찢기지 않으신다.","r":["2:4.3"]}]}],"see":["우주 아버지","하나님의 인격","자비","정의","사랑","하나님의 뜻"],"n":2,"en":"Attributes of God"},{"t":"하나님의 아들됨","sum":"하나님의 아들됨은 사람이 신앙으로 하나님을 아버지로 받아들일 때 실재가 되는, 하늘 아버지와 개인 사이의 가족 관계이다. 예수가 전한 왕국 복음의 중심은 하나님의 아버지됨과 그로부터 나오는 사람의 아들됨이다. 이 아들됨은 행위로 사는 것이 아니라 선물로 받는 것이며, 내주하는 조절자와 진리의 영과 성령이 그 사실을 사람의 영과 더불어 증언한다.","sections":[{"h":"신앙으로 받는 아들됨","items":[{"x":"사람은 아들됨의 지위를 받아들이고 그 실체를 믿음으로써, 하나님과의 아들됨이 영원히 실재하게 된다.","r":["40:6.4"]},{"q":"하나님의 아버지됨에 대한 신앙으로 너희는 하늘 왕국에 들어가 하나님의 아들이 될 수 있다.","r":"142:1.3"},{"q":"너희가 하나님을 아버지로 받아들이면, 너희는 참으로 하나님의 아들들이다.","r":"142:5.2"},{"x":"구원은 아버지의 선물이며, 신앙으로 받아들이는 이는 신성한 본성에 참여하여 하나님의 아들이나 딸이 된다.","r":["150:5.3"]},{"x":"왕국에 들어가는 첫 조건은 어린아이처럼 와서 아들됨의 증여를 선물로 받는 신앙과 진실함이다.","r":["170:2.21"]}]},{"h":"필사자가 아들인 이유","items":[{"x":"미천하고 물질적인 인간이 지극히 높으신 이의 신앙 자녀라는 것은 엄숙하고 숭고한 사실이다.","r":["40:6.2"]},{"x":"창조자 아들이 사람이 되어 우리의 맏형이 되었으므로, 그와 형제인 우리는 같은 아버지의 아들이다.","r":["40:6.5"]},{"x":"아들의 영이 모든 종족에게 부어졌고, 아버지께 인격을 받았으며, 아버지의 단편이 내주하기에 우리는 아들이다.","r":["40:6.6","40:6.7","40:6.8"]},{"x":"성령과 진리의 영과 조절자가 함께 현존하므로 필사자는 하나님의 아들됨을 의식적으로 깨달을 자격을 얻는다.","r":["34:5.7"]},{"x":"영은 “너희의 영에게”가 아니라 “너희의 영과 더불어” 우리가 하나님의 자녀임을 증언한다.","r":["34:6.12"]},{"q":"그는 사실상 너희의 맏형이다.","r":"40:6.5"}]},{"h":"종의 신분에서 자유로운 아들로","items":[{"x":"왕국의 백성은 통치자의 법을 듣지만, 신앙으로 아들임을 발견한 이는 자신을 사랑하는 아버지의 특권 있는 아들로 본다.","r":["141:2.2"]},{"x":"아버지의 뜻이 법일 때는 고귀한 노예이지만, 아버지의 뜻이 나의 뜻이 될 때 하나님의 자유로운 자녀가 된다.","r":["141:2.2"]},{"x":"이 땅의 좋은 아버지가 자녀를 불안 속에 두지 않듯, 하늘 아버지도 신앙의 자녀들을 의심 속에 남겨 두지 않으신다.","r":["142:5.2"]},{"q":"영으로 태어난 사람은 누구나 모든 의심을 이길 힘을 자기 안에 지니고 있으며, 이것이 모든 불확실성을 이기는 승리, 곧 너희의 신앙이다.","r":"142:5.3"}]},{"h":"아들됨의 열매","items":[{"x":"의로움은 구원의 조건이 아니라, 아들됨이라는 영으로 거듭난 삶의 자연스러운 열매이다.","r":["150:5.5"]},{"q":"아들됨의 자각은 죄를 짓고자 하는 욕망과 양립할 수 없다.","r":"150:5.5"},{"x":"영으로 태어났다는 세상을 향한 증거는 신자들이 서로를 진실하게 사랑하는 것이다.","r":["142:5.4"]},{"x":"우리의 이상이 초인간적 기원에서 왔음을 살아 있는 신앙으로 받아들일 때 아들됨의 믿음이 유효해지고 형제애도 실재가 된다.","r":["103:5.9"]},{"x":"종교는 원시적 두려움의 속박에서 하나님과의 아들됨을 자각하는 신앙의 자유에까지 이르는 체험이다.","r":["101:0.1"]},{"q":"너희가 영으로 태어났다는 온 세상을 향한 증거는 너희가 서로를 진실하게 사랑하는 것이다.","r":"142:5.4"}]},{"h":"예수가 전한 복음의 중심","items":[{"x":"예수는 모든 필사 창조체가 사랑의 아버지의 자녀, 곧 하나님의 아들이라고 선포함으로써 아버지 개념을 숭고한 체험으로 높였다.","r":["196:0.2"]},{"x":"예수는 제자들에게 하나님이 아버지시고 사람이 그 아들이라는 것을 먼저 알게 한 뒤에 교리를 논하라고 일렀다.","r":["141:6.4"]},{"x":"예수는 다른 시대 사람들이 복음을 하나님의 아버지됨과 사람의 형제단과 하나님과의 아들됨이라는 가족의 말로 더 잘 이해하리라고 했다.","r":["142:7.4"]},{"x":"왕국의 복음은 하나님의 아버지됨이라는 사실에 사람들의 아들됨-형제단의 진리가 결합된 것이다.","r":["194:0.4"]},{"x":"진리의 영은 신자들을 하나님과의 영원하고 상승하는 아들됨을 아는 자라나는 의식으로 인도하려고 왔다.","r":["194:2.7"]}]}],"see":["우주 아버지","사람의 형제됨","하나님 나라","신앙","진리의 영","생각 조절자"],"n":47,"en":"Sonship with God"},{"t":"하나님의 인격","sum":"우주 아버지는 무한하시면서도 참된 인격이시다. 인격은 하나님의 여러 속성 가운데 하나가 아니라 그분의 무한한 본성과 통일된 의지 전체가 드러나는 방식이다. 모든 창조체의 인격은 아버지가 주시고 그의 인격 회로로 붙드시며, 인격적 하나님이시기에 사람은 그와 교제하고 그를 사랑하며 그의 친구가 될 수 있다.","sections":[{"h":"무한하면서 인격적인 하나님","items":[{"q":"하나님은 무한하시며 인격적이시다. 그는 무한한 인격이시다.","r":"1:5.1"},{"x":"하나님은 인간이 파악할 수 있는 인격 개념을 훨씬 초월하시지만, 영원하고 참되며 선하고 아름다운 인격 이하의 어떤 것도 될 수 없다.","r":["1:5.2"]},{"x":"하나님과 그의 중심 인격이 없다면 광대한 우주 어디에도 인격은 존재하지 않을 것이다.","r":["1:5.7"]},{"x":"인격은 하나님의 한 속성이 아니라 조율된 무한한 본성과 통일된 신성한 의지의 총체이며, 우주들의 우주에 대한 하나님의 계시이다.","r":["1:5.13"]},{"x":"하나님은 권능·에너지·원형·현존 이상이시다. 그는 주권적 의지를 행사하고 신성의 자의식을 체험하며 자녀에게 아버지의 사랑을 드러내시는 인격이시다.","r":["3:6.7"]}]},{"h":"인격 개념을 둘러싼 오해","items":[{"q":"인간의 인격은 신성한 창조주 인격이 시간-공간에 드리운 형상-그림자이다.","r":"1:6.1"},{"x":"인격에는 물질적 몸이 필요하지 않다. 이 오해 때문에 유물론은 죽은 사람의 인격을, 범신론은 몸이 없는 하나님의 인격을 부정한다.","r":["1:5.12"]},{"x":"첫째 근원이며 중심의 인격을 부정하면 유물론과 범신론이라는 두 철학적 딜레마만 남는다.","r":["1:5.11"]},{"x":"이성과 지혜와 종교 체험은 하나님의 인격을 암시하지만 증명하지는 못하며, 이 개념은 주로 계시를 통해 인류에게 왔다.","r":["1:5.10"]},{"q":"하나님은 과학에는 원인이요, 철학에는 하나의 관념이며, 종교에는 한 인격, 더 나아가 사랑의 하늘 아버지이시다.","r":"1:6.2"},{"x":"사람은 유한에서 무한을 보고 하나님은 무한에서 유한을 보신다. 그래서 신성한 인격에 대한 개념은 인간 인격에 대한 이해가 나아질 때 함께 향상된다.","r":["1:6.3"]}]},{"h":"인격을 주시는 분","items":[{"x":"아버지는 가장 낮은 필사자부터 가장 높은 창조자까지 모든 인격의 증여자이자 보존자이며, 그의 뜻을 택하는 모든 유한 인격의 운명이시다.","r":["5:6.1"]},{"x":"마음이나 영, 물리 에너지만으로는 인격이 되지 않는다. 인격은 물질·마음·영의 살아 있는 체계에 아버지가 독점적으로 주시는 자질이다.","r":["5:6.3","5:6.4"]},{"q":"인격은 점진적 성취도 아니다.","r":"5:6.3"},{"x":"모든 중력이 파라다이스 섬에, 마음이 공동 행위자에, 영이 영원 아들에 연결되듯이, 모든 인격은 아버지의 인격 회로에 연결되어 있다.","r":["5:6.11"]},{"x":"아버지는 조절자의 사명과 무관하게 자의식적 존재의 모든 수준에 있는 인격들을 인격적으로 의식하고 접촉하신다.","r":["5:6.10"]}]},{"h":"자유 의지를 존중하심","items":[{"x":"창조체에게 인격을 주실 때 아버지는 선행 원인에 대한 노예적 반응에서 상대적으로 해방하는 자유를 함께 주신다.","r":["5:6.9"]},{"x":"혼이 자랄 준비를 마련한 뒤 아버지는 한 걸음 물러나시며, 영원한 생존에 관해서는 필사 의지의 주권을 절대적 법령으로 정하셨다.","r":["5:6.8"]},{"q":"어떤 인격적 창조체도 영원한 모험으로 강제될 수 없다.","r":"5:6.12"}]},{"h":"인격적 하나님과의 교제","items":[{"x":"비인격적 사물들 사이에는 상호작용만 있을 뿐이며, 아버지와 아들 같은 교제는 양쪽이 모두 인격일 때에만 누릴 수 있다.","r":["1:7.1"]},{"q":"인간은 하나님과의 연합을, 마치 물방울이 바다에 녹아 하나가 되는 방식으로 달성할 수 없다.","r":"1:7.2"},{"x":"진리와 아름다움은 인격 없이도 생각할 수 있지만, 신성한 선함은 인격과의 관계 안에서만 이해되며 오직 인격만이 사랑하고 사랑받을 수 있다.","r":["1:7.3"]},{"x":"하나님은 알고 알려질 수 있으며 사랑하고 사랑받을 수 있는 분이시므로, 사람도 하나님의 친구로 알려질 수 있다.","r":["1:5.8"]},{"x":"예수는 인간 체험 안에서 영 인격의 잠재력을 온전히 실현했으므로, 그의 삶은 하나님의 인격에 대한 가장 실제적인 계시이다.","r":["1:6.8"]},{"x":"사람이 인격적 하나님의 사랑을 보지 못하면 하나님의 왕국은 그저 선의 왕국이 되고 만다.","r":["2:5.12"]}]}],"see":["우주 아버지","인격","자유 의지","하나님의 속성","사랑","예수의 증여"],"n":3,"en":"Personality of God"},{"t":"하보나","sum":"하보나는 파라다이스 섬을 둘러싼 십억 개의 완전한 세계로 이루어진 영원한 중앙 우주이다. 진화의 산물이 아니라 처음부터 완전하게 창조된 우주로서 모든 우주의 원형이며, 일곱 회로의 세계들은 시간의 우주에서 온 상승 순례자들이 파라다이스에 들어가기 전에 거치는 최종 훈련장이다. 정부도 죄도 없는 완전함 속에서 하보나는 아버지와 창조자들에게 만족을, 상승자들에게는 끝없는 경이를 준다.","sections":[{"h":"영원하고 완전한 중앙 우주","items":[{"x":"하보나는 온 창조계의 중심에 자리한 완전하고 신성한 우주이며, 시간과 공간의 광대한 창조계들이 그 둘레를 돈다.","r":["14:0.1"]},{"q":"이것은 전체적으로 창조된 완전한 우주이지, 진화적 산물이 아니다.","r":"14:0.2"},{"x":"창조자 아들들은 이 원형 우주의 신성한 완전함을 시간 속에서 복제하고 공간 속에서 재현하고자 한다.","r":["14:0.2"]},{"x":"하보나는 정확히 유한하지도 절대적이지도 않으며, 절대적 파라다이스와 유한한 창조계 사이에서 완충 역할을 한다.","r":["105:7.2"]},{"x":"하보나는 영원하지만 성장이 없다는 뜻의 불변은 아니며, 지금 시대에는 진화하는 초우주들과 조율되면서 일정한 진행적 변화를 겪는다.","r":["105:7.2","106:0.18"]}]},{"h":"회로와 구조","items":[{"x":"하보나의 십억 세계는 파라다이스 위성들의 세 회로를 둘러싼 일곱 동심 회로에 배열되어 있다.","r":["14:1.9"]},{"x":"각 회로에는 무한 영의 특화된 표현인 회로의 영이 충만하여 그 회로의 천상 업무를 조율한다.","r":["14:1.9"]},{"x":"바깥에는 빛을 반사하지도 흡수하지도 않는 거대한 암흑 중력체들이 서로 반대 방향으로 돌며 하보나를 가리고 안정시킨다.","r":["14:1.14","14:1.15"]},{"x":"파라다이스-하보나의 하루는 유란시아의 천 년에 가까우며, 일곱 초우주의 표준 시간이 된다.","r":["14:1.12","14:1.13"]},{"x":"하보나의 물질은 삼중 에너지 조직으로 되어 있어, 초우주의 이중 에너지 체계와 근본적으로 다르다.","r":["14:2.2","14:2.6"]},{"q":"만일 유란시아 필사자가 하보나로 옮겨질 수 있다면, 그는 그곳에서 귀먹고 눈멀 것이며, 다른 모든 감각 반응도 완전히 결여될 것이다.","r":"14:2.4"}]},{"h":"정부 없는 완전한 세계","items":[{"q":"중앙 우주의 정부에 관해서 말하면, 아무 정부도 없다.","r":"14:3.1"},{"x":"각 하보나 구체는 삼위일체 기원의 영원으로 늘 계신 이가 지휘하며, 그의 계획에 따라 독창적으로 가꾸어져 어느 둘도 같지 않다.","r":["14:3.3","14:5.6"]},{"x":"하보나에서는 원주민이든 순례자든 어떤 창조체도 죄를 지은 적이 없으며, 때가 되기 전에 입장한 상승 혼도 없다.","r":["14:2.9"]},{"x":"쇠퇴와 죽음은 하보나 생명 주기에 없으며, 하등 생물들은 형태가 바뀔 뿐 분해되지 않는다.","r":["14:4.9"]},{"x":"하보나 원주민은 파라다이스 삼위일체의 소생으로 창조체 부모가 없으며, 그 본성 자체로 하나님의 뜻을 산다.","r":["14:4.10","14:4.13"]}]},{"h":"상승자의 최종 훈련장","items":[{"x":"시간의 순례자는 일곱째 회로의 영접 세계에 내려, 행성마다 회로마다 안쪽으로 나아가 마침내 파라다이스에 이른다.","r":["14:3.4"]},{"x":"순례자는 단 하나의 완전함, 곧 시험을 거쳐 입증된 목적의 완전함만을 지닌 채 하보나에 도착한다.","r":["26:4.12","26:4.13"]},{"q":"이해하는 능력은 파라다이스로 가는 필사자의 여권이다. 기꺼이 믿으려는 마음은 하보나에 이르는 열쇠이다.","r":"26:4.15"},{"x":"순례자는 회로를 따라 안쪽으로 나아가며 주 영의 정체성, 최상 존재, 무한 영, 영원 아들, 우주 아버지를 차례로 달성한다.","r":["14:5.4"]},{"x":"인간 마음의 ‘진보의 원’이라는 이름도 중앙 우주의 이 회로 배치에서 유래했다.","r":["14:5.4"]}]},{"h":"끝없는 경이","items":[{"x":"중앙 우주의 삶은 너무나 풍요롭고 충만하여, 창조된 존재가 체험할 수 있는 것에 대한 인간의 개념을 초월한다.","r":["14:5.2"]},{"q":"단조로움은 하보나 생애의 일부가 아니다.","r":"14:5.9"},{"x":"십억 세계 하나하나가 진정한 놀라움의 대학이며, 순례자는 회로를 건널 때마다 상상하지 못한 변화를 만난다.","r":["14:5.9"]},{"x":"모험심과 호기심은 지상에서는 자주 억눌리지만, 다가올 긴 시대에 온전히 충족되도록 주어진 신성한 부여이다.","r":["14:5.10","14:5.11"]}]},{"h":"중앙 우주의 목적","items":[{"x":"아버지는 하보나의 완전함에서 최상의 부모로서의 만족을 얻으시며, 완벽한 창조체의 경배를 기뻐하신다.","r":["14:6.6"]},{"x":"하보나는 창조자 아들들이 우주 창조를 준비하는 훈련장이며, 모든 창조자 아들은 자기 우주를 이 완전함의 수준으로 이끌려 한다.","r":["14:6.27"]},{"x":"하보나는 최상 존재의 완전한 영 본성의 계시이자, 그의 미래 통일을 미리 보여 주는 예시이다.","r":["14:6.23","14:6.24"]},{"q":"파라다이스는 최종자들의 집이며, 하보나는 작업장이자 놀이터이다.","r":"14:6.39"},{"x":"하보나는 미래 시대에도 아절대 존재들을 위한 훈련 우주로서 무제한의 잠재력을 지닐 것으로 보인다.","r":["14:6.41"]}]}],"see":["파라다이스","일곱 초우주","최상 존재","필사자의 상승 여정","최종자 군단","대우주와 주(主)우주"],"n":12,"en":"Havona"},{"t":"혼","sum":"혼은 물질적 마음과 내주하는 생각 조절자의 관계에서 새로 생겨나는 모론시아 실체로, 인간의 노력과 신성한 영이 함께 낳은 자녀이다. 육신의 삶 동안에는 배아처럼 자라다가 죽음을 넘어 살아남아 맨션 세계에서 인격의 새로운 매개체가 된다. 혼의 성장은 도덕적 선택과 하나님을 찾는 결단에 달려 있으며, 인격 정체성은 혼의 생존 안에서 살아남는다.","sections":[{"h":"혼은 어떻게 생겨나는가","items":[{"x":"필사자가 아버지의 뜻을 행하기로 선택할 때, 내주하는 영은 새 실체의 아버지가 되고 물질적 마음은 그 어머니가 된다.","r":["0:5.10"]},{"x":"혼을 만드는 데는 인간의 마음, 내주하는 신성한 영, 그리고 그 둘 사이의 관계라는 세 요인이 작용한다.","r":["111:2.4","111:2.5","111:2.6"]},{"q":"이 독특한 관계의 실체는 물질도 영도 아니며, 모론시아이다. 그것은 혼이다.","r":"111:2.7"},{"x":"신성한 영은 인간 마음이 처음 도덕적 활동을 시작할 때 도착하며, 바로 그 순간 혼이 탄생한다.","r":["133:6.5"]},{"x":"상승 필사자의 모론시아 생명은 실제로 혼이 잉태되는 순간, 곧 조절자가 내주할 때 이미 시작된다.","r":["48:6.2"]}]},{"h":"혼의 본성","items":[{"x":"중도 창조체들은 이 혼을 물질 마음과 우주 마음 사이에 있다는 뜻에서 ‘중간 마음’이라 불렀다.","r":["111:2.8"]},{"x":"혼은 인간을 동물 수준 위로 높이는 부분으로, 도덕적 선택과 하나님을 알고 닮으려는 충동이 그 특징이다.","r":["133:6.5"]},{"x":"자의식 자체는 혼이 아니며, 도덕적 자의식이 참된 자아실현으로서 혼의 기초를 이룬다.","r":["133:6.5"]},{"x":"혼은 물질적 조사로도 순수한 영 시험으로도 증명되지 않지만, 도덕적으로 깨어 있는 필사자는 그 실재를 체험으로 안다.","r":["133:6.7"]},{"q":"그 최초의 발상부터 혼은 실제적이며, 우주적 생존 특질들을 가지고 있다.","r":"16:9.2"},{"x":"모론시아 혼은 아버지의 조절자 작용의 자녀이자 최상 존재의 우주적 반응의 자녀이기도 하다.","r":["117:6.5"]}]},{"h":"혼의 성장","items":[{"x":"마음은 인간의 토양이며, 조절자는 인격의 협력을 얻어 그 위에서 모론시아 혼을 진화시킨다.","r":["111:1.1"]},{"q":"필사 인간의 물질 마음은 모론시아 천이 걸린 우주의 베틀이며,","r":"111:2.2"},{"x":"혼은 문화 수준과 상관없이 자랄 수 있지만, 생존을 택하고 아버지의 뜻을 행하려는 결단 없이는 자라지 못한다.","r":["65:8.4"]},{"x":"실수와 잘못은 혼의 진화를 늦출 수 있으나, 의지의 동의로 시작된 혼의 진화를 막지는 못한다.","r":["111:3.1"]},{"q":"인간의 혼은 도덕적 사고와 영적 활동 없이는 존재할 수 없으며, 정체된 혼은 죽어 가는 혼이다.","r":"133:6.5"},{"x":"혼이 진리와 아름다움과 선하심으로 충만할수록 그 결과로 생긴 존재는 파괴될 수 없게 된다.","r":["111:3.7"]}]},{"h":"혼과 인간의 의지","items":[{"x":"생애 동안 결정하는 의지는 물질 마음에 있지만, 자아는 성장하면서 출현하는 모론시아 혼과 점점 더 동일화된다.","r":["111:3.2"]},{"q":"따라서 혼은 인격 정체성의 미래 모론시아 매개체의 배아(胚芽)이다.","r":"111:3.2"},{"x":"필사 인격은 자기 선택으로 정체성의 자리를 일시적 물질-지성 체계에서 모론시아-혼 체계로 옮길 수 있다.","r":["112:5.4","112:2.20"]},{"q":"신앙으로 활성화된 인간의 혼은 이 운명 목표의 달성에서 멈출 수 없으며,","r":"132:3.7"},{"x":"혼의 구원이나 상실은 도덕적 의식이 불멸의 영 부여물과 영원히 결연하여 생존 가치를 얻느냐에 달려 있다.","r":["133:6.6"]}]},{"h":"죽음 이후의 혼","items":[{"q":"이 새로 출현한 실체는 혼이며, 그것은 너희의 물질적 몸과 물질적 마음의 죽음 후에도 살아남는다.","r":"112:5.12"},{"x":"혼은 죽음에서 재인격화까지 완전히 무의식 상태로 세라핌 운명 수호자의 보호 아래 있다.","r":["112:5.13"]},{"x":"부활 전당에서 세라핌은 잠자던 혼을 새 모론시아 형태에 부여하고 돌아온 조절자와 연합하게 한다.","r":["112:5.18","112:5.19"]},{"x":"필사자가 생존하지 못하면 그 체험의 영적 가치는 조절자 안에 남지만 정체성은 살아남지 못한다.","r":["16:9.3"]},{"x":"육체 속 혼은 배아 상태이며, 모론시아 생명에서 태어나 맨션 세계들을 거치며 성장한다.","r":["66:4.9"]},{"x":"불멸의 혼은 처음엔 모론시아적이지만 참된 영 수준으로 올라가, 보통 자신을 시작한 아버지의 영과 융합한다.","r":["111:3.3"]}]},{"h":"혼에 관한 인류의 생각","items":[{"x":"원시인은 혼을 피, 숨, 그림자, 물에 비친 모습과 연관 짓거나 여러 신체 기관에 머문다고 여겼다.","r":["111:0.3"]},{"x":"초기 인간은 꿈속의 또 다른 자아를 혼으로 여겼고, 이 생각이 자연 영 신앙으로 이어졌다.","r":["86:5.1"]},{"x":"힌두 교사들은 아트만 개념에서 조절자를 거의 바로 보았지만, 함께 진화하는 혼은 구별하지 못했다.","r":["111:0.4"]}]}],"see":["생각 조절자","인격","마음","모론시아","생존","조절자 융합"],"n":35,"en":"Soul"}];
